/// Definition-local anchors needed by the direct checked-image linker.
///
/// These IDs deliberately remain local until every definition has been
/// solved. One prefix-sum layout can then globalize the whole snapshot without
/// re-opening parser arenas or rediscovering an owner's public surface.
#[derive(Clone, Copy, Debug, Default, Eq, Hash, PartialEq, Serialize)]
pub struct KernelDefinitionLinkage {
    pub root_statement: Option<KernelStatementId>,
    /// The declaration exported by this definition. Nested SOURCE, HOLD, and
    /// LIST definitions deliberately share the declaration owned by their
    /// enclosing definition instead of fabricating a local row.
    pub public_declaration: Option<KernelDeclarationReference>,
    pub result_expression: Option<KernelExpressionId>,
    /// The definition-local formal ordinal reserved for inherited `PASSED`.
    /// Ordinary authored parameters always precede it.
    pub context_formal_ordinal: Option<u32>,
}

/// Dense lexical-scope identity inside one definition artifact.
///
/// Scope IDs are deliberately separate from expression and statement IDs. A
/// definition may borrow its containing scope from an enclosing definition,
/// while every scope it creates remains a compact local row.
#[derive(Clone, Copy, Debug, Eq, Hash, Ord, PartialEq, PartialOrd, Serialize)]
pub struct KernelScopeId(pub u32);

/// One lexical scope authority before the checked snapshot is globally linked.
#[derive(Clone, Copy, Debug, Default, Eq, Hash, PartialEq, Serialize)]
pub enum KernelScopeReference {
    #[default]
    ProjectRoot,
    /// The scope supplied by this definition's lexical placement. This keeps
    /// local rows stable while an enclosing definition is dense-relocated.
    Containing,
    Local(KernelScopeId),
    Owner {
        owner: KernelOwnerId,
        scope: KernelScopeId,
    },
}

#[derive(Clone, Copy, Debug, Eq, Hash, PartialEq, Serialize)]
pub enum KernelScopeKind {
    Function,
    Block,
    Record,
    RepeatedOutput,
    CallContext,
}

/// Structural source of a scope row. This is compact linker authority, not a
/// copy of the old owner-shard stable-key DTO.
#[derive(Clone, Copy, Debug, Eq, Hash, PartialEq, Serialize)]
pub enum KernelScopeOrigin {
    StatementBody {
        statement: KernelStatementId,
    },
    Record {
        expression: KernelExpressionId,
    },
    MatchArm {
        expression: KernelExpressionId,
    },
    RepeatedOutput {
        statement: KernelStatementId,
        parameter_ordinal: u32,
    },
    CallbackOutput {
        call: KernelExpressionId,
        formal_ordinal: u32,
    },
    CallContext {
        expression: KernelExpressionId,
        context_ordinal: u32,
    },
}

