/// Presentation facts needed to construct checked rows without reopening a
/// parser arena or a legacy owner shard.
#[derive(Clone, Debug, Default, Eq, Hash, PartialEq, Serialize)]
pub struct KernelDefinitionPresentation {
    pub containing_scope: KernelScopeReference,
    pub scopes: Box<[KernelScopePresentation]>,
    pub expressions: Box<[KernelExpressionPresentation]>,
    pub statements: Box<[KernelStatementPresentation]>,
    pub declarations: Box<[KernelDeclarationPresentation]>,
}

impl KernelDefinitionPresentation {
    pub fn is_empty(&self) -> bool {
        self.scopes.is_empty()
            && self.expressions.is_empty()
            && self.statements.is_empty()
            && self.declarations.is_empty()
    }
}

/// Stable-within-definition structural origin of one declaration row.
///
/// The dense declaration ID is intentionally revision-local. The origin is
/// expressed only through other definition-local IDs so a linker can relocate
/// it without retaining parser arenas, byte offsets, or legacy checker IDs.
#[derive(Clone, Copy, Debug, Eq, Hash, Ord, PartialEq, PartialOrd, Serialize)]
pub enum KernelDeclarationOrigin {
    Statement {
        statement: KernelStatementId,
    },
    Parameter {
        statement: KernelStatementId,
        ordinal: u32,
    },
    RecordField {
        object: KernelExpressionId,
        ordinal: u32,
    },
    PatternBinding {
        arm: KernelExpressionId,
        ordinal: u32,
    },
    CallbackBinding {
        call: KernelExpressionId,
        ordinal: u32,
    },
    /// ABI-supplied declaration that exists only while evaluating one call.
    ///
    /// This is ordinary callable metadata, not a language-level UI concept.
    /// Different ABIs may publish different context declarations or none.
    CallContext {
        call: KernelExpressionId,
        ordinal: u32,
    },
}

#[derive(Clone, Copy, Debug, Eq, Hash, Ord, PartialEq, PartialOrd, Serialize)]
pub enum KernelDeclarationKind {
    Function,
    ValueParameter,
    OutParameter,
    Field,
    Source,
    Hold,
    List,
    PatternBinding,
    FreshOut,
    ElementState,
}

#[derive(Clone, Debug, Eq, Hash, PartialEq, Serialize)]
pub struct KernelDeclarationInput {
    pub id: KernelDeclarationId,
    pub origin: KernelDeclarationOrigin,
    pub name: Box<str>,
    pub kind: KernelDeclarationKind,
    pub value: Option<KernelExpressionId>,
    /// Exact ABI-declared type when the declaration has no value/formal
    /// equation from which the checked linker can derive one.
    pub declared_flow_type: Option<FlowType>,
}

#[derive(Clone, Copy, Debug, Eq, Hash, PartialEq, Serialize)]
pub enum KernelDeclarationReference {
    Local(KernelDeclarationId),
    /// The unique public declaration exported by another dense definition.
    OwnerPublic(KernelOwnerId),
    /// One exact non-public declaration owned by another dense definition.
    ///
    /// This is required when owner partitioning places a value expression in
    /// a child definition while its lexical pattern/callback declaration
    /// remains in the enclosing definition. The pair is definition-local and
    /// relocates directly; it is never a path or name lookup.
    OwnerDeclaration {
        owner: KernelOwnerId,
        declaration: KernelDeclarationId,
    },
}

#[derive(Clone, Copy, Debug, Eq, Hash, PartialEq, Serialize)]
pub enum KernelStatementReference {
    Local(KernelStatementId),
    /// The public/root statement exported by another dense definition.
    OwnerPublic(KernelOwnerId),
}

#[derive(Clone, Copy, Debug, Eq, Hash, PartialEq, Serialize)]
pub enum KernelLexicalBindingTargetInput {
    Declaration(KernelDeclarationReference),
    ContextFormal {
        ordinal: u32,
    },
    /// A definition-local or external value authority without an authored
    /// declaration (for example a contextual callback item).
    Value {
        provider: KernelExpressionId,
    },
    RuntimeContext,
}

#[derive(Clone, Copy, Debug, Eq, Hash, PartialEq, Serialize)]
pub enum KernelLexicalAccess {
    Read,
    Drain,
}

/// One occurrence-to-authority lexical equation.
