#[derive(Clone, Debug)]
struct KernelProjectOwnerOutputs {
    result: OutputId,
    formals: Box<[OutputId]>,
    formal_modes: Box<[FlowMode]>,
    expressions: Box<[OutputId]>,
    expression_modes: Box<[FlowMode]>,
    calls: Box<[KernelProjectCallSolve]>,
    /// Formals whose public type is an aggregate of branch-local projection
    /// requirements. That aggregate is useful to the solver, but is not a
    /// sound direct assignability contract for call diagnostics.
    syntax_discriminated_formals: Box<[u32]>,
    basis_fingerprint_v14: [u8; 32],
}

/// Allocation-free structural access to one compiled definition.
///
/// Owned solve products keep only dense solver coordinates. Immutable syntax
/// and linker facts remain in their project-level authorities and are borrowed
/// for the duration of each projection pass; no reference is stored in an
/// owned snapshot.
#[derive(Clone, Copy)]
struct KernelDefinitionInputRef<'a> {
    owner: KernelOwnerId,
    input: PackedKernelOwnerProgramRef<'a>,
    facts: &'a KernelDefinitionFactsInput,
    outputs: &'a KernelProjectOwnerOutputs,
}

struct KernelProjectDefinitionRefs<'a> {
    program: &'a PackedKernelProjectProgram,
    facts: &'a [KernelDefinitionFactsInput],
    outputs: &'a [KernelProjectOwnerOutputs],
}

impl<'a> KernelProjectDefinitionRefs<'a> {
    fn new(
        program: &'a PackedKernelProjectProgram,
        facts: &'a [KernelDefinitionFactsInput],
        outputs: &'a [KernelProjectOwnerOutputs],
    ) -> Result<Self, KernelSolveError> {
        if program.definition_count() != facts.len() || facts.len() != outputs.len() {
            return Err(KernelSolveError::new(format!(
                "kernel definition authorities have {} program, {} fact, and {} solve rows",
                program.definition_count(),
                facts.len(),
                outputs.len(),
            )));
        }
        Ok(Self {
            program,
            facts,
            outputs,
        })
    }

    fn definitions(&self) -> impl ExactSizeIterator<Item = KernelDefinitionInputRef<'a>> + '_ {
        self.program
            .owners()
            .zip(self.facts)
            .zip(self.outputs)
            .enumerate()
            .map(
                |(index, ((input, facts), outputs))| KernelDefinitionInputRef {
                    owner: KernelOwnerId(
                        u32::try_from(index).expect("kernel definition count exceeds u32"),
                    ),
                    input,
                    facts,
                    outputs,
                },
            )
    }
}

impl<'a> KernelDefinitionInputRef<'a> {
    fn resolve_value(
        self,
        encoded: KernelExpressionId,
        consumer: usize,
    ) -> Result<KernelValueReference, KernelOwnerBuildError> {
        packed_kernel_value_reference(self.input, encoded, consumer)
    }

    fn call(self, ordinal: usize) -> Option<KernelProjectCallRef<'a>> {
        let solve = self.outputs.calls.get(ordinal)?;
        let node = self.input.node(solve.expression)?;
        Some(KernelProjectCallRef {
            definition: self,
            solve,
            node,
        })
    }

    fn calls(self) -> impl ExactSizeIterator<Item = KernelProjectCallRef<'a>> + 'a {
        (0..self.outputs.calls.len()).map(move |ordinal| {
            self.call(ordinal)
                .expect("validated call sidecar remains aligned with the owner program")
        })
    }
}

/// Borrowed production view over one definition's immutable authored facts
/// and its single packed solve authority.
///
/// The view contains no owned strings, vectors, or recursive types and cannot
/// outlive the checked snapshot from which it was obtained.
#[derive(Clone, Copy)]
pub struct KernelDefinitionRef<'a> {
    owner: KernelOwnerId,
    input: PackedKernelOwnerProgramRef<'a>,
    facts: Option<&'a KernelDefinitionFactsInput>,
    code: crate::DefinitionCodeRef<'a>,
}

pub struct KernelDefinitionIter<'a> {
    snapshot: &'a KernelCheckedSnapshot,
    next: usize,
}

#[derive(Clone, Copy)]
pub struct KernelDefinitionCallRef<'a> {
    definition: KernelDefinitionRef<'a>,
    expression: KernelExpressionId,
    node: &'a PackedKernelOwnerNode,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum KernelStatePathRef<'a> {
    Authored(crate::PackedKernelPathRef<'a>),
    Synthetic(u32),
}

#[derive(Clone, Copy, Debug, Eq, Hash, PartialEq)]
pub enum KernelLexicalBindingTargetRef {
    Declaration(KernelDeclarationReference),
    ContextFormal { ordinal: u32 },
    Value { provider: KernelValueReference },
    RuntimeContext,
}

#[derive(Clone, Copy)]
pub struct KernelPublishedStateRef<'a> {
    definition: KernelDefinitionRef<'a>,
    id: KernelStateId,
    input: &'a crate::PackedState,
    synthetic_ordinal: Option<u32>,
}

pub struct KernelPublishedStateIter<'a> {
    definition: KernelDefinitionRef<'a>,
    rows: std::slice::Iter<'a, PackedPublishedState>,
    next_id: u32,
}

impl<'a> Iterator for KernelDefinitionIter<'a> {
    type Item = KernelDefinitionRef<'a>;

    fn next(&mut self) -> Option<Self::Item> {
        let owner = KernelOwnerId(u32::try_from(self.next).ok()?);
        let definition = self.snapshot.definition(owner)?;
        self.next += 1;
        Some(definition)
    }

    fn size_hint(&self) -> (usize, Option<usize>) {
        let remaining = self.snapshot.definition_count().saturating_sub(self.next);
        (remaining, Some(remaining))
    }
}

impl ExactSizeIterator for KernelDefinitionIter<'_> {}

impl<'a> Iterator for KernelPublishedStateIter<'a> {
    type Item = KernelPublishedStateRef<'a>;

    fn next(&mut self) -> Option<Self::Item> {
        let row = *self.rows.next()?;
        let id = KernelStateId(self.next_id);
        self.next_id = self
            .next_id
            .checked_add(1)
            .expect("sealed kernel state namespace exceeds u32");
        Some(KernelPublishedStateRef {
            definition: self.definition,
            id,
            input: self
                .definition
                .runtime_facts()
                .states()
                .get(row.input_ordinal as usize)
                .expect("sealed published-state coordinate is inside packed definition facts"),
            synthetic_ordinal: row.synthetic_ordinal(),
        })
    }

    fn size_hint(&self) -> (usize, Option<usize>) {
        self.rows.size_hint()
    }
}

impl ExactSizeIterator for KernelPublishedStateIter<'_> {}

impl<'a> KernelDefinitionRef<'a> {
    pub(crate) fn from_authorities(
        program: &'a PackedKernelProjectProgram,
        code: &'a DefinitionCodeStore,
        owner: KernelOwnerId,
    ) -> Option<Self> {
        let index = owner.0 as usize;
        Some(Self {
            owner,
            input: program.owner_at(index)?,
            facts: None,
            code: code.definition(owner)?,
        })
    }

    pub(crate) fn from_rich_authorities(
        program: &'a PackedKernelProjectProgram,
        facts: &'a [KernelDefinitionFactsInput],
        code: &'a DefinitionCodeStore,
        owner: KernelOwnerId,
    ) -> Option<Self> {
        let mut definition = Self::from_authorities(program, code, owner)?;
        definition.facts = Some(facts.get(owner.0 as usize)?);
        Some(definition)
    }

    pub const fn owner(self) -> KernelOwnerId {
        self.owner
    }

    pub const fn input(self) -> PackedKernelOwnerProgramRef<'a> {
        self.input
    }

    pub const fn facts(self) -> &'a KernelDefinitionFactsInput {
        self.facts.expect(
            "rich definition facts are available only during compatibility receipt construction",
        )
    }

    pub(crate) fn runtime_facts(self) -> crate::PackedDefinitionFactsRef<'a> {
        self.code.runtime_facts()
    }

    pub const fn code(self) -> crate::DefinitionCodeRef<'a> {
        self.code
    }

    pub fn linkage(self) -> KernelDefinitionLinkage {
        self.code.runtime_facts().linkage()
    }

    pub fn resolve_value(
        self,
        encoded: KernelExpressionId,
        consumer: usize,
    ) -> Result<KernelValueReference, KernelOwnerBuildError> {
        packed_kernel_value_reference(self.input, encoded, consumer)
    }

    pub fn resolve_structural_declaration(
        self,
        declaration: KernelStructuralDeclarationInput,
        value: KernelExpressionId,
        consumer: usize,
    ) -> Result<KernelDeclarationReference, KernelOwnerBuildError> {
        link_packed_structural_declaration(self.input, declaration, value, consumer)
    }

    pub fn resolve_lexical_target(
        self,
        binding: &'a KernelLexicalBindingInput,
    ) -> Result<KernelLexicalBindingTargetRef, KernelOwnerBuildError> {
        Ok(match binding.target {
            KernelLexicalBindingTargetInput::Declaration(declaration) => {
                KernelLexicalBindingTargetRef::Declaration(declaration)
            }
            KernelLexicalBindingTargetInput::ContextFormal { ordinal } => {
                KernelLexicalBindingTargetRef::ContextFormal { ordinal }
            }
            KernelLexicalBindingTargetInput::Value { provider } => {
                KernelLexicalBindingTargetRef::Value {
                    provider: self.resolve_value(provider, binding.expression.0 as usize)?,
                }
            }
            KernelLexicalBindingTargetInput::RuntimeContext => {
                KernelLexicalBindingTargetRef::RuntimeContext
            }
        })
    }

    pub fn expression_effect(self, expression: KernelExpressionId) -> Option<KernelEffectSummary> {
        let node = self.input.node(expression)?;
        match &node.kind {
            PackedKernelOwnerNodeKind::UserCall { target, .. } => {
                self.code.effect_summary_for(*target)
            }
            _ => Some(local_packed_expression_effect(&node.kind)),
        }
    }

    pub fn expression_kind(
        self,
        expression: KernelExpressionId,
    ) -> Option<KernelExpressionKindRef<'a>> {
        self.input
            .node(expression)
            .and_then(|node| KernelExpressionKindRef::from_packed(self.input, &node.kind))
    }

    pub fn call_count(self) -> usize {
        self.code.call_count()
    }

    pub fn call(self, ordinal: usize) -> Option<KernelDefinitionCallRef<'a>> {
        let expression = self.code.call_expression(ordinal)?;
        Some(KernelDefinitionCallRef {
            definition: self,
            expression,
            node: self.input.node(expression)?,
        })
    }

    pub fn state_count(self) -> usize {
        self.code.state_count()
    }

    pub fn states(self) -> KernelPublishedStateIter<'a> {
        KernelPublishedStateIter {
            definition: self,
            rows: self.code.states().iter(),
            next_id: 0,
        }
    }

    pub fn materialize_host_effects(
        self,
    ) -> Result<Box<[KernelHostEffectArtifact]>, KernelOwnerBuildError> {
        collect_packed_host_effect_artifacts(self.input)
    }
}

impl<'a> KernelDefinitionCallRef<'a> {
    pub const fn expression(self) -> KernelExpressionId {
        self.expression
    }

    pub const fn node(self) -> &'a PackedKernelOwnerNode {
        self.node
    }

    pub fn target(self) -> KernelCallTargetRef<'a> {
        kernel_call_target_ref(self.definition.input, &self.node.kind)
            .expect("sealed packed call coordinate points to a call node")
    }

    pub fn inputs(self) -> &'a [crate::PackedKernelOwnerInputEdge] {
        self.node.inputs(self.definition.input)
    }

    pub fn input_value(
        self,
        edge: &crate::PackedKernelOwnerInputEdge,
    ) -> Result<KernelValueReference, KernelOwnerBuildError> {
        self.definition
            .resolve_value(edge.expression, self.expression.0 as usize)
    }

    pub fn input_role(
        self,
        edge: &'a crate::PackedKernelOwnerInputEdge,
    ) -> Result<KernelCallInputRoleRef<'a>, KernelOwnerBuildError> {
        kernel_call_input_role_ref(
            self.definition.input,
            &self.node.kind,
            &edge.role,
            self.expression,
        )
    }
}

impl<'a> KernelPublishedStateRef<'a> {
    pub const fn id(self) -> KernelStateId {
        self.id
    }

    pub const fn binding_declaration(self) -> KernelDeclarationReference {
        self.input.binding_declaration
    }

    pub const fn declaration(self) -> KernelDeclarationReference {
        self.input.declaration
    }

    pub const fn statement(self) -> KernelStatementReference {
        self.input.statement
    }

    pub const fn expression(self) -> KernelExpressionId {
        self.input.expression
    }

    pub const fn kind(self) -> CheckedStateKind {
        self.input.kind
    }

    pub fn path(self) -> KernelStatePathRef<'a> {
        match self.synthetic_ordinal {
            Some(ordinal) => KernelStatePathRef::Synthetic(ordinal),
            None => KernelStatePathRef::Authored(
                self.definition
                    .input()
                    .path(self.input.projection)
                    .expect("sealed state path belongs to its text authority"),
            ),
        }
    }

    pub fn initial(self) -> Result<KernelValueReference, KernelOwnerBuildError> {
        self.definition
            .resolve_value(self.input.initial, self.input.expression.0 as usize)
    }
}

