/// Former type-free structural publication retained only as a differential
/// oracle. Production checked snapshots borrow the program/fact/code
/// authorities directly and never construct this graph.
#[cfg(test)]
#[derive(Clone, Debug, Eq, PartialEq, Serialize)]
pub struct DefinitionArtifact {
    pub linkage: KernelDefinitionLinkage,
    pub call_syntax: Box<[KernelCallSyntaxArtifact]>,
    pub execution_shapes: Box<[KernelExecutionShapeArtifact]>,
    pub expressions: Box<[KernelExpressionArtifact]>,
    pub statements: Box<[KernelStatementArtifact]>,
    pub declarations: Box<[KernelDeclarationArtifact]>,
    pub lexical_bindings: Box<[KernelLexicalBindingArtifact]>,
    pub calls: Box<[KernelCallArtifact]>,
    pub effects: Box<[KernelHostEffectArtifact]>,
    pub sources: Box<[KernelSourceArtifact]>,
    pub states: Box<[KernelStateArtifact]>,
    pub lists: Box<[KernelListArtifact]>,
}

/// Immutable checked result surface for one definition.
///
/// This is deliberately free of solver cells, operation IDs, and work
/// counters. Later checked rows (calls, effects, state, lists, diagnostics)
/// extend this single artifact instead of creating parallel owner products.
#[derive(Clone, Debug, Eq, PartialEq, Serialize)]
pub struct RichDefinitionArtifact {
    pub result: FlowType,
    /// Principal callable formal surfaces in dense declaration order. This is
    /// empty for non-callable definitions.
    pub formals: Box<[FlowType]>,
    pub linkage: KernelDefinitionLinkage,
    /// Exact stable source identities retained for direct checked/semantic
    /// linking. Dense IDs remain definition-local and revision-local.
    pub relocations: KernelDefinitionRelocations,
    /// Compact lexical scopes, source spans, and row ownership required by the
    /// direct checked-image materializer.
    pub presentation: KernelDefinitionPresentation,
    pub expression_payloads: Box<[KernelExpressionSemanticPayload]>,
    pub call_syntax: Box<[KernelCallSyntaxArtifact]>,
    pub execution_shapes: Box<[KernelExecutionShapeArtifact]>,
    pub expressions: Box<[RichKernelExpressionArtifact]>,
    pub statements: Box<[KernelStatementArtifact]>,
    pub declarations: Box<[RichKernelDeclarationArtifact]>,
    pub lexical_bindings: Box<[KernelLexicalBindingArtifact]>,
    pub calls: Box<[RichKernelCallArtifact]>,
    pub effects: Box<[KernelHostEffectArtifact]>,
    pub sources: Box<[RichKernelSourceArtifact]>,
    pub states: Box<[RichKernelStateArtifact]>,
    pub lists: Box<[RichKernelListArtifact]>,
    pub diagnostics: Box<[KernelDiagnosticArtifact]>,
}

impl Hash for RichDefinitionArtifact {
    fn hash<H: Hasher>(&self, state: &mut H) {
        // Preserve the exact V16 rich-artifact byte contract while the solved
        // term DAG is a derived sidecar. The semantic V5 cut gives the term
        // digest its own explicit proof/currentness domain instead of silently
        // changing an existing contract through `derive(Hash)`.
        self.result.hash(state);
        self.formals.hash(state);
        self.linkage.hash(state);
        self.relocations.hash(state);
        self.presentation.hash(state);
        self.expression_payloads.hash(state);
        self.call_syntax.hash(state);
        self.execution_shapes.hash(state);
        self.expressions.hash(state);
        self.statements.hash(state);
        self.declarations.hash(state);
        self.lexical_bindings.hash(state);
        self.calls.hash(state);
        self.effects.hash(state);
        self.sources.hash(state);
        self.states.hash(state);
        self.lists.hash(state);
        self.diagnostics.hash(state);
    }
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub struct KernelDefinitionSnapshot {
    pub definition: RichDefinitionArtifact,
    pub type_store: Arc<FrozenTypeStore>,
    pub dependencies: crate::KernelDefinitionDependencyGraph,
    pub currentness: crate::KernelDefinitionCurrentnessReceipt,
    pub work: KernelSolveWork,
}

/// Immutable checked snapshot produced by one complete dense solve.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct KernelCheckedSnapshot {
    #[cfg(test)]
    pub(crate) definitions: Box<[DefinitionArtifact]>,
    /// Shared normalized owner program retained once for borrowed structural
    /// views. Published definition rows remain a compatibility product until
    /// their downstream consumers are moved onto this authority.
    pub(crate) program: Arc<PackedKernelProjectProgram>,
    /// Test-only compatibility oracle. Production snapshots retain the packed
    /// fact authority in `definition_code` and no recursive rich graph.
    #[cfg(test)]
    pub(crate) definition_facts: Arc<[KernelDefinitionFactsInput]>,
    /// One packed, store-qualified authority for all solver-owned definition
    /// flow roots. The checked linker consumes this directly; rich artifacts
    /// no longer retain one boxed flow sidecar per definition.
    pub(crate) definition_code: Arc<DefinitionCodeStore>,
    /// Packed public callable interfaces and typed diagnostic roots. Rich
    /// checked types are materialized only at explicit compatibility and
    /// presentation boundaries.
    pub(crate) interface: Arc<KernelInterfaceSnapshot>,
    pub dependencies: crate::KernelDefinitionDependencyGraph,
    pub currentness: Box<[crate::KernelPackedDefinitionCurrentnessReceipt]>,
    pub work: KernelSolveWork,
}

impl KernelCheckedSnapshot {
    pub fn definition_count(&self) -> usize {
        self.definition_code.definition_count()
    }

    pub fn definition(&self, owner: KernelOwnerId) -> Option<KernelDefinitionRef<'_>> {
        KernelDefinitionRef::from_authorities(&self.program, &self.definition_code, owner)
    }

    pub fn definition_refs(&self) -> KernelDefinitionIter<'_> {
        KernelDefinitionIter {
            snapshot: self,
            next: 0,
        }
    }

    pub fn interface(&self) -> &KernelInterfaceSnapshot {
        &self.interface
    }

    pub fn type_store(&self) -> &Arc<FrozenTypeStore> {
        self.definition_code.type_store()
    }

    pub fn definition_code(&self) -> &Arc<DefinitionCodeStore> {
        &self.definition_code
    }

    pub fn dependencies(&self) -> &crate::KernelDefinitionDependencyGraph {
        &self.dependencies
    }

    pub fn currentness(&self) -> &[crate::KernelPackedDefinitionCurrentnessReceipt] {
        &self.currentness
    }

    pub const fn work(&self) -> KernelSolveWork {
        self.work
    }

    pub fn materialize_result_flow(&self, owner: KernelOwnerId) -> Option<FlowType> {
        self.interface.materialize_result_flow(owner)
    }

    pub fn materialize_formal_flows(&self, owner: KernelOwnerId) -> Option<Box<[FlowType]>> {
        self.interface.materialize_formal_flows(owner)
    }

    pub fn expression_flow(
        &self,
        owner: KernelOwnerId,
        expression: KernelExpressionId,
    ) -> Option<FlowType> {
        self.definition_code
            .definition(owner)?
            .materialize_published_expression(expression.0 as usize)
    }

    pub fn call_facts(
        &self,
        owner: KernelOwnerId,
        ordinal: usize,
    ) -> Option<crate::MaterializedCallFacts> {
        self.definition_code
            .definition(owner)?
            .materialize_call_facts(ordinal)
    }

    pub fn diagnostics_for(&self, owner: KernelOwnerId) -> Option<Box<[KernelDiagnosticArtifact]>> {
        self.interface.diagnostics_for(owner)
    }
}

/// The complete public type surface needed by diagnostics and link planning.
///
/// This deliberately contains no expression, statement, resource, dependency,
/// or currentness rows. A diagnostics-only request must be able to stop here
/// without paying to construct and fingerprint a checked image.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub(crate) struct PackedInterfaceSpan {
    pub(crate) start: u32,
    pub(crate) len: u32,
}

impl PackedInterfaceSpan {
    pub(crate) fn range(self) -> std::ops::Range<usize> {
        self.start as usize..self.start as usize + self.len as usize
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub(crate) struct PackedInterfaceDefinition {
    pub(crate) result: PackedFlow,
    pub(crate) formals: PackedInterfaceSpan,
    pub(crate) diagnostics: PackedInterfaceSpan,
    pub(crate) diagnostic_values: PackedInterfaceSpan,
    pub(crate) alpha_variables: PackedInterfaceSpan,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub(crate) struct PackedDiagnosticValue {
    pub(crate) value: KernelValueReference,
    pub(crate) term: TypeTermId,
}

/// Definition-scoped borrowed view of one packed interface type.
///
/// The definition scope is part of the reference because raw type-variable
/// ordinals are never project-global. Structural policy checks can borrow this
/// view without allocating; explicit compatibility callers can materialize it
/// with the same alpha mapping as the interface publication.
#[derive(Clone, Copy)]
pub struct KernelInterfaceTypeRef<'a> {
    interface: &'a KernelInterfaceSnapshot,
    definition: &'a PackedInterfaceDefinition,
    term: TypeTermId,
}

impl KernelInterfaceTypeRef<'_> {
    pub fn materialize_checked(self) -> Type {
        self.interface.materialize_type(self.definition, self.term)
    }

    fn with_term(self, term: TypeTermId) -> Self {
        Self { term, ..self }
    }
}

impl boon_checked::CheckedTypeView for KernelInterfaceTypeRef<'_> {
    fn list_item(self) -> Option<Self> {
        match self.interface.types.as_arena().term(self.term) {
            TypeTerm::List(item) => Some(self.with_term(item)),
            _ => None,
        }
    }

    fn is_text(self) -> bool {
        matches!(
            self.interface.types.as_arena().term(self.term),
            TypeTerm::Text
        )
    }

    fn is_number(self) -> bool {
        matches!(
            self.interface.types.as_arena().term(self.term),
            TypeTerm::Number
        )
    }

    fn is_render_contract(self) -> bool {
        matches!(
            self.interface.types.as_arena().term(self.term),
            TypeTerm::RenderContract
        )
    }

    fn object_field(self, name: &str) -> Option<Self> {
        let TypeTerm::Object { fields, .. } = self.interface.types.as_arena().term(self.term)
        else {
            return None;
        };
        fields
            .canonical_iter()
            .find(|field| self.interface.types.as_arena().name(field.name) == name)
            .map(|field| self.with_term(field.ty))
    }

    fn all_variants_are_bare_tags(self, mut predicate: impl FnMut(&str) -> bool) -> bool {
        let TypeTerm::VariantSet(variants) = self.interface.types.as_arena().term(self.term) else {
            return false;
        };
        variants.iter().all(|variant| match variant {
            VariantTerm::Tag(tag) => predicate(self.interface.types.as_arena().name(*tag)),
            VariantTerm::Tagged { .. } => false,
        })
    }
}

