#[derive(Clone, Debug, Eq, PartialEq)]
pub struct KernelInterfaceSnapshot {
    pub(crate) types: Arc<FrozenTypeStore>,
    pub(crate) definitions: Box<[PackedInterfaceDefinition]>,
    pub(crate) flows: Box<[PackedFlow]>,
    pub(crate) diagnostics: Box<[PackedDiagnosticMetadata]>,
    pub(crate) diagnostic_types: Box<[Option<PackedDiagnosticTypes>]>,
    pub(crate) diagnostic_values: Box<[PackedDiagnosticValue]>,
    pub(crate) alpha_variables: Box<[TypeVariableId]>,
    pub work: KernelSolveWork,
}

impl KernelInterfaceSnapshot {
    pub fn definition_count(&self) -> usize {
        self.definitions.len()
    }

    pub fn diagnostic_count(&self) -> usize {
        self.diagnostics.len()
    }

    pub fn diagnostic_value_count(&self) -> usize {
        self.diagnostic_values.len()
    }

    pub fn diagnostic_refs(&self) -> impl Iterator<Item = KernelInterfaceDiagnosticRef<'_>> + '_ {
        self.definitions.iter().flat_map(move |definition| {
            definition.diagnostics.range().map(move |ordinal| {
                let kind = match &self.diagnostics[ordinal] {
                    PackedDiagnosticMetadata::Plain(diagnostic) => {
                        debug_assert!(!matches!(
                            diagnostic.kind,
                            KernelDiagnosticKind::CallInputType { .. }
                        ));
                        KernelInterfaceDiagnosticKindRef::Plain(&diagnostic.kind)
                    }
                    PackedDiagnosticMetadata::CallInputType { mismatch, .. } => {
                        let types = self.diagnostic_types[ordinal].expect(
                            "packed call-input diagnostic retains actual and expected roots",
                        );
                        KernelInterfaceDiagnosticKindRef::CallInputType {
                            actual: KernelInterfaceTypeRef {
                                interface: self,
                                definition,
                                term: types.actual,
                            },
                            expected: KernelInterfaceTypeRef {
                                interface: self,
                                definition,
                                term: types.expected,
                            },
                            mismatch,
                        }
                    }
                };
                let metadata = &self.diagnostics[ordinal];
                let (owner, severity, site) = match metadata {
                    PackedDiagnosticMetadata::Plain(diagnostic) => {
                        (diagnostic.owner, diagnostic.severity, &diagnostic.site)
                    }
                    PackedDiagnosticMetadata::CallInputType {
                        owner,
                        severity,
                        site,
                        ..
                    } => (*owner, *severity, site),
                };
                KernelInterfaceDiagnosticRef {
                    owner,
                    severity,
                    site,
                    kind,
                }
            })
        })
    }

    pub fn diagnostic_value_refs(
        &self,
    ) -> impl Iterator<Item = KernelInterfaceDiagnosticValueRef<'_>> + '_ {
        self.definitions
            .iter()
            .enumerate()
            .flat_map(move |(owner, definition)| {
                self.diagnostic_values[definition.diagnostic_values.range()]
                    .iter()
                    .copied()
                    .enumerate()
                    .map(move |(ordinal, value)| KernelInterfaceDiagnosticValueRef {
                        owner: KernelOwnerId(owner as u32),
                        ordinal: ordinal as u32,
                        value: value.value,
                        ty: KernelInterfaceTypeRef {
                            interface: self,
                            definition,
                            term: value.term,
                        },
                    })
            })
    }

    pub fn materialize_result_flow(&self, owner: KernelOwnerId) -> Option<FlowType> {
        let definition = self.definitions.get(owner.0 as usize)?;
        Some(self.materialize_flow(definition, definition.result))
    }

    pub fn materialize_formal_flows(&self, owner: KernelOwnerId) -> Option<Box<[FlowType]>> {
        let definition = self.definitions.get(owner.0 as usize)?;
        Some(
            self.flows[definition.formals.range()]
                .iter()
                .copied()
                .map(|flow| self.materialize_flow(definition, flow))
                .collect::<Vec<_>>()
                .into_boxed_slice(),
        )
    }

    pub fn materialize_public_results(&self) -> impl ExactSizeIterator<Item = FlowType> + '_ {
        self.definitions
            .iter()
            .map(|definition| self.materialize_flow(definition, definition.result))
    }

    #[cfg(test)]
    pub fn materialize_diagnostics(&self) -> Box<[KernelDiagnosticArtifact]> {
        let mut materialized = Vec::with_capacity(self.diagnostics.len());
        for definition in &self.definitions {
            for ordinal in definition.diagnostics.range() {
                let metadata = &self.diagnostics[ordinal];
                let diagnostic = match metadata {
                    PackedDiagnosticMetadata::Plain(diagnostic) => diagnostic.clone(),
                    PackedDiagnosticMetadata::CallInputType {
                        owner,
                        severity,
                        site,
                        mismatch,
                    } => {
                        let types = self.diagnostic_types[ordinal].expect(
                            "packed call-input diagnostic retains actual and expected roots",
                        );
                        KernelDiagnosticArtifact {
                            owner: *owner,
                            severity: *severity,
                            site: site.clone(),
                            kind: KernelDiagnosticKind::CallInputType {
                                actual: self.materialize_type(definition, types.actual),
                                expected: self.materialize_type(definition, types.expected),
                                mismatch: mismatch.clone(),
                            },
                        }
                    }
                };
                materialized.push(diagnostic);
            }
        }
        materialized.into_boxed_slice()
    }

    pub fn diagnostics_for(&self, owner: KernelOwnerId) -> Option<Box<[KernelDiagnosticArtifact]>> {
        let definition = self.definitions.get(owner.0 as usize)?;
        let mut materialized = Vec::with_capacity(definition.diagnostics.len as usize);
        for ordinal in definition.diagnostics.range() {
            let metadata = &self.diagnostics[ordinal];
            materialized.push(match metadata {
                PackedDiagnosticMetadata::Plain(diagnostic) => diagnostic.clone(),
                PackedDiagnosticMetadata::CallInputType {
                    owner,
                    severity,
                    site,
                    mismatch,
                } => {
                    let types = self.diagnostic_types[ordinal]
                        .expect("packed call-input diagnostic retains actual and expected roots");
                    KernelDiagnosticArtifact {
                        owner: *owner,
                        severity: *severity,
                        site: site.clone(),
                        kind: KernelDiagnosticKind::CallInputType {
                            actual: self.materialize_type(definition, types.actual),
                            expected: self.materialize_type(definition, types.expected),
                            mismatch: mismatch.clone(),
                        },
                    }
                }
            });
        }
        Some(materialized.into_boxed_slice())
    }

    #[cfg(test)]
    pub fn materialize_diagnostic_values(&self) -> Box<[KernelDiagnosticValueArtifact]> {
        let mut materialized = Vec::with_capacity(self.diagnostic_values.len());
        for (owner, definition) in self.definitions.iter().enumerate() {
            for (ordinal, value) in self.diagnostic_values[definition.diagnostic_values.range()]
                .iter()
                .copied()
                .enumerate()
            {
                materialized.push(KernelDiagnosticValueArtifact {
                    owner: KernelOwnerId(owner as u32),
                    ordinal: ordinal as u32,
                    value: value.value,
                    ty: self.materialize_type(definition, value.term),
                });
            }
        }
        materialized.into_boxed_slice()
    }

    fn materialize_flow(
        &self,
        definition: &PackedInterfaceDefinition,
        flow: PackedFlow,
    ) -> FlowType {
        FlowType {
            mode: flow.mode,
            ty: self.materialize_type(definition, flow.term),
        }
    }

    fn materialize_type(&self, definition: &PackedInterfaceDefinition, term: TypeTermId) -> Type {
        let sources = &self.alpha_variables[definition.alpha_variables.range()];
        let mut variables = sources
            .iter()
            .copied()
            .enumerate()
            .map(|(ordinal, source)| {
                (
                    boon_checked::TypeVar(source.0),
                    boon_checked::TypeVar(ordinal as u32),
                )
            })
            .collect::<BTreeMap<_, _>>();
        let mut next = sources.len() as u32;
        let materialized = self.types.as_arena().export_checked_type(term);
        let materialized = crate::alpha_normalize_flow_type(
            &FlowType {
                mode: FlowMode::Continuous,
                ty: materialized,
            },
            &mut variables,
            &mut next,
        )
        .ty;
        assert_eq!(
            next,
            sources.len() as u32,
            "packed interface alpha scope omitted a reached variable"
        );
        materialized
    }
}

#[cfg(test)]
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct KernelDiagnosticValueArtifact {
    pub owner: KernelOwnerId,
    pub ordinal: u32,
    pub value: KernelValueReference,
    pub ty: Type,
}

/// Sparse borrowed-definition product for explicit definition demand.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct KernelDemandedDefinitionSnapshot {
    owners: Box<[KernelOwnerId]>,
    program: Arc<PackedKernelProjectProgram>,
    definition_code: Arc<DefinitionCodeStore>,
    interface: Arc<KernelInterfaceSnapshot>,
    work: KernelSolveWork,
}

impl KernelDemandedDefinitionSnapshot {
    pub fn definition_count(&self) -> usize {
        self.owners.len()
    }

    pub fn owners(&self) -> &[KernelOwnerId] {
        &self.owners
    }

    pub fn definition(&self, owner: KernelOwnerId) -> Option<KernelDefinitionRef<'_>> {
        self.owners.binary_search(&owner).ok()?;
        KernelDefinitionRef::from_authorities(&self.program, &self.definition_code, owner)
    }

    pub fn definition_refs(
        &self,
    ) -> impl ExactSizeIterator<Item = (KernelOwnerId, KernelDefinitionRef<'_>)> + '_ {
        self.owners.iter().copied().map(|owner| {
            let definition =
                KernelDefinitionRef::from_authorities(&self.program, &self.definition_code, owner)
                    .expect("validated demanded owner remains in every shared authority");
            (owner, definition)
        })
    }

    pub fn program(&self) -> &Arc<PackedKernelProjectProgram> {
        &self.program
    }

    pub fn definition_code(&self) -> &Arc<DefinitionCodeStore> {
        &self.definition_code
    }

    pub fn type_store(&self) -> &Arc<FrozenTypeStore> {
        self.definition_code.type_store()
    }

    pub fn interface(&self) -> &Arc<KernelInterfaceSnapshot> {
        &self.interface
    }

    pub const fn work(&self) -> KernelSolveWork {
        self.work
    }

    pub(crate) fn into_selected_parts(
        self,
    ) -> (
        Box<[KernelOwnerId]>,
        Arc<DefinitionCodeStore>,
        Arc<KernelInterfaceSnapshot>,
        KernelSolveWork,
    ) {
        (self.owners, self.definition_code, self.interface, self.work)
    }
}

/// Returns whether the permanent kernel can resolve this operation entirely
/// from the lower-level host-effect ABI registry.
pub fn is_kernel_host_effect(operation: &str) -> bool {
    host_effect_policy(operation).is_some_and(|policy| {
        policy.result_policy == ResultPolicySpec::ReturnValue && policy.has_typed_schema
    })
}

/// Returns whether the stable host-effect registry owns `operation`, even
/// when its compact result policy has not migrated into this kernel yet.
pub fn is_registered_kernel_host_effect(operation: &str) -> bool {
    host_effect_policy(operation).is_some()
}

impl KernelOwnerProgram {
    pub fn solve(self) -> Result<KernelDefinitionSnapshot, KernelSolveError> {
        let basis_fingerprint_v14 = self.basis_fingerprint_v14;
        let artifact = solve_component(self.component)?;
        let mut result = artifact
            .output_flow(self.result_output)
            .expect("owner result output belongs to its component");
        let expression_flows = self
            .expression_outputs
            .iter()
            .zip(self.expression_modes.iter().copied())
            .map(|(output, mode)| {
                let mut flow = artifact
                    .output_flow(*output)
                    .expect("owner expression output belongs to its component");
                flow.mode = mode;
                flow
            })
            .collect::<Vec<_>>()
            .into_boxed_slice();
        let result_index = self
            .expression_outputs
            .iter()
            .position(|output| *output == self.result_output)
            .expect("owner result belongs to its expression outputs");
        result.mode = self.expression_modes[result_index];
        let formal_flows = self
            .formal_outputs
            .iter()
            .zip(self.formal_modes.iter().copied())
            .map(|(output, mode)| {
                let mut flow = artifact
                    .output_flow(*output)
                    .expect("owner formal output belongs to its component");
                flow.mode = mode;
                flow
            })
            .collect::<Vec<_>>()
            .into_boxed_slice();
        let calls = materialize_call_artifacts(
            KernelOwnerId(0),
            self.calls,
            &expression_flows,
            std::slice::from_ref(&formal_flows),
            std::slice::from_ref(&result),
        );
        let mut state_path_ordinals = BTreeMap::new();
        let synthetic_state_ordinals = allocate_synthetic_state_ordinals(
            KernelOwnerId(0),
            &self.resources.states,
            &self.expression_modes,
            &mut state_path_ordinals,
        );
        let (sources, states, lists) = materialize_resource_artifacts(
            self.resources,
            &expression_flows,
            None,
            &synthetic_state_ordinals,
        );
        let expressions = materialize_expression_artifacts_with_local_flushes(
            self.expression_artifacts,
            expression_flows,
            &[],
        );
        let mut definition = RichDefinitionArtifact {
            result,
            formals: formal_flows,
            linkage: self.linkage,
            relocations: self.relocations,
            presentation: self.presentation,
            expression_payloads: self.expression_payloads,
            call_syntax: self.call_syntax,
            execution_shapes: self.execution_shapes,
            expressions,
            statements: self.statements,
            declarations: self.declarations,
            lexical_bindings: self.lexical_bindings,
            calls,
            effects: self.effects,
            sources,
            states,
            lists,
            diagnostics: self.diagnostics,
        };
        let (dependencies, currentness) = build_snapshot_receipts(
            std::slice::from_mut(&mut definition),
            &[basis_fingerprint_v14],
        )?;
        let [currentness] = currentness.as_ref() else {
            unreachable!("one standalone kernel definition produces one receipt")
        };
        let type_store = artifact.type_store();
        Ok(KernelDefinitionSnapshot {
            definition,
            type_store,
            dependencies,
            currentness: *currentness,
            work: artifact.work,
        })
    }

    pub fn component(&self) -> &ComponentProgram {
        &self.component
    }
}

impl KernelProjectProgram {
    pub fn solve(self) -> Result<KernelCheckedSnapshot, KernelSolveError> {
        self.solve_graph()?.into_checked_snapshot()
    }

    /// Solve the complete project type graph but publish only its public
    /// interfaces. This is the diagnostics boundary: it performs no checked
    /// expression/resource projection, alpha-normalization of definition
    /// artifacts, dependency indexing, or currentness hashing.
    pub fn solve_interfaces(self) -> Result<KernelInterfaceSnapshot, KernelSolveError> {
        self.into_solve_session()?.solve_interfaces()
    }

    /// Publish borrowed views for only the explicitly demanded definitions.
    ///
    /// The shared type graph and packed `DefinitionCode` are finalized for the
    /// complete project because cross-owner equations and one code/type store
    /// form a single authority. This demand only selects views; it constructs
    /// no rich compatibility artifacts and seals no dependency receipts.
    pub fn solve_definitions(
        self,
        demanded: &[KernelOwnerId],
    ) -> Result<KernelDemandedDefinitionSnapshot, KernelSolveError> {
        self.solve_graph()?.into_demanded_definitions(demanded)
    }

    /// Solve all type equations once without publishing any optional checked
    /// product. `KernelSession` retains this quiescent graph across multiple
    /// demands in the same revision.
    pub fn solve_graph(self) -> Result<KernelSolvedProject, KernelSolveError> {
        self.into_solve_session()?.finish_graph()
    }

    pub(crate) fn into_solve_session(self) -> Result<KernelProjectSolveSession, KernelSolveError> {
        Ok(KernelProjectSolveSession {
            component: ComponentSolveSession::new(self.component)?,
            program: self.program,
            owners: self.owners,
            definition_facts: self.definition_facts,
            runtime_facts: self.runtime_facts,
            abi: self.abi,
            compile_work: self.compile_work,
        })
    }

    pub fn component(&self) -> &ComponentProgram {
        &self.component
    }

    pub const fn compile_work(&self) -> KernelCompileWork {
        self.compile_work
    }
}

impl KernelProjectSolveSession {
    pub(crate) const fn compile_work(&self) -> KernelCompileWork {
        self.compile_work
    }

    pub(crate) fn solve_interfaces(&mut self) -> Result<KernelInterfaceSnapshot, KernelSolveError> {
        let demand = interface_output_demand(&self.program, &self.definition_facts, &self.owners);
        let mut artifact = self.component.solve_outputs(&demand)?;
        let public_results = project_public_results(&self.owners, &artifact);
        let public_formals = project_public_formals(&self.owners, &artifact);
        let call_projection = project_call_facts_and_diagnostics(
            &self.program,
            &self.definition_facts,
            &self.owners,
            &self.abi,
            &mut artifact,
            &public_results,
            &public_formals,
            false,
        )?;
        let diagnostics = call_projection.diagnostics;
        let interface = project_interface_snapshot(
            &self.program,
            &self.definition_facts,
            &self.owners,
            &artifact,
            &public_results,
            &public_formals,
            &diagnostics,
        )?;
        Ok(interface.finish_reachable(artifact.terms()))
    }

    pub(crate) fn finish_graph(self) -> Result<KernelSolvedProject, KernelSolveError> {
        let trace = std::env::var_os("BOON_KERNEL_TRACE").is_some();
        let solve_started = Instant::now();
        let mut artifact = self.component.solve_all_unsealed()?;
        let solve_us = solve_started.elapsed().as_micros();
        let finalize_started = Instant::now();
        let mut projected = ComponentOutputSnapshot::project_unsealed(&mut artifact);
        let public_results = project_public_results(&self.owners, &projected);
        let public_formals = project_public_formals(&self.owners, &projected);
        let call_projection = project_call_facts_and_diagnostics(
            &self.program,
            &self.definition_facts,
            &self.owners,
            &self.abi,
            &mut projected,
            &public_results,
            &public_formals,
            true,
        )?;
        let SolvedProjectCallProjection {
            definitions: call_facts,
            diagnostics,
            abi_catalog,
        } = call_projection;
        let interface = project_interface_snapshot(
            &self.program,
            &self.definition_facts,
            &self.owners,
            &projected,
            &public_results,
            &public_formals,
            &diagnostics,
        )?;
        drop(projected);
        let flush_terms =
            project_expression_flush_terms(&self.program, &self.owners, &mut artifact)?;
        let resource_projection_facts = project_resource_projection_facts(
            &self.program,
            &self.owners,
            &self.definition_facts,
            &self.abi,
            &mut artifact,
        )?;
        let definition_code = build_definition_code_builder(
            &self.program,
            &self.owners,
            &self.definition_facts,
            Arc::clone(&self.runtime_facts),
            &self.abi,
            &mut artifact,
            &flush_terms,
            call_facts,
            &diagnostics,
            &resource_projection_facts,
            abi_catalog,
        )?;
        let artifact = artifact.seal();
        let types = artifact.type_store();
        let interface = Arc::new(interface.finish(Arc::clone(&types)));
        let definition_code = Arc::new(definition_code.finish(types)?);
        let receipts_started = Instant::now();
        let (dependencies, currentness) = build_borrowed_snapshot_receipts(
            &self.program,
            &self.definition_facts,
            &definition_code,
            &interface,
        )?;
        let receipts_us = receipts_started.elapsed().as_micros();
        let finalize_us = finalize_started.elapsed().as_micros();
        if trace {
            eprintln!(
                "kernel-solve-detail component_us={solve_us} packed_finalize_us={finalize_us} receipts_us={receipts_us}"
            );
        }
        let work = artifact.work;
        Ok(KernelSolvedProject {
            definition_code,
            program: self.program,
            #[cfg(test)]
            owners: self.owners,
            #[cfg(test)]
            definition_facts: self.definition_facts,
            dependencies,
            currentness,
            derived: Arc::new(KernelSolvedDerived { interface }),
            work,
        })
    }
}

impl KernelSolvedProject {
    pub fn interface_snapshot(&self) -> Arc<KernelInterfaceSnapshot> {
        Arc::clone(&self.derived.interface)
    }

    pub fn checked_snapshot(&self) -> Result<KernelCheckedSnapshot, KernelSolveError> {
        let trace = std::env::var_os("BOON_KERNEL_TRACE").is_some();
        let total_started = Instant::now();
        let definition_code = Arc::clone(&self.definition_code);
        let interface_started = Instant::now();
        let interface = Arc::clone(&self.derived.interface);
        let interface_us = interface_started.elapsed().as_micros();
        #[cfg(test)]
        let (definitions, basis_fingerprints, effects_us, preparation_us, definitions_us) = {
            let effects_started = Instant::now();
            let owner_effects =
                project_owner_effect_summaries(&self.program, &self.definition_facts);
            let effects_us = effects_started.elapsed().as_micros();
            let preparation_started = Instant::now();
            let basis_fingerprints = self
                .definition_code
                .definitions()
                .map(crate::DefinitionCodeRef::basis_fingerprint_v14)
                .collect::<Vec<_>>();
            let synthetic_state_ordinals = allocate_project_synthetic_state_ordinals(
                &self.program,
                &self.owners,
                &self.definition_facts,
            );
            let preparation_us = preparation_started.elapsed().as_micros();
            let definitions_started = Instant::now();
            let definitions = materialize_project_definition_structures(
                &self.program,
                &self.definition_facts,
                &self.owners,
                &synthetic_state_ordinals,
                &owner_effects,
                None,
            )?;
            let definitions_us = definitions_started.elapsed().as_micros();
            (
                definitions,
                basis_fingerprints,
                effects_us,
                preparation_us,
                definitions_us,
            )
        };
        #[cfg(not(test))]
        let (effects_us, preparation_us, definitions_us) = (0_u128, 0_u128, 0_u128);
        let dependencies = self.dependencies.clone();
        let currentness = self.currentness.clone();
        #[cfg(test)]
        {
            let (compatibility_dependencies, compatibility_currentness) =
                build_packed_snapshot_receipts(
                    &definitions,
                    &self.definition_facts,
                    &definition_code,
                    &interface,
                    &basis_fingerprints,
                )?;
            assert_eq!(
                dependencies, compatibility_dependencies,
                "borrowed dependency construction must exactly match the compatibility artifact",
            );
            assert_eq!(
                currentness, compatibility_currentness,
                "borrowed V17/V3/V18 receipts must exactly match the compatibility artifact",
            );
        }
        let receipts_us = 0_u128;
        if trace {
            eprintln!(
                "kernel-checked-detail interface_us={interface_us} effects_us={effects_us} preparation_us={preparation_us} definitions_us={definitions_us} receipts_us={receipts_us} total_us={}",
                total_started.elapsed().as_micros(),
            );
        }
        Ok(KernelCheckedSnapshot {
            #[cfg(test)]
            definitions,
            program: Arc::clone(&self.program),
            #[cfg(test)]
            definition_facts: Arc::clone(&self.definition_facts),
            definition_code,
            interface,
            dependencies,
            currentness,
            work: self.work,
        })
    }

    pub fn into_checked_snapshot(self) -> Result<KernelCheckedSnapshot, KernelSolveError> {
        self.checked_snapshot()
    }

    pub fn demanded_definitions(
        &self,
        demanded: &[KernelOwnerId],
    ) -> Result<KernelDemandedDefinitionSnapshot, KernelSolveError> {
        let interface = Arc::clone(&self.derived.interface);
        let definition_code = Arc::clone(&self.definition_code);
        let mut demanded = demanded.to_vec();
        demanded.sort_unstable();
        demanded.dedup();
        if let Some(owner) = demanded
            .iter()
            .find(|owner| owner.0 as usize >= self.definition_code.definition_count())
        {
            return Err(KernelSolveError::new(format!(
                "kernel definition demand references missing owner {}",
                owner.0
            )));
        }
        Ok(KernelDemandedDefinitionSnapshot {
            owners: demanded.into_boxed_slice(),
            program: Arc::clone(&self.program),
            definition_code,
            interface,
            work: self.work,
        })
    }

    pub fn into_demanded_definitions(
        self,
        demanded: &[KernelOwnerId],
    ) -> Result<KernelDemandedDefinitionSnapshot, KernelSolveError> {
        self.demanded_definitions(demanded)
    }
}

#[derive(Clone, Copy, Debug, Eq, Hash, PartialEq)]
struct ResourceDeclarationKey {
    owner: KernelOwnerId,
    declaration: KernelDeclarationId,
}

#[derive(Clone, Copy, Debug, Eq, Hash, PartialEq)]
struct ResourceExpressionKey {
    owner: KernelOwnerId,
    expression: KernelExpressionId,
}

#[repr(transparent)]
#[derive(Clone, Copy, Debug, Eq, Hash, PartialEq)]
struct ResourceProjectionId(u32);

impl ResourceProjectionId {
    const ROOT: Self = Self(0);
}

#[derive(Clone, Copy, Debug)]
struct ResourceProjectionRow {
    head: SymbolId,
    tail: ResourceProjectionId,
    depth: u32,
}

/// Phase-local authority for SOURCE projections.
///
/// A projection owns no strings and allocates no per-path object. Each unique
/// `(head, tail)` cons cell is one packed row, so recursive provenance queries
/// carry a four-byte ID rather than cloning `Vec<SymbolId>` at every step.
#[derive(Default)]
struct ResourceProjectionArena {
    rows: Vec<ResourceProjectionRow>,
    conses: HashMap<(SymbolId, ResourceProjectionId), ResourceProjectionId>,
}

impl ResourceProjectionArena {
    fn with_capacity(edges: usize) -> Self {
        Self {
            rows: Vec::with_capacity(edges),
            conses: HashMap::with_capacity(edges),
        }
    }

    fn cons(&mut self, head: SymbolId, tail: ResourceProjectionId) -> ResourceProjectionId {
        if let Some(existing) = self.conses.get(&(head, tail)) {
            return *existing;
        }
        let id = ResourceProjectionId(
            u32::try_from(self.rows.len())
                .expect("kernel resource projection count exceeds u32")
                .checked_add(1)
                .expect("kernel resource projection namespace exhausted"),
        );
        let depth = self
            .depth(tail)
            .checked_add(1)
            .expect("kernel resource projection depth exceeds u32");
        self.rows.push(ResourceProjectionRow { head, tail, depth });
        self.conses.insert((head, tail), id);
        id
    }

    fn row(&self, id: ResourceProjectionId) -> Option<ResourceProjectionRow> {
        id.0.checked_sub(1)
            .and_then(|ordinal| self.rows.get(ordinal as usize))
            .copied()
    }

    fn depth(&self, id: ResourceProjectionId) -> u32 {
        self.row(id).map_or(0, |row| row.depth)
    }

    fn append(
        &mut self,
        prefix: ResourceProjectionId,
        suffix: ResourceProjectionId,
        symbols: &mut Vec<SymbolId>,
    ) -> ResourceProjectionId {
        symbols.clear();
        self.extend_symbols(prefix, symbols);
        let mut combined = suffix;
        for symbol in symbols.drain(..).rev() {
            combined = self.cons(symbol, combined);
        }
        combined
    }

    fn has_prefix(&self, mut path: ResourceProjectionId, mut prefix: ResourceProjectionId) -> bool {
        while prefix != ResourceProjectionId::ROOT {
            let Some(path_row) = self.row(path) else {
                return false;
            };
            let prefix_row = self
                .row(prefix)
                .expect("non-root resource projection has a row");
            if path_row.head != prefix_row.head {
                return false;
            }
            path = path_row.tail;
            prefix = prefix_row.tail;
        }
        true
    }

    fn suffix_after(
        &self,
        mut path: ResourceProjectionId,
        mut prefix: ResourceProjectionId,
    ) -> Option<ResourceProjectionId> {
        while prefix != ResourceProjectionId::ROOT {
            let path_row = self.row(path)?;
            let prefix_row = self.row(prefix)?;
            if path_row.head != prefix_row.head {
                return None;
            }
            path = path_row.tail;
            prefix = prefix_row.tail;
        }
        Some(path)
    }

    fn extend_symbols(&self, mut path: ResourceProjectionId, output: &mut Vec<SymbolId>) {
        while let Some(row) = self.row(path) {
            output.push(row.head);
            path = row.tail;
        }
    }

    fn segment_at(&self, mut path: ResourceProjectionId, ordinal: u32) -> Option<SymbolId> {
        for _ in 0..ordinal {
            path = self.row(path)?.tail;
        }
        self.row(path).map(|row| row.head)
    }

    fn compare(
        &self,
        text: &ProjectTextSnapshot,
        left: ResourceProjectionId,
        right: ResourceProjectionId,
    ) -> std::cmp::Ordering {
        let left_depth = self.depth(left);
        let right_depth = self.depth(right);
        for ordinal in 0..left_depth.min(right_depth) {
            let left = self
                .segment_at(left, ordinal)
                .expect("resource projection segment is in range");
            let right = self
                .segment_at(right, ordinal)
                .expect("resource projection segment is in range");
            let order = text
                .compare_symbols(left, right)
                .unwrap_or_else(|_| left.as_u32().cmp(&right.as_u32()));
            if order != std::cmp::Ordering::Equal {
                return order;
            }
        }
        left_depth.cmp(&right_depth)
    }
}

fn intern_resource_projection_path(
    text: &ProjectTextSnapshot,
    paths: &mut ResourceProjectionArena,
    path: &[Box<str>],
) -> Result<ResourceProjectionId, KernelSolveError> {
    let mut projection = ResourceProjectionId::ROOT;
    for segment in path.iter().rev() {
        let symbol = text.lookup_symbol(segment).ok_or_else(|| {
            KernelSolveError::new(format!(
                "kernel resource provenance symbol `{segment}` is absent from the project text authority"
            ))
        })?;
        projection = paths.cons(symbol, projection);
    }
    Ok(projection)
}

#[derive(Clone, Copy, Debug, Eq, Hash, PartialEq)]
struct ResourceSourceRead {
    owner: KernelOwnerId,
    source: KernelSourceId,
    payload_projection: ResourceProjectionId,
}

#[derive(Clone, Copy, Debug, Eq, Hash, PartialEq)]
enum ResourceResolution {
    Declaration(ResourceDeclarationKey, ResourceProjectionId),
    Expression(ResourceExpressionKey, ResourceProjectionId),
    ListItem(ResourceExpressionKey, ResourceProjectionId),
    Output(ResourceDeclarationKey, ResourceProjectionId),
}

#[derive(Clone, Copy, Debug)]
struct ResourceLexicalIndex {
    ordinal: u32,
    projection: ResourceProjectionId,
}

#[derive(Clone, Copy, Debug)]
struct ResourceSourceSpan {
    start: u32,
    len: u32,
}

#[derive(Default)]
struct ResourceTraversalScratch {
    explored: HashSet<ResourceResolution>,
    active: HashSet<ResourceResolutionNode>,
    resolved: Vec<ResourceSourceRead>,
    symbols: Vec<SymbolId>,
}

impl ResourceTraversalScratch {
    fn reset(&mut self) {
        self.explored.clear();
        self.active.clear();
        self.resolved.clear();
        self.symbols.clear();
    }
}

#[derive(Clone, Copy, Debug, Eq, Hash, PartialEq)]
enum ResourceResolutionNode {
    Declaration(ResourceDeclarationKey),
    Expression(ResourceExpressionKey),
    ListItem(ResourceExpressionKey),
    Output(ResourceDeclarationKey),
}

impl ResourceResolution {
    const fn node(&self) -> ResourceResolutionNode {
        match self {
            Self::Declaration(declaration, _) => ResourceResolutionNode::Declaration(*declaration),
            Self::Expression(expression, _) => ResourceResolutionNode::Expression(*expression),
            Self::ListItem(expression, _) => ResourceResolutionNode::ListItem(*expression),
            Self::Output(declaration, _) => ResourceResolutionNode::Output(*declaration),
        }
    }
}

#[derive(Default)]
struct DefinitionResourceProjectionFacts {
    requirements: Vec<ResourceProjectionRequirementFact>,
    origins: Vec<PackedSourceReadInput>,
    symbols: Vec<SymbolId>,
}

#[derive(Clone, Copy)]
struct ResourceProjectionRequirementFact {
    expression: KernelExpressionId,
    target: KernelDeclarationReference,
    projection_start: u32,
    projection_len: u32,
    origin_start: u32,
    origin_len: u32,
    required_term: TypeTermId,
    publishes_required_type: bool,
}

struct ResourceProjectionResolver<'a> {
    program: &'a PackedKernelProjectProgram,
    owners: &'a [KernelProjectOwnerOutputs],
    definition_facts: &'a [KernelDefinitionFactsInput],
    abi: &'a crate::KernelAbiInput,
    text: ProjectTextSnapshot,
    lexical_by_expression: Box<[Box<[Option<ResourceLexicalIndex>]>]>,
    call_by_expression: Box<[Box<[Option<usize>]>]>,
    shape_by_expression: Box<[Box<[Option<usize>]>]>,
    paths: ResourceProjectionArena,
    source_paths: HashMap<ResourceDeclarationKey, Vec<(ResourceProjectionId, ResourceSourceRead)>>,
    source_expressions: HashMap<ResourceExpressionKey, Vec<ResourceSourceRead>>,
    actual_inputs_by_formal: HashMap<ResourceDeclarationKey, Vec<ResourceExpressionKey>>,
    contextual_lists_by_output: HashMap<ResourceDeclarationKey, Vec<ResourceExpressionKey>>,
    forwarded_outputs_by_formal: HashMap<ResourceDeclarationKey, Vec<ResourceDeclarationKey>>,
    declaration_cache: HashMap<(ResourceDeclarationKey, ResourceProjectionId), ResourceSourceSpan>,
    cached_sources: Vec<ResourceSourceRead>,
    scratch: ResourceTraversalScratch,
}

impl<'a> ResourceProjectionResolver<'a> {
    fn new(
        program: &'a PackedKernelProjectProgram,
        owners: &'a [KernelProjectOwnerOutputs],
        definition_facts: &'a [KernelDefinitionFactsInput],
        abi: &'a crate::KernelAbiInput,
        text: ProjectTextSnapshot,
    ) -> Result<Self, KernelSolveError> {
        let authored_projection_edges = definition_facts
            .iter()
            .map(|facts| {
                facts
                    .lexical_bindings
                    .iter()
                    .map(|binding| binding.projection.len())
                    .sum::<usize>()
                    + facts
                        .sources
                        .iter()
                        .map(|source| source.projection.len())
                        .sum::<usize>()
            })
            .sum();
        let mut paths = ResourceProjectionArena::with_capacity(authored_projection_edges);
        let lexical_by_expression = definition_facts
            .iter()
            .enumerate()
            .map(|(owner_index, facts)| {
                let mut index = vec![None; owners[owner_index].expressions.len()];
                for (ordinal, binding) in facts.lexical_bindings.iter().enumerate() {
                    let projection =
                        intern_resource_projection_path(&text, &mut paths, &binding.projection)?;
                    let slot = index
                        .get_mut(binding.expression.0 as usize)
                        .ok_or_else(|| {
                            KernelSolveError::new(format!(
                                "kernel resource provenance owner {owner_index} lexical expression {} is out of range",
                                binding.expression.0
                            ))
                        })?;
                    let ordinal = u32::try_from(ordinal).map_err(|_| {
                        KernelSolveError::new(
                            "kernel resource provenance lexical binding count exceeds u32",
                        )
                    })?;
                    if slot
                        .replace(ResourceLexicalIndex {
                            ordinal,
                            projection,
                        })
                        .is_some()
                    {
                        return Err(KernelSolveError::new(format!(
                            "kernel resource provenance owner {owner_index} repeats lexical expression {}",
                            binding.expression.0
                        )));
                    }
                }
                Ok(index.into_boxed_slice())
            })
            .collect::<Result<Vec<_>, KernelSolveError>>()?
            .into_boxed_slice();
        let call_by_expression = owners
            .iter()
            .enumerate()
            .map(|(owner_index, owner)| {
                let mut index = vec![None; owner.expressions.len()];
                for (ordinal, call) in owner.calls.iter().enumerate() {
                    let slot = index
                        .get_mut(call.expression.0 as usize)
                        .ok_or_else(|| {
                            KernelSolveError::new(format!(
                                "kernel resource provenance owner {owner_index} call expression {} is out of range",
                                call.expression.0
                            ))
                        })?;
                    if slot.replace(ordinal).is_some() {
                        return Err(KernelSolveError::new(format!(
                            "kernel resource provenance owner {owner_index} repeats call expression {}",
                            call.expression.0
                        )));
                    }
                }
                Ok(index.into_boxed_slice())
            })
            .collect::<Result<Vec<_>, KernelSolveError>>()?
            .into_boxed_slice();
        let shape_by_expression = definition_facts
            .iter()
            .enumerate()
            .map(|(owner_index, facts)| {
                let mut index = vec![None; owners[owner_index].expressions.len()];
                for (ordinal, shape) in facts.execution_shapes.iter().enumerate() {
                    let slot = index
                        .get_mut(shape.expression().0 as usize)
                        .ok_or_else(|| {
                            KernelSolveError::new(format!(
                                "kernel resource provenance owner {owner_index} execution shape {} is out of range",
                                shape.expression().0
                            ))
                        })?;
                    if slot.replace(ordinal).is_some() {
                        return Err(KernelSolveError::new(format!(
                            "kernel resource provenance owner {owner_index} repeats execution shape {}",
                            shape.expression().0
                        )));
                    }
                }
                Ok(index.into_boxed_slice())
            })
            .collect::<Result<Vec<_>, KernelSolveError>>()?
            .into_boxed_slice();

        let mut resolver = Self {
            program,
            owners,
            definition_facts,
            abi,
            text,
            lexical_by_expression,
            call_by_expression,
            shape_by_expression,
            paths,
            source_paths: HashMap::new(),
            source_expressions: HashMap::new(),
            actual_inputs_by_formal: HashMap::new(),
            contextual_lists_by_output: HashMap::new(),
            forwarded_outputs_by_formal: HashMap::new(),
            declaration_cache: HashMap::new(),
            cached_sources: Vec::new(),
            scratch: ResourceTraversalScratch::default(),
        };
        resolver.index_sources()?;
        resolver.index_calls()?;
        Ok(resolver)
    }

    fn symbol(&self, value: &str) -> Result<SymbolId, KernelSolveError> {
        self.text.lookup_symbol(value).ok_or_else(|| {
            KernelSolveError::new(format!(
                "kernel resource provenance symbol `{value}` is absent from the project text authority"
            ))
        })
    }

    fn input(&self, owner: KernelOwnerId) -> Option<PackedKernelOwnerProgramRef<'a>> {
        self.program.owner(owner)
    }

    fn facts(&self, owner: KernelOwnerId) -> Option<&'a KernelDefinitionFactsInput> {
        self.definition_facts.get(owner.0 as usize)
    }

    fn definition(&self, owner: KernelOwnerId) -> Option<KernelDefinitionInputRef<'a>> {
        let index = owner.0 as usize;
        Some(KernelDefinitionInputRef {
            owner,
            input: self.program.owner_at(index)?,
            facts: self.definition_facts.get(index)?,
            outputs: self.owners.get(index)?,
        })
    }

    fn declaration_key(
        &self,
        owner: KernelOwnerId,
        reference: KernelDeclarationReference,
    ) -> Option<ResourceDeclarationKey> {
        let mut owner = owner;
        let mut reference = reference;
        let mut remaining = self.owners.len().saturating_add(1);
        loop {
            if remaining == 0 {
                return None;
            }
            remaining -= 1;
            match reference {
                KernelDeclarationReference::Local(declaration) => {
                    return Some(ResourceDeclarationKey { owner, declaration });
                }
                KernelDeclarationReference::OwnerDeclaration {
                    owner: target,
                    declaration,
                } => {
                    return Some(ResourceDeclarationKey {
                        owner: target,
                        declaration,
                    });
                }
                KernelDeclarationReference::OwnerPublic(target) => {
                    owner = target;
                    reference = self.facts(target)?.linkage.public_declaration?;
                }
            }
        }
    }

    fn declaration(&self, key: ResourceDeclarationKey) -> Option<&'a KernelDeclarationInput> {
        self.facts(key.owner)?
            .declarations
            .get(key.declaration.0 as usize)
            .filter(|declaration| declaration.id == key.declaration)
    }

    fn declaration_value(
        &self,
        key: ResourceDeclarationKey,
        declaration: &KernelDeclarationInput,
    ) -> Option<ResourceExpressionKey> {
        let encoded = declaration.value?;
        let value = packed_kernel_value_reference(
            self.input(key.owner)?,
            encoded,
            declaration.id.0 as usize,
        )
        .ok()?;
        self.expression_key(key.owner, value)
    }

    fn expression_key(
        &self,
        owner: KernelOwnerId,
        value: KernelValueReference,
    ) -> Option<ResourceExpressionKey> {
        match value {
            KernelValueReference::Local(expression) => {
                Some(ResourceExpressionKey { owner, expression })
            }
            KernelValueReference::External(external) => match external.target {
                KernelExternalTarget::Expression(expression) => Some(ResourceExpressionKey {
                    owner: external.owner,
                    expression,
                }),
                KernelExternalTarget::Result => Some(ResourceExpressionKey {
                    owner: external.owner,
                    expression: self.facts(external.owner)?.linkage.result_expression?,
                }),
            },
        }
    }

    fn expression(&self, key: ResourceExpressionKey) -> Option<&'a PackedKernelOwnerNode> {
        self.input(key.owner)?.node(key.expression)
    }

    fn lexical_index(&self, key: ResourceExpressionKey) -> Option<ResourceLexicalIndex> {
        self.lexical_by_expression
            .get(key.owner.0 as usize)?
            .get(key.expression.0 as usize)?
            .as_ref()
            .copied()
    }

    fn lexical(&self, key: ResourceExpressionKey) -> Option<&'a KernelLexicalBindingInput> {
        let index = self.lexical_index(key)?;
        self.facts(key.owner)?
            .lexical_bindings
            .get(index.ordinal as usize)
    }

    fn lexical_projection(&self, key: ResourceExpressionKey) -> Option<ResourceProjectionId> {
        self.lexical_index(key).map(|index| index.projection)
    }

    fn call(&self, key: ResourceExpressionKey) -> Option<KernelProjectCallRef<'a>> {
        let ordinal = self
            .call_by_expression
            .get(key.owner.0 as usize)?
            .get(key.expression.0 as usize)?
            .as_ref()
            .copied()?;
        self.definition(key.owner)?.call(ordinal)
    }

    fn call_syntax(&self, key: ResourceExpressionKey) -> Option<&'a KernelCallSyntaxInput> {
        self.facts(key.owner)?
            .call_syntax
            .iter()
            .find(|call| call.expression == key.expression)
    }

    fn shape(&self, key: ResourceExpressionKey) -> Option<&'a KernelExecutionShapeInput> {
        let ordinal = self
            .shape_by_expression
            .get(key.owner.0 as usize)?
            .get(key.expression.0 as usize)?
            .as_ref()
            .copied()?;
        self.facts(key.owner)?.execution_shapes.get(ordinal)
    }

    fn inputs(&self, key: ResourceExpressionKey) -> &'a [crate::PackedKernelOwnerInputEdge] {
        self.expression(key).map_or(&[], |expression| {
            expression.inputs(
                self.input(key.owner)
                    .expect("indexed resource expression retains its owner"),
            )
        })
    }

    fn input_expression_key(
        &self,
        consumer: ResourceExpressionKey,
        input: &crate::PackedKernelOwnerInputEdge,
    ) -> Option<ResourceExpressionKey> {
        let value = packed_kernel_value_reference(
            self.input(consumer.owner)?,
            input.expression,
            consumer.expression.0 as usize,
        )
        .ok()?;
        self.expression_key(consumer.owner, value)
    }

    fn first_input(
        &self,
        key: ResourceExpressionKey,
        matches: impl Fn(&PackedKernelOwnerEdgeRole) -> bool,
    ) -> Option<ResourceExpressionKey> {
        self.expression(key)?
            .inputs(self.input(key.owner)?)
            .iter()
            .find(|input| matches(&input.role))
            .and_then(|input| self.input_expression_key(key, input))
    }

    fn parameter_declaration(
        &self,
        owner: KernelOwnerId,
        ordinal: u32,
    ) -> Option<ResourceDeclarationKey> {
        let declaration = self.facts(owner)?.declarations.iter().find(|declaration| {
            matches!(
                declaration.origin,
                KernelDeclarationOrigin::Parameter {
                    ordinal: candidate,
                    ..
                } if candidate == ordinal
            )
        })?;
        Some(ResourceDeclarationKey {
            owner,
            declaration: declaration.id,
        })
    }

    fn callback_declaration(
        &self,
        owner: KernelOwnerId,
        call: KernelExpressionId,
        ordinal: u32,
    ) -> Option<ResourceDeclarationKey> {
        let declaration = self.facts(owner)?.declarations.iter().find(|declaration| {
            declaration.origin == KernelDeclarationOrigin::CallbackBinding { call, ordinal }
        })?;
        Some(ResourceDeclarationKey {
            owner,
            declaration: declaration.id,
        })
    }

    fn abi_parameter<'b>(
        &'b self,
        key: ResourceExpressionKey,
        call: KernelProjectCallRef<'a>,
        input: &'a crate::PackedKernelOwnerInputEdge,
    ) -> Option<&'b crate::KernelAbiParameterInput> {
        let callable = self.abi.callable(&self.call_syntax(key)?.function)?;
        match call.input_role(input).ok()? {
            KernelCallInputRoleRef::Abi { name } => callable
                .parameters
                .iter()
                .find(|parameter| parameter.name.as_ref() == name)
                .or_else(|| {
                    (name == "$pipe").then(|| {
                        callable.parameters.iter().find(|parameter| {
                            parameter.kind == boon_checked::CheckedParameterKind::Value
                        })
                    })?
                }),
            KernelCallInputRoleRef::Formal { .. } => None,
        }
    }

    fn call_input_for_abi_parameter(
        &self,
        key: ResourceExpressionKey,
        ordinal: u32,
    ) -> Option<ResourceExpressionKey> {
        let call = self.call(key)?;
        call.inputs()
            .iter()
            .find(|input| {
                self.abi_parameter(key, call, input)
                    .is_some_and(|parameter| parameter.ordinal == ordinal)
            })
            .and_then(|input| self.input_expression_key(key, input))
    }

    fn call_input_named(
        &self,
        key: ResourceExpressionKey,
        name: &str,
    ) -> Option<ResourceExpressionKey> {
        let call = self.call(key)?;
        call.inputs()
            .iter()
            .find(|input| {
                self.abi_parameter(key, call, input)
                    .is_some_and(|parameter| parameter.name.as_ref() == name)
            })
            .and_then(|input| self.input_expression_key(key, input))
    }

    fn output_declaration_for_input(
        &self,
        key: ResourceExpressionKey,
        call: KernelProjectCallRef<'a>,
        input: &'a crate::PackedKernelOwnerInputEdge,
        ordinal: u32,
        name: &str,
    ) -> Option<ResourceDeclarationKey> {
        let syntax = self.call_syntax(key)?;
        let input_value = call.input_value(input).ok()?;
        let argument = syntax.arguments.iter().find(|argument| {
            argument.name.as_ref() == name
                && packed_kernel_value_reference(
                    self.input(key.owner).expect("checked call owner"),
                    argument.value,
                    call.expression().0 as usize,
                )
                .ok()
                    == Some(input_value)
        })?;
        match argument.kind {
            KernelCallArgumentKind::BareBinding => {
                self.callback_declaration(key.owner, call.expression(), ordinal)
            }
            KernelCallArgumentKind::Named => {
                let KernelValueReference::Local(expression) = input_value else {
                    return None;
                };
                let binding = self
                    .facts(key.owner)?
                    .lexical_bindings
                    .iter()
                    .find(|binding| {
                        binding.expression == expression && binding.projection.is_empty()
                    })?;
                let KernelLexicalBindingTargetInput::Declaration(target) = binding.target else {
                    return None;
                };
                self.declaration_key(key.owner, target)
            }
        }
    }

    fn index_calls(&mut self) -> Result<(), KernelSolveError> {
        for owner_index in 0..self.owners.len() {
            let owner_id = KernelOwnerId(u32::try_from(owner_index).map_err(|_| {
                KernelSolveError::new("kernel resource provenance owner count exceeds u32")
            })?);
            let definition = self.definition(owner_id).ok_or_else(|| {
                KernelSolveError::new(format!(
                    "kernel resource provenance owner {} is missing",
                    owner_id.0,
                ))
            })?;
            for call in definition.calls() {
                let key = ResourceExpressionKey {
                    owner: owner_id,
                    expression: call.expression(),
                };
                match call.target() {
                    KernelCallTargetRef::User { target, .. } => {
                        for (input_index, input) in call.inputs().iter().enumerate() {
                            let Ok(KernelCallInputRoleRef::Formal { ordinal }) =
                                call.input_role(input)
                            else {
                                continue;
                            };
                            if !project_call_input_is_first_for_formal(call, input_index, ordinal) {
                                continue;
                            }
                            // Solver-only unit programs may intentionally omit
                            // presentation declarations. Such calls cannot
                            // participate in SOURCE provenance, so leave them
                            // outside this auxiliary reverse index. A concrete
                            // resource projection still fails closed later if
                            // its own declaration authority is absent.
                            let Some(formal) = self.parameter_declaration(target, ordinal) else {
                                continue;
                            };
                            let Some(declaration) = self.declaration(formal) else {
                                continue;
                            };
                            match declaration.kind {
                                KernelDeclarationKind::ValueParameter => {
                                    if let Some(actual) = call
                                        .input_value(input)
                                        .ok()
                                        .and_then(|value| self.expression_key(owner_id, value))
                                    {
                                        self.actual_inputs_by_formal
                                            .entry(formal)
                                            .or_default()
                                            .push(actual);
                                    }
                                }
                                KernelDeclarationKind::OutParameter => {
                                    if let Some(output) = self.output_declaration_for_input(
                                        key,
                                        call,
                                        input,
                                        ordinal,
                                        &declaration.name,
                                    ) {
                                        self.forwarded_outputs_by_formal
                                            .entry(formal)
                                            .or_default()
                                            .push(output);
                                    }
                                }
                                _ => {}
                            }
                        }
                    }
                    KernelCallTargetRef::RenderConstructor { .. }
                    | KernelCallTargetRef::PureBuiltin { .. }
                    | KernelCallTargetRef::FixedAbi
                    | KernelCallTargetRef::HostEffect { .. }
                    | KernelCallTargetRef::FieldProjection { .. } => {
                        let Some(contract) = self
                            .call_syntax(key)
                            .and_then(|syntax| self.abi.callable(&syntax.function))
                        else {
                            continue;
                        };
                        let Some(operation) = contract.contextual_operation else {
                            continue;
                        };
                        let (list_ordinal, row_ordinal, _) =
                            contextual_operation_formals(operation);
                        let Some(list) = self.call_input_for_abi_parameter(key, list_ordinal)
                        else {
                            continue;
                        };
                        for input in call.inputs() {
                            let Some(parameter) = self.abi_parameter(key, call, input) else {
                                continue;
                            };
                            if parameter.ordinal != row_ordinal
                                || parameter.kind != boon_checked::CheckedParameterKind::Out
                            {
                                continue;
                            }
                            if let Some(output) = self.output_declaration_for_input(
                                key,
                                call,
                                input,
                                parameter.ordinal,
                                &parameter.name,
                            ) {
                                self.contextual_lists_by_output
                                    .entry(output)
                                    .or_default()
                                    .push(list);
                            }
                        }
                    }
                }
            }
        }
        Ok(())
    }

    fn lexical_declaration_for_scope(
        &self,
        mut owner: KernelOwnerId,
        mut scope: KernelScopeReference,
    ) -> Option<ResourceDeclarationKey> {
        let mut remaining = self
            .definition_facts
            .iter()
            .map(|facts| facts.presentation.scopes.len())
            .sum::<usize>()
            .saturating_add(self.owners.len())
            .saturating_add(1);
        loop {
            if remaining == 0 {
                return None;
            }
            remaining -= 1;
            match scope {
                KernelScopeReference::ProjectRoot => return None,
                KernelScopeReference::Containing => {
                    scope = self.facts(owner)?.presentation.containing_scope;
                }
                KernelScopeReference::Owner {
                    owner: provider,
                    scope: provider_scope,
                } => {
                    owner = provider;
                    scope = KernelScopeReference::Local(provider_scope);
                }
                KernelScopeReference::Local(local) => {
                    let row = self
                        .facts(owner)?
                        .presentation
                        .scopes
                        .get(local.0 as usize)?;
                    if let Some(declaration) = row.owner {
                        return self.declaration_key(owner, declaration);
                    }
                    scope = row.parent;
                }
            }
        }
    }

    fn declaration_presentation(
        &self,
        key: ResourceDeclarationKey,
    ) -> Option<&'a KernelDeclarationPresentation> {
        self.facts(key.owner)?
            .presentation
            .declarations
            .iter()
            .find(|presentation| presentation.declaration == key.declaration)
    }

    fn index_sources(&mut self) -> Result<(), KernelSolveError> {
        let mut seen = Vec::new();
        for (owner_index, facts) in self.definition_facts.iter().enumerate() {
            let owner_id = KernelOwnerId(u32::try_from(owner_index).map_err(|_| {
                KernelSolveError::new("kernel resource provenance owner count exceeds u32")
            })?);
            for source in &facts.sources {
                let read = ResourceSourceRead {
                    owner: owner_id,
                    source: source.id,
                    payload_projection: ResourceProjectionId::ROOT,
                };
                self.source_expressions
                    .entry(ResourceExpressionKey {
                        owner: owner_id,
                        expression: source.expression,
                    })
                    .or_default()
                    .push(read.clone());
                let path = intern_resource_projection_path(
                    &self.text,
                    &mut self.paths,
                    &source.projection,
                )?;
                let anchor = self
                    .declaration_key(owner_id, source.declaration)
                    .ok_or_else(|| {
                        KernelSolveError::new(format!(
                            "kernel resource provenance SOURCE {} has no path anchor",
                            source.id.0
                        ))
                    })?;
                self.source_paths
                    .entry(anchor)
                    .or_default()
                    .push((path, read));

                let declaration = self
                    .declaration_key(owner_id, source.declaration)
                    .ok_or_else(|| {
                        KernelSolveError::new(format!(
                            "kernel resource provenance SOURCE {} has no declaration",
                            source.id.0
                        ))
                    })?;
                let declaration_row = self.declaration(declaration).ok_or_else(|| {
                    KernelSolveError::new(
                        "kernel resource provenance SOURCE declaration is missing",
                    )
                })?;
                let presentation = self.declaration_presentation(declaration).ok_or_else(|| {
                    KernelSolveError::new(
                        "kernel resource provenance SOURCE declaration has no presentation",
                    )
                })?;
                let declaration_name = self.symbol(&declaration_row.name)?;
                let mut alias = self.paths.cons(declaration_name, path);
                let mut scope_owner = declaration.owner;
                let mut scope = presentation.scope;
                seen.clear();
                while let Some(parent) = self.lexical_declaration_for_scope(scope_owner, scope) {
                    if seen.contains(&parent) || parent == declaration {
                        break;
                    }
                    seen.push(parent);
                    self.source_paths
                        .entry(parent)
                        .or_default()
                        .push((alias, read));
                    let Some(parent_row) = self.declaration(parent) else {
                        break;
                    };
                    let Some(parent_presentation) = self.declaration_presentation(parent) else {
                        break;
                    };
                    let parent_name = self.symbol(&parent_row.name)?;
                    alias = self.paths.cons(parent_name, alias);
                    scope_owner = parent.owner;
                    scope = parent_presentation.scope;
                }
            }
        }
        let projection_paths = &self.paths;
        for paths in self.source_paths.values_mut() {
            paths.sort_by(|(left_path, left), (right_path, right)| {
                projection_paths
                    .depth(*right_path)
                    .cmp(&projection_paths.depth(*left_path))
                    .then_with(|| left.owner.0.cmp(&right.owner.0))
                    .then_with(|| left.source.0.cmp(&right.source.0))
            });
        }
        Ok(())
    }

    fn exact_source_match(
        &self,
        paths: &ResourceProjectionArena,
        target: ResourceDeclarationKey,
        projection: ResourceProjectionId,
    ) -> Option<(ResourceProjectionId, ResourceSourceRead)> {
        let mut matches = self
            .source_paths
            .get(&target)?
            .iter()
            .filter(|(path, _)| paths.has_prefix(projection, *path));
        let (path, source) = matches.next().copied()?;
        let length = paths.depth(path);
        if matches
            .next()
            .is_some_and(|(candidate, _)| paths.depth(*candidate) == length)
        {
            return None;
        }
        Some((path, source))
    }

    fn exact_source_read(
        &self,
        paths: &ResourceProjectionArena,
        target: ResourceDeclarationKey,
        projection: ResourceProjectionId,
    ) -> Option<ResourceSourceRead> {
        let (source_path, mut source) = self.exact_source_match(paths, target, projection)?;
        let payload = paths.suffix_after(projection, source_path)?;
        source.payload_projection =
            canonical_resource_payload_projection_id(&self.text, paths, payload);
        Some(source)
    }

    fn has_exact_source_read(
        &self,
        target: ResourceDeclarationKey,
        projection: ResourceProjectionId,
    ) -> bool {
        self.exact_source_match(&self.paths, target, projection)
            .is_some()
    }

    fn sort_and_dedup_sources(
        &self,
        paths: &ResourceProjectionArena,
        sources: &mut Vec<ResourceSourceRead>,
    ) {
        sources.sort_by(|left, right| {
            left.owner
                .0
                .cmp(&right.owner.0)
                .then_with(|| left.source.0.cmp(&right.source.0))
                .then_with(|| {
                    paths.compare(
                        &self.text,
                        left.payload_projection,
                        right.payload_projection,
                    )
                })
        });
        sources.dedup();
    }

    fn sources_for_declaration(
        &mut self,
        target: ResourceDeclarationKey,
        projection: ResourceProjectionId,
    ) -> ResourceSourceSpan {
        let key = (target, projection);
        if let Some(cached) = self.declaration_cache.get(&key) {
            return *cached;
        }
        let mut paths = std::mem::take(&mut self.paths);
        let mut scratch = std::mem::take(&mut self.scratch);
        scratch.reset();
        self.declaration_sources(&mut paths, target, projection, &mut scratch);
        self.sort_and_dedup_sources(&paths, &mut scratch.resolved);
        let span = ResourceSourceSpan {
            start: u32::try_from(self.cached_sources.len())
                .expect("kernel resource source cache exceeds u32"),
            len: u32::try_from(scratch.resolved.len())
                .expect("kernel resource source answer exceeds u32"),
        };
        self.cached_sources.extend_from_slice(&scratch.resolved);
        scratch.reset();
        self.paths = paths;
        self.scratch = scratch;
        self.declaration_cache.insert(key, span);
        span
    }

    fn cached_source_reads(&self, span: ResourceSourceSpan) -> &[ResourceSourceRead] {
        let start = span.start as usize;
        &self.cached_sources[start..start + span.len as usize]
    }

    fn declaration_sources(
        &self,
        paths: &mut ResourceProjectionArena,
        target: ResourceDeclarationKey,
        projection: ResourceProjectionId,
        scratch: &mut ResourceTraversalScratch,
    ) {
        let key = ResourceResolution::Declaration(target, projection);
        let node = key.node();
        if scratch.active.contains(&node) || !scratch.explored.insert(key) {
            return;
        }
        scratch.active.insert(node);
        if let Some(source) = self.exact_source_read(paths, target, projection) {
            scratch.resolved.push(source);
        }
        let Some(declaration) = self.declaration(target) else {
            scratch.active.remove(&node);
            return;
        };
        if declaration.kind == KernelDeclarationKind::ValueParameter {
            for actual in self
                .actual_inputs_by_formal
                .get(&target)
                .into_iter()
                .flatten()
            {
                self.expression_sources(paths, *actual, projection, scratch);
            }
        }
        if matches!(
            declaration.kind,
            KernelDeclarationKind::FreshOut | KernelDeclarationKind::OutParameter
        ) {
            self.output_sources(paths, target, projection, scratch);
        }
        if let Some(value) = self.declaration_value(target, declaration) {
            self.expression_sources(paths, value, projection, scratch);
        }
        if declaration.kind == KernelDeclarationKind::Function
            && let Some(result) = self
                .facts(target.owner)
                .and_then(|facts| facts.linkage.result_expression)
        {
            self.expression_sources(
                paths,
                ResourceExpressionKey {
                    owner: target.owner,
                    expression: result,
                },
                projection,
                scratch,
            );
        }
        scratch.active.remove(&node);
    }

    fn expression_sources(
        &self,
        paths: &mut ResourceProjectionArena,
        expression: ResourceExpressionKey,
        projection: ResourceProjectionId,
        scratch: &mut ResourceTraversalScratch,
    ) {
        let key = ResourceResolution::Expression(expression, projection);
        let node = key.node();
        if scratch.active.contains(&node) || !scratch.explored.insert(key) {
            return;
        }
        scratch.active.insert(node);
        if let Some(sources) = self.source_expressions.get(&expression) {
            let payload = canonical_resource_payload_projection_id(&self.text, paths, projection);
            scratch.resolved.extend(sources.iter().map(|source| {
                let mut source = *source;
                source.payload_projection = payload;
                source
            }));
            scratch.active.remove(&node);
            return;
        }
        let Some(row) = self.expression(expression) else {
            scratch.active.remove(&node);
            return;
        };
        if let Some(binding) = self.lexical(expression)
            && let KernelLexicalBindingTargetInput::Declaration(target) = binding.target
            && let Some(target) = self.declaration_key(expression.owner, target)
        {
            let prefix = self
                .lexical_projection(expression)
                .expect("indexed lexical binding has a projection");
            let combined = paths.append(prefix, projection, &mut scratch.symbols);
            self.declaration_sources(paths, target, combined, scratch);
            scratch.active.remove(&node);
            return;
        }
        match &row.kind {
            PackedKernelOwnerNodeKind::Record { .. } => {
                if let Some(projection) = paths.row(projection)
                    && let Some(KernelExecutionShapeInput::Record { fields, .. }) =
                        self.shape(expression)
                {
                    for candidate in fields.iter().filter(|candidate| {
                        self.text.lookup_symbol(&candidate.name) == Some(projection.head)
                    }) {
                        if let Some(value) = packed_kernel_value_reference(
                            self.input(expression.owner)
                                .expect("checked expression owner"),
                            candidate.value,
                            expression.expression.0 as usize,
                        )
                        .ok()
                        .and_then(|value| self.expression_key(expression.owner, value))
                        {
                            self.expression_sources(paths, value, projection.tail, scratch);
                        }
                    }
                }
            }
            PackedKernelOwnerNodeKind::UserCall { .. }
            | PackedKernelOwnerNodeKind::RenderConstructor { .. }
            | PackedKernelOwnerNodeKind::PureBuiltin { .. }
            | PackedKernelOwnerNodeKind::FixedAbiCall { .. }
            | PackedKernelOwnerNodeKind::HostEffect { .. }
            | PackedKernelOwnerNodeKind::FieldProjection { .. } => {
                if let Some(call) = self.call(expression) {
                    match call.target() {
                        KernelCallTargetRef::User { target, .. } => {
                            if let Some(result) = self
                                .facts(target)
                                .and_then(|facts| facts.linkage.result_expression)
                            {
                                self.expression_sources(
                                    paths,
                                    ResourceExpressionKey {
                                        owner: target,
                                        expression: result,
                                    },
                                    projection,
                                    scratch,
                                );
                            }
                        }
                        _ => {
                            let function = self
                                .call_syntax(expression)
                                .map(|call| call.function.as_ref());
                            let contextual_find = self
                                .call_syntax(expression)
                                .and_then(|syntax| self.abi.callable(&syntax.function))
                                .and_then(|callable| callable.contextual_operation)
                                .is_some_and(|operation| {
                                    matches!(
                                        operation,
                                        crate::KernelAbiContextualOperation::Find { .. }
                                    )
                                });
                            if contextual_find
                                || matches!(
                                    function,
                                    Some("List/get" | "List/latest" | "List/find")
                                )
                            {
                                let list = self
                                    .call_syntax(expression)
                                    .and_then(|syntax| self.abi.callable(&syntax.function))
                                    .and_then(|callable| callable.contextual_operation)
                                    .and_then(|operation| {
                                        let (list, _, _) = contextual_operation_formals(operation);
                                        self.call_input_for_abi_parameter(expression, list)
                                    })
                                    .or_else(|| self.call_input_named(expression, "list"));
                                if let Some(list) = list {
                                    self.list_item_sources(paths, list, projection, scratch);
                                }
                            }
                        }
                    }
                }
            }
            PackedKernelOwnerNodeKind::Draining => {
                if let Some(input) = self.first_input(expression, |role| {
                    matches!(role, PackedKernelOwnerEdgeRole::DrainingInput)
                }) {
                    self.expression_sources(paths, input, projection, scratch);
                }
            }
            PackedKernelOwnerNodeKind::Hold => {
                if let Some(input) = self.first_input(expression, |role| {
                    matches!(role, PackedKernelOwnerEdgeRole::HoldInitial)
                }) {
                    self.expression_sources(paths, input, projection, scratch);
                }
            }
            PackedKernelOwnerNodeKind::Flush => {
                if let Some(input) = self.first_input(expression, |role| {
                    matches!(role, PackedKernelOwnerEdgeRole::FlushPayload)
                }) {
                    self.expression_sources(paths, input, projection, scratch);
                }
            }
            PackedKernelOwnerNodeKind::Latest => {
                for input in self.inputs(expression) {
                    if matches!(input.role, PackedKernelOwnerEdgeRole::LatestBranch)
                        && let Some(branch) = self.input_expression_key(expression, input)
                    {
                        self.expression_sources(paths, branch, projection, scratch);
                    }
                }
            }
            PackedKernelOwnerNodeKind::When => {
                for input in self.inputs(expression) {
                    if matches!(input.role, PackedKernelOwnerEdgeRole::WhenArm)
                        && let Some(arm) = self.input_expression_key(expression, input)
                    {
                        self.expression_sources(paths, arm, projection, scratch);
                    }
                }
            }
            PackedKernelOwnerNodeKind::Then => {
                if let Some(output) = self.first_input(expression, |role| {
                    matches!(role, PackedKernelOwnerEdgeRole::ThenOutput)
                }) {
                    self.expression_sources(paths, output, projection, scratch);
                }
            }
            PackedKernelOwnerNodeKind::MatchArm { .. } => {
                if let Some(output) = self.first_input(expression, |role| {
                    matches!(role, PackedKernelOwnerEdgeRole::MatchOutput)
                }) {
                    self.expression_sources(paths, output, projection, scratch);
                }
            }
            PackedKernelOwnerNodeKind::Block => {
                if let Some(KernelExecutionShapeInput::Block {
                    result: Some(result),
                    ..
                }) = self.shape(expression)
                    && let Some(result) = packed_kernel_value_reference(
                        self.input(expression.owner)
                            .expect("checked expression owner"),
                        *result,
                        expression.expression.0 as usize,
                    )
                    .ok()
                    .and_then(|value| self.expression_key(expression.owner, value))
                {
                    self.expression_sources(paths, result, projection, scratch);
                }
            }
            PackedKernelOwnerNodeKind::MapEntry => {
                if let Some(key) = self.first_input(expression, |role| {
                    matches!(role, PackedKernelOwnerEdgeRole::MapKey)
                }) {
                    self.expression_sources(paths, key, ResourceProjectionId::ROOT, scratch);
                }
                if let Some(value) = self.first_input(expression, |role| {
                    matches!(role, PackedKernelOwnerEdgeRole::MapValue)
                }) {
                    self.expression_sources(paths, value, projection, scratch);
                }
            }
            PackedKernelOwnerNodeKind::Collection {
                kind: KernelCollectionKind::Map,
                ..
            } => {
                for input in self.inputs(expression) {
                    if matches!(input.role, PackedKernelOwnerEdgeRole::MapEntry)
                        && let Some(entry) = self.input_expression_key(expression, input)
                    {
                        self.expression_sources(paths, entry, projection, scratch);
                    }
                }
            }
            PackedKernelOwnerNodeKind::Collection {
                kind: KernelCollectionKind::Set,
                ..
            } => {
                for input in self.inputs(expression) {
                    if matches!(input.role, PackedKernelOwnerEdgeRole::CollectionItem)
                        && let Some(item) = self.input_expression_key(expression, input)
                    {
                        self.expression_sources(paths, item, projection, scratch);
                    }
                }
            }
            _ => {}
        }
        scratch.active.remove(&node);
    }

    fn list_item_sources(
        &self,
        paths: &mut ResourceProjectionArena,
        expression: ResourceExpressionKey,
        projection: ResourceProjectionId,
        scratch: &mut ResourceTraversalScratch,
    ) {
        let key = ResourceResolution::ListItem(expression, projection);
        let node = key.node();
        if scratch.active.contains(&node) || !scratch.explored.insert(key) {
            return;
        }
        scratch.active.insert(node);
        let Some(row) = self.expression(expression) else {
            scratch.active.remove(&node);
            return;
        };
        match &row.kind {
            PackedKernelOwnerNodeKind::Collection {
                kind: KernelCollectionKind::List,
                ..
            } => {
                for input in self.inputs(expression) {
                    if matches!(&input.role, PackedKernelOwnerEdgeRole::CollectionItem)
                        && let Some(item) = self.input_expression_key(expression, input)
                    {
                        self.expression_sources(paths, item, projection, scratch);
                    }
                }
            }
            _ if self.lexical(expression).is_some_and(|binding| {
                binding.access == KernelLexicalAccess::Read
                    && self.lexical_projection(expression) == Some(ResourceProjectionId::ROOT)
            }) =>
            {
                let binding = self.lexical(expression).expect("checked lexical binding");
                if let KernelLexicalBindingTargetInput::Declaration(target) = binding.target
                    && let Some(target) = self.declaration_key(expression.owner, target)
                    && let Some(declaration) = self.declaration(target)
                {
                    if declaration.kind == KernelDeclarationKind::ValueParameter {
                        for actual in self
                            .actual_inputs_by_formal
                            .get(&target)
                            .into_iter()
                            .flatten()
                        {
                            self.list_item_sources(paths, *actual, projection, scratch);
                        }
                    }
                    if let Some(value) = self.declaration_value(target, declaration) {
                        self.list_item_sources(paths, value, projection, scratch);
                    }
                }
            }
            PackedKernelOwnerNodeKind::UserCall { .. }
            | PackedKernelOwnerNodeKind::RenderConstructor { .. }
            | PackedKernelOwnerNodeKind::PureBuiltin { .. }
            | PackedKernelOwnerNodeKind::FixedAbiCall { .. }
            | PackedKernelOwnerNodeKind::HostEffect { .. }
            | PackedKernelOwnerNodeKind::FieldProjection { .. } => {
                if let Some(call) = self.call(expression) {
                    match call.target() {
                        KernelCallTargetRef::User { target, .. } => {
                            if let Some(result) = self
                                .facts(target)
                                .and_then(|facts| facts.linkage.result_expression)
                            {
                                self.list_item_sources(
                                    paths,
                                    ResourceExpressionKey {
                                        owner: target,
                                        expression: result,
                                    },
                                    projection,
                                    scratch,
                                );
                            }
                        }
                        _ => {
                            let operation = self
                                .call_syntax(expression)
                                .and_then(|syntax| self.abi.callable(&syntax.function))
                                .and_then(|callable| callable.contextual_operation);
                            match operation {
                                Some(crate::KernelAbiContextualOperation::Map { body, .. }) => {
                                    if let Some(body) =
                                        self.call_input_for_abi_parameter(expression, body)
                                    {
                                        self.expression_sources(paths, body, projection, scratch);
                                    }
                                }
                                Some(
                                    crate::KernelAbiContextualOperation::Filter { list, .. }
                                    | crate::KernelAbiContextualOperation::Retain { list, .. }
                                    | crate::KernelAbiContextualOperation::Remove { list, .. }
                                    | crate::KernelAbiContextualOperation::SortBy { list, .. }
                                    | crate::KernelAbiContextualOperation::ThenBy { list, .. },
                                ) => {
                                    if let Some(list) =
                                        self.call_input_for_abi_parameter(expression, list)
                                    {
                                        self.list_item_sources(paths, list, projection, scratch);
                                    }
                                }
                                Some(
                                    crate::KernelAbiContextualOperation::Every { .. }
                                    | crate::KernelAbiContextualOperation::Any { .. }
                                    | crate::KernelAbiContextualOperation::Find { .. },
                                )
                                | None => {
                                    if self.call_syntax(expression).is_some_and(|syntax| {
                                        matches!(
                                            syntax.function.as_ref(),
                                            "List/take" | "List/page"
                                        )
                                    }) && let Some(list) =
                                        self.call_input_named(expression, "list")
                                    {
                                        self.list_item_sources(paths, list, projection, scratch);
                                    }
                                }
                            }
                        }
                    }
                }
            }
            PackedKernelOwnerNodeKind::Draining => {
                if let Some(input) = self.first_input(expression, |role| {
                    matches!(role, PackedKernelOwnerEdgeRole::DrainingInput)
                }) {
                    self.list_item_sources(paths, input, projection, scratch);
                }
            }
            PackedKernelOwnerNodeKind::Hold => {
                if let Some(input) = self.first_input(expression, |role| {
                    matches!(role, PackedKernelOwnerEdgeRole::HoldInitial)
                }) {
                    self.list_item_sources(paths, input, projection, scratch);
                }
            }
            PackedKernelOwnerNodeKind::Latest => {
                for input in self.inputs(expression) {
                    if matches!(&input.role, PackedKernelOwnerEdgeRole::LatestBranch)
                        && let Some(branch) = self.input_expression_key(expression, input)
                    {
                        self.list_item_sources(paths, branch, projection, scratch);
                    }
                }
            }
            PackedKernelOwnerNodeKind::When => {
                for input in self.inputs(expression) {
                    if matches!(&input.role, PackedKernelOwnerEdgeRole::WhenArm)
                        && let Some(arm) = self.input_expression_key(expression, input)
                    {
                        self.list_item_sources(paths, arm, projection, scratch);
                    }
                }
            }
            PackedKernelOwnerNodeKind::Then => {
                if let Some(output) = self.first_input(expression, |role| {
                    matches!(role, PackedKernelOwnerEdgeRole::ThenOutput)
                }) {
                    self.list_item_sources(paths, output, projection, scratch);
                }
            }
            PackedKernelOwnerNodeKind::MatchArm { .. } => {
                if let Some(output) = self.first_input(expression, |role| {
                    matches!(role, PackedKernelOwnerEdgeRole::MatchOutput)
                }) {
                    self.list_item_sources(paths, output, projection, scratch);
                }
            }
            PackedKernelOwnerNodeKind::Block => {
                if let Some(KernelExecutionShapeInput::Block {
                    result: Some(result),
                    ..
                }) = self.shape(expression)
                    && let Some(result) = packed_kernel_value_reference(
                        self.input(expression.owner)
                            .expect("checked expression owner"),
                        *result,
                        expression.expression.0 as usize,
                    )
                    .ok()
                    .and_then(|value| self.expression_key(expression.owner, value))
                {
                    self.list_item_sources(paths, result, projection, scratch);
                }
            }
            _ => {}
        }
        scratch.active.remove(&node);
    }

    fn output_sources(
        &self,
        paths: &mut ResourceProjectionArena,
        target: ResourceDeclarationKey,
        projection: ResourceProjectionId,
        scratch: &mut ResourceTraversalScratch,
    ) {
        let key = ResourceResolution::Output(target, projection);
        let node = key.node();
        if scratch.active.contains(&node) || !scratch.explored.insert(key) {
            return;
        }
        scratch.active.insert(node);
        for list in self
            .contextual_lists_by_output
            .get(&target)
            .into_iter()
            .flatten()
        {
            self.list_item_sources(paths, *list, projection, scratch);
        }
        for output in self
            .forwarded_outputs_by_formal
            .get(&target)
            .into_iter()
            .flatten()
        {
            self.output_sources(paths, *output, projection, scratch);
        }
        scratch.active.remove(&node);
    }
}

#[cfg(test)]
fn user_call_input_is_first_for_formal(
    inputs: &[KernelCallInputArtifact],
    input_index: usize,
    ordinal: u32,
) -> bool {
    !inputs[..input_index].iter().any(|earlier| {
        matches!(
            &earlier.role,
            KernelCallInputRole::Formal {
                ordinal: earlier_ordinal,
            } if *earlier_ordinal == ordinal
        )
    })
}

fn project_call_input_is_first_for_formal(
    call: KernelProjectCallRef<'_>,
    input_index: usize,
    ordinal: u32,
) -> bool {
    !call.inputs()[..input_index].iter().any(|earlier| {
        matches!(
            call.input_role(earlier),
            Ok(KernelCallInputRoleRef::Formal {
                ordinal: earlier_ordinal,
            }) if earlier_ordinal == ordinal
        )
    })
}

fn canonical_resource_payload_projection_id(
    text: &ProjectTextSnapshot,
    paths: &ResourceProjectionArena,
    projection: ResourceProjectionId,
) -> ResourceProjectionId {
    let name = |symbol: SymbolId| text.symbol(symbol).unwrap_or("");
    let mut stripped = projection;
    if paths.depth(stripped) >= 2
        && let Some(first) = paths.row(stripped)
        && matches!(name(first.head), "event" | "events")
    {
        stripped = first.tail;
    }
    let Some(first) = paths.row(stripped) else {
        return stripped;
    };
    let Some(second) = paths.row(first.tail) else {
        return stripped;
    };
    if second.tail != ResourceProjectionId::ROOT {
        return stripped;
    }
    if (name(first.head) == "change" && matches!(name(second.head), "text" | "bytes"))
        || (name(first.head) == "key_down" && name(second.head) == "key")
    {
        first.tail
    } else {
        stripped
    }
}

#[cfg(test)]
fn canonical_resource_payload_projection(
    text: &ProjectTextSnapshot,
    projection: &[SymbolId],
) -> Vec<SymbolId> {
    if projection.is_empty() {
        return Vec::new();
    }
    let name = |symbol: SymbolId| text.symbol(symbol).unwrap_or("");
    let stripped = if projection.len() >= 2
        && projection
            .first()
            .is_some_and(|symbol| matches!(name(*symbol), "event" | "events"))
    {
        &projection[1..]
    } else {
        projection
    };
    match stripped {
        [first, second] if name(*first) == "change" && name(*second) == "text" => vec![*second],
        [first, second] if name(*first) == "change" && name(*second) == "bytes" => vec![*second],
        [first, second] if name(*first) == "key_down" && name(*second) == "key" => vec![*second],
        _ => stripped.to_vec(),
    }
}

const fn contextual_operation_formals(
    operation: crate::KernelAbiContextualOperation,
) -> (u32, u32, u32) {
    match operation {
        crate::KernelAbiContextualOperation::Map { list, row, body }
        | crate::KernelAbiContextualOperation::Filter {
            list,
            row,
            predicate: body,
        }
        | crate::KernelAbiContextualOperation::Retain {
            list,
            row,
            predicate: body,
        }
        | crate::KernelAbiContextualOperation::Remove {
            list,
            row,
            predicate: body,
        }
        | crate::KernelAbiContextualOperation::Every {
            list,
            row,
            predicate: body,
        }
        | crate::KernelAbiContextualOperation::Any {
            list,
            row,
            predicate: body,
        }
        | crate::KernelAbiContextualOperation::Find {
            list,
            row,
            predicate: body,
        }
        | crate::KernelAbiContextualOperation::SortBy {
            list,
            row,
            key: body,
            ..
        }
        | crate::KernelAbiContextualOperation::ThenBy {
            list,
            row,
            key: body,
            ..
        } => (list, row, body),
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum ResourceNonspecificType {
    Absent,
    Unknown,
    Variable(TypeVariableId),
    UnresolvedShape(TypeTermId),
    OpenObject,
    ListOfOpenObject,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum ResourceTypeSpecificity {
    Specific,
    Nonspecific(ResourceNonspecificType),
}

fn packed_resource_projection_type_specificity(
    terms: &crate::TypeTermArena,
    term: TypeTermId,
) -> ResourceTypeSpecificity {
    match terms.term(term) {
        TypeTerm::Absent => ResourceTypeSpecificity::Nonspecific(ResourceNonspecificType::Absent),
        TypeTerm::UnresolvedShape(_) => {
            ResourceTypeSpecificity::Nonspecific(ResourceNonspecificType::UnresolvedShape(term))
        }
        TypeTerm::Unknown => ResourceTypeSpecificity::Nonspecific(ResourceNonspecificType::Unknown),
        TypeTerm::Variable(variable) => {
            ResourceTypeSpecificity::Nonspecific(ResourceNonspecificType::Variable(variable))
        }
        TypeTerm::OpenObjectPlaceholder => {
            ResourceTypeSpecificity::Nonspecific(ResourceNonspecificType::OpenObject)
        }
        TypeTerm::Object { fields, open } if open && fields.is_empty() => {
            ResourceTypeSpecificity::Nonspecific(ResourceNonspecificType::OpenObject)
        }
        TypeTerm::List(item) => match packed_resource_projection_type_specificity(terms, item) {
            ResourceTypeSpecificity::Nonspecific(ResourceNonspecificType::OpenObject) => {
                ResourceTypeSpecificity::Nonspecific(ResourceNonspecificType::ListOfOpenObject)
            }
            ResourceTypeSpecificity::Specific | ResourceTypeSpecificity::Nonspecific(_) => {
                ResourceTypeSpecificity::Specific
            }
        },
        TypeTerm::Union(members) => {
            let mut canonical = None;
            for member in members {
                match packed_resource_projection_type_specificity(terms, *member) {
                    ResourceTypeSpecificity::Specific => {
                        return ResourceTypeSpecificity::Specific;
                    }
                    ResourceTypeSpecificity::Nonspecific(ResourceNonspecificType::Absent) => {}
                    ResourceTypeSpecificity::Nonspecific(member) => match canonical {
                        None => canonical = Some(member),
                        Some(existing) if existing == member => {}
                        Some(_) => return ResourceTypeSpecificity::Specific,
                    },
                }
            }
            ResourceTypeSpecificity::Nonspecific(
                canonical.unwrap_or(ResourceNonspecificType::Absent),
            )
        }
        _ => ResourceTypeSpecificity::Specific,
    }
}

fn packed_resource_projection_type_is_specific(
    terms: &crate::TypeTermArena,
    term: TypeTermId,
) -> bool {
    matches!(
        packed_resource_projection_type_specificity(terms, term),
        ResourceTypeSpecificity::Specific
    )
}

fn project_resource_projection_facts(
    program: &PackedKernelProjectProgram,
    owners: &[KernelProjectOwnerOutputs],
    definition_facts: &[KernelDefinitionFactsInput],
    abi: &crate::KernelAbiInput,
    artifact: &mut UnsealedComponentArtifact,
) -> Result<Box<[DefinitionResourceProjectionFacts]>, KernelSolveError> {
    let mut resolver = ResourceProjectionResolver::new(
        program,
        owners,
        definition_facts,
        abi,
        artifact.terms().text_snapshot().clone(),
    )?;
    let mut facts = owners
        .iter()
        .map(|_| DefinitionResourceProjectionFacts::default())
        .collect::<Vec<_>>();
    for (owner_index, owner) in owners.iter().enumerate() {
        let owner_id = KernelOwnerId(u32::try_from(owner_index).map_err(|_| {
            KernelSolveError::new("kernel resource-projection owner count exceeds u32")
        })?);
        for expression_ordinal in 0..owner.expressions.len() {
            let expression =
                KernelExpressionId(u32::try_from(expression_ordinal).map_err(|_| {
                    KernelSolveError::new("kernel resource-projection expression count exceeds u32")
                })?);
            let Some(binding) = resolver.lexical(ResourceExpressionKey {
                owner: owner_id,
                expression,
            }) else {
                continue;
            };
            let KernelLexicalBindingTargetInput::Declaration(target_reference) = binding.target
            else {
                continue;
            };
            let expression_key = ResourceExpressionKey {
                owner: owner_id,
                expression,
            };
            let projection = resolver
                .lexical_projection(expression_key)
                .expect("indexed lexical binding has a projection");
            if projection == ResourceProjectionId::ROOT {
                continue;
            }
            let target = resolver
                .declaration_key(owner_id, target_reference)
                .ok_or_else(|| {
                    KernelSolveError::new(format!(
                        "kernel resource projection {} has no declaration authority",
                        binding.expression.0
                    ))
                })?;
            if binding.access == KernelLexicalAccess::Read
                && resolver.has_exact_source_read(target, projection)
            {
                continue;
            }
            let output = owner
                .expressions
                .get(binding.expression.0 as usize)
                .ok_or_else(|| {
                    KernelSolveError::new(format!(
                        "kernel resource projection expression {} is out of range",
                        binding.expression.0
                    ))
                })?;
            let base_term = artifact
                .output(*output)
                .ok_or_else(|| {
                    KernelSolveError::new(format!(
                        "kernel resource projection expression {} has no solved output",
                        binding.expression.0
                    ))
                })?
                .term();
            let required_term =
                if packed_resource_projection_type_is_specific(artifact.terms(), base_term) {
                    base_term
                } else {
                    let field = resolver
                        .paths
                        .depth(projection)
                        .checked_sub(1)
                        .and_then(|ordinal| resolver.paths.segment_at(projection, ordinal))
                        .and_then(|field| resolver.text.symbol(field));
                    match field {
                        Some(
                            "press" | "click" | "double_click" | "blur" | "change" | "key_down",
                        ) => artifact.terms_mut().object([], false),
                        Some("bytes") => artifact.terms_mut().bytes(crate::BytesTerm::Dynamic),
                        Some(_) => artifact.terms().text(),
                        None => artifact.terms().unknown(),
                    }
                };
            let origins = resolver.sources_for_declaration(target, projection);
            let definition = &mut facts[owner_index];
            let projection_start = u32::try_from(definition.symbols.len()).map_err(|_| {
                KernelSolveError::new("kernel resource-projection symbol count exceeds u32")
            })?;
            resolver
                .paths
                .extend_symbols(projection, &mut definition.symbols);
            let projection_len = resolver.paths.depth(projection);
            let origin_start = u32::try_from(definition.origins.len()).map_err(|_| {
                KernelSolveError::new("kernel resource-projection origin count exceeds u32")
            })?;
            for origin in resolver.cached_source_reads(origins) {
                let payload_projection_start =
                    u32::try_from(definition.symbols.len()).map_err(|_| {
                        KernelSolveError::new("kernel resource-projection symbol count exceeds u32")
                    })?;
                resolver
                    .paths
                    .extend_symbols(origin.payload_projection, &mut definition.symbols);
                definition.origins.push(PackedSourceReadInput {
                    owner: origin.owner,
                    source: origin.source,
                    payload_projection_start,
                    payload_projection_len: resolver.paths.depth(origin.payload_projection),
                });
            }
            let publishes_required_type = origins.len != 0
                && packed_resource_projection_type_is_specific(artifact.terms(), required_term)
                && !packed_resource_projection_type_is_specific(artifact.terms(), base_term);
            definition
                .requirements
                .push(ResourceProjectionRequirementFact {
                    expression: binding.expression,
                    target: target_reference,
                    projection_start,
                    projection_len,
                    origin_start,
                    origin_len: origins.len,
                    required_term,
                    publishes_required_type,
                });
        }
    }
    if std::env::var_os("BOON_KERNEL_TRACE").is_some() {
        let lexical_slots = resolver
            .lexical_by_expression
            .iter()
            .map(|rows| rows.len())
            .sum::<usize>();
        let fact_requirements = facts
            .iter()
            .map(|definition| definition.requirements.len())
            .sum::<usize>();
        let fact_origins = facts
            .iter()
            .map(|definition| definition.origins.len())
            .sum::<usize>();
        let fact_symbols = facts
            .iter()
            .map(|definition| definition.symbols.len())
            .sum::<usize>();
        let fact_requirement_capacity = facts
            .iter()
            .map(|definition| definition.requirements.capacity())
            .sum::<usize>();
        let fact_origin_capacity = facts
            .iter()
            .map(|definition| definition.origins.capacity())
            .sum::<usize>();
        let fact_symbol_capacity = facts
            .iter()
            .map(|definition| definition.symbols.capacity())
            .sum::<usize>();
        eprintln!(
            "kernel-resource-detail lexical_slots={lexical_slots} projection_rows={} projection_row_capacity={} projection_conses={} projection_cons_capacity={} source_path_keys={} source_expression_keys={} actual_formal_keys={} contextual_output_keys={} forwarded_output_keys={} cache_entries={} cache_capacity={} cached_sources={} cached_source_capacity={} scratch_explored_capacity={} scratch_active_capacity={} scratch_result_capacity={} requirements={fact_requirements} requirement_capacity={fact_requirement_capacity} origins={fact_origins} origin_capacity={fact_origin_capacity} symbols={fact_symbols} symbol_capacity={fact_symbol_capacity}",
            resolver.paths.rows.len(),
            resolver.paths.rows.capacity(),
            resolver.paths.conses.len(),
            resolver.paths.conses.capacity(),
            resolver.source_paths.len(),
            resolver.source_expressions.len(),
            resolver.actual_inputs_by_formal.len(),
            resolver.contextual_lists_by_output.len(),
            resolver.forwarded_outputs_by_formal.len(),
            resolver.declaration_cache.len(),
            resolver.declaration_cache.capacity(),
            resolver.cached_sources.len(),
            resolver.cached_sources.capacity(),
            resolver.scratch.explored.capacity(),
            resolver.scratch.active.capacity(),
            resolver.scratch.resolved.capacity(),
        );
    }
    Ok(facts.into_boxed_slice())
}

fn build_definition_code_builder(
    program: &PackedKernelProjectProgram,
    owners: &[KernelProjectOwnerOutputs],
    definition_facts: &[KernelDefinitionFactsInput],
    runtime_facts: Arc<crate::PackedDefinitionFactsStore>,
    abi: &crate::KernelAbiInput,
    artifact: &mut UnsealedComponentArtifact,
    flush_terms: &ProjectExpressionFlushTerms,
    call_facts: Box<[SolvedDefinitionCallFacts]>,
    diagnostics: &[SolvedDefinitionDiagnostics],
    resource_projection_facts: &[DefinitionResourceProjectionFacts],
    abi_catalog: crate::PackedAbiCatalogInput,
) -> Result<DefinitionCodeBuilder, KernelSolveError> {
    if call_facts.len() != owners.len()
        || diagnostics.len() != owners.len()
        || resource_projection_facts.len() != owners.len()
    {
        return Err(KernelSolveError::new(
            "kernel definition-code finalization received incomplete derived owner rows",
        ));
    }
    let flow_capacity = owners
        .iter()
        .map(|owner| owner.formals.len().saturating_add(owner.expressions.len()))
        .sum();
    let mut builder =
        DefinitionCodeBuilder::with_capacity(owners.len(), flow_capacity, flow_capacity);
    builder.use_prepared_runtime_facts(runtime_facts)?;
    builder.install_abi_catalog(abi_catalog)?;
    let mut formal_roots = Vec::new();
    let mut expression_roots = Vec::new();
    let mut packed_formal_flows = Vec::new();
    let mut packed_expression_flows = Vec::new();
    let mut expression_kind_types = Vec::new();
    let mut declaration_flows = Vec::new();
    let mut packed_diagnostic_types = Vec::new();
    let mut source_payload_types = Vec::new();
    let mut state_flows = Vec::new();
    let mut published_states = Vec::new();
    let mut list_item_types = Vec::new();
    let mut packed_resource_projection_requirements = Vec::new();
    let mut proof_scratch = DefinitionTermProofScratch::default();
    let mut callable_type_scratch = crate::PackedCallableParameterTraversalScratch::default();
    let mut callable_parameter_sources = Vec::new();
    let mut callable_type_parameters = Vec::new();
    let owner_effects = project_owner_effect_summaries(program, definition_facts);
    let synthetic_state_ordinals =
        allocate_project_synthetic_state_ordinals(program, owners, definition_facts);
    for (owner_index, (owner, owner_call_facts)) in
        owners.iter().zip(call_facts.into_vec()).enumerate()
    {
        let SolvedDefinitionCallFacts {
            calls: packed_calls,
            entries: packed_call_entries,
            contexts: packed_call_contexts,
            substitutions: packed_call_substitutions,
        } = owner_call_facts;
        let resource_projection_facts = &resource_projection_facts[owner_index];
        formal_roots.clear();
        formal_roots.extend(
            owner
                .formals
                .iter()
                .zip(owner.formal_modes.iter().copied())
                .map(|(output, mode)| {
                    (
                        artifact
                            .output(*output)
                            .expect("project owner formal belongs to its component")
                            .term(),
                        mode,
                    )
                }),
        );
        expression_roots.clear();
        expression_roots.extend(
            owner
                .expressions
                .iter()
                .zip(owner.expression_modes.iter().copied())
                .map(|(output, mode)| {
                    (
                        artifact
                            .output(*output)
                            .expect("project owner expression belongs to its component")
                            .term(),
                        mode,
                    )
                }),
        );
        let input = program.owner_at(owner_index).ok_or_else(|| {
            KernelSolveError::new(format!(
                "kernel definition-code omits packed owner {owner_index}"
            ))
        })?;
        expression_kind_types.clear();
        for expression in input.nodes() {
            let term = match &expression.kind {
                PackedKernelOwnerNodeKind::Known(reference)
                | PackedKernelOwnerNodeKind::Source(reference)
                | PackedKernelOwnerNodeKind::FixedAbiCall { result: reference } => Some(
                    artifact.terms().resolve_type_ref(*reference).ok_or_else(|| {
                        KernelSolveError::new(
                            "kernel expression type reference belongs to another project authority",
                        )
                    })?,
                ),
                _ => None,
            };
            expression_kind_types.push(term);
        }
        declaration_flows.clear();
        for declaration in &definition_facts[owner_index].declarations {
            declaration_flows.push(declaration.declared_flow_type.as_ref().map(|flow| {
                PackedFlow {
                    mode: flow.mode,
                    term: import_post_solve_type(artifact.terms_mut(), &flow.ty),
                }
            }));
        }
        if packed_calls.len() != owner.calls.len() {
            return Err(KernelSolveError::new(format!(
                "kernel definition-code owner {owner_index} has {} calls and {} solved call rows",
                owner.calls.len(),
                packed_calls.len()
            )));
        }
        if packed_calls
            .iter()
            .zip(&owner.calls)
            .any(|(facts, solve)| facts.expression != solve.expression)
        {
            return Err(KernelSolveError::new(format!(
                "kernel definition-code owner {owner_index} call rows lost expression alignment",
            )));
        }
        packed_diagnostic_types.clear();
        packed_diagnostic_types.extend(
            diagnostics[owner_index]
                .rows
                .iter()
                .map(|diagnostic| diagnostic.types),
        );
        source_payload_types.clear();
        for source in &definition_facts[owner_index].sources {
            let output = owner.expressions[source.expression.0 as usize];
            source_payload_types.push(
                artifact
                    .output(output)
                    .expect("kernel SOURCE expression belongs to its solved component")
                    .term(),
            );
        }
        state_flows.clear();
        published_states.clear();
        for (input_ordinal, (state, synthetic_ordinal)) in definition_facts[owner_index]
            .states
            .iter()
            .zip(synthetic_state_ordinals[owner_index].iter().copied())
            .enumerate()
            .filter(|(_, (state, _))| {
                packed_state_input_candidate_survives(input, state, &owner.expression_modes)
            })
        {
            if state.synthetic_path != synthetic_ordinal.is_some() {
                return Err(KernelSolveError::new(format!(
                    "kernel definition-code owner {owner_index} state input {input_ordinal} disagrees with its synthetic-path ordinal",
                )));
            }
            let expression = state.expression.0 as usize;
            let output = owner.expressions[expression];
            let flow = PackedFlow {
                mode: owner.expression_modes[expression],
                term: artifact
                    .output(output)
                    .expect("kernel state expression belongs to its solved component")
                    .term(),
            };
            state_flows.push(flow);
            published_states.push(PackedPublishedState::new(
                u32::try_from(input_ordinal)
                    .expect("kernel state input count exceeds dense u32 namespace"),
                synthetic_ordinal,
                flow,
            ));
        }
        list_item_types.clear();
        for list in &definition_facts[owner_index].lists {
            let producer = owner.expressions[list.producer.0 as usize];
            let producer = artifact
                .output(producer)
                .expect("kernel LIST producer belongs to its solved component")
                .term();
            let authority = match list.declaration {
                KernelDeclarationReference::OwnerPublic(target) => {
                    let target = owners
                        .get(target.0 as usize)
                        .and_then(|target| artifact.output(target.result))
                        .map(|output| output.term());
                    target
                        .filter(|term| {
                            matches!(artifact.terms().term_head(*term), TypeTermHead::List(_))
                        })
                        .unwrap_or(producer)
                }
                KernelDeclarationReference::Local(_)
                | KernelDeclarationReference::OwnerDeclaration { .. } => producer,
            };
            let TypeTermHead::List(item) = artifact.terms().term_head(authority) else {
                return Err(KernelSolveError::new(format!(
                    "kernel definition {owner_index} LIST {} has non-list type authority",
                    list.id.0
                )));
            };
            list_item_types.push(item);
        }
        let result_mode = owner
            .expressions
            .iter()
            .position(|output| *output == owner.result)
            .map(|index| owner.expression_modes[index])
            .expect("project owner result belongs to its expression outputs");
        let expression_flush_types = flush_terms.definition(owner_index).ok_or_else(|| {
            KernelSolveError::new(format!(
                "kernel definition-code owner {owner_index} has no packed FLUSH rows"
            ))
        })?;
        proof_scratch.begin_alpha_variables(artifact.terms());
        for (term, _) in &formal_roots {
            proof_scratch.visit_alpha_root(artifact.terms(), *term)?;
        }
        let result_term = artifact
            .output(owner.result)
            .expect("project owner result belongs to its component")
            .term();
        proof_scratch.visit_alpha_root(artifact.terms(), result_term)?;
        for (ordinal, (term, _)) in expression_roots.iter().enumerate() {
            proof_scratch.visit_alpha_root(artifact.terms(), *term)?;
            if let Some(term) = expression_flush_types[ordinal] {
                proof_scratch.visit_alpha_root(artifact.terms(), term)?;
            }
            if let Some(term) = expression_kind_types[ordinal] {
                proof_scratch.visit_alpha_root(artifact.terms(), term)?;
            }
        }
        for flow in declaration_flows.iter().flatten() {
            proof_scratch.visit_alpha_root(artifact.terms(), flow.term)?;
        }
        for facts in &packed_calls {
            let start = facts.substitution_start as usize;
            let end = start + facts.substitution_len as usize;
            for substitution in &packed_call_substitutions[start..end] {
                proof_scratch.visit_alpha_root(artifact.terms(), substitution.term)?;
            }
        }
        for term in source_payload_types.iter().copied() {
            proof_scratch.visit_alpha_root(artifact.terms(), term)?;
        }
        for flow in &state_flows {
            proof_scratch.visit_alpha_root(artifact.terms(), flow.term)?;
        }
        for term in list_item_types.iter().copied() {
            proof_scratch.visit_alpha_root(artifact.terms(), term)?;
        }
        for diagnostic in packed_diagnostic_types.iter().flatten() {
            proof_scratch.visit_alpha_root(artifact.terms(), diagnostic.actual)?;
            proof_scratch.visit_alpha_root(artifact.terms(), diagnostic.expected)?;
        }
        for requirement in &resource_projection_facts.requirements {
            proof_scratch.visit_alpha_root(artifact.terms(), requirement.required_term)?;
        }
        collect_packed_callable_type_parameter_sources(
            artifact.terms(),
            formal_roots.iter().map(|(term, _)| *term),
            result_term,
            &mut callable_type_scratch,
            &mut callable_parameter_sources,
        );
        callable_type_parameters.clear();
        for source in callable_parameter_sources.iter().copied() {
            let linked_local = proof_scratch
                .alpha_variable_sources()
                .iter()
                .position(|candidate| *candidate == source)
                .ok_or_else(|| {
                    KernelSolveError::new(format!(
                        "kernel definition-code owner {owner_index} callable parameter {} is absent from its linked alpha authority",
                        source.0,
                    ))
                })?;
            callable_type_parameters.push(PackedCallableTypeParameter {
                source,
                linked_local: u32::try_from(linked_local).map_err(|_| {
                    KernelSolveError::new(
                        "kernel definition callable parameter ordinal exceeds u32",
                    )
                })?,
            });
        }
        let stable_digest = definition_code_types_stable_digest(
            artifact.terms(),
            &mut proof_scratch,
            (result_term, result_mode),
            &formal_roots,
            &expression_roots,
            expression_flush_types,
            &expression_kind_types,
            &declaration_flows,
            &packed_calls,
            &packed_call_substitutions,
            &packed_diagnostic_types,
            &source_payload_types,
            &state_flows,
            &list_item_types,
            &resource_projection_facts.requirements,
            &resource_projection_facts.origins,
            &resource_projection_facts.symbols,
        )?;
        packed_formal_flows.clear();
        for (term, mode) in &formal_roots {
            packed_formal_flows.push(proof_scratch.materialize_alpha_flow_root(
                artifact.terms(),
                *term,
                *mode,
            )?);
        }
        let result_flow = proof_scratch.materialize_alpha_flow_root(
            artifact.terms(),
            result_term,
            result_mode,
        )?;
        packed_expression_flows.clear();
        for (term, mode) in &expression_roots {
            packed_expression_flows.push(proof_scratch.materialize_alpha_flow_root(
                artifact.terms(),
                *term,
                *mode,
            )?);
        }
        packed_resource_projection_requirements.clear();
        for requirement in &resource_projection_facts.requirements {
            let mode = *owner
                .expression_modes
                .get(requirement.expression.0 as usize)
                .ok_or_else(|| {
                    KernelSolveError::new(format!(
                        "kernel definition-code owner {owner_index} resource projection references missing expression {}",
                        requirement.expression.0,
                    ))
                })?;
            let published_expression = requirement
                .publishes_required_type
                .then(|| {
                    proof_scratch.materialize_alpha_flow_root(
                        artifact.terms(),
                        requirement.required_term,
                        mode,
                    )
                })
                .transpose()?;
            packed_resource_projection_requirements.push(
                PackedResourceProjectionRequirementInput {
                    expression: requirement.expression,
                    target: requirement.target,
                    projection_start: requirement.projection_start,
                    projection_len: requirement.projection_len,
                    origin_start: requirement.origin_start,
                    origin_len: requirement.origin_len,
                    required_term: requirement.required_term,
                    published_expression,
                },
            );
        }
        builder.push(
            KernelOwnerId(
                u32::try_from(owner_index)
                    .expect("kernel definition count exceeds the dense u32 namespace"),
            ),
            result_flow,
            &packed_formal_flows,
            &packed_expression_flows,
            DefinitionAdditionalTypeRoots {
                effect_summary: owner_effects[owner_index],
                basis_fingerprint_v14: owner.basis_fingerprint_v14,
                expression_flush_types,
                expression_kind_types: &expression_kind_types,
                declaration_flows: &declaration_flows,
                calls: &packed_calls,
                call_entries: &packed_call_entries,
                call_contexts: &packed_call_contexts,
                call_substitutions: &packed_call_substitutions,
                source_payload_types: &source_payload_types,
                state_input_count: definition_facts[owner_index].states.len(),
                states: &published_states,
                list_item_types: &list_item_types,
                resource_projection_requirements: &packed_resource_projection_requirements,
                resource_projection_origins: &resource_projection_facts.origins,
                resource_projection_symbols: &resource_projection_facts.symbols,
                alpha_variables: proof_scratch.alpha_variable_sources(),
                callable_type_parameters: &callable_type_parameters,
                stable_digest,
            },
        )?;
    }
    build_definition_execution_code(program, owners, definition_facts, abi, &mut builder)?;
    Ok(builder)
}

#[derive(Clone, Copy, Debug, Eq, Ord, PartialEq, PartialOrd)]
struct PackedDeclarationKey {
    owner: KernelOwnerId,
    declaration: KernelDeclarationId,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct PackedStatementRef {
    owner: KernelOwnerId,
    statement: KernelStatementId,
}

fn definition_execution_owner<'a>(
    owners: &'a [KernelProjectOwnerOutputs],
    owner: KernelOwnerId,
    context: &str,
) -> Result<&'a KernelProjectOwnerOutputs, KernelSolveError> {
    owners.get(owner.0 as usize).ok_or_else(|| {
        KernelSolveError::new(format!(
            "kernel packed execution {context} references missing owner {}",
            owner.0,
        ))
    })
}

fn definition_execution_expression(
    program: &PackedKernelProjectProgram,
    owner: KernelOwnerId,
    expression: KernelExpressionId,
    context: &str,
) -> Result<PackedExpressionRef, KernelSolveError> {
    if program
        .owner(owner)
        .and_then(|definition| definition.node(expression))
        .is_none()
    {
        return Err(KernelSolveError::new(format!(
            "kernel packed execution {context} references missing expression {}:{}",
            owner.0, expression.0,
        )));
    }
    Ok(PackedExpressionRef::new(owner, expression))
}

fn definition_execution_value(
    program: &PackedKernelProjectProgram,
    definition_facts: &[KernelDefinitionFactsInput],
    owner: KernelOwnerId,
    value: KernelValueReference,
    context: &str,
) -> Result<PackedExpressionRef, KernelSolveError> {
    match value {
        KernelValueReference::Local(expression) => {
            definition_execution_expression(program, owner, expression, context)
        }
        KernelValueReference::External(external) => match external.target {
            KernelExternalTarget::Expression(expression) => {
                definition_execution_expression(program, external.owner, expression, context)
            }
            KernelExternalTarget::Result => {
                let expression = definition_facts
                    .get(external.owner.0 as usize)
                    .and_then(|facts| facts.linkage.result_expression)
                    .ok_or_else(|| {
                        KernelSolveError::new(format!(
                            "kernel packed execution {context} references owner {} without a result expression",
                            external.owner.0,
                        ))
                    })?;
                definition_execution_expression(program, external.owner, expression, context)
            }
        },
    }
}

fn definition_execution_declaration(
    definition_facts: &[KernelDefinitionFactsInput],
    mut owner: KernelOwnerId,
    mut reference: KernelDeclarationReference,
    context: &str,
) -> Result<PackedDeclarationKey, KernelSolveError> {
    for _ in 0..=definition_facts.len() {
        match reference {
            KernelDeclarationReference::Local(declaration) => {
                if !definition_facts
                    .get(owner.0 as usize)
                    .and_then(|facts| facts.declarations.get(declaration.0 as usize))
                    .is_some_and(|row| row.id == declaration)
                {
                    return Err(KernelSolveError::new(format!(
                        "kernel packed execution {context} references missing declaration {}:{}",
                        owner.0, declaration.0,
                    )));
                }
                return Ok(PackedDeclarationKey { owner, declaration });
            }
            KernelDeclarationReference::OwnerDeclaration {
                owner: target,
                declaration,
            } => {
                owner = target;
                reference = KernelDeclarationReference::Local(declaration);
            }
            KernelDeclarationReference::OwnerPublic(target) => {
                owner = target;
                reference = definition_facts
                    .get(target.0 as usize)
                    .ok_or_else(|| {
                        KernelSolveError::new(format!(
                            "kernel packed execution {context} references missing owner {}",
                            target.0,
                        ))
                    })?
                    .linkage
                    .public_declaration
                    .ok_or_else(|| {
                        KernelSolveError::new(format!(
                            "kernel packed execution {context} references owner {} without a public declaration",
                            target.0,
                        ))
                    })?;
            }
        }
    }
    Err(KernelSolveError::new(format!(
        "kernel packed execution {context} contains a public-declaration cycle",
    )))
}

fn definition_execution_scope_callable(
    definition_facts: &[KernelDefinitionFactsInput],
    mut owner: KernelOwnerId,
    mut scope: KernelScopeReference,
    context: &str,
) -> Result<Option<PackedDeclarationKey>, KernelSolveError> {
    let scope_limit = definition_facts
        .iter()
        .map(|facts| facts.presentation.scopes.len())
        .sum::<usize>()
        .saturating_add(definition_facts.len())
        .saturating_add(1);
    for _ in 0..scope_limit {
        match scope {
            KernelScopeReference::ProjectRoot => return Ok(None),
            KernelScopeReference::Containing => {
                scope = definition_facts
                    .get(owner.0 as usize)
                    .ok_or_else(|| {
                        KernelSolveError::new(format!(
                            "kernel packed execution {context} references missing definition facts {}",
                            owner.0,
                        ))
                    })?
                    .presentation
                    .containing_scope;
            }
            KernelScopeReference::Owner {
                owner: target,
                scope: target_scope,
            } => {
                owner = target;
                scope = KernelScopeReference::Local(target_scope);
            }
            KernelScopeReference::Local(scope_id) => {
                let facts = definition_facts.get(owner.0 as usize).ok_or_else(|| {
                    KernelSolveError::new(format!(
                        "kernel packed execution {context} references missing definition facts {}",
                        owner.0,
                    ))
                })?;
                let row = facts
                    .presentation
                    .scopes
                    .get(scope_id.0 as usize)
                    .filter(|row| row.id == scope_id)
                    .ok_or_else(|| {
                        KernelSolveError::new(format!(
                            "kernel packed execution {context} references missing scope {}:{}",
                            owner.0, scope_id.0,
                        ))
                    })?;
                if row.kind == KernelScopeKind::Function {
                    return row
                        .owner
                        .map(|declaration| {
                            definition_execution_declaration(
                                definition_facts,
                                owner,
                                declaration,
                                context,
                            )
                        })
                        .transpose();
                }
                scope = row.parent;
            }
        }
    }
    Err(KernelSolveError::new(format!(
        "kernel packed execution {context} contains a lexical-scope cycle",
    )))
}

fn definition_execution_statement<'a>(
    definition_facts: &'a [KernelDefinitionFactsInput],
    owner: KernelOwnerId,
    statement: KernelStatementId,
    context: &str,
) -> Result<&'a KernelStatementInput, KernelSolveError> {
    definition_facts
        .get(owner.0 as usize)
        .ok_or_else(|| {
            KernelSolveError::new(format!(
                "kernel packed execution {context} references missing owner {}",
                owner.0,
            ))
        })?
        .statements
        .get(statement.0 as usize)
        .filter(|row| row.id == statement)
        .ok_or_else(|| {
            KernelSolveError::new(format!(
                "kernel packed execution {context} references missing statement {}:{}",
                owner.0, statement.0,
            ))
        })
}

fn definition_execution_statement_child(
    definition_facts: &[KernelDefinitionFactsInput],
    owner: KernelOwnerId,
    child: KernelStatementChildReference,
) -> Result<PackedStatementRef, KernelSolveError> {
    let reference = match child {
        KernelStatementChildReference::Local(statement) => PackedStatementRef { owner, statement },
        KernelStatementChildReference::Owner(owner) => PackedStatementRef {
            owner,
            statement: definition_facts
                .get(owner.0 as usize)
                .ok_or_else(|| {
                    KernelSolveError::new(format!(
                        "kernel packed execution statement child references missing owner {}",
                        owner.0,
                    ))
                })?
                .linkage
                .root_statement
                .ok_or_else(|| {
                    KernelSolveError::new(format!(
                        "kernel packed execution statement child owner {} has no root statement",
                        owner.0,
                    ))
                })?,
        },
    };
    definition_execution_statement(
        definition_facts,
        reference.owner,
        reference.statement,
        "statement child",
    )?;
    Ok(reference)
}

fn definition_execution_offsets(
    counts: impl IntoIterator<Item = usize>,
    label: &str,
) -> Result<Vec<u32>, KernelSolveError> {
    let mut offsets = Vec::new();
    offsets.push(0_u32);
    for count in counts {
        let count = u32::try_from(count).map_err(|_| {
            KernelSolveError::new(format!(
                "kernel packed execution {label} definition count exceeds u32",
            ))
        })?;
        let next = offsets
            .last()
            .copied()
            .expect("packed execution offsets contain their zero origin")
            .checked_add(count)
            .ok_or_else(|| {
                KernelSolveError::new(format!(
                    "kernel packed execution {label} namespace exceeds u32",
                ))
            })?;
        offsets.push(next);
    }
    Ok(offsets)
}

fn definition_execution_expression_index(
    offsets: &[u32],
    expression: PackedExpressionRef,
) -> Result<usize, KernelSolveError> {
    let owner = expression.owner().0 as usize;
    let start = *offsets.get(owner).ok_or_else(|| {
        KernelSolveError::new(format!(
            "kernel packed execution expression references missing owner {}",
            expression.owner().0,
        ))
    })?;
    let end = *offsets.get(owner + 1).ok_or_else(|| {
        KernelSolveError::new(format!(
            "kernel packed execution expression owner {} has no range end",
            expression.owner().0,
        ))
    })?;
    let index = start
        .checked_add(expression.expression().0)
        .filter(|index| *index < end)
        .ok_or_else(|| {
            KernelSolveError::new(format!(
                "kernel packed execution expression {}:{} is outside its dense range",
                expression.owner().0,
                expression.expression().0,
            ))
        })?;
    Ok(index as usize)
}

fn definition_execution_statement_index(
    offsets: &[u32],
    statement: PackedStatementRef,
) -> Result<usize, KernelSolveError> {
    let owner = statement.owner.0 as usize;
    let start = *offsets.get(owner).ok_or_else(|| {
        KernelSolveError::new(format!(
            "kernel packed execution statement references missing owner {}",
            statement.owner.0,
        ))
    })?;
    let end = *offsets.get(owner + 1).ok_or_else(|| {
        KernelSolveError::new(format!(
            "kernel packed execution statement owner {} has no range end",
            statement.owner.0,
        ))
    })?;
    let index = start
        .checked_add(statement.statement.0)
        .filter(|index| *index < end)
        .ok_or_else(|| {
            KernelSolveError::new(format!(
                "kernel packed execution statement {}:{} is outside its dense range",
                statement.owner.0, statement.statement.0,
            ))
        })?;
    Ok(index as usize)
}

fn definition_execution_call_syntax<'a>(
    facts: &'a KernelDefinitionFactsInput,
    expression: KernelExpressionId,
) -> Result<&'a KernelCallSyntaxInput, KernelSolveError> {
    let mut matching = facts
        .call_syntax
        .iter()
        .filter(|syntax| syntax.expression == expression);
    let syntax = matching.next().ok_or_else(|| {
        KernelSolveError::new(format!(
            "kernel packed execution call expression {} has no authored syntax",
            expression.0,
        ))
    })?;
    if matching.next().is_some() {
        return Err(KernelSolveError::new(format!(
            "kernel packed execution repeats call syntax for expression {}",
            expression.0,
        )));
    }
    Ok(syntax)
}

fn append_definition_execution_statement_dependencies(
    program: &PackedKernelProjectProgram,
    definition_facts: &[KernelDefinitionFactsInput],
    expression_offsets: &[u32],
    statement_offsets: &[u32],
    root: PackedExpressionRef,
    statement_root_by_expression: &[Option<PackedStatementRef>],
    statement_generations: &mut [u32],
    generation: u32,
    statement_stack: &mut Vec<PackedStatementRef>,
    dependencies: &mut Vec<PackedExpressionRef>,
) -> Result<(), KernelSolveError> {
    let Some(root_statement) = statement_root_by_expression
        .get(definition_execution_expression_index(
            expression_offsets,
            root,
        )?)
        .copied()
        .flatten()
    else {
        return Ok(());
    };
    let root_row = definition_execution_statement(
        definition_facts,
        root_statement.owner,
        root_statement.statement,
        "statement dependency root",
    )?;
    statement_stack.clear();
    for child in root_row.children.iter().rev().copied() {
        statement_stack.push(definition_execution_statement_child(
            definition_facts,
            root_statement.owner,
            child,
        )?);
    }
    while let Some(statement) = statement_stack.pop() {
        let index = definition_execution_statement_index(statement_offsets, statement)?;
        let seen = statement_generations.get_mut(index).ok_or_else(|| {
            KernelSolveError::new("kernel packed execution statement generation is out of range")
        })?;
        if *seen == generation {
            continue;
        }
        *seen = generation;
        let row = definition_execution_statement(
            definition_facts,
            statement.owner,
            statement.statement,
            "statement dependency",
        )?;
        let value = row
            .value
            .map(|encoded| {
                let value = packed_kernel_value_reference(
                    program.owner(statement.owner).ok_or_else(|| {
                        KernelSolveError::new(format!(
                            "kernel packed execution statement references missing owner {}",
                            statement.owner.0,
                        ))
                    })?,
                    encoded,
                    statement.statement.0 as usize,
                )
                .map_err(|error| KernelSolveError::new(error.to_string()))?;
                definition_execution_value(
                    program,
                    definition_facts,
                    statement.owner,
                    value,
                    "statement dependency value",
                )
            })
            .transpose()?;
        if let Some(value) = value
            && value != root
        {
            dependencies.push(value);
            continue;
        }
        for child in row.children.iter().rev().copied() {
            statement_stack.push(definition_execution_statement_child(
                definition_facts,
                statement.owner,
                child,
            )?);
        }
    }
    Ok(())
}

fn definition_execution_conditional_shape<'a>(
    facts: &'a KernelDefinitionFactsInput,
    expression: KernelExpressionId,
) -> Result<Option<&'a KernelExecutionShapeInput>, KernelSolveError> {
    let mut matching = facts.execution_shapes.iter().filter(|shape| {
        shape.expression() == expression
            && matches!(shape, KernelExecutionShapeInput::Conditional { .. })
    });
    let shape = matching.next();
    if matching.next().is_some() {
        return Err(KernelSolveError::new(format!(
            "kernel packed execution repeats a conditional shape for expression {}",
            expression.0,
        )));
    }
    Ok(shape)
}

fn definition_execution_block_shape<'a>(
    facts: &'a KernelDefinitionFactsInput,
    expression: KernelExpressionId,
) -> Result<&'a KernelExecutionShapeInput, KernelSolveError> {
    let mut matching = facts.execution_shapes.iter().filter(|shape| {
        shape.expression() == expression && matches!(shape, KernelExecutionShapeInput::Block { .. })
    });
    let shape = matching.next().ok_or_else(|| {
        KernelSolveError::new(format!(
            "kernel packed execution BLOCK expression {} has no shape",
            expression.0,
        ))
    })?;
    if matching.next().is_some() {
        return Err(KernelSolveError::new(format!(
            "kernel packed execution repeats a BLOCK shape for expression {}",
            expression.0,
        )));
    }
    Ok(shape)
}

#[allow(clippy::too_many_arguments)]
fn collect_definition_execution_dependencies(
    program: &PackedKernelProjectProgram,
    owners: &[KernelProjectOwnerOutputs],
    definition_facts: &[KernelDefinitionFactsInput],
    abi: &crate::KernelAbiInput,
    expression_offsets: &[u32],
    statement_offsets: &[u32],
    call_by_expression: &[u32],
    statement_root_by_expression: &[Option<PackedStatementRef>],
    read_provider_present: &[bool],
    read_provider_callable: &[Option<PackedDeclarationKey>],
    template_callable: PackedDeclarationKey,
    expression: PackedExpressionRef,
    statement_generations: &mut [u32],
    statement_generation: &mut u32,
    statement_stack: &mut Vec<PackedStatementRef>,
    dependencies: &mut Vec<PackedExpressionRef>,
) -> Result<(), KernelSolveError> {
    dependencies.clear();
    let owner = expression.owner();
    let definition = definition_execution_owner(owners, owner, "node dependency")?;
    let facts = definition_facts.get(owner.0 as usize).ok_or_else(|| {
        KernelSolveError::new(format!(
            "kernel packed execution references missing definition facts {}",
            owner.0,
        ))
    })?;
    let owner_input = program.owner(owner).ok_or_else(|| {
        KernelSolveError::new(format!(
            "kernel packed execution references missing owner {}",
            owner.0,
        ))
    })?;
    let expression_row = owner_input.node(expression.expression()).ok_or_else(|| {
        KernelSolveError::new(format!(
            "kernel packed execution references missing node {}:{}",
            owner.0,
            expression.expression().0,
        ))
    })?;
    let payload = facts
        .expression_payloads
        .get(expression.expression().0 as usize)
        .ok_or_else(|| {
            KernelSolveError::new(format!(
                "kernel packed execution node {}:{} has no semantic payload",
                owner.0,
                expression.expression().0,
            ))
        })?;
    if matches!(payload, KernelExpressionSemanticPayload::Delimiter) {
        return Ok(());
    }
    let resolve_input = |input: &crate::PackedKernelOwnerInputEdge| {
        packed_kernel_value_reference(
            owner_input,
            input.expression,
            expression.expression().0 as usize,
        )
        .map_err(|error| KernelSolveError::new(error.to_string()))
    };

    let flat_expression = definition_execution_expression_index(expression_offsets, expression)?;
    let call_ordinal = *call_by_expression.get(flat_expression).ok_or_else(|| {
        KernelSolveError::new("kernel packed execution call index is out of range")
    })?;
    if call_ordinal != u32::MAX {
        let definition_ref = KernelDefinitionInputRef {
            owner,
            input: owner_input,
            facts,
            outputs: definition,
        };
        let call = definition_ref
            .call(call_ordinal as usize)
            .filter(|call| call.expression() == expression.expression())
            .ok_or_else(|| {
                KernelSolveError::new(format!(
                    "kernel packed execution call {}:{} is missing",
                    owner.0, call_ordinal,
                ))
            })?;
        let user_call = call.target().is_user();
        let abi_callable = if user_call {
            None
        } else {
            let syntax = definition_execution_call_syntax(facts, expression.expression())?;
            Some(abi.callable(&syntax.function).ok_or_else(|| {
                KernelSolveError::new(format!(
                    "kernel packed execution call `{}` has no immutable ABI contract",
                    syntax.function,
                ))
            })?)
        };
        for input in expression_row.inputs(owner_input) {
            let consumed = match (user_call, &input.role) {
                (true, PackedKernelOwnerEdgeRole::CallArgument { .. }) => true,
                (true, PackedKernelOwnerEdgeRole::CallOutArgument { .. }) => false,
                (false, PackedKernelOwnerEdgeRole::AbiArgument { name }) => {
                    let name = owner_input.symbol(*name).ok_or_else(|| {
                        KernelSolveError::new(
                            "kernel packed execution ABI argument name is outside its text authority",
                        )
                    })?;
                    let callable = abi_callable.expect("non-user call has an ABI contract");
                    let parameter = callable
                        .parameters
                        .iter()
                        .find(|parameter| parameter.name.as_ref() == name)
                        .or_else(|| {
                            (name == "$pipe").then(|| {
                                callable
                                    .parameters
                                    .iter()
                                    .find(|parameter| parameter.kind == CheckedParameterKind::Value)
                            })?
                        })
                        .ok_or_else(|| {
                            KernelSolveError::new(format!(
                                "kernel packed execution call `{}` has no ABI parameter `{name}`",
                                callable.name,
                            ))
                        })?;
                    parameter.kind == CheckedParameterKind::Value
                }
                (_, role) => {
                    return Err(KernelSolveError::new(format!(
                        "kernel packed execution call {}:{} has non-call input role {role:?}",
                        owner.0,
                        expression.expression().0,
                    )));
                }
            };
            if consumed {
                let value = resolve_input(input)?;
                dependencies.push(definition_execution_value(
                    program,
                    definition_facts,
                    owner,
                    value,
                    "call dependency",
                )?);
            }
        }
        dependencies.sort_unstable();
        dependencies.dedup();
        return Ok(());
    }

    for input in expression_row.inputs(owner_input) {
        if matches!(
            input.role,
            PackedKernelOwnerEdgeRole::CallOutArgument { .. }
                | PackedKernelOwnerEdgeRole::HoldUpdate
        ) {
            continue;
        }
        if matches!(input.role, PackedKernelOwnerEdgeRole::ReadProvider) {
            let present = *read_provider_present.get(flat_expression).ok_or_else(|| {
                KernelSolveError::new(
                    "kernel packed execution read-provider presence index is out of range",
                )
            })?;
            if !present {
                return Err(KernelSolveError::new(format!(
                    "kernel packed execution read {}:{} has no lexical callable authority",
                    owner.0,
                    expression.expression().0,
                )));
            }
            if read_provider_callable
                .get(flat_expression)
                .copied()
                .flatten()
                != Some(template_callable)
            {
                continue;
            }
        }
        let value = resolve_input(input)?;
        dependencies.push(definition_execution_value(
            program,
            definition_facts,
            owner,
            value,
            "expression dependency",
        )?);
    }

    if matches!(
        expression_row.kind,
        PackedKernelOwnerNodeKind::Hold | PackedKernelOwnerNodeKind::MatchArm { .. }
    ) {
        *statement_generation = statement_generation.wrapping_add(1);
        if *statement_generation == 0 {
            statement_generations.fill(0);
            *statement_generation = 1;
        }
        append_definition_execution_statement_dependencies(
            program,
            definition_facts,
            expression_offsets,
            statement_offsets,
            expression,
            statement_root_by_expression,
            statement_generations,
            *statement_generation,
            statement_stack,
            dependencies,
        )?;
    }
    if matches!(expression_row.kind, PackedKernelOwnerNodeKind::Block) {
        let KernelExecutionShapeInput::Block {
            bindings, result, ..
        } = definition_execution_block_shape(facts, expression.expression())?
        else {
            unreachable!("BLOCK shape helper returned a non-BLOCK row")
        };
        for binding in bindings {
            let value = packed_kernel_value_reference(
                owner_input,
                binding.value,
                expression.expression().0 as usize,
            )
            .map_err(|error| KernelSolveError::new(error.to_string()))?;
            dependencies.push(definition_execution_value(
                program,
                definition_facts,
                owner,
                value,
                "BLOCK binding dependency",
            )?);
        }
        if let Some(result) = result {
            let value = packed_kernel_value_reference(
                owner_input,
                *result,
                expression.expression().0 as usize,
            )
            .map_err(|error| KernelSolveError::new(error.to_string()))?;
            dependencies.push(definition_execution_value(
                program,
                definition_facts,
                owner,
                value,
                "BLOCK result dependency",
            )?);
        }
    }
    dependencies.sort_unstable();
    dependencies.dedup();
    Ok(())
}

fn collect_definition_execution_selector(
    program: &PackedKernelProjectProgram,
    definition_facts: &[KernelDefinitionFactsInput],
    owners: &[KernelProjectOwnerOutputs],
    expression: PackedExpressionRef,
    arms: &mut Vec<PackedExpressionRef>,
) -> Result<Option<PackedExpressionRef>, KernelSolveError> {
    arms.clear();
    definition_execution_owner(owners, expression.owner(), "selector")?;
    let facts = definition_facts
        .get(expression.owner().0 as usize)
        .ok_or_else(|| KernelSolveError::new("kernel packed selector facts are missing"))?;
    let Some(shape) = definition_execution_conditional_shape(facts, expression.expression())?
    else {
        return Ok(None);
    };
    let KernelExecutionShapeInput::Conditional { kind, .. } = shape else {
        unreachable!("conditional-shape helper returned a non-conditional row")
    };
    if *kind == KernelConditionalKind::While {
        return Ok(None);
    }
    let input = program.owner(expression.owner()).ok_or_else(|| {
        KernelSolveError::new("kernel packed execution selector owner is missing")
    })?;
    let row = input
        .node(expression.expression())
        .ok_or_else(|| KernelSolveError::new("kernel packed execution selector node is missing"))?;
    let mut selector_inputs = row
        .inputs(input)
        .iter()
        .filter(|input| matches!(input.role, PackedKernelOwnerEdgeRole::WhenInput));
    let selector = selector_inputs.next().ok_or_else(|| {
        KernelSolveError::new(format!(
            "kernel packed execution WHEN {}:{} has no selector input",
            expression.owner().0,
            expression.expression().0,
        ))
    })?;
    if selector_inputs.next().is_some() {
        return Err(KernelSolveError::new(format!(
            "kernel packed execution WHEN {}:{} has multiple selector inputs",
            expression.owner().0,
            expression.expression().0,
        )));
    }
    for arm in row
        .inputs(input)
        .iter()
        .filter(|input| matches!(input.role, PackedKernelOwnerEdgeRole::WhenArm))
    {
        let value = packed_kernel_value_reference(
            input,
            arm.expression,
            expression.expression().0 as usize,
        )
        .map_err(|error| KernelSolveError::new(error.to_string()))?;
        arms.push(definition_execution_value(
            program,
            definition_facts,
            expression.owner(),
            value,
            "WHEN arm",
        )?);
    }
    let selector = packed_kernel_value_reference(
        input,
        selector.expression,
        expression.expression().0 as usize,
    )
    .map_err(|error| KernelSolveError::new(error.to_string()))?;
    definition_execution_value(
        program,
        definition_facts,
        expression.owner(),
        selector,
        "WHEN selector",
    )
    .map(Some)
}

fn build_definition_execution_code(
    program: &PackedKernelProjectProgram,
    owners: &[KernelProjectOwnerOutputs],
    definition_facts: &[KernelDefinitionFactsInput],
    abi: &crate::KernelAbiInput,
    builder: &mut DefinitionCodeBuilder,
) -> Result<(), KernelSolveError> {
    let expression_offsets = definition_execution_offsets(
        program
            .owners()
            .map(PackedKernelOwnerProgramRef::node_count),
        "expression",
    )?;
    let statement_offsets = definition_execution_offsets(
        definition_facts.iter().map(|facts| facts.statements.len()),
        "statement",
    )?;
    let expression_count = expression_offsets.last().copied().unwrap_or(0) as usize;
    let statement_count = statement_offsets.last().copied().unwrap_or(0) as usize;
    let dependency_capacity = program
        .owners()
        .map(|owner| {
            owner
                .nodes()
                .iter()
                .map(|expression| expression.inputs(owner).len())
                .sum::<usize>()
        })
        .sum::<usize>()
        .saturating_add(
            definition_facts
                .iter()
                .flat_map(|facts| facts.execution_shapes.iter())
                .map(|shape| match shape {
                    KernelExecutionShapeInput::Block {
                        bindings, result, ..
                    } => bindings.len().saturating_add(usize::from(result.is_some())),
                    _ => 0,
                })
                .sum(),
        )
        .saturating_add(statement_count);
    let selector_capacity = definition_facts
        .iter()
        .flat_map(|facts| facts.execution_shapes.iter())
        .filter(|shape| {
            matches!(
                shape,
                KernelExecutionShapeInput::Conditional {
                    kind: KernelConditionalKind::When,
                    ..
                }
            )
        })
        .count();
    let selector_arm_capacity = program
        .owners()
        .map(|owner| {
            owner
                .nodes()
                .iter()
                .flat_map(|expression| expression.inputs(owner))
                .filter(|input| matches!(input.role, PackedKernelOwnerEdgeRole::WhenArm))
                .count()
        })
        .sum::<usize>();
    let call_capacity = owners.iter().map(|owner| owner.calls.len()).sum();
    builder.reserve_execution(
        expression_count,
        dependency_capacity,
        selector_capacity,
        selector_arm_capacity,
        call_capacity,
    );

    let mut call_by_expression = vec![u32::MAX; expression_count];
    let mut statement_root_by_expression = vec![None; expression_count];
    let mut read_provider_present = vec![false; expression_count];
    let mut read_provider_callable = vec![None; expression_count];

    for (owner_index, definition) in owners.iter().enumerate() {
        let facts = &definition_facts[owner_index];
        let owner = KernelOwnerId(u32::try_from(owner_index).map_err(|_| {
            KernelSolveError::new("kernel packed execution definition count exceeds u32")
        })?);
        let input = program.owner(owner).ok_or_else(|| {
            KernelSolveError::new(format!(
                "kernel packed execution references missing owner {}",
                owner.0,
            ))
        })?;
        for (ordinal, call) in definition.calls.iter().enumerate() {
            let expression = definition_execution_expression(
                program,
                owner,
                call.expression,
                "call reverse index",
            )?;
            let index = definition_execution_expression_index(&expression_offsets, expression)?;
            let ordinal = u32::try_from(ordinal).map_err(|_| {
                KernelSolveError::new(format!(
                    "kernel packed execution definition {} call count exceeds u32",
                    owner.0,
                ))
            })?;
            if std::mem::replace(&mut call_by_expression[index], ordinal) != u32::MAX {
                return Err(KernelSolveError::new(format!(
                    "kernel packed execution repeats a call for expression {}:{}",
                    owner.0, call.expression.0,
                )));
            }
        }
        for statement in &facts.statements {
            if statement.children.is_empty() {
                continue;
            }
            let Some(encoded) = statement.value else {
                continue;
            };
            let value = packed_kernel_value_reference(input, encoded, statement.id.0 as usize)
                .map_err(|error| KernelSolveError::new(error.to_string()))?;
            let expression = definition_execution_value(
                program,
                definition_facts,
                owner,
                value,
                "statement reverse index",
            )?;
            let index = definition_execution_expression_index(&expression_offsets, expression)?;
            if statement_root_by_expression[index].is_none() {
                statement_root_by_expression[index] = Some(PackedStatementRef {
                    owner,
                    statement: statement.id,
                });
            }
        }
        for binding in &facts.lexical_bindings {
            let expression = definition_execution_expression(
                program,
                owner,
                binding.expression,
                "lexical read",
            )?;
            let expression_row = input.node(binding.expression).ok_or_else(|| {
                KernelSolveError::new(format!(
                    "kernel packed execution lexical binding references missing expression {}:{}",
                    owner.0, binding.expression.0,
                ))
            })?;
            if !expression_row
                .inputs(input)
                .iter()
                .any(|input| matches!(input.role, PackedKernelOwnerEdgeRole::ReadProvider))
            {
                continue;
            }
            let index = definition_execution_expression_index(&expression_offsets, expression)?;
            if read_provider_present[index] {
                return Err(KernelSolveError::new(format!(
                    "kernel packed execution repeats lexical callable authority for expression {}:{}",
                    owner.0, binding.expression.0,
                )));
            }
            read_provider_present[index] = true;
            read_provider_callable[index] = match binding.target {
                KernelLexicalBindingTargetInput::Declaration(reference) => {
                    let declaration = definition_execution_declaration(
                        definition_facts,
                        owner,
                        reference,
                        "lexical read target",
                    )?;
                    let target = &definition_facts[declaration.owner.0 as usize].declarations
                        [declaration.declaration.0 as usize];
                    if target.value.is_none() {
                        None
                    } else {
                        let presentation = definition_facts
                        .get(declaration.owner.0 as usize)
                        .ok_or_else(|| {
                            KernelSolveError::new(format!(
                                "kernel packed execution lexical read target references missing definition facts {}",
                                declaration.owner.0,
                            ))
                        })?
                        .presentation
                        .declarations
                        .get(declaration.declaration.0 as usize)
                        .filter(|row| row.declaration == declaration.declaration)
                        .ok_or_else(|| {
                            KernelSolveError::new(format!(
                                "kernel packed execution declaration {}:{} has no presentation",
                                declaration.owner.0, declaration.declaration.0,
                            ))
                        })?;
                        definition_execution_scope_callable(
                            definition_facts,
                            declaration.owner,
                            presentation.scope,
                            "lexical read callable",
                        )?
                    }
                }
                KernelLexicalBindingTargetInput::ContextFormal { .. }
                | KernelLexicalBindingTargetInput::Value { .. }
                | KernelLexicalBindingTargetInput::RuntimeContext => None,
            };
        }
    }

    let mut assigned_template = vec![None::<KernelOwnerId>; expression_count];
    let mut visit_generations = vec![0_u32; expression_count];
    let mut visit_states = vec![0_u8; expression_count];
    let mut visit_generation = 0_u32;
    let mut dependency_starts = vec![u32::MAX; expression_count];
    let mut dependency_lengths = vec![0_u32; expression_count];
    let mut packed_dependencies = Vec::with_capacity(dependency_capacity);
    let mut dependency_scratch = Vec::new();
    let mut pending = Vec::<(PackedExpressionRef, bool)>::new();
    let mut node_order = Vec::<PackedExpressionRef>::new();
    let mut calls = Vec::<PackedCallRef>::new();
    let mut selector_arms = Vec::<PackedExpressionRef>::new();
    let mut statement_generations = vec![0_u32; statement_count];
    let mut statement_generation = 0_u32;
    let mut statement_stack = Vec::<PackedStatementRef>::new();

    for owner_index in 0..owners.len() {
        let facts = &definition_facts[owner_index];
        let owner = KernelOwnerId(u32::try_from(owner_index).map_err(|_| {
            KernelSolveError::new("kernel packed execution definition count exceeds u32")
        })?);
        let Some(root_statement) = facts.linkage.root_statement else {
            continue;
        };
        let root_statement = definition_execution_statement(
            definition_facts,
            owner,
            root_statement,
            "template root",
        )?;
        if !matches!(root_statement.kind, KernelStatementKind::Function { .. }) {
            continue;
        }
        let result = facts.linkage.result_expression.ok_or_else(|| {
            KernelSolveError::new(format!(
                "kernel packed callable definition {} has no result expression",
                owner.0,
            ))
        })?;
        let result = definition_execution_expression(program, owner, result, "template result")?;
        let public_declaration = facts.linkage.public_declaration.ok_or_else(|| {
            KernelSolveError::new(format!(
                "kernel packed callable definition {} has no public declaration",
                owner.0,
            ))
        })?;
        let template_callable = definition_execution_declaration(
            definition_facts,
            owner,
            public_declaration,
            "template callable",
        )?;

        visit_generation = visit_generation.wrapping_add(1);
        if visit_generation == 0 {
            visit_generations.fill(0);
            visit_generation = 1;
        }
        pending.clear();
        node_order.clear();
        pending.push((result, false));
        while let Some((expression, exiting)) = pending.pop() {
            let index = definition_execution_expression_index(&expression_offsets, expression)?;
            if exiting {
                if visit_generations[index] == visit_generation && visit_states[index] == 1 {
                    visit_states[index] = 2;
                    node_order.push(expression);
                }
                continue;
            }
            if let Some(previous) = assigned_template[index]
                && previous != owner
            {
                return Err(KernelSolveError::new(format!(
                    "kernel packed execution expression {}:{} belongs to callable definitions {} and {}",
                    expression.owner().0,
                    expression.expression().0,
                    previous.0,
                    owner.0,
                )));
            }
            assigned_template[index] = Some(owner);
            if visit_generations[index] == visit_generation {
                continue;
            }
            visit_generations[index] = visit_generation;
            visit_states[index] = 1;

            if dependency_starts[index] == u32::MAX {
                collect_definition_execution_dependencies(
                    program,
                    owners,
                    definition_facts,
                    abi,
                    &expression_offsets,
                    &statement_offsets,
                    &call_by_expression,
                    &statement_root_by_expression,
                    &read_provider_present,
                    &read_provider_callable,
                    template_callable,
                    expression,
                    &mut statement_generations,
                    &mut statement_generation,
                    &mut statement_stack,
                    &mut dependency_scratch,
                )?;
                let start = u32::try_from(packed_dependencies.len()).map_err(|_| {
                    KernelSolveError::new("kernel packed execution dependency start exceeds u32")
                })?;
                let len = u32::try_from(dependency_scratch.len()).map_err(|_| {
                    KernelSolveError::new("kernel packed execution dependency count exceeds u32")
                })?;
                packed_dependencies.extend(dependency_scratch.iter().copied());
                dependency_starts[index] = start;
                dependency_lengths[index] = len;
            }
            let start = dependency_starts[index] as usize;
            let end = start
                .checked_add(dependency_lengths[index] as usize)
                .ok_or_else(|| {
                    KernelSolveError::new("kernel packed execution dependency span overflows usize")
                })?;
            let dependencies = packed_dependencies.get(start..end).ok_or_else(|| {
                KernelSolveError::new("kernel packed execution dependency span is out of range")
            })?;
            pending.push((expression, true));
            pending.extend(
                dependencies
                    .iter()
                    .rev()
                    .copied()
                    .map(|dependency| (dependency, false)),
            );
        }

        calls.clear();
        let token = builder.begin_execution_template(owner, result)?;
        for expression in node_order.iter().copied() {
            let index = definition_execution_expression_index(&expression_offsets, expression)?;
            let start = dependency_starts[index] as usize;
            let end = start
                .checked_add(dependency_lengths[index] as usize)
                .ok_or_else(|| {
                    KernelSolveError::new("kernel packed execution dependency span overflows usize")
                })?;
            let dependencies = packed_dependencies.get(start..end).ok_or_else(|| {
                KernelSolveError::new("kernel packed execution dependency span is out of range")
            })?;
            let call_ordinal = call_by_expression[index];
            let call = (call_ordinal != u32::MAX)
                .then(|| PackedCallRef::new(expression.owner(), call_ordinal));
            if let Some(call) = call {
                calls.push(call);
            }
            let selector = collect_definition_execution_selector(
                program,
                definition_facts,
                owners,
                expression,
                &mut selector_arms,
            )?;
            builder.push_execution_node(
                token,
                expression,
                dependencies,
                call,
                selector.map(|input| (input, selector_arms.as_slice())),
            )?;
        }
        calls.sort_unstable();
        calls.dedup();
        builder.finish_execution_template(token, &calls)?;
    }
    Ok(())
}

fn import_post_solve_type(terms: &mut crate::TypeTermArena, ty: &Type) -> TypeTermId {
    terms.import_checked_type(ty, &mut |variable| TypeVariableId(variable.0))
}

const DEFINITION_CODE_DOMAIN_V4: &[u8] = b"boon.compiler-kernel.definition-code.v4\0";

fn update_definition_code_len(digest: &mut Sha256, len: usize) {
    digest.update(u64::try_from(len).unwrap_or(u64::MAX).to_be_bytes());
}

fn update_definition_code_type(
    digest: &mut Sha256,
    source: &crate::TypeTermArena,
    scratch: &mut DefinitionTermProofScratch,
    term: TypeTermId,
) -> Result<(), KernelSolveError> {
    digest.update(scratch.visit_alpha_root(source, term)?);
    Ok(())
}

fn update_definition_code_flow(
    digest: &mut Sha256,
    source: &crate::TypeTermArena,
    scratch: &mut DefinitionTermProofScratch,
    term: TypeTermId,
    mode: FlowMode,
) -> Result<(), KernelSolveError> {
    digest.update(scratch.visit_alpha_flow_root(source, term, mode)?);
    Ok(())
}

fn update_definition_code_optional_type(
    digest: &mut Sha256,
    source: &crate::TypeTermArena,
    scratch: &mut DefinitionTermProofScratch,
    term: Option<TypeTermId>,
) -> Result<(), KernelSolveError> {
    if let Some(term) = term {
        digest.update([1]);
        update_definition_code_type(digest, source, scratch, term)?;
    } else {
        digest.update([0]);
    }
    Ok(())
}

fn update_definition_code_u32(digest: &mut Sha256, value: u32) {
    digest.update(value.to_be_bytes());
}

fn update_definition_code_text(digest: &mut Sha256, value: &str) {
    update_definition_code_len(digest, value.len());
    digest.update(value.as_bytes());
}

fn update_definition_code_resource_path(
    digest: &mut Sha256,
    text: &ProjectTextSnapshot,
    symbols: &[SymbolId],
    start: u32,
    len: u32,
    context: &str,
) -> Result<(), KernelSolveError> {
    let start = start as usize;
    let end = start
        .checked_add(len as usize)
        .ok_or_else(|| KernelSolveError::new(format!("{context} span overflows usize")))?;
    let path = symbols
        .get(start..end)
        .ok_or_else(|| KernelSolveError::new(format!("{context} is outside its definition")))?;
    update_definition_code_len(digest, path.len());
    for symbol in path {
        let value = text.symbol(*symbol).ok_or_else(|| {
            KernelSolveError::new(format!(
                "{context} symbol {} is outside the frozen text authority",
                symbol.as_u32()
            ))
        })?;
        update_definition_code_text(digest, value);
    }
    Ok(())
}

fn update_definition_code_declaration_reference(
    digest: &mut Sha256,
    target: KernelDeclarationReference,
) {
    match target {
        KernelDeclarationReference::Local(declaration) => {
            digest.update([0]);
            update_definition_code_u32(digest, declaration.0);
        }
        KernelDeclarationReference::OwnerPublic(owner) => {
            digest.update([1]);
            update_definition_code_u32(digest, owner.0);
        }
        KernelDeclarationReference::OwnerDeclaration { owner, declaration } => {
            digest.update([2]);
            update_definition_code_u32(digest, owner.0);
            update_definition_code_u32(digest, declaration.0);
        }
    }
}

#[allow(clippy::too_many_arguments)]
fn definition_code_types_stable_digest(
    source: &crate::TypeTermArena,
    scratch: &mut DefinitionTermProofScratch,
    result: (TypeTermId, FlowMode),
    formals: &[(TypeTermId, FlowMode)],
    expressions: &[(TypeTermId, FlowMode)],
    flushes: &[Option<TypeTermId>],
    kinds: &[Option<TypeTermId>],
    declarations: &[Option<PackedFlow>],
    calls: &[PackedCallFactsInput],
    substitutions: &[PackedCallTypeSubstitution],
    diagnostics: &[Option<PackedDiagnosticTypes>],
    sources: &[TypeTermId],
    states: &[PackedFlow],
    lists: &[TypeTermId],
    resource_projection_requirements: &[ResourceProjectionRequirementFact],
    resource_projection_origins: &[PackedSourceReadInput],
    resource_projection_symbols: &[SymbolId],
) -> Result<[u8; 32], KernelSolveError> {
    let mut digest = Sha256::new();
    digest.update(DEFINITION_CODE_DOMAIN_V4);
    update_definition_code_flow(&mut digest, source, scratch, result.0, result.1)?;
    update_definition_code_len(&mut digest, formals.len());
    for (term, mode) in formals.iter().copied() {
        update_definition_code_flow(&mut digest, source, scratch, term, mode)?;
    }
    update_definition_code_len(&mut digest, expressions.len());
    for (term, mode) in expressions.iter().copied() {
        update_definition_code_flow(&mut digest, source, scratch, term, mode)?;
    }
    update_definition_code_len(&mut digest, flushes.len());
    for term in flushes.iter().copied() {
        update_definition_code_optional_type(&mut digest, source, scratch, term)?;
    }
    update_definition_code_len(&mut digest, kinds.len());
    for term in kinds.iter().copied() {
        update_definition_code_optional_type(&mut digest, source, scratch, term)?;
    }
    update_definition_code_len(&mut digest, declarations.len());
    for flow in declarations.iter().copied() {
        if let Some(flow) = flow {
            digest.update([1]);
            update_definition_code_flow(&mut digest, source, scratch, flow.term, flow.mode)?;
        } else {
            digest.update([0]);
        }
    }
    update_definition_code_len(&mut digest, calls.len());
    for call in calls {
        digest.update([u8::from(call.syntax_discriminated_result)]);
        let start = call.substitution_start as usize;
        let end = start
            .checked_add(call.substitution_len as usize)
            .ok_or_else(|| KernelSolveError::new("kernel call proof span overflows usize"))?;
        let substitutions = substitutions.get(start..end).ok_or_else(|| {
            KernelSolveError::new("kernel call proof span is outside its definition")
        })?;
        update_definition_code_len(&mut digest, substitutions.len());
        for substitution in substitutions {
            digest.update(substitution.variable.0.to_be_bytes());
            update_definition_code_type(&mut digest, source, scratch, substitution.term)?;
        }
    }
    update_definition_code_len(&mut digest, diagnostics.len());
    for diagnostic in diagnostics.iter().copied() {
        if let Some(diagnostic) = diagnostic {
            digest.update([1]);
            update_definition_code_type(&mut digest, source, scratch, diagnostic.actual)?;
            update_definition_code_type(&mut digest, source, scratch, diagnostic.expected)?;
        } else {
            digest.update([0]);
        }
    }
    update_definition_code_len(&mut digest, sources.len());
    for term in sources.iter().copied() {
        update_definition_code_type(&mut digest, source, scratch, term)?;
    }
    update_definition_code_len(&mut digest, states.len());
    for flow in states.iter().copied() {
        update_definition_code_flow(&mut digest, source, scratch, flow.term, flow.mode)?;
    }
    update_definition_code_len(&mut digest, lists.len());
    for term in lists.iter().copied() {
        update_definition_code_type(&mut digest, source, scratch, term)?;
    }
    update_definition_code_len(&mut digest, resource_projection_requirements.len());
    let text = source.text_snapshot();
    for requirement in resource_projection_requirements {
        update_definition_code_u32(&mut digest, requirement.expression.0);
        update_definition_code_declaration_reference(&mut digest, requirement.target);
        digest.update([u8::from(requirement.publishes_required_type)]);
        update_definition_code_resource_path(
            &mut digest,
            text,
            resource_projection_symbols,
            requirement.projection_start,
            requirement.projection_len,
            "kernel definition-code resource requirement path",
        )?;
        let origin_start = requirement.origin_start as usize;
        let origin_end = origin_start
            .checked_add(requirement.origin_len as usize)
            .ok_or_else(|| {
                KernelSolveError::new(
                    "kernel definition-code resource requirement origin span overflows usize",
                )
            })?;
        let origins = resource_projection_origins
            .get(origin_start..origin_end)
            .ok_or_else(|| {
                KernelSolveError::new(
                    "kernel definition-code resource requirement origins are outside its definition",
                )
            })?;
        update_definition_code_len(&mut digest, origins.len());
        for origin in origins {
            update_definition_code_u32(&mut digest, origin.owner.0);
            update_definition_code_u32(&mut digest, origin.source.0);
            update_definition_code_resource_path(
                &mut digest,
                text,
                resource_projection_symbols,
                origin.payload_projection_start,
                origin.payload_projection_len,
                "kernel definition-code resource origin path",
            )?;
        }
        update_definition_code_type(&mut digest, source, scratch, requirement.required_term)?;
    }
    Ok(digest.finalize().into())
}

#[cfg(test)]
std::thread_local! {
    static TEST_COMPATIBILITY_DEFINITION_MATERIALIZATIONS: std::cell::Cell<usize> =
        const { std::cell::Cell::new(0) };
}

#[cfg(test)]
pub(crate) fn reset_test_compatibility_definition_materializations() {
    TEST_COMPATIBILITY_DEFINITION_MATERIALIZATIONS.set(0);
}

#[cfg(test)]
pub(crate) fn test_compatibility_definition_materializations() -> usize {
    TEST_COMPATIBILITY_DEFINITION_MATERIALIZATIONS.get()
}

#[cfg(test)]
fn materialize_packed_owner_program(
    input: PackedKernelOwnerProgramRef<'_>,
) -> KernelOwnerProgramInput {
    let nodes = input
        .nodes()
        .iter()
        .map(|node| {
            let artifact = KernelExpressionKindRef::from_packed(input, &node.kind)
                .expect("validated packed opcode resolves")
                .to_owned();
            let kind = match artifact {
                KernelExpressionArtifactKind::Known => {
                    let PackedKernelOwnerNodeKind::Known(reference) = node.kind else {
                        unreachable!("packed Known view retains its type reference")
                    };
                    KernelOwnerNodeKind::KnownPacked(reference)
                }
                KernelExpressionArtifactKind::Source => {
                    let PackedKernelOwnerNodeKind::Source(reference) = node.kind else {
                        unreachable!("packed Source view retains its type reference")
                    };
                    KernelOwnerNodeKind::SourcePacked(reference)
                }
                KernelExpressionArtifactKind::Absent => KernelOwnerNodeKind::Absent,
                KernelExpressionArtifactKind::Text => KernelOwnerNodeKind::Text,
                KernelExpressionArtifactKind::TextTemplate => KernelOwnerNodeKind::TextTemplate,
                KernelExpressionArtifactKind::Number => KernelOwnerNodeKind::Number,
                KernelExpressionArtifactKind::Byte => KernelOwnerNodeKind::Byte,
                KernelExpressionArtifactKind::Bits(width) => KernelOwnerNodeKind::Bits(width),
                KernelExpressionArtifactKind::Tag(tag) => KernelOwnerNodeKind::Tag(tag),
                KernelExpressionArtifactKind::Record { tag } => KernelOwnerNodeKind::Record { tag },
                KernelExpressionArtifactKind::Block => KernelOwnerNodeKind::Block,
                KernelExpressionArtifactKind::Collection { kind, capacity } => {
                    KernelOwnerNodeKind::Collection { kind, capacity }
                }
                KernelExpressionArtifactKind::MapEntry => KernelOwnerNodeKind::MapEntry,
                KernelExpressionArtifactKind::FormalRead { formal, fields } => {
                    KernelOwnerNodeKind::FormalRead { formal, fields }
                }
                KernelExpressionArtifactKind::ContextRead { formal, fields } => {
                    KernelOwnerNodeKind::ContextRead { formal, fields }
                }
                KernelExpressionArtifactKind::LexicalRead { fields } => {
                    KernelOwnerNodeKind::LexicalRead { fields }
                }
                KernelExpressionArtifactKind::ValueRead {
                    fields,
                    mode_narrowing,
                } => KernelOwnerNodeKind::ValueRead {
                    fields,
                    mode_narrowing,
                },
                KernelExpressionArtifactKind::DerivedRead { fields } => {
                    KernelOwnerNodeKind::DerivedRead { fields }
                }
                KernelExpressionArtifactKind::PatternRead { pattern, fields } => {
                    KernelOwnerNodeKind::PatternRead { pattern, fields }
                }
                KernelExpressionArtifactKind::CollectionItemRead => {
                    KernelOwnerNodeKind::CollectionItemRead
                }
                KernelExpressionArtifactKind::FreshOut => KernelOwnerNodeKind::FreshOut,
                KernelExpressionArtifactKind::UserCall {
                    target,
                    inherited_formal,
                } => KernelOwnerNodeKind::UserCall {
                    target,
                    inherited_formal,
                },
                KernelExpressionArtifactKind::RenderConstructor { kind } => {
                    KernelOwnerNodeKind::RenderConstructor { kind }
                }
                KernelExpressionArtifactKind::PureBuiltin { kind } => {
                    KernelOwnerNodeKind::PureBuiltin { kind }
                }
                KernelExpressionArtifactKind::FixedAbiCall => {
                    let PackedKernelOwnerNodeKind::FixedAbiCall { result } = node.kind else {
                        unreachable!("packed fixed ABI view retains its type reference")
                    };
                    KernelOwnerNodeKind::FixedAbiCallPacked { result }
                }
                KernelExpressionArtifactKind::HostEffect { operation } => {
                    KernelOwnerNodeKind::HostEffect { operation }
                }
                KernelExpressionArtifactKind::Latest => KernelOwnerNodeKind::Latest,
                KernelExpressionArtifactKind::When => KernelOwnerNodeKind::When,
                KernelExpressionArtifactKind::Then => KernelOwnerNodeKind::Then,
                KernelExpressionArtifactKind::Infix { operation } => {
                    KernelOwnerNodeKind::Infix { operation }
                }
                KernelExpressionArtifactKind::Draining => KernelOwnerNodeKind::Draining,
                KernelExpressionArtifactKind::Hold => KernelOwnerNodeKind::Hold,
                KernelExpressionArtifactKind::MatchArm { pattern } => {
                    KernelOwnerNodeKind::MatchArm { pattern }
                }
                KernelExpressionArtifactKind::Arrow => KernelOwnerNodeKind::Arrow,
                KernelExpressionArtifactKind::Delimiter => KernelOwnerNodeKind::Delimiter,
                KernelExpressionArtifactKind::Unknown => KernelOwnerNodeKind::Unknown,
                KernelExpressionArtifactKind::Flush => KernelOwnerNodeKind::Flush,
                KernelExpressionArtifactKind::FieldProjection { field } => {
                    KernelOwnerNodeKind::FieldProjection { field }
                }
            };
            KernelOwnerNode {
                kind,
                inputs: node
                    .inputs(input)
                    .iter()
                    .map(|edge| KernelOwnerInputEdge {
                        role: input
                            .materialize_edge_role(edge.role)
                            .expect("validated packed edge role resolves"),
                        expression: edge.expression,
                    })
                    .collect::<Vec<_>>()
                    .into_boxed_slice(),
                mode: node.mode,
            }
        })
        .collect::<Vec<_>>()
        .into_boxed_slice();
    KernelOwnerProgramInput {
        nodes,
        formal_count: input.formal_count(),
        external_expressions: input.external_expressions().into(),
        result: input.result(),
    }
}

#[cfg(test)]
fn materialize_project_definition_structures(
    program: &PackedKernelProjectProgram,
    definition_facts: &[KernelDefinitionFactsInput],
    owners: &[KernelProjectOwnerOutputs],
    synthetic_state_ordinals: &[Box<[Option<u32>]>],
    owner_effects: &[KernelEffectSummary],
    demanded: Option<&[KernelOwnerId]>,
) -> Result<Box<[DefinitionArtifact]>, KernelSolveError> {
    if program.definition_count() != owners.len() || definition_facts.len() != owners.len() {
        return Err(KernelSolveError::new(
            "kernel structural publication received mismatched program authorities",
        ));
    }
    if owners.len() != synthetic_state_ordinals.len() {
        return Err(KernelSolveError::new(
            "kernel structural definition rows and synthetic state paths differ in length",
        ));
    }
    owners
        .iter()
        .zip(synthetic_state_ordinals)
        .enumerate()
        .filter(|(owner_index, _)| {
            demanded.is_none_or(|demanded| {
                demanded
                    .binary_search(&KernelOwnerId(
                        u32::try_from(*owner_index)
                            .expect("kernel definition count exceeds the dense u32 namespace"),
                    ))
                    .is_ok()
            })
        })
        .map(|(owner_index, (owner, synthetic_state_ordinals))| {
            #[cfg(test)]
            TEST_COMPATIBILITY_DEFINITION_MATERIALIZATIONS
                .set(TEST_COMPATIBILITY_DEFINITION_MATERIALIZATIONS.get() + 1);
            let packed_input = program
                .owner_at(owner_index)
                .expect("validated materialized owner remains present");
            let input = materialize_packed_owner_program(packed_input);
            let facts = &definition_facts[owner_index];
            if facts.states.len() != synthetic_state_ordinals.len() {
                return Err(KernelSolveError::new(
                    "kernel structural state rows and synthetic paths differ in length",
                ));
            }
            let expressions = input
                .nodes
                .iter()
                .enumerate()
                .map(|(index, expression)| {
                    let id = KernelExpressionId(
                        u32::try_from(index).expect("kernel expression count exceeds u32"),
                    );
                    let inputs = expression
                        .inputs
                        .iter()
                        .map(|edge| {
                            Ok(KernelExpressionInputArtifact {
                                role: edge.role.clone(),
                                value: kernel_value_reference(&input, edge.expression, index)
                                    .map_err(|error| KernelSolveError::new(error.to_string()))?,
                            })
                        })
                        .collect::<Result<Vec<_>, KernelSolveError>>()?
                        .into_boxed_slice();
                    Ok(KernelExpressionArtifact {
                        id,
                        kind: (&expression.kind).into(),
                        inputs,
                        effect: direct_expression_effect(&expression.kind, owner_effects),
                    })
                })
                .collect::<Result<Vec<_>, KernelSolveError>>()?
                .into_boxed_slice();
            let statements = collect_statement_artifacts(&input, facts)
                .map_err(|error| KernelSolveError::new(error.to_string()))?;
            let execution_shapes = collect_execution_shape_artifacts(&input, facts)
                .map_err(|error| KernelSolveError::new(error.to_string()))?;
            let call_syntax = collect_call_syntax_artifacts(&input, facts)
                .map_err(|error| KernelSolveError::new(error.to_string()))?;
            let declarations = facts
                .declarations
                .iter()
                .map(|declaration| {
                    Ok(KernelDeclarationArtifact {
                        id: declaration.id,
                        origin: declaration.origin.clone(),
                        name: declaration.name.clone(),
                        kind: declaration.kind,
                        value: declaration
                            .value
                            .map(|value| {
                                kernel_value_reference(&input, value, declaration.id.0 as usize)
                                    .map_err(|error| KernelSolveError::new(error.to_string()))
                            })
                            .transpose()?,
                    })
                })
                .collect::<Result<Vec<_>, KernelSolveError>>()?
                .into_boxed_slice();
            let lexical_bindings = collect_lexical_binding_artifacts(&input, facts)
                .map_err(|error| KernelSolveError::new(error.to_string()))?;
            let definition = KernelDefinitionInputRef {
                owner: KernelOwnerId(
                    u32::try_from(owner_index).expect("kernel definition count exceeds u32"),
                ),
                input: packed_input,
                facts,
                outputs: owner,
            };
            let calls = definition
                .calls()
                .map(|call| {
                    let inputs = call
                        .inputs()
                        .iter()
                        .map(|edge| {
                            let role = match call
                                .input_role(edge)
                                .map_err(|error| KernelSolveError::new(error.to_string()))?
                            {
                                KernelCallInputRoleRef::Formal { ordinal } => {
                                    KernelCallInputRole::Formal { ordinal }
                                }
                                KernelCallInputRoleRef::Abi { name } => {
                                    KernelCallInputRole::Abi { name: name.into() }
                                }
                            };
                            Ok(KernelCallInputArtifact {
                                role,
                                value: call
                                    .input_value(edge)
                                    .map_err(|error| KernelSolveError::new(error.to_string()))?,
                            })
                        })
                        .collect::<Result<Vec<_>, KernelSolveError>>()?
                        .into_boxed_slice();
                    Ok(KernelCallArtifact {
                        expression: call.expression(),
                        target: call.target().to_owned(),
                        inputs,
                    })
                })
                .collect::<Result<Vec<_>, KernelSolveError>>()?
                .into_boxed_slice();
            let sources = facts
                .sources
                .iter()
                .map(|source| KernelSourceArtifact {
                    id: source.id,
                    declaration: source.declaration,
                    statement: source.statement,
                    expression: source.expression,
                    path: KernelSemanticPath {
                        anchor: source.declaration,
                        projection: source.projection.clone(),
                    },
                    interval_ms: source.interval_ms,
                })
                .collect::<Vec<_>>()
                .into_boxed_slice();
            let states = facts
                .states
                .iter()
                .zip(synthetic_state_ordinals.iter().copied())
                .filter(|(state, _)| {
                    state_input_candidate_survives(&input, state, &owner.expression_modes)
                })
                .enumerate()
                .map(|(index, (state, synthetic_ordinal))| {
                    let mut path = KernelSemanticPath {
                        anchor: state.declaration,
                        projection: state.projection.clone(),
                    };
                    if state.synthetic_path {
                        let ordinal = synthetic_ordinal.expect(
                            "surviving synthetic state candidate has no allocated path ordinal",
                        );
                        debug_assert!(path.projection.is_empty());
                        path.projection =
                            vec![format!("state_{ordinal}").into_boxed_str()].into_boxed_slice();
                    } else {
                        debug_assert!(synthetic_ordinal.is_none());
                    }
                    Ok(KernelStateArtifact {
                        id: KernelStateId(
                            u32::try_from(index)
                                .expect("kernel materialized state count exceeds u32"),
                        ),
                        binding_declaration: state.binding_declaration,
                        declaration: state.declaration,
                        statement: state.statement,
                        expression: state.expression,
                        initial: kernel_value_reference(
                            &input,
                            state.initial,
                            state.expression.0 as usize,
                        )
                        .map_err(|error| KernelSolveError::new(error.to_string()))?,
                        path,
                        kind: state.kind,
                    })
                })
                .collect::<Result<Vec<_>, KernelSolveError>>()?
                .into_boxed_slice();
            let lists = facts
                .lists
                .iter()
                .map(|list| KernelListArtifact {
                    id: list.id,
                    declaration: list.declaration,
                    statement: list.statement,
                    producer: list.producer,
                    path: KernelSemanticPath {
                        anchor: list.declaration,
                        projection: list.projection.clone(),
                    },
                    capacity: list.capacity,
                    key_policy: list.key_policy,
                })
                .collect::<Vec<_>>()
                .into_boxed_slice();
            Ok(DefinitionArtifact {
                linkage: facts.linkage,
                call_syntax,
                execution_shapes,
                expressions,
                statements,
                declarations,
                lexical_bindings,
                calls,
                effects: collect_packed_host_effect_artifacts(packed_input)
                    .map_err(|error| KernelSolveError::new(error.to_string()))?,
                sources,
                states,
                lists,
            })
        })
        .collect::<Result<Vec<_>, _>>()
        .map(Vec::into_boxed_slice)
}

fn project_public_results(
    owners: &[KernelProjectOwnerOutputs],
    artifact: &ComponentOutputSnapshot<'_>,
) -> Box<[PackedFlow]> {
    owners
        .iter()
        .map(|owner| {
            let mut result = artifact
                .flow(owner.result)
                .expect("project owner result belongs to its component");
            let result_index = owner
                .expressions
                .iter()
                .position(|output| *output == owner.result)
                .expect("owner result belongs to its expression outputs");
            result.mode = owner.expression_modes[result_index];
            result
        })
        .collect::<Vec<_>>()
        .into_boxed_slice()
}

/// Solve the checker-private FLUSH channel over the already-quiescent value
/// graph. This is deliberately a separate dense work queue: FLUSH is control
/// flow, so forcing its payload into ordinary value unification would pollute
/// both public interfaces and runtime value types.
#[derive(Clone, Debug)]
struct ProjectExpressionFlushTerms {
    definition_offsets: Box<[u32]>,
    terms: Box<[Option<TypeTermId>]>,
}

impl ProjectExpressionFlushTerms {
    fn definition(&self, owner: usize) -> Option<&[Option<TypeTermId>]> {
        let start = *self.definition_offsets.get(owner)? as usize;
        let end = *self.definition_offsets.get(owner + 1)? as usize;
        self.terms.get(start..end)
    }
}

fn project_expression_flush_terms(
    program: &PackedKernelProjectProgram,
    owners: &[KernelProjectOwnerOutputs],
    artifact: &mut UnsealedComponentArtifact,
) -> Result<ProjectExpressionFlushTerms, KernelSolveError> {
    let mut definition_offsets = Vec::with_capacity(owners.len() + 1);
    definition_offsets.push(0_u32);
    for owner in owners {
        let len = u32::try_from(owner.expressions.len())
            .map_err(|_| KernelSolveError::new("kernel definition expression count exceeds u32"))?;
        let end = definition_offsets
            .last()
            .copied()
            .expect("kernel FLUSH offsets have a root")
            .checked_add(len)
            .ok_or_else(|| KernelSolveError::new("kernel project expression count exceeds u32"))?;
        definition_offsets.push(end);
    }
    let total = definition_offsets.last().copied().unwrap_or_default() as usize;
    let result_expressions = owners
        .iter()
        .enumerate()
        .map(|(owner_index, owner)| {
            let local = owner
                .expressions
                .iter()
                .position(|output| *output == owner.result)
                .expect("owner result belongs to its expression outputs");
            definition_offsets[owner_index] as usize + local
        })
        .collect::<Vec<_>>();

    let value_index = |caller: usize, value: KernelValueReference| -> Option<usize> {
        match value {
            KernelValueReference::Local(expression) => ((expression.0 as usize)
                < owners.get(caller)?.expressions.len())
            .then_some(definition_offsets[caller] as usize + expression.0 as usize),
            KernelValueReference::External(KernelExternalExpression {
                owner,
                target: KernelExternalTarget::Result,
            }) => result_expressions.get(owner.0 as usize).copied(),
            KernelValueReference::External(KernelExternalExpression {
                owner,
                target: KernelExternalTarget::Expression(expression),
            }) => {
                let owner = owner.0 as usize;
                ((expression.0 as usize) < owners.get(owner)?.expressions.len())
                    .then_some(definition_offsets[owner] as usize + expression.0 as usize)
            }
        }
    };
    let value_term = |caller: usize,
                      value: KernelValueReference,
                      artifact: &UnsealedComponentArtifact|
     -> Option<TypeTermId> {
        let output = match value {
            KernelValueReference::Local(expression) => owners
                .get(caller)?
                .expressions
                .get(expression.0 as usize)
                .copied()?,
            KernelValueReference::External(KernelExternalExpression {
                owner,
                target: KernelExternalTarget::Result,
            }) => owners.get(owner.0 as usize)?.result,
            KernelValueReference::External(KernelExternalExpression {
                owner,
                target: KernelExternalTarget::Expression(expression),
            }) => owners
                .get(owner.0 as usize)?
                .expressions
                .get(expression.0 as usize)
                .copied()?,
        };
        artifact.output(output).map(|output| output.term())
    };

    let mut dependency_counts = vec![0_u32; total];
    let mut base_counts = vec![0_u32; total];
    for (owner_index, input) in program.owners().enumerate() {
        for (local, expression) in input.nodes().iter().enumerate() {
            let index = definition_offsets[owner_index] as usize + local;
            let carries_input_flush = |role: &PackedKernelOwnerEdgeRole| match &expression.kind {
                PackedKernelOwnerNodeKind::Record { .. } | PackedKernelOwnerNodeKind::Block => {
                    false
                }
                PackedKernelOwnerNodeKind::Hold => {
                    matches!(role, PackedKernelOwnerEdgeRole::HoldUpdate)
                }
                _ => true,
            };
            for edge in expression
                .inputs(input)
                .iter()
                .filter(|input| carries_input_flush(&input.role))
            {
                let value = packed_kernel_value_reference(input, edge.expression, local)
                    .map_err(|error| KernelSolveError::new(error.to_string()))?;
                if value_index(owner_index, value).is_some() {
                    dependency_counts[index] =
                        dependency_counts[index].checked_add(1).ok_or_else(|| {
                            KernelSolveError::new("kernel FLUSH dependency count exceeds u32")
                        })?;
                }
            }
            if let PackedKernelOwnerNodeKind::UserCall { target, .. } = &expression.kind
                && result_expressions.get(target.0 as usize).is_some()
            {
                dependency_counts[index] =
                    dependency_counts[index].checked_add(1).ok_or_else(|| {
                        KernelSolveError::new("kernel FLUSH dependency count exceeds u32")
                    })?;
            }
            if matches!(expression.kind, PackedKernelOwnerNodeKind::Flush) {
                for payload in expression
                    .inputs(input)
                    .iter()
                    .filter(|input| matches!(input.role, PackedKernelOwnerEdgeRole::FlushPayload))
                {
                    let value = packed_kernel_value_reference(input, payload.expression, local)
                        .map_err(|error| KernelSolveError::new(error.to_string()))?;
                    if value_term(owner_index, value, artifact).is_some() {
                        base_counts[index] =
                            base_counts[index].checked_add(1).ok_or_else(|| {
                                KernelSolveError::new("kernel FLUSH base count exceeds u32")
                            })?;
                    }
                }
            }
        }
    }

    fn counted_offsets(counts: &[u32], label: &str) -> Result<(Vec<u32>, usize), KernelSolveError> {
        let mut offsets = Vec::with_capacity(counts.len() + 1);
        offsets.push(0_u32);
        for count in counts {
            let end = offsets
                .last()
                .copied()
                .expect("kernel counted offsets have a root")
                .checked_add(*count)
                .ok_or_else(|| KernelSolveError::new(format!("kernel {label} rows exceed u32")))?;
            offsets.push(end);
        }
        let len = offsets.last().copied().unwrap_or_default() as usize;
        Ok((offsets, len))
    }

    let (dependency_offsets, dependency_len) =
        counted_offsets(&dependency_counts, "FLUSH dependency")?;
    let (base_offsets, base_len) = counted_offsets(&base_counts, "FLUSH base")?;
    let mut dependencies = vec![0_usize; dependency_len];
    let mut bases = vec![artifact.terms().absent(); base_len];
    let mut dependency_cursors = dependency_offsets[..total].to_vec();
    let mut base_cursors = base_offsets[..total].to_vec();
    for (owner_index, input) in program.owners().enumerate() {
        for (local, expression) in input.nodes().iter().enumerate() {
            let index = definition_offsets[owner_index] as usize + local;
            let carries_input_flush = |role: &PackedKernelOwnerEdgeRole| match &expression.kind {
                PackedKernelOwnerNodeKind::Record { .. } | PackedKernelOwnerNodeKind::Block => {
                    false
                }
                PackedKernelOwnerNodeKind::Hold => {
                    matches!(role, PackedKernelOwnerEdgeRole::HoldUpdate)
                }
                _ => true,
            };
            for edge in expression
                .inputs(input)
                .iter()
                .filter(|input| carries_input_flush(&input.role))
            {
                let value = packed_kernel_value_reference(input, edge.expression, local)
                    .map_err(|error| KernelSolveError::new(error.to_string()))?;
                if let Some(provider) = value_index(owner_index, value) {
                    let cursor = &mut dependency_cursors[index];
                    dependencies[*cursor as usize] = provider;
                    *cursor += 1;
                }
            }
            if let PackedKernelOwnerNodeKind::UserCall { target, .. } = &expression.kind
                && let Some(provider) = result_expressions.get(target.0 as usize)
            {
                let cursor = &mut dependency_cursors[index];
                dependencies[*cursor as usize] = *provider;
                *cursor += 1;
            }
            if matches!(expression.kind, PackedKernelOwnerNodeKind::Flush) {
                for payload in expression
                    .inputs(input)
                    .iter()
                    .filter(|input| matches!(input.role, PackedKernelOwnerEdgeRole::FlushPayload))
                {
                    let value = packed_kernel_value_reference(input, payload.expression, local)
                        .map_err(|error| KernelSolveError::new(error.to_string()))?;
                    if let Some(term) = value_term(owner_index, value, artifact) {
                        let cursor = &mut base_cursors[index];
                        bases[*cursor as usize] = term;
                        *cursor += 1;
                    }
                }
            }
        }
    }
    debug_assert_eq!(dependency_cursors, dependency_offsets[1..]);
    debug_assert_eq!(base_cursors, base_offsets[1..]);

    let mut consumer_counts = vec![0_u32; total];
    for provider in &dependencies {
        consumer_counts[*provider] = consumer_counts[*provider]
            .checked_add(1)
            .ok_or_else(|| KernelSolveError::new("kernel FLUSH consumer count exceeds u32"))?;
    }
    let (consumer_offsets, consumer_len) = counted_offsets(&consumer_counts, "FLUSH consumer")?;
    let mut consumers = vec![0_usize; consumer_len];
    let mut consumer_cursors = consumer_offsets[..total].to_vec();
    for consumer in 0..total {
        for provider in &dependencies
            [dependency_offsets[consumer] as usize..dependency_offsets[consumer + 1] as usize]
        {
            let cursor = &mut consumer_cursors[*provider];
            consumers[*cursor as usize] = consumer;
            *cursor += 1;
        }
    }
    debug_assert_eq!(consumer_cursors, consumer_offsets[1..]);

    let mut values = vec![None; total];
    let mut queued = vec![true; total];
    let mut queue = (0..total).collect::<VecDeque<_>>();
    let mut candidates = Vec::new();
    while let Some(index) = queue.pop_front() {
        queued[index] = false;
        candidates.clear();
        candidates.extend_from_slice(
            &bases[base_offsets[index] as usize..base_offsets[index + 1] as usize],
        );
        candidates.extend(
            dependencies
                [dependency_offsets[index] as usize..dependency_offsets[index + 1] as usize]
                .iter()
                .filter_map(|provider| values[*provider]),
        );
        let next = if candidates.is_empty() {
            None
        } else {
            let term = artifact.terms_mut().union(candidates.iter().copied());
            match artifact.terms().term_head(term) {
                TypeTermHead::Absent | TypeTermHead::Unknown | TypeTermHead::UnresolvedShape(_) => {
                    None
                }
                _ => Some(term),
            }
        };
        if values[index] == next {
            continue;
        }
        values[index] = next;
        for consumer in
            &consumers[consumer_offsets[index] as usize..consumer_offsets[index + 1] as usize]
        {
            if !queued[*consumer] {
                queued[*consumer] = true;
                queue.push_back(*consumer);
            }
        }
    }
    Ok(ProjectExpressionFlushTerms {
        definition_offsets: definition_offsets.into_boxed_slice(),
        terms: values.into_boxed_slice(),
    })
}

fn solve_flush_graph(bases: Vec<Vec<Type>>, dependencies: Vec<Vec<usize>>) -> Vec<Option<Type>> {
    assert_eq!(bases.len(), dependencies.len());
    let mut consumers = vec![Vec::<usize>::new(); dependencies.len()];
    for (consumer, providers) in dependencies.iter().enumerate() {
        for provider in providers {
            consumers[*provider].push(consumer);
        }
    }
    for row in &mut consumers {
        row.sort_unstable();
        row.dedup();
    }

    let mut values = vec![None; dependencies.len()];
    let mut queued = vec![true; dependencies.len()];
    let mut queue = (0..dependencies.len()).collect::<VecDeque<_>>();
    while let Some(index) = queue.pop_front() {
        queued[index] = false;
        let mut candidates = bases[index].clone();
        candidates.extend(
            dependencies[index]
                .iter()
                .filter_map(|provider| values[*provider].clone()),
        );
        let next = match canonical_union_type(candidates) {
            Type::Absent | Type::Unknown | Type::UnresolvedShape { .. } => None,
            ty => Some(ty),
        };
        if values[index] == next {
            continue;
        }
        values[index] = next;
        for consumer in &consumers[index] {
            if !queued[*consumer] {
                queued[*consumer] = true;
                queue.push_back(*consumer);
            }
        }
    }
    values
}

fn project_public_formals(
    owners: &[KernelProjectOwnerOutputs],
    artifact: &ComponentOutputSnapshot<'_>,
) -> Box<[Box<[PackedFlow]>]> {
    owners
        .iter()
        .map(|owner| {
            owner
                .formals
                .iter()
                .zip(owner.formal_modes.iter().copied())
                .map(|(output, mode)| {
                    let mut flow = artifact
                        .flow(*output)
                        .expect("project owner formal belongs to its component");
                    flow.mode = mode;
                    flow
                })
                .collect::<Vec<_>>()
                .into_boxed_slice()
        })
        .collect::<Vec<_>>()
        .into_boxed_slice()
}

fn merge_kernel_effects(
    left: KernelEffectSummary,
    right: KernelEffectSummary,
) -> KernelEffectSummary {
    KernelEffectSummary {
        reads_state: left.reads_state || right.reads_state,
        writes_state: left.writes_state || right.writes_state,
        emits_source: left.emits_source || right.emits_source,
        invokes_host: left.invokes_host || right.invokes_host,
    }
}

fn local_expression_effect(kind: &KernelOwnerNodeKind) -> KernelEffectSummary {
    match kind {
        KernelOwnerNodeKind::Source(_) | KernelOwnerNodeKind::SourcePacked(_) => {
            KernelEffectSummary {
                emits_source: true,
                ..KernelEffectSummary::default()
            }
        }
        KernelOwnerNodeKind::Hold
        | KernelOwnerNodeKind::Latest
        | KernelOwnerNodeKind::PureBuiltin {
            kind: KernelPureBuiltinKind::BoolToggle,
        } => KernelEffectSummary {
            reads_state: true,
            writes_state: true,
            ..KernelEffectSummary::default()
        },
        KernelOwnerNodeKind::HostEffect { .. } => KernelEffectSummary {
            invokes_host: true,
            ..KernelEffectSummary::default()
        },
        _ => KernelEffectSummary::default(),
    }
}

fn local_packed_expression_effect(kind: &PackedKernelOwnerNodeKind) -> KernelEffectSummary {
    match kind {
        PackedKernelOwnerNodeKind::Source(_) => KernelEffectSummary {
            emits_source: true,
            ..KernelEffectSummary::default()
        },
        PackedKernelOwnerNodeKind::Hold
        | PackedKernelOwnerNodeKind::Latest
        | PackedKernelOwnerNodeKind::PureBuiltin {
            kind: KernelPureBuiltinKind::BoolToggle,
        } => KernelEffectSummary {
            reads_state: true,
            writes_state: true,
            ..KernelEffectSummary::default()
        },
        PackedKernelOwnerNodeKind::HostEffect { .. } => KernelEffectSummary {
            invokes_host: true,
            ..KernelEffectSummary::default()
        },
        _ => KernelEffectSummary::default(),
    }
}

/// Compute each callable's direct effect surface once over the dense owner
/// graph. Effects form a four-bit monotone lattice, so reverse-call consumers
/// converge by queue exhaustion even for recursive call components.
fn project_owner_effect_summaries(
    program: &PackedKernelProjectProgram,
    definition_facts: &[KernelDefinitionFactsInput],
) -> Box<[KernelEffectSummary]> {
    debug_assert_eq!(definition_facts.len(), program.definition_count());
    let mut summaries = program
        .owners()
        .zip(definition_facts)
        .map(|(input, facts)| {
            let mut summary =
                input
                    .nodes()
                    .iter()
                    .fold(KernelEffectSummary::default(), |summary, expression| {
                        merge_kernel_effects(
                            summary,
                            local_packed_expression_effect(&expression.kind),
                        )
                    });
            for declaration in &facts.declarations {
                match declaration.kind {
                    KernelDeclarationKind::Source => summary.emits_source = true,
                    KernelDeclarationKind::Hold => {
                        summary.reads_state = true;
                        summary.writes_state = true;
                    }
                    KernelDeclarationKind::Function
                    | KernelDeclarationKind::ValueParameter
                    | KernelDeclarationKind::OutParameter
                    | KernelDeclarationKind::Field
                    | KernelDeclarationKind::PatternBinding
                    | KernelDeclarationKind::FreshOut
                    | KernelDeclarationKind::ElementState
                    | KernelDeclarationKind::List => {}
                }
            }
            summary
        })
        .collect::<Vec<_>>();
    let mut consumers = vec![Vec::<usize>::new(); program.definition_count()];
    for (caller, owner) in program.owners().enumerate() {
        for target in owner.nodes().iter().filter_map(|expression| {
            let PackedKernelOwnerNodeKind::UserCall { target, .. } = &expression.kind else {
                return None;
            };
            Some(target.0 as usize)
        }) {
            if let Some(target_consumers) = consumers.get_mut(target) {
                target_consumers.push(caller);
            }
        }
    }
    for target_consumers in &mut consumers {
        target_consumers.sort_unstable();
        target_consumers.dedup();
    }
    let mut queued = vec![true; program.definition_count()];
    let mut pending = (0..program.definition_count()).collect::<VecDeque<_>>();
    while let Some(target) = pending.pop_front() {
        queued[target] = false;
        let target_summary = summaries[target];
        for caller in consumers[target].iter().copied() {
            let merged = merge_kernel_effects(summaries[caller], target_summary);
            if merged != summaries[caller] {
                summaries[caller] = merged;
                if !queued[caller] {
                    queued[caller] = true;
                    pending.push_back(caller);
                }
            }
        }
    }
    summaries.into_boxed_slice()
}

fn direct_expression_effect(
    kind: &KernelOwnerNodeKind,
    owner_effects: &[KernelEffectSummary],
) -> KernelEffectSummary {
    match kind {
        KernelOwnerNodeKind::UserCall { target, .. } => owner_effects
            .get(target.0 as usize)
            .copied()
            .unwrap_or_default(),
        _ => local_expression_effect(kind),
    }
}

fn interface_output_demand(
    program: &PackedKernelProjectProgram,
    definition_facts: &[KernelDefinitionFactsInput],
    owners: &[KernelProjectOwnerOutputs],
) -> Box<[OutputId]> {
    fn insert_value(
        outputs: &mut Vec<OutputId>,
        owners: &[KernelProjectOwnerOutputs],
        caller: usize,
        value: KernelValueReference,
    ) {
        let output = match value {
            KernelValueReference::Local(expression) => owners
                .get(caller)
                .and_then(|owner| owner.expressions.get(expression.0 as usize)),
            KernelValueReference::External(KernelExternalExpression {
                owner,
                target: KernelExternalTarget::Result,
            }) => owners.get(owner.0 as usize).map(|owner| &owner.result),
            KernelValueReference::External(KernelExternalExpression {
                owner,
                target: KernelExternalTarget::Expression(expression),
            }) => owners
                .get(owner.0 as usize)
                .and_then(|owner| owner.expressions.get(expression.0 as usize)),
        };
        if let Some(output) = output {
            outputs.push(*output);
        }
    }

    debug_assert_eq!(program.definition_count(), owners.len());
    debug_assert_eq!(definition_facts.len(), owners.len());
    let estimated = owners
        .iter()
        .enumerate()
        .map(|(index, owner)| {
            owner.formals.len()
                + owner.calls.len() * 2
                + definition_facts[index].diagnostic_values.len()
                + 1
        })
        .sum();
    let mut outputs = Vec::with_capacity(estimated);
    let definitions = KernelProjectDefinitionRefs::new(program, definition_facts, owners)
        .expect("validated definition authorities remain aligned");
    for definition in definitions.definitions() {
        let owner_index = definition.owner.0 as usize;
        outputs.push(definition.outputs.result);
        outputs.extend_from_slice(&definition.outputs.formals);
        for call in definition.calls() {
            for input in call.inputs() {
                insert_value(
                    &mut outputs,
                    owners,
                    owner_index,
                    call.input_value(input)
                        .expect("validated call input remains in its definition namespace"),
                );
            }
            if let Some(output) = call.solve.syntax_discriminated_root_output {
                outputs.push(output);
            }
        }
        for value in definition_facts[owner_index]
            .diagnostic_values
            .iter()
            .copied()
            .map(|value| {
                packed_kernel_value_reference(
                    program
                        .owner_at(owner_index)
                        .expect("validated diagnostic owner remains present"),
                    value,
                    value.0 as usize,
                )
                .expect("validated diagnostic value remains in its definition namespace")
            })
        {
            insert_value(&mut outputs, owners, owner_index, value);
        }
    }
    outputs.sort_unstable();
    outputs.dedup();
    outputs.into_boxed_slice()
}

#[derive(Debug)]
struct KernelInterfaceBuilder {
    definitions: Vec<PackedInterfaceDefinition>,
    flows: Vec<PackedFlow>,
    diagnostics: Vec<PackedDiagnosticMetadata>,
    diagnostic_types: Vec<Option<PackedDiagnosticTypes>>,
    diagnostic_values: Vec<PackedDiagnosticValue>,
    alpha_variables: Vec<TypeVariableId>,
    work: KernelSolveWork,
}

impl KernelInterfaceBuilder {
    fn finish(mut self, types: Arc<FrozenTypeStore>) -> KernelInterfaceSnapshot {
        self.work.frozen_type_store = types.layout();
        KernelInterfaceSnapshot {
            types,
            definitions: self.definitions.into_boxed_slice(),
            flows: self.flows.into_boxed_slice(),
            diagnostics: self.diagnostics.into_boxed_slice(),
            diagnostic_types: self.diagnostic_types.into_boxed_slice(),
            diagnostic_values: self.diagnostic_values.into_boxed_slice(),
            alpha_variables: self.alpha_variables.into_boxed_slice(),
            work: self.work,
        }
    }

    /// Seal only the exact public/diagnostic root DAGs into a compact store.
    /// The source remains the live staged solver arena, so a subsequent
    /// checked-image demand can continue from the same quiescent graph.
    fn finish_reachable(mut self, source: &crate::TypeTermArena) -> KernelInterfaceSnapshot {
        let mut compact = crate::TypeTermArena::with_text(source.text_snapshot().clone());
        let mut term_cache = vec![None; source.len()];
        {
            // Preserve raw IDs until the legacy checked-union Debug ordering
            // contract is replaced. Reordering `Var(10)` and `Var(2)` before
            // interface alpha-normalization would change canonical unions.
            let mut map_variable = |variable: TypeVariableId| variable;
            for definition in &mut self.definitions {
                for flow in &mut self.flows[definition.formals.range()] {
                    flow.term = compact.import_mapped_term(
                        source,
                        flow.term,
                        &mut map_variable,
                        &mut term_cache,
                        false,
                    );
                }
                definition.result.term = compact.import_mapped_term(
                    source,
                    definition.result.term,
                    &mut map_variable,
                    &mut term_cache,
                    false,
                );
                for types in self.diagnostic_types[definition.diagnostics.range()]
                    .iter_mut()
                    .flatten()
                {
                    types.actual = compact.import_mapped_term(
                        source,
                        types.actual,
                        &mut map_variable,
                        &mut term_cache,
                        false,
                    );
                    types.expected = compact.import_mapped_term(
                        source,
                        types.expected,
                        &mut map_variable,
                        &mut term_cache,
                        false,
                    );
                }
                for value in &mut self.diagnostic_values[definition.diagnostic_values.range()] {
                    value.term = compact.import_mapped_term(
                        source,
                        value.term,
                        &mut map_variable,
                        &mut term_cache,
                        false,
                    );
                }
            }
        }
        self.finish(Arc::new(compact.freeze()))
    }
}

fn append_interface_span<T>(
    rows: &mut Vec<T>,
    additional: impl IntoIterator<Item = T>,
    context: &str,
) -> Result<PackedInterfaceSpan, KernelSolveError> {
    let start = u32::try_from(rows.len())
        .map_err(|_| KernelSolveError::new(format!("kernel {context} start exceeds u32")))?;
    rows.extend(additional);
    let end = u32::try_from(rows.len())
        .map_err(|_| KernelSolveError::new(format!("kernel {context} end exceeds u32")))?;
    Ok(PackedInterfaceSpan {
        start,
        len: end - start,
    })
}

fn project_interface_snapshot(
    program: &PackedKernelProjectProgram,
    definition_facts: &[KernelDefinitionFactsInput],
    owners: &[KernelProjectOwnerOutputs],
    artifact: &ComponentOutputSnapshot<'_>,
    solved_results: &[PackedFlow],
    solved_formals: &[Box<[PackedFlow]>],
    solved_diagnostics: &[SolvedDefinitionDiagnostics],
) -> Result<KernelInterfaceBuilder, KernelSolveError> {
    if solved_results.len() != owners.len()
        || solved_formals.len() != owners.len()
        || solved_diagnostics.len() != owners.len()
    {
        return Err(KernelSolveError::new(
            "kernel interface projection received incomplete definition columns",
        ));
    }
    let mut definitions = Vec::with_capacity(owners.len());
    let mut flows = Vec::new();
    let mut diagnostics = Vec::new();
    let mut diagnostic_types = Vec::new();
    let mut diagnostic_values = Vec::new();
    let mut alpha_variables = Vec::new();
    let mut owner_values = Vec::new();
    let mut owner_value_types = Vec::new();
    let mut proof_scratch = DefinitionTermProofScratch::default();
    for (owner, (packed_formals, packed_result)) in
        solved_formals.iter().zip(solved_results).enumerate()
    {
        owner_values.clear();
        owner_values.extend(
            definition_facts[owner]
                .diagnostic_values
                .iter()
                .copied()
                .map(|value| {
                    packed_kernel_value_reference(
                        program
                            .owner_at(owner)
                            .expect("validated diagnostic owner remains present"),
                        value,
                        value.0 as usize,
                    )
                    .expect("validated diagnostic value remains in its definition namespace")
                }),
        );
        owner_value_types.clear();
        owner_value_types.extend(owner_values.iter().map(|value| {
            project_call_value_term(owner, *value, owners, artifact, solved_results)
                .expect("validated diagnostic value has a solved provider")
        }));

        proof_scratch.begin_alpha_variables(artifact.terms());
        for flow in packed_formals {
            proof_scratch.visit_alpha_root(artifact.terms(), flow.term)?;
        }
        proof_scratch.visit_alpha_root(artifact.terms(), packed_result.term)?;
        for diagnostic in &solved_diagnostics[owner].rows {
            if let Some(types) = diagnostic.types {
                proof_scratch.visit_alpha_root(artifact.terms(), types.actual)?;
                proof_scratch.visit_alpha_root(artifact.terms(), types.expected)?;
            }
        }
        for term in owner_value_types.iter().copied() {
            proof_scratch.visit_alpha_root(artifact.terms(), term)?;
        }

        let formals = append_interface_span(
            &mut flows,
            packed_formals.iter().copied(),
            "interface formal",
        )?;
        let diagnostic_start = diagnostics.len();
        diagnostics.extend(
            solved_diagnostics[owner]
                .rows
                .iter()
                .map(|diagnostic| diagnostic.metadata.clone()),
        );
        diagnostic_types.extend(
            solved_diagnostics[owner]
                .rows
                .iter()
                .map(|diagnostic| diagnostic.types),
        );
        let diagnostic_end = diagnostics.len();
        let diagnostic_span = PackedInterfaceSpan {
            start: u32::try_from(diagnostic_start)
                .map_err(|_| KernelSolveError::new("kernel diagnostic start exceeds u32"))?,
            len: u32::try_from(diagnostic_end - diagnostic_start)
                .map_err(|_| KernelSolveError::new("kernel diagnostic count exceeds u32"))?,
        };
        let diagnostic_value_span = append_interface_span(
            &mut diagnostic_values,
            owner_values
                .iter()
                .copied()
                .zip(owner_value_types.iter().copied())
                .map(|(value, term)| PackedDiagnosticValue { value, term }),
            "diagnostic value",
        )?;
        let alpha_span = append_interface_span(
            &mut alpha_variables,
            proof_scratch.alpha_variable_sources().iter().copied(),
            "interface alpha-variable",
        )?;
        definitions.push(PackedInterfaceDefinition {
            result: *packed_result,
            formals,
            diagnostics: diagnostic_span,
            diagnostic_values: diagnostic_value_span,
            alpha_variables: alpha_span,
        });
    }
    Ok(KernelInterfaceBuilder {
        definitions,
        flows,
        diagnostics,
        diagnostic_types,
        diagnostic_values,
        alpha_variables,
        work: artifact.work(),
    })
}

/// Project reusable call facts and user-facing type failures directly from the
/// quiescent graph.
///
/// Derive user-facing call diagnostics from compact call edges and public
/// interfaces. Complete checked demand additionally retains substitutions and
/// exact call-result syntax receipts; diagnostics demand deliberately neither
/// computes nor roots those checked-only facts.
fn packed_call_parameter<'a>(
    program: &'a PackedKernelProjectProgram,
    definition_facts: &'a [KernelDefinitionFactsInput],
    abi: &'a crate::KernelAbiInput,
    target: crate::KernelCallableSchemeId,
    role: KernelCallInputRoleRef<'_>,
) -> Result<(u32, CheckedParameterKind, &'a str), KernelSolveError> {
    match (target, role) {
        (
            crate::KernelCallableSchemeId::User(owner),
            KernelCallInputRoleRef::Formal { ordinal },
        ) => {
            let target_input = program.owner(owner).ok_or_else(|| {
                KernelSolveError::new(format!(
                    "kernel packed call topology references missing user owner {}",
                    owner.0,
                ))
            })?;
            let facts = definition_facts.get(owner.0 as usize).ok_or_else(|| {
                KernelSolveError::new(format!(
                    "kernel packed call topology references missing user facts {}",
                    owner.0,
                ))
            })?;
            let root = facts
                .linkage
                .root_statement
                .and_then(|root| facts.statements.get(root.0 as usize))
                .ok_or_else(|| {
                    KernelSolveError::new(format!(
                        "kernel packed call topology user owner {} has no function header",
                        owner.0,
                    ))
                })?;
            let KernelStatementKind::Function { parameters, .. } = &root.kind else {
                return Err(KernelSolveError::new(format!(
                    "kernel packed call topology user owner {} is not callable",
                    owner.0,
                )));
            };
            let parameter = parameters
                .get(ordinal as usize)
                .filter(|parameter| parameter.ordinal == ordinal)
                .ok_or_else(|| {
                    KernelSolveError::new(format!(
                        "kernel packed call topology user owner {} has no parameter {ordinal}",
                        owner.0,
                    ))
                })?;
            if ordinal >= target_input.formal_count() {
                return Err(KernelSolveError::new(format!(
                    "kernel packed call topology user owner {} parameter {ordinal} is outside its formal count {}",
                    owner.0,
                    target_input.formal_count(),
                )));
            }
            Ok((
                ordinal,
                match parameter.kind {
                    KernelParameterKind::Value => CheckedParameterKind::Value,
                    KernelParameterKind::Out => CheckedParameterKind::Out,
                },
                parameter.name.as_ref(),
            ))
        }
        (crate::KernelCallableSchemeId::Abi(callable), KernelCallInputRoleRef::Abi { name }) => {
            let callable = abi.callable_by_id(callable).ok_or_else(|| {
                KernelSolveError::new(
                    "kernel packed call topology references a missing ABI callable",
                )
            })?;
            let parameter = callable
                .parameters
                .iter()
                .find(|parameter| parameter.name.as_ref() == name)
                .or_else(|| {
                    (name == "$pipe").then(|| {
                        callable
                            .parameters
                            .iter()
                            .find(|parameter| parameter.kind == CheckedParameterKind::Value)
                    })?
                })
                .ok_or_else(|| {
                    KernelSolveError::new(format!(
                        "kernel packed call topology ABI `{}` has no parameter `{name}`",
                        callable.name,
                    ))
                })?;
            Ok((parameter.ordinal, parameter.kind, parameter.name.as_ref()))
        }
        (crate::KernelCallableSchemeId::User(owner), KernelCallInputRoleRef::Abi { name }) => {
            Err(KernelSolveError::new(format!(
                "kernel packed call topology user owner {} received ABI parameter `{name}`",
                owner.0,
            )))
        }
        (
            crate::KernelCallableSchemeId::Abi(callable),
            KernelCallInputRoleRef::Formal { ordinal },
        ) => Err(KernelSolveError::new(format!(
            "kernel packed call topology ABI {} received user formal {ordinal}",
            callable.0,
        ))),
    }
}

fn exact_call_declaration_by_origin<'a>(
    facts: &'a KernelDefinitionFactsInput,
    origin: &KernelDeclarationOrigin,
    label: &str,
) -> Result<&'a KernelDeclarationInput, KernelSolveError> {
    let mut declarations = facts
        .declarations
        .iter()
        .filter(|declaration| &declaration.origin == origin);
    let declaration = declarations.next().ok_or_else(|| {
        KernelSolveError::new(format!(
            "kernel packed call topology has no {label} declaration for {origin:?}",
        ))
    })?;
    if declarations.next().is_some() {
        return Err(KernelSolveError::new(format!(
            "kernel packed call topology has multiple {label} declarations for {origin:?}",
        )));
    }
    Ok(declaration)
}

fn exact_call_declaration_presentation<'a>(
    facts: &'a KernelDefinitionFactsInput,
    declaration: KernelDeclarationId,
) -> Result<&'a KernelDeclarationPresentation, KernelSolveError> {
    facts
        .presentation
        .declarations
        .get(declaration.0 as usize)
        .filter(|row| row.declaration == declaration)
        .ok_or_else(|| {
            KernelSolveError::new(format!(
                "kernel packed call topology declaration {} has no presentation row",
                declaration.0,
            ))
        })
}

fn project_call_facts_and_diagnostics(
    program: &PackedKernelProjectProgram,
    definition_facts: &[KernelDefinitionFactsInput],
    owners: &[KernelProjectOwnerOutputs],
    abi: &crate::KernelAbiInput,
    artifact: &mut ComponentOutputSnapshot<'_>,
    public_results: &[PackedFlow],
    public_formals: &[Box<[PackedFlow]>],
    retain_call_facts: bool,
) -> Result<SolvedProjectCallProjection, KernelSolveError> {
    let abi_catalog = if retain_call_facts {
        let first_projection_variable = u32::try_from(artifact.work().variables)
            .expect("kernel solver variable namespace exceeds u32");
        pack_abi_call_surfaces(abi, artifact.terms_mut(), first_projection_variable)?
    } else {
        crate::PackedAbiCatalogInput::empty(abi.role())
    };
    let mut project_call_facts = Vec::with_capacity(owners.len());
    let mut project_diagnostics = Vec::with_capacity(owners.len());
    let mut call_scratch = crate::PackedCallTypeScratch::default();
    let mut actuals = Vec::new();
    let mut substitutions = Vec::new();
    let mut mismatch_path = Vec::new();
    let definitions = KernelProjectDefinitionRefs::new(program, definition_facts, owners)
        .expect("validated definition authorities remain aligned");
    for definition in definitions.definitions() {
        let owner_index = definition.owner.0 as usize;
        let owner_id = definition.owner;
        let owner = definition.outputs;
        let mut owner_call_facts = Vec::with_capacity(owner.calls.len());
        let mut owner_call_entries = Vec::new();
        let mut owner_call_contexts = Vec::new();
        let mut owner_call_substitutions = Vec::new();
        let mut diagnostics = collect_packed_definition_diagnostic_artifacts(
            owner_id,
            definition.input,
            definition.facts,
        )
        .expect("validated definition diagnostics remain structurally valid")
        .into_vec()
        .into_iter()
        .map(|diagnostic| SolvedKernelDiagnostic {
            metadata: PackedDiagnosticMetadata::Plain(diagnostic),
            types: None,
        })
        .collect::<Vec<_>>();
        for (call_ordinal, call) in definition.calls().enumerate() {
            let call_target = call.target();
            let mut target_scheme = match call_target {
                KernelCallTargetRef::User { target, .. } => {
                    Some(crate::KernelCallableSchemeId::User(target))
                }
                KernelCallTargetRef::RenderConstructor { .. }
                | KernelCallTargetRef::PureBuiltin { .. }
                | KernelCallTargetRef::FixedAbi
                | KernelCallTargetRef::HostEffect { .. }
                | KernelCallTargetRef::FieldProjection { .. } => None,
            };
            substitutions.clear();
            if let KernelCallTargetRef::User { target, .. } = call_target {
                let target_formals = public_formals
                    .get(target.0 as usize)
                    .expect("validated kernel call target has public formals");
                let target_result = public_results
                    .get(target.0 as usize)
                    .expect("validated kernel call target has a public result");

                actuals.clear();
                for input in call.inputs() {
                    let Ok(KernelCallInputRoleRef::Formal { ordinal }) = call.input_role(input)
                    else {
                        continue;
                    };
                    let Ok(value) = call.input_value(input) else {
                        continue;
                    };
                    if let Some(actual) = project_call_value_term(
                        owner_index,
                        value,
                        owners,
                        artifact,
                        public_results,
                    ) {
                        actuals.push((ordinal, actual));
                    }
                }
                if let KernelCallTargetRef::User {
                    inherited_formal: Some(inherited),
                    ..
                } = call_target
                    && let Some(actual) = public_formals
                        .get(owner_index)
                        .and_then(|formals| formals.get(inherited.caller_ordinal as usize))
                {
                    actuals.push((inherited.target_ordinal, actual.term));
                }
                crate::derive_packed_call_type_substitutions(
                    artifact.terms(),
                    target_formals,
                    *target_result,
                    &actuals,
                    None,
                    &mut call_scratch,
                    &mut substitutions,
                );
                // Inherited context has no authored call-input site. Its
                // requirements are propagated through the separate formal
                // requirement channel and are intentionally not diagnosed as
                // an explicit argument error here.
                for input in call.inputs() {
                    let Ok(KernelCallInputRoleRef::Formal { ordinal }) = call.input_role(input)
                    else {
                        continue;
                    };
                    if owners.get(target.0 as usize).is_some_and(|target| {
                        target
                            .syntax_discriminated_formals
                            .binary_search(&ordinal)
                            .is_ok()
                    }) {
                        // The target's aggregate formal combines projection
                        // requirements from mutually exclusive syntax arms.
                        // It is a solver surface, not a direct object-shape
                        // contract for this occurrence.
                        continue;
                    }
                    let Ok(value) = call.input_value(input) else {
                        continue;
                    };
                    let Some(actual) = project_call_value_term(
                        owner_index,
                        value,
                        owners,
                        artifact,
                        public_results,
                    ) else {
                        continue;
                    };
                    let Some(expected) = target_formals.get(ordinal as usize) else {
                        continue;
                    };
                    let expected = crate::instantiate_packed_call_type(
                        artifact.terms_mut(),
                        expected.term,
                        &substitutions,
                        &mut call_scratch,
                    );
                    if crate::packed_type_is_assignable_to(artifact.terms(), actual, expected) {
                        continue;
                    }
                    let mismatch = packed_kernel_type_mismatch(
                        artifact.terms(),
                        actual,
                        expected,
                        &mut mismatch_path,
                    );
                    diagnostics.push(SolvedKernelDiagnostic {
                        metadata: PackedDiagnosticMetadata::CallInputType {
                            owner: owner_id,
                            severity: KernelDiagnosticSeverity::Error,
                            site: KernelDiagnosticSite::CallInput {
                                call: call.expression(),
                                target,
                                formal_ordinal: ordinal,
                            },
                            mismatch,
                        },
                        types: Some(PackedDiagnosticTypes { actual, expected }),
                    });
                }
            } else if retain_call_facts {
                target_scheme = project_abi_call_type_substitutions(
                    owner_index,
                    call,
                    owners,
                    abi,
                    artifact,
                    public_results,
                    &abi_catalog,
                    &mut call_scratch,
                    &mut actuals,
                    &mut substitutions,
                )
                .map(crate::KernelCallableSchemeId::Abi);
            }
            if !retain_call_facts {
                continue;
            }
            let source_topology_complete = definition
                .facts
                .call_syntax
                .get(call_ordinal)
                .is_some_and(|syntax| syntax.expression == call.expression())
                && definition
                    .facts
                    .presentation
                    .expressions
                    .get(call.expression().0 as usize)
                    .is_some_and(|row| row.expression == call.expression());
            if cfg!(test) && !source_topology_complete {
                // Focused solver tests intentionally construct only type
                // equations. They never enter the checked linker, so retain
                // their call type facts while leaving source topology absent.
                // Non-test builds fail closed below and can never publish a
                // RuntimePacked call without exact syntax/presentation.
                let substitution_start = u32::try_from(owner_call_substitutions.len())
                    .expect("kernel definition call-substitution start exceeds u32");
                owner_call_substitutions.extend_from_slice(&substitutions);
                let substitution_len = u32::try_from(substitutions.len())
                    .expect("kernel definition call-substitution count exceeds u32");
                let result_output = owner.expressions.get(call.expression().0 as usize).copied();
                let result_is_concrete = result_output
                    .and_then(|output| artifact.term(output))
                    .is_some_and(|term| {
                        packed_term_has_concrete_outer_shape(artifact.terms(), term)
                    });
                let call_syntax_selected = result_output.is_some_and(|output| {
                    artifact
                        .output_flags(output)
                        .is_some_and(|flags| flags.call_syntax_selected)
                });
                let exact_structural_constructor = matches!(
                    call_target,
                    KernelCallTargetRef::RenderConstructor { .. }
                        | KernelCallTargetRef::PureBuiltin {
                            kind: KernelPureBuiltinKind::RecordConstructor,
                        }
                );
                owner_call_facts.push(PackedCallFactsInput {
                    expression: call.expression(),
                    target: target_scheme,
                    function: None,
                    entry_start: u32::try_from(owner_call_entries.len())
                        .expect("kernel definition call-entry start exceeds u32"),
                    entry_len: 0,
                    context_start: u32::try_from(owner_call_contexts.len())
                        .expect("kernel definition call-context start exceeds u32"),
                    context_len: 0,
                    context_binding: PackedCallContextBinding::None,
                    substitution_start,
                    substitution_len,
                    syntax_discriminated_result: (exact_structural_constructor
                        || call.solve.syntax_discriminated_candidate
                        || (matches!(call_target, KernelCallTargetRef::User { .. })
                            && (call_syntax_selected
                                || call.solve.syntax_discriminated_root_output.is_some_and(
                                    |output| {
                                        artifact
                                            .output_flags(output)
                                            .is_some_and(|flags| flags.syntax_selected_here)
                                    },
                                ))))
                        && result_is_concrete,
                    span: KernelSourceSpan::default(),
                    authored_site_digest_v4: [0; 32],
                });
                continue;
            }
            let syntax = definition
                .facts
                .call_syntax
                .get(call_ordinal)
                .filter(|syntax| syntax.expression == call.expression())
                .ok_or_else(|| {
                    KernelSolveError::new(format!(
                        "kernel definition {} call expression {} has no aligned authored syntax row",
                        owner_id.0,
                        call.expression().0,
                    ))
                })?;
            let target_scheme = target_scheme.ok_or_else(|| {
                KernelSolveError::new(format!(
                    "kernel definition {} call `{}` has no retained target scheme",
                    owner_id.0, syntax.function,
                ))
            })?;
            let function = artifact
                .terms()
                .text_snapshot()
                .lookup_symbol(&syntax.function)
                .ok_or_else(|| {
                    KernelSolveError::new(format!(
                        "kernel definition {} call function `{}` is absent from the project text authority",
                        owner_id.0, syntax.function,
                    ))
                })?;
            let presentation = definition
                .facts
                .presentation
                .expressions
                .get(call.expression().0 as usize)
                .filter(|row| row.expression == call.expression())
                .ok_or_else(|| {
                    KernelSolveError::new(format!(
                        "kernel definition {} call expression {} has no presentation row",
                        owner_id.0,
                        call.expression().0,
                    ))
                })?;
            let entry_start = u32::try_from(owner_call_entries.len())
                .expect("kernel definition call-entry start exceeds u32");
            let pipe_input = syntax
                .pipe_input
                .map(|value| definition.resolve_value(value, call.expression().0 as usize))
                .transpose()
                .map_err(|error| KernelSolveError::new(error.to_string()))?;
            for input in call.inputs() {
                let role = call
                    .input_role(input)
                    .map_err(|error| KernelSolveError::new(error.to_string()))?;
                if let (
                    KernelCallTargetRef::User { target, .. },
                    KernelCallInputRoleRef::Formal { ordinal },
                ) = (call_target, role)
                    && definition_facts
                        .get(target.0 as usize)
                        .is_some_and(|facts| facts.linkage.context_formal_ordinal == Some(ordinal))
                {
                    // PASSED is retained by the dedicated context binding,
                    // never as an ordinary call entry.
                    continue;
                }
                let value = call
                    .input_value(input)
                    .map_err(|error| KernelSolveError::new(error.to_string()))?;
                let (parameter_ordinal, parameter_kind, parameter_name) =
                    packed_call_parameter(program, definition_facts, abi, target_scheme, role)?;
                let from_pipe = pipe_input == Some(value);
                let argument = if from_pipe {
                    None
                } else {
                    syntax.arguments.iter().find(|argument| {
                        argument.name.as_ref() == parameter_name
                            && definition
                                .resolve_value(argument.value, call.expression().0 as usize)
                                .is_ok_and(|argument| argument == value)
                    })
                };
                match parameter_kind {
                    CheckedParameterKind::Value => {
                        if argument
                            .is_some_and(|argument| argument.kind != KernelCallArgumentKind::Named)
                        {
                            return Err(KernelSolveError::new(format!(
                                "kernel definition {} call `{}` binds value input `{parameter_name}` as a bare OUT",
                                owner_id.0, syntax.function,
                            )));
                        }
                        if !from_pipe && argument.is_none() {
                            return Err(KernelSolveError::new(format!(
                                "kernel definition {} call `{}` value input `{parameter_name}` has no exact authored argument",
                                owner_id.0, syntax.function,
                            )));
                        }
                        owner_call_entries.push(PackedCallEntry::Input {
                            parameter_ordinal,
                            value,
                            from_pipe,
                        });
                    }
                    CheckedParameterKind::Out => {
                        if from_pipe {
                            return Err(KernelSolveError::new(format!(
                                "kernel definition {} call `{}` pipes into OUT parameter `{parameter_name}`",
                                owner_id.0, syntax.function,
                            )));
                        }
                        let argument = argument.ok_or_else(|| {
                            KernelSolveError::new(format!(
                                "kernel definition {} call `{}` OUT input `{parameter_name}` has no exact authored argument",
                                owner_id.0, syntax.function,
                            ))
                        })?;
                        match argument.kind {
                            KernelCallArgumentKind::BareBinding => {
                                let declaration = exact_call_declaration_by_origin(
                                    definition.facts,
                                    &KernelDeclarationOrigin::CallbackBinding {
                                        call: call.expression(),
                                        ordinal: parameter_ordinal,
                                    },
                                    "FreshOut",
                                )?;
                                let presentation = exact_call_declaration_presentation(
                                    definition.facts,
                                    declaration.id,
                                )?;
                                let scope = presentation.body_scope.ok_or_else(|| {
                                    KernelSolveError::new(format!(
                                        "kernel definition {} FreshOut `{parameter_name}` has no output scope",
                                        owner_id.0,
                                    ))
                                })?;
                                owner_call_entries.push(PackedCallEntry::FreshOut {
                                    parameter_ordinal,
                                    output: declaration.id,
                                    scope,
                                });
                            }
                            KernelCallArgumentKind::Named => {
                                let KernelValueReference::Local(expression) = value else {
                                    return Err(KernelSolveError::new(format!(
                                        "kernel definition {} call `{}` forwards OUT `{parameter_name}` through a non-local occurrence",
                                        owner_id.0, syntax.function,
                                    )));
                                };
                                let binding = definition
                                    .facts
                                    .lexical_bindings
                                    .iter()
                                    .find(|binding| {
                                        binding.expression == expression
                                            && binding.projection.is_empty()
                                    })
                                    .ok_or_else(|| {
                                        KernelSolveError::new(format!(
                                            "kernel definition {} call `{}` forwarded OUT `{parameter_name}` has no exact lexical target",
                                            owner_id.0, syntax.function,
                                        ))
                                    })?;
                                let KernelLexicalBindingTargetInput::Declaration(target) =
                                    binding.target
                                else {
                                    return Err(KernelSolveError::new(format!(
                                        "kernel definition {} call `{}` forwarded OUT `{parameter_name}` targets a non-declaration",
                                        owner_id.0, syntax.function,
                                    )));
                                };
                                owner_call_entries.push(PackedCallEntry::ForwardOut {
                                    parameter_ordinal,
                                    target,
                                });
                            }
                        }
                    }
                }
            }
            let entry_len = u32::try_from(owner_call_entries.len())
                .expect("kernel definition call-entry count exceeds u32")
                .checked_sub(entry_start)
                .expect("kernel definition call-entry range is monotonic");

            let context_start = u32::try_from(owner_call_contexts.len())
                .expect("kernel definition call-context start exceeds u32");
            if let crate::KernelCallableSchemeId::Abi(callable) = target_scheme {
                let callable = abi.callable_by_id(callable).ok_or_else(|| {
                    KernelSolveError::new(format!(
                        "kernel definition {} call `{}` references a missing ABI context scheme",
                        owner_id.0, syntax.function,
                    ))
                })?;
                for (context_ordinal, context) in callable.contexts.iter().enumerate() {
                    let context_ordinal = u32::try_from(context_ordinal)
                        .expect("kernel call-context ordinal exceeds u32");
                    let declaration = exact_call_declaration_by_origin(
                        definition.facts,
                        &KernelDeclarationOrigin::CallContext {
                            call: call.expression(),
                            ordinal: context_ordinal,
                        },
                        "call context",
                    )?;
                    if declaration.name != context.name {
                        return Err(KernelSolveError::new(format!(
                            "kernel definition {} call `{}` context {context_ordinal} is named `{}` instead of `{}`",
                            owner_id.0, syntax.function, declaration.name, context.name,
                        )));
                    }
                    let presentation =
                        exact_call_declaration_presentation(definition.facts, declaration.id)?;
                    owner_call_contexts.push(PackedCallContext {
                        declaration: declaration.id,
                        signature_ordinal: context_ordinal,
                        scope: presentation.scope,
                    });
                }
            }
            let context_len = u32::try_from(owner_call_contexts.len())
                .expect("kernel definition call-context count exceeds u32")
                .checked_sub(context_start)
                .expect("kernel definition call-context range is monotonic");
            let context_binding = if let Some(pass) = syntax.pass {
                PackedCallContextBinding::Explicit {
                    value: definition
                        .resolve_value(pass.value, call.expression().0 as usize)
                        .map_err(|error| KernelSolveError::new(error.to_string()))?,
                    span: pass.span,
                }
            } else if let KernelCallTargetRef::User {
                inherited_formal: Some(inherited),
                ..
            } = call_target
            {
                if definition.facts.linkage.context_formal_ordinal != Some(inherited.caller_ordinal)
                {
                    return Err(KernelSolveError::new(format!(
                        "kernel definition {} call `{}` inherits caller formal {} without matching linkage",
                        owner_id.0, syntax.function, inherited.caller_ordinal,
                    )));
                }
                PackedCallContextBinding::Inherited {
                    caller_formal_ordinal: inherited.caller_ordinal,
                }
            } else {
                PackedCallContextBinding::None
            };
            let substitution_start = u32::try_from(owner_call_substitutions.len())
                .expect("kernel definition call-substitution start exceeds u32");
            owner_call_substitutions.extend_from_slice(&substitutions);
            let substitution_len = u32::try_from(substitutions.len())
                .expect("kernel definition call-substitution count exceeds u32");
            let result_output = owner.expressions.get(call.expression().0 as usize).copied();
            let result_is_concrete = result_output
                .and_then(|output| artifact.term(output))
                .is_some_and(|term| packed_term_has_concrete_outer_shape(artifact.terms(), term));
            let call_syntax_selected = result_output.is_some_and(|output| {
                artifact
                    .output_flags(output)
                    .is_some_and(|flags| flags.call_syntax_selected)
            });
            let exact_structural_constructor = matches!(
                call_target,
                KernelCallTargetRef::RenderConstructor { .. }
                    | KernelCallTargetRef::PureBuiltin {
                        kind: KernelPureBuiltinKind::RecordConstructor,
                    }
            );
            owner_call_facts.push(PackedCallFactsInput {
                expression: call.expression(),
                target: Some(target_scheme),
                function: Some(function),
                entry_start,
                entry_len,
                context_start,
                context_len,
                context_binding,
                substitution_start,
                substitution_len,
                // CheckedCall exposes one existing exact-occurrence bit to
                // OutNet. Besides a selected user-call result, a structural
                // constructor is intrinsically occurrence-owned: its named
                // arguments are part of the solved record even when the
                // immutable ABI signature intentionally retains only a
                // kind-only base contract.
                syntax_discriminated_result: (exact_structural_constructor
                    || call.solve.syntax_discriminated_candidate
                    || (matches!(call_target, KernelCallTargetRef::User { .. })
                        && (call_syntax_selected
                            || call.solve.syntax_discriminated_root_output.is_some_and(
                                |output| {
                                    artifact
                                        .output_flags(output)
                                        .is_some_and(|flags| flags.syntax_selected_here)
                                },
                            ))))
                    && result_is_concrete,
                span: presentation.span,
                authored_site_digest_v4: syntax.authored_site_digest_v4,
            });
        }
        diagnostics.sort_unstable_by(|left, right| left.metadata.site().cmp(right.metadata.site()));
        project_call_facts.push(SolvedDefinitionCallFacts {
            calls: owner_call_facts.into_boxed_slice(),
            entries: owner_call_entries.into_boxed_slice(),
            contexts: owner_call_contexts.into_boxed_slice(),
            substitutions: owner_call_substitutions.into_boxed_slice(),
        });
        project_diagnostics.push(SolvedDefinitionDiagnostics {
            rows: diagnostics.into_boxed_slice(),
        });
    }
    Ok(SolvedProjectCallProjection {
        definitions: project_call_facts.into_boxed_slice(),
        diagnostics: project_diagnostics.into_boxed_slice(),
        abi_catalog,
    })
}

/// Publish immutable-ABI substitutions while the caller's solver namespace is
/// still authoritative. `DefinitionCodeBuilder` then imports these values as
/// caller-owned packed roots and alpha-links them exactly once. Reconstructing
/// the substitutions later from a provider's rich checked row loses that
/// caller-frame ownership for cross-definition inputs.
fn project_abi_call_type_substitutions(
    owner_index: usize,
    call: KernelProjectCallRef<'_>,
    owners: &[KernelProjectOwnerOutputs],
    abi: &crate::KernelAbiInput,
    artifact: &ComponentOutputSnapshot<'_>,
    public_results: &[PackedFlow],
    packed_abi: &crate::PackedAbiCatalogInput,
    scratch: &mut crate::PackedCallTypeScratch,
    actuals: &mut Vec<(u32, TypeTermId)>,
    substitutions: &mut Vec<PackedCallTypeSubstitution>,
) -> Option<crate::KernelAbiCallableId> {
    let facts = call.definition.facts;
    let Ok(syntax) = facts
        .call_syntax
        .binary_search_by_key(&call.expression(), |syntax| syntax.expression)
        .map(|index| &facts.call_syntax[index])
    else {
        // Lower-level equation tests intentionally omit checked-image syntax.
        // Production linking validates and requires the authored row.
        return None;
    };
    let Some(target_id) = abi.callable_id(&syntax.function) else {
        // The same lower-level tests may install a builtin equation directly
        // without the project ABI table. A production project cannot reach the
        // checked linker with that incomplete contract.
        return None;
    };
    let target = abi
        .callable_by_id(target_id)
        .expect("validated ABI callable ID resolves");
    let packed_target = &packed_abi.callables[target_id.0 as usize];
    let packed_formals = packed_target
        .formals
        .get(&packed_abi.formals)
        .expect("fresh packed ABI formal span is valid");
    actuals.clear();
    for input in call.inputs() {
        let Ok(KernelCallInputRoleRef::Abi { name }) = call.input_role(input) else {
            continue;
        };
        let Some(parameter) = target
            .parameters
            .iter()
            .find(|parameter| parameter.name.as_ref() == name)
            .or_else(|| {
                (name == "$pipe").then(|| {
                    target.parameters.iter().find(|parameter| {
                        parameter.kind == boon_checked::CheckedParameterKind::Value
                    })
                })?
            })
        else {
            continue;
        };
        let Ok(value) = call.input_value(input) else {
            continue;
        };
        if let Some(actual) =
            project_call_value_term(owner_index, value, owners, artifact, public_results)
        {
            actuals.push((parameter.ordinal, actual));
        }
    }
    let actual_result = matches!(
        call.target(),
        KernelCallTargetRef::PureBuiltin {
            kind: KernelPureBuiltinKind::ListAppend
                | KernelPureBuiltinKind::MapUpsert
                | KernelPureBuiltinKind::SetAdd,
        }
    )
    .then(|| {
        project_call_value_term(
            owner_index,
            KernelValueReference::Local(call.expression()),
            owners,
            artifact,
            public_results,
        )
    })
    .flatten();
    crate::derive_packed_call_type_substitutions(
        artifact.terms(),
        packed_formals,
        packed_target.result,
        actuals,
        actual_result,
        scratch,
        substitutions,
    );
    Some(target_id)
}

fn project_call_value_term(
    caller: usize,
    value: KernelValueReference,
    owners: &[KernelProjectOwnerOutputs],
    artifact: &ComponentOutputSnapshot<'_>,
    public_results: &[PackedFlow],
) -> Option<TypeTermId> {
    match value {
        KernelValueReference::Local(expression) => owners
            .get(caller)?
            .expressions
            .get(expression.0 as usize)
            .and_then(|output| artifact.term(*output)),
        KernelValueReference::External(KernelExternalExpression {
            owner,
            target: KernelExternalTarget::Result,
        }) => public_results
            .get(owner.0 as usize)
            .map(|result| result.term),
        KernelValueReference::External(KernelExternalExpression {
            owner,
            target: KernelExternalTarget::Expression(expression),
        }) => owners
            .get(owner.0 as usize)?
            .expressions
            .get(expression.0 as usize)
            .and_then(|output| artifact.term(*output)),
    }
}

fn pack_abi_call_surfaces(
    abi: &crate::KernelAbiInput,
    terms: &mut crate::TypeTermArena,
    mut next_variable: u32,
) -> Result<crate::PackedAbiCatalogInput, KernelSolveError> {
    let referenced_abi_fingerprint_v1 = boon_contract::canonical_serde_hash_v1(
        crate::KERNEL_CHECKED_REFERENCED_ABI_SEAL_DOMAIN_V1,
        abi,
    )
    .map_err(|error| {
        KernelSolveError::new(format!(
            "cannot fingerprint packed kernel ABI input: {error}"
        ))
    })?;
    let mut parameter_scratch = crate::PackedCallableParameterTraversalScratch::default();
    let mut parameter_sources = Vec::new();
    let mut callables = Vec::with_capacity(abi.callables().len());
    let mut formals = Vec::new();
    let mut parameters = Vec::new();
    let mut contexts = Vec::new();
    let mut type_parameters = Vec::new();
    let mut default_text = Vec::new();
    for callable in abi.callables() {
        let callable_name = terms
            .text_snapshot()
            .lookup_symbol(&callable.name)
            .ok_or_else(|| {
                KernelSolveError::new(format!(
                    "packed ABI callable `{}` is absent from the project text authority",
                    callable.name,
                ))
            })?;
        let parameter_start = parameters.len();
        for parameter in &callable.parameters {
            let name = terms
                .text_snapshot()
                .lookup_symbol(&parameter.name)
                .ok_or_else(|| {
                    KernelSolveError::new(format!(
                        "packed ABI callable `{}` parameter `{}` is absent from the project text authority",
                        callable.name, parameter.name,
                    ))
                })?;
            let requirement = match &parameter.requirement {
                boon_checked::CheckedParameterRequirement::Required => {
                    crate::PackedAbiParameterRequirement::Required
                }
                boon_checked::CheckedParameterRequirement::Optional { default } => match default {
                    boon_checked::CheckedParameterDefault::CallableProfile { profile } => {
                        crate::PackedAbiParameterRequirement::CallableProfile(
                            terms.text_snapshot().lookup_symbol(profile).ok_or_else(|| {
                                KernelSolveError::new(format!(
                                    "packed ABI callable `{}` parameter `{}` profile `{profile}` is absent from the project text authority",
                                    callable.name, parameter.name,
                                ))
                            })?,
                        )
                    }
                    boon_checked::CheckedParameterDefault::Tag { name } => {
                        crate::PackedAbiParameterRequirement::Tag(
                            terms.text_snapshot().lookup_symbol(name).ok_or_else(|| {
                                KernelSolveError::new(format!(
                                    "packed ABI callable `{}` parameter `{}` tag `{name}` is absent from the project text authority",
                                    callable.name, parameter.name,
                                ))
                            })?,
                        )
                    }
                    boon_checked::CheckedParameterDefault::ExactInteger { value } => {
                        crate::PackedAbiParameterRequirement::ExactInteger(*value)
                    }
                    boon_checked::CheckedParameterDefault::Text { value } => {
                        let start = default_text.len();
                        default_text.extend_from_slice(value.as_bytes());
                        crate::PackedAbiParameterRequirement::Text(crate::Span32::from_bounds(
                            start,
                            default_text.len(),
                            "ABI default text",
                        )?)
                    }
                },
            };
            parameters.push(crate::PackedAbiParameter {
                name,
                kind: parameter.kind,
                ordinal: parameter.ordinal,
                requirement,
                evaluation_scope: parameter.evaluation_scope,
            });
        }
        let parameter_span =
            crate::Span32::from_bounds(parameter_start, parameters.len(), "ABI parameter")?;

        let base = next_variable;
        let mut variable_count = 0_u32;
        for parameter in &callable.parameters {
            extend_checked_type_variable_extent(&parameter.flow_type.ty, &mut variable_count);
        }
        for context in &callable.contexts {
            extend_checked_type_variable_extent(&context.flow_type.ty, &mut variable_count);
        }
        extend_checked_type_variable_extent(&callable.result.ty, &mut variable_count);

        let formal_start = formals.len();
        let context_start = contexts.len();
        for parameter in &callable.parameters {
            formals.push(PackedFlow {
                mode: parameter.flow_type.mode,
                term: import_abi_type(terms, &parameter.flow_type.ty, base, variable_count),
            });
        }
        for context in &callable.contexts {
            let name = terms
                .text_snapshot()
                .lookup_symbol(&context.name)
                .expect("validated ABI context name belongs to the frozen text authority");
            contexts.push(crate::PackedAbiContext {
                name,
                kind: context.kind,
                provider_parameter_ordinal: context.provider_parameter_ordinal,
                flow: PackedFlow {
                    mode: context.flow_type.mode,
                    term: import_abi_type(terms, &context.flow_type.ty, base, variable_count),
                },
            });
        }
        let result = PackedFlow {
            mode: callable.result.mode,
            term: import_abi_type(terms, &callable.result.ty, base, variable_count),
        };
        let formal_span = crate::Span32::from_bounds(formal_start, formals.len(), "ABI formal")?;
        let context_span =
            crate::Span32::from_bounds(context_start, contexts.len(), "ABI context")?;
        next_variable = next_variable.checked_add(variable_count).ok_or_else(|| {
            KernelSolveError::new("kernel ABI projection variable namespace exceeds u32")
        })?;
        collect_packed_callable_type_parameter_sources(
            terms,
            formal_span
                .get(&formals)
                .expect("fresh packed ABI formal span is valid")
                .iter()
                .map(|formal| formal.term),
            result.term,
            &mut parameter_scratch,
            &mut parameter_sources,
        );
        let type_parameter_start = type_parameters.len();
        type_parameters.extend(parameter_sources.iter().copied().map(|source| {
            PackedCallableTypeParameter {
                source,
                linked_local: source
                    .0
                    .checked_sub(base)
                    .expect("packed ABI parameter precedes its variable base"),
            }
        }));
        let type_parameter_span = crate::Span32::from_bounds(
            type_parameter_start,
            type_parameters.len(),
            "ABI type parameter",
        )?;
        callables.push(crate::PackedAbiCallableScheme {
            name: callable_name,
            kind: callable.kind,
            intrinsic: callable.intrinsic,
            external_identity: callable.external_identity,
            parameters: parameter_span,
            contexts: context_span,
            formals: formal_span,
            result,
            type_parameters: type_parameter_span,
            variable_base: TypeVariableId(base),
            variable_count,
            effect: callable.effect,
            contextual_operation: callable.contextual_operation,
        });
    }
    Ok(crate::PackedAbiCatalogInput {
        role: abi.role(),
        referenced_abi_fingerprint_v1,
        callables: callables.into_boxed_slice(),
        formals: formals.into_boxed_slice(),
        parameters: parameters.into_boxed_slice(),
        contexts: contexts.into_boxed_slice(),
        type_parameters: type_parameters.into_boxed_slice(),
        default_text: default_text.into_boxed_slice(),
    })
}

fn import_abi_type(
    terms: &mut crate::TypeTermArena,
    ty: &Type,
    variable_base: u32,
    variable_count: u32,
) -> TypeTermId {
    terms.import_checked_type(ty, &mut |source| {
        debug_assert!(source.0 < variable_count);
        TypeVariableId(
            variable_base
                .checked_add(source.0)
                .expect("kernel ABI projection variable namespace exceeds u32"),
        )
    })
}

fn extend_checked_type_variable_extent(ty: &Type, extent: &mut u32) {
    match ty {
        Type::Var(variable) => *extent = (*extent).max(variable.0.saturating_add(1)),
        Type::Object(shape) => {
            for field in shape.fields.values() {
                extend_checked_type_variable_extent(field, extent);
            }
        }
        Type::List(item) | Type::Set(item) => extend_checked_type_variable_extent(item, extent),
        Type::Map { key, value } => {
            extend_checked_type_variable_extent(key, extent);
            extend_checked_type_variable_extent(value, extent);
        }
        Type::Function { args, result } => {
            for argument in args {
                extend_checked_type_variable_extent(argument, extent);
            }
            extend_checked_type_variable_extent(&result.ty, extent);
        }
        Type::VariantSet(variants) => {
            for variant in variants {
                if let Variant::Tagged { fields, .. } = variant {
                    for field in fields.fields.values() {
                        extend_checked_type_variable_extent(field, extent);
                    }
                }
            }
        }
        Type::Union(members) => {
            for member in members {
                extend_checked_type_variable_extent(member, extent);
            }
        }
        Type::Text
        | Type::Number
        | Type::Bytes(_)
        | Type::Bits { .. }
        | Type::Absent
        | Type::RenderContract
        | Type::UnresolvedShape { .. }
        | Type::Unknown => {}
    }
}

fn packed_kernel_type_mismatch(
    terms: &crate::TypeTermArena,
    actual: TypeTermId,
    expected: TypeTermId,
    path: &mut Vec<SymbolId>,
) -> KernelTypeMismatch {
    match crate::packed_type_mismatch(terms, actual, expected, path) {
        crate::PackedTypeMismatchKind::Type => KernelTypeMismatch::Type,
        crate::PackedTypeMismatchKind::MissingField => KernelTypeMismatch::MissingField(
            path.iter()
                .map(|field| terms.name(*field))
                .collect::<Vec<_>>()
                .join(".")
                .into_boxed_str(),
        ),
        crate::PackedTypeMismatchKind::IncompatibleField => KernelTypeMismatch::IncompatibleField(
            path.iter()
                .map(|field| terms.name(*field))
                .collect::<Vec<_>>()
                .join(".")
                .into_boxed_str(),
        ),
    }
}

#[cfg(test)]
fn instantiate_kernel_call_type(
    ty: &Type,
    target_formals: &[FlowType],
    target_result: &FlowType,
    substitutions: &[KernelCallTypeSubstitution],
) -> Type {
    let mut parameter_ids = BTreeMap::new();
    for formal in target_formals {
        collect_callable_type_parameters(&formal.ty, &mut parameter_ids);
    }
    collect_callable_type_parameters(&target_result.ty, &mut parameter_ids);
    let substitutions = substitutions
        .iter()
        .map(|substitution| (substitution.variable, &substitution.value))
        .collect::<BTreeMap<_, _>>();
    substitute_kernel_call_type(ty, &parameter_ids, &substitutions)
}

#[cfg(test)]
fn substitute_kernel_call_type(
    ty: &Type,
    parameter_ids: &BTreeMap<boon_checked::TypeVar, KernelTypeParameterId>,
    substitutions: &BTreeMap<KernelTypeParameterId, &Type>,
) -> Type {
    match ty {
        Type::Var(variable) => parameter_ids
            .get(variable)
            .and_then(|parameter| substitutions.get(parameter).copied())
            .cloned()
            .unwrap_or_else(|| ty.clone()),
        Type::Object(shape) => Type::object(ObjectShape {
            fields: shape
                .fields
                .iter()
                .map(|(name, field)| {
                    (
                        name.clone(),
                        substitute_kernel_call_type(field, parameter_ids, substitutions),
                    )
                })
                .collect(),
            field_order: shape.field_order.clone(),
            open: shape.open,
        }),
        Type::List(item) => Type::List(Type::shared(substitute_kernel_call_type(
            item,
            parameter_ids,
            substitutions,
        ))),
        Type::Set(item) => Type::Set(Type::shared(substitute_kernel_call_type(
            item,
            parameter_ids,
            substitutions,
        ))),
        Type::Map { key, value } => Type::Map {
            key: Box::new(substitute_kernel_call_type(
                key,
                parameter_ids,
                substitutions,
            )),
            value: Box::new(substitute_kernel_call_type(
                value,
                parameter_ids,
                substitutions,
            )),
        },
        Type::Function { args, result } => Type::Function {
            args: args
                .iter()
                .map(|argument| substitute_kernel_call_type(argument, parameter_ids, substitutions))
                .collect(),
            result: Box::new(FlowType {
                mode: result.mode,
                ty: substitute_kernel_call_type(&result.ty, parameter_ids, substitutions),
            }),
        },
        Type::VariantSet(variants) => Type::VariantSet(
            variants
                .iter()
                .map(|variant| match variant {
                    Variant::Tag(tag) => Variant::Tag(tag.clone()),
                    Variant::Tagged { tag, fields } => Variant::tagged(
                        tag.clone(),
                        ObjectShape {
                            fields: fields
                                .fields
                                .iter()
                                .map(|(name, field)| {
                                    (
                                        name.clone(),
                                        substitute_kernel_call_type(
                                            field,
                                            parameter_ids,
                                            substitutions,
                                        ),
                                    )
                                })
                                .collect(),
                            field_order: fields.field_order.clone(),
                            open: fields.open,
                        },
                    ),
                })
                .collect(),
        ),
        Type::Union(members) => Type::Union(
            members
                .iter()
                .map(|member| substitute_kernel_call_type(member, parameter_ids, substitutions))
                .collect(),
        ),
        Type::Text
        | Type::Number
        | Type::Bytes(_)
        | Type::Bits { .. }
        | Type::Absent
        | Type::RenderContract
        | Type::UnresolvedShape { .. }
        | Type::Unknown => ty.clone(),
    }
}

#[cfg(test)]
fn kernel_type_is_assignable_to(actual: &Type, expected: &Type) -> bool {
    if actual == expected {
        return true;
    }
    if call_type_is_placeholder(actual) || call_type_is_placeholder(expected) {
        return true;
    }
    match (actual, expected) {
        // RenderContract is an internal, API-provided boundary rather than a
        // language-level tag set. Until the concrete API contract is present
        // in the callable interface, diagnostics must not invent special tag
        // knowledge (including `NoElement`).
        (Type::RenderContract, _) | (_, Type::RenderContract) => true,
        (Type::Union(actual), _) if actual.is_empty() => false,
        (_, Type::Union(expected)) if expected.is_empty() => false,
        (Type::Union(actual), Type::Union(expected)) => actual.iter().all(|actual| {
            expected
                .iter()
                .any(|expected| kernel_type_is_assignable_to(actual, expected))
        }),
        (Type::Union(actual), expected) => actual
            .iter()
            .all(|actual| kernel_type_is_assignable_to(actual, expected)),
        (actual, Type::Union(expected)) => expected
            .iter()
            .any(|expected| kernel_type_is_assignable_to(actual, expected)),
        (Type::Text, Type::Text) | (Type::Number, Type::Number) | (Type::Absent, Type::Absent) => {
            true
        }
        (Type::Bytes(actual), Type::Bytes(expected)) => match (actual, expected) {
            (_, BytesType::Dynamic) => true,
            (BytesType::Fixed(actual), BytesType::Fixed(expected)) => actual == expected,
            (BytesType::Dynamic, BytesType::Fixed(_)) => false,
        },
        (Type::Bits { width: actual }, Type::Bits { width: expected }) => actual == expected,
        (Type::List(actual), Type::List(expected)) | (Type::Set(actual), Type::Set(expected)) => {
            kernel_type_is_assignable_to(actual, expected)
        }
        (
            Type::Map {
                key: actual_key,
                value: actual_value,
            },
            Type::Map {
                key: expected_key,
                value: expected_value,
            },
        ) => {
            kernel_type_is_assignable_to(actual_key, expected_key)
                && kernel_type_is_assignable_to(actual_value, expected_value)
        }
        (Type::Object(actual), Type::Object(expected)) => {
            expected.fields.iter().all(|(name, expected_field)| {
                actual.fields.get(name).is_some_and(|actual_field| {
                    kernel_type_is_assignable_to(actual_field, expected_field)
                }) || actual.open
            })
        }
        (Type::VariantSet(actual), Type::Object(expected)) => actual.iter().all(|variant| {
            let fields = match variant {
                Variant::Tag(_) => return expected.fields.is_empty(),
                Variant::Tagged { fields, .. } => fields,
            };
            kernel_type_is_assignable_to(
                &Type::Object(fields.clone()),
                &Type::Object(expected.clone()),
            )
        }),
        (Type::VariantSet(actual), Type::VariantSet(expected)) => actual.iter().all(|actual| {
            expected
                .iter()
                .any(|expected| kernel_variant_is_assignable_to(actual, expected))
        }),
        (
            Type::Function {
                args: actual_args,
                result: actual_result,
            },
            Type::Function {
                args: expected_args,
                result: expected_result,
            },
        ) => {
            actual_args.len() == expected_args.len()
                && actual_result.mode == expected_result.mode
                && expected_args
                    .iter()
                    .zip(actual_args)
                    .all(|(expected, actual)| kernel_type_is_assignable_to(expected, actual))
                && kernel_type_is_assignable_to(&actual_result.ty, &expected_result.ty)
        }
        _ => false,
    }
}

#[cfg(test)]
fn kernel_variant_is_assignable_to(actual: &Variant, expected: &Variant) -> bool {
    match (actual, expected) {
        (Variant::Tag(actual), Variant::Tag(expected)) => actual == expected,
        (
            Variant::Tagged {
                tag: actual_tag,
                fields: actual_fields,
            },
            Variant::Tagged {
                tag: expected_tag,
                fields: expected_fields,
            },
        ) => {
            actual_tag == expected_tag
                && kernel_type_is_assignable_to(
                    &Type::Object(actual_fields.clone()),
                    &Type::Object(expected_fields.clone()),
                )
        }
        _ => false,
    }
}

#[cfg(test)]
fn kernel_type_mismatch(actual: &Type, expected: &Type) -> KernelTypeMismatch {
    if let Some(field) = kernel_missing_field_name(actual, expected) {
        KernelTypeMismatch::MissingField(field.into_boxed_str())
    } else if let Some(field) = kernel_incompatible_field_name(actual, expected) {
        KernelTypeMismatch::IncompatibleField(field.into_boxed_str())
    } else {
        KernelTypeMismatch::Type
    }
}

#[cfg(test)]
fn kernel_missing_field_name(actual: &Type, expected: &Type) -> Option<String> {
    let (Type::Object(actual), Type::Object(expected)) = (actual, expected) else {
        return None;
    };
    expected.fields.iter().find_map(|(name, expected_field)| {
        let Some(actual_field) = actual.fields.get(name) else {
            return (!actual.open).then(|| name.clone());
        };
        kernel_missing_field_name(actual_field, expected_field)
            .map(|nested| format!("{name}.{nested}"))
    })
}

#[cfg(test)]
fn kernel_incompatible_field_name(actual: &Type, expected: &Type) -> Option<String> {
    let (Type::Object(actual), Type::Object(expected)) = (actual, expected) else {
        return None;
    };
    expected.fields.iter().find_map(|(name, expected_field)| {
        let actual_field = actual.fields.get(name)?;
        if let Some(nested) = kernel_incompatible_field_name(actual_field, expected_field) {
            return Some(format!("{name}.{nested}"));
        }
        (!kernel_type_is_assignable_to(actual_field, expected_field)).then(|| name.clone())
    })
}

pub fn compile_owner_program(
    input: &KernelOwnerProgramInput,
) -> Result<KernelOwnerProgram, KernelOwnerBuildError> {
    compile_owner_program_with_definition_facts(input, &KernelDefinitionFactsInput::default())
}

fn validate_definition_linker_facts(
    input: &KernelOwnerProgramInput,
    facts: &KernelDefinitionFactsInput,
    definition: Option<usize>,
    call_digest_scratch: &mut Vec<u8>,
) -> Result<(), KernelOwnerBuildError> {
    let label = definition
        .map(|definition| format!("definition {definition}"))
        .unwrap_or_else(|| "standalone definition".to_owned());
    for syntax in &facts.call_syntax {
        let recomputed =
            boon_syntax::checked_structural_call_site_digest_v4_from_parts_with_buffer(
                &syntax.occurrence.source_unit_id,
                &syntax.occurrence.route,
                call_digest_scratch,
            )
            .map_err(KernelOwnerBuildError::new)?;
        if recomputed != syntax.authored_site_digest_v4 {
            return Err(KernelOwnerBuildError::new(format!(
                "kernel {label} call `{}` parser-sealed V4 identity differs from its rich occurrence",
                syntax.function,
            )));
        }
    }
    let relocations = &facts.relocations;
    if !relocations.is_empty() {
        if !relocations.is_complete_for(input.nodes.len(), facts.statements.len()) {
            return Err(KernelOwnerBuildError::new(format!(
                "kernel {label} has {} expression and {} statement relocations for {} expressions and {} statements",
                relocations.expressions.len(),
                relocations.statements.len(),
                input.nodes.len(),
                facts.statements.len(),
            )));
        }
        if relocations
            .expressions
            .iter()
            .collect::<BTreeSet<_>>()
            .len()
            != relocations.expressions.len()
        {
            return Err(KernelOwnerBuildError::new(format!(
                "kernel {label} repeats a stable expression relocation"
            )));
        }
        if relocations.statements.iter().collect::<BTreeSet<_>>().len()
            != relocations.statements.len()
        {
            return Err(KernelOwnerBuildError::new(format!(
                "kernel {label} repeats a stable statement relocation"
            )));
        }
    }

    validate_definition_linkage(input, facts, &label, relocations, definition.is_some())?;
    validate_definition_presentation(input, facts, &label, definition.is_some())?;

    if !facts.expression_payloads.is_empty() {
        if facts.expression_payloads.len() != input.nodes.len() {
            return Err(KernelOwnerBuildError::new(format!(
                "kernel {label} has {} expression semantic payloads for {} expressions",
                facts.expression_payloads.len(),
                input.nodes.len(),
            )));
        }
        for (index, (node, payload)) in input
            .nodes
            .iter()
            .zip(facts.expression_payloads.iter())
            .enumerate()
        {
            let compatible = match payload {
                KernelExpressionSemanticPayload::None => true,
                KernelExpressionSemanticPayload::Text(_) => {
                    matches!(&node.kind, KernelOwnerNodeKind::Text)
                }
                KernelExpressionSemanticPayload::TextTemplate(segments) => {
                    if !matches!(&node.kind, KernelOwnerNodeKind::TextTemplate) {
                        false
                    } else {
                        let dynamic_input_count = node
                            .inputs
                            .iter()
                            .filter(|edge| matches!(edge.role, KernelOwnerEdgeRole::TextDynamic))
                            .count();
                        let dynamic_ordinals = segments
                            .iter()
                            .filter_map(|segment| match segment {
                                KernelTextTemplateSegment::Static(_) => None,
                                KernelTextTemplateSegment::Dynamic(ordinal) => Some(*ordinal),
                            })
                            .collect::<BTreeSet<_>>();
                        dynamic_ordinals.len() == dynamic_input_count
                            && dynamic_ordinals
                                .iter()
                                .enumerate()
                                .all(|(expected, ordinal)| {
                                    usize::try_from(*ordinal) == Ok(expected)
                                })
                    }
                }
                KernelExpressionSemanticPayload::Number(_) => {
                    matches!(&node.kind, KernelOwnerNodeKind::Number)
                }
                KernelExpressionSemanticPayload::Byte(_) => {
                    matches!(&node.kind, KernelOwnerNodeKind::Byte)
                }
                KernelExpressionSemanticPayload::Bits(value) => {
                    matches!(&node.kind, KernelOwnerNodeKind::Bits(width) if *width == value.width())
                }
                KernelExpressionSemanticPayload::HoldName(_) => {
                    matches!(&node.kind, KernelOwnerNodeKind::Hold)
                }
                KernelExpressionSemanticPayload::MatchPattern(_) => {
                    matches!(&node.kind, KernelOwnerNodeKind::MatchArm { .. })
                }
                KernelExpressionSemanticPayload::Delimiter => matches!(
                    &node.kind,
                    KernelOwnerNodeKind::Delimiter | KernelOwnerNodeKind::Record { tag: None }
                ),
                KernelExpressionSemanticPayload::LexicalPath(_) => matches!(
                    &node.kind,
                    KernelOwnerNodeKind::Known(_)
                        | KernelOwnerNodeKind::KnownPacked(_)
                        | KernelOwnerNodeKind::FormalRead { .. }
                        | KernelOwnerNodeKind::ContextRead { .. }
                        | KernelOwnerNodeKind::LexicalRead { .. }
                        | KernelOwnerNodeKind::ValueRead { .. }
                        | KernelOwnerNodeKind::DerivedRead { .. }
                        | KernelOwnerNodeKind::PatternRead { .. }
                        | KernelOwnerNodeKind::CollectionItemRead
                        | KernelOwnerNodeKind::FreshOut
                        | KernelOwnerNodeKind::Unknown
                ),
                KernelExpressionSemanticPayload::Invalid(_) => matches!(
                    &node.kind,
                    KernelOwnerNodeKind::Unknown
                        | KernelOwnerNodeKind::Number
                        | KernelOwnerNodeKind::Bits(_)
                ),
            };
            if !compatible {
                return Err(KernelOwnerBuildError::new(format!(
                    "kernel {label} expression {index} semantic payload {payload:?} is incompatible with node {:?}",
                    node.kind,
                )));
            }
        }
    }

    validate_execution_shapes(input, facts, &label, relocations)?;

    let call_count = input
        .nodes
        .iter()
        .filter(|node| {
            matches!(
                &node.kind,
                KernelOwnerNodeKind::UserCall { .. }
                    | KernelOwnerNodeKind::FieldProjection { .. }
                    | KernelOwnerNodeKind::RenderConstructor { .. }
                    | KernelOwnerNodeKind::PureBuiltin { .. }
                    | KernelOwnerNodeKind::FixedAbiCall { .. }
                    | KernelOwnerNodeKind::FixedAbiCallPacked { .. }
                    | KernelOwnerNodeKind::HostEffect { .. }
            )
        })
        .count();
    if facts.call_syntax.is_empty() {
        if !relocations.is_empty() && call_count != 0 {
            return Err(KernelOwnerBuildError::new(format!(
                "kernel {label} has no authored call syntax for {call_count} call expressions"
            )));
        }
        return Ok(());
    }
    if facts.call_syntax.len() != call_count {
        return Err(KernelOwnerBuildError::new(format!(
            "kernel {label} has {} authored call rows for {call_count} call expressions",
            facts.call_syntax.len(),
        )));
    }
    let input_namespace_len = input
        .nodes
        .len()
        .checked_add(input.external_expressions.len())
        .ok_or_else(|| {
            KernelOwnerBuildError::new(format!(
                "kernel {label} call input namespace overflows usize"
            ))
        })?;
    let mut previous_expression = None;
    for call in &facts.call_syntax {
        let expression = call.expression.0 as usize;
        let Some(node) = input.nodes.get(expression) else {
            return Err(KernelOwnerBuildError::new(format!(
                "kernel {label} authored call references missing expression {expression}"
            )));
        };
        if previous_expression.is_some_and(|previous| previous >= call.expression) {
            return Err(KernelOwnerBuildError::new(format!(
                "kernel {label} authored call rows are not strictly ordered by expression"
            )));
        }
        previous_expression = Some(call.expression);
        if call.function.is_empty()
            || !matches!(
                &node.kind,
                KernelOwnerNodeKind::UserCall { .. }
                    | KernelOwnerNodeKind::FieldProjection { .. }
                    | KernelOwnerNodeKind::RenderConstructor { .. }
                    | KernelOwnerNodeKind::PureBuiltin { .. }
                    | KernelOwnerNodeKind::FixedAbiCall { .. }
                    | KernelOwnerNodeKind::FixedAbiCallPacked { .. }
                    | KernelOwnerNodeKind::HostEffect { .. }
            )
        {
            return Err(KernelOwnerBuildError::new(format!(
                "kernel {label} authored call expression {expression} does not name a call node"
            )));
        }
        if let KernelOwnerNodeKind::HostEffect { operation } = &node.kind
            && operation != &call.function
        {
            return Err(KernelOwnerBuildError::new(format!(
                "kernel {label} host-effect expression {expression} spells `{}` but resolves `{operation}`",
                call.function,
            )));
        }
        if let KernelOwnerNodeKind::FieldProjection { field } = &node.kind
            && call.function.as_ref() != format!("Field/{field}")
        {
            return Err(KernelOwnerBuildError::new(format!(
                "kernel {label} field projection expression {expression} spells `{}` but resolves `Field/{field}`",
                call.function,
            )));
        }
        let mut authored_values = BTreeMap::<KernelExpressionId, usize>::new();
        if let Some(pipe_input) = call.pipe_input {
            *authored_values.entry(pipe_input).or_default() += 1;
        }
        for (ordinal, argument) in call.arguments.iter().enumerate() {
            if usize::try_from(argument.ordinal) != Ok(ordinal)
                || argument.name.is_empty()
                || argument.value.0 as usize >= input_namespace_len
            {
                return Err(KernelOwnerBuildError::new(format!(
                    "kernel {label} call expression {expression} has an invalid authored argument at ordinal {ordinal}"
                )));
            }
            *authored_values.entry(argument.value).or_default() += 1;
        }
        if let Some(pass) = call.pass {
            *authored_values.entry(pass.value).or_default() += 1;
        }
        if authored_values
            .keys()
            .any(|value| value.0 as usize >= input_namespace_len)
        {
            return Err(KernelOwnerBuildError::new(format!(
                "kernel {label} call expression {expression} references a missing authored input"
            )));
        }
        let mut canonical_values = BTreeMap::<KernelExpressionId, usize>::new();
        for edge in &node.inputs {
            *canonical_values.entry(edge.expression).or_default() += 1;
        }
        if authored_values != canonical_values {
            return Err(KernelOwnerBuildError::new(format!(
                "kernel {label} call expression {expression} authored inputs {authored_values:?} differ from canonical inputs {canonical_values:?}"
            )));
        }
    }
    Ok(())
}

fn validate_presentation_scope_reference(
    reference: KernelScopeReference,
    scope_count: usize,
    label: &str,
) -> Result<(), KernelOwnerBuildError> {
    if let KernelScopeReference::Local(scope) = reference
        && scope.0 as usize >= scope_count
    {
        return Err(KernelOwnerBuildError::new(format!(
            "kernel {label} checked presentation references missing local scope {}",
            scope.0,
        )));
    }
    Ok(())
}

fn validate_presentation_declaration_reference(
    reference: KernelDeclarationReference,
    declaration_count: usize,
    project_definition: bool,
    label: &str,
) -> Result<(), KernelOwnerBuildError> {
    match reference {
        KernelDeclarationReference::Local(declaration)
            if declaration.0 as usize >= declaration_count =>
        {
            Err(KernelOwnerBuildError::new(format!(
                "kernel {label} checked presentation references missing declaration {}",
                declaration.0,
            )))
        }
        KernelDeclarationReference::OwnerPublic(_)
        | KernelDeclarationReference::OwnerDeclaration { .. }
            if !project_definition =>
        {
            Err(KernelOwnerBuildError::new(format!(
                "kernel {label} checked presentation imports a declaration in a standalone definition"
            )))
        }
        KernelDeclarationReference::Local(_)
        | KernelDeclarationReference::OwnerPublic(_)
        | KernelDeclarationReference::OwnerDeclaration { .. } => Ok(()),
    }
}

fn validate_definition_presentation(
    input: &KernelOwnerProgramInput,
    facts: &KernelDefinitionFactsInput,
    label: &str,
    project_definition: bool,
) -> Result<(), KernelOwnerBuildError> {
    let presentation = &facts.presentation;
    if presentation.is_empty() {
        if project_definition && !facts.relocations.is_empty() {
            return Err(KernelOwnerBuildError::new(format!(
                "kernel {label} source-linked definition omits checked presentation facts"
            )));
        }
        return Ok(());
    }
    if presentation.expressions.len() != input.nodes.len()
        || presentation.statements.len() != facts.statements.len()
        || presentation.declarations.len() != facts.declarations.len()
    {
        return Err(KernelOwnerBuildError::new(format!(
            "kernel {label} checked presentation has {} expression, {} statement, and {} declaration rows for {} expressions, {} statements, and {} declarations",
            presentation.expressions.len(),
            presentation.statements.len(),
            presentation.declarations.len(),
            input.nodes.len(),
            facts.statements.len(),
            facts.declarations.len(),
        )));
    }
    if matches!(
        presentation.containing_scope,
        KernelScopeReference::Local(_) | KernelScopeReference::Containing
    ) {
        return Err(KernelOwnerBuildError::new(format!(
            "kernel {label} checked presentation has an unresolved containing scope"
        )));
    }
    if matches!(
        presentation.containing_scope,
        KernelScopeReference::Owner { .. }
    ) && !project_definition
    {
        return Err(KernelOwnerBuildError::new(format!(
            "kernel {label} checked presentation imports a containing scope in a standalone definition"
        )));
    }

    let scope_count = presentation.scopes.len();
    for (index, scope) in presentation.scopes.iter().enumerate() {
        if scope.id.0 as usize != index {
            return Err(KernelOwnerBuildError::new(format!(
                "kernel {label} checked presentation scope rows do not have dense IDs"
            )));
        }
        validate_presentation_scope_reference(scope.parent, scope_count, label)?;
        if scope.parent == KernelScopeReference::Local(scope.id) {
            return Err(KernelOwnerBuildError::new(format!(
                "kernel {label} checked presentation scope {index} is its own parent"
            )));
        }
        if let KernelScopeReference::Owner { .. } = scope.parent
            && !project_definition
        {
            return Err(KernelOwnerBuildError::new(format!(
                "kernel {label} checked presentation scope {index} imports a parent in a standalone definition"
            )));
        }
        if let Some(owner) = scope.owner {
            validate_presentation_declaration_reference(
                owner,
                facts.declarations.len(),
                project_definition,
                label,
            )?;
        }
        if scope.span.start > scope.span.end {
            return Err(KernelOwnerBuildError::new(format!(
                "kernel {label} checked presentation scope {index} has an inverted span"
            )));
        }
        match scope.origin {
            KernelScopeOrigin::StatementBody { statement }
            | KernelScopeOrigin::RepeatedOutput { statement, .. }
                if statement.0 as usize >= facts.statements.len() =>
            {
                return Err(KernelOwnerBuildError::new(format!(
                    "kernel {label} checked presentation scope {index} references missing statement {}",
                    statement.0,
                )));
            }
            KernelScopeOrigin::Record { expression }
            | KernelScopeOrigin::MatchArm { expression }
            | KernelScopeOrigin::CallbackOutput {
                call: expression, ..
            }
            | KernelScopeOrigin::CallContext { expression, .. }
                if expression.0 as usize >= input.nodes.len() =>
            {
                return Err(KernelOwnerBuildError::new(format!(
                    "kernel {label} checked presentation scope {index} references missing expression {}",
                    expression.0,
                )));
            }
            _ => {}
        }
    }
    for start in 0..scope_count {
        let mut active = BTreeSet::new();
        let mut current = start;
        while active.insert(current) {
            match presentation.scopes[current].parent {
                KernelScopeReference::Local(parent) => current = parent.0 as usize,
                KernelScopeReference::ProjectRoot
                | KernelScopeReference::Containing
                | KernelScopeReference::Owner { .. } => break,
            }
        }
        if active.contains(&current)
            && matches!(
                presentation.scopes[current].parent,
                KernelScopeReference::Local(_)
            )
        {
            return Err(KernelOwnerBuildError::new(format!(
                "kernel {label} checked presentation scopes contain a local parent cycle"
            )));
        }
    }

    for (index, expression) in presentation.expressions.iter().enumerate() {
        if expression.expression.0 as usize != index || expression.span.start > expression.span.end
        {
            return Err(KernelOwnerBuildError::new(format!(
                "kernel {label} checked expression presentation row {index} is malformed"
            )));
        }
        validate_presentation_scope_reference(expression.scope, scope_count, label)?;
        if let Some(declaration_scope) = expression.declaration_scope {
            validate_presentation_scope_reference(declaration_scope, scope_count, label)?;
        }
        if let Some(declaration) = expression.declaration {
            validate_presentation_declaration_reference(
                declaration,
                facts.declarations.len(),
                project_definition,
                label,
            )?;
        }
    }
    for (index, statement) in presentation.statements.iter().enumerate() {
        if statement.statement.0 as usize != index || statement.span.start > statement.span.end {
            return Err(KernelOwnerBuildError::new(format!(
                "kernel {label} checked statement presentation row {index} is malformed"
            )));
        }
        validate_presentation_scope_reference(statement.scope, scope_count, label)?;
        if let Some(body) = statement.body_scope
            && body.0 as usize >= scope_count
        {
            return Err(KernelOwnerBuildError::new(format!(
                "kernel {label} checked statement presentation row {index} references missing body scope {}",
                body.0,
            )));
        }
    }
    for (index, declaration) in presentation.declarations.iter().enumerate() {
        if declaration.declaration.0 as usize != index
            || declaration.span.start > declaration.span.end
        {
            return Err(KernelOwnerBuildError::new(format!(
                "kernel {label} checked declaration presentation row {index} is malformed"
            )));
        }
        validate_presentation_scope_reference(declaration.scope, scope_count, label)?;
        if let Some(body) = declaration.body_scope
            && body.0 as usize >= scope_count
        {
            return Err(KernelOwnerBuildError::new(format!(
                "kernel {label} checked declaration presentation row {index} references missing body scope {}",
                body.0,
            )));
        }
    }
    Ok(())
}

fn validate_definition_linkage(
    input: &KernelOwnerProgramInput,
    facts: &KernelDefinitionFactsInput,
    label: &str,
    relocations: &KernelDefinitionRelocations,
    project_definition: bool,
) -> Result<(), KernelOwnerBuildError> {
    let linkage = facts.linkage;
    if linkage == KernelDefinitionLinkage::default() {
        if relocations.is_empty() || !project_definition {
            return Ok(());
        }
        return Err(KernelOwnerBuildError::new(format!(
            "kernel {label} has source relocations without direct-linker definition anchors"
        )));
    }
    let root_statement = linkage.root_statement.ok_or_else(|| {
        KernelOwnerBuildError::new(format!(
            "kernel {label} direct-linker anchors omit the root statement"
        ))
    })?;
    let public_declaration = linkage.public_declaration.ok_or_else(|| {
        KernelOwnerBuildError::new(format!(
            "kernel {label} direct-linker anchors omit the public declaration"
        ))
    })?;
    let result_expression = linkage.result_expression.ok_or_else(|| {
        KernelOwnerBuildError::new(format!(
            "kernel {label} direct-linker anchors omit the result expression"
        ))
    })?;
    let statement = facts
        .statements
        .get(root_statement.0 as usize)
        .filter(|statement| statement.id == root_statement)
        .ok_or_else(|| {
            KernelOwnerBuildError::new(format!(
                "kernel {label} direct-linker root statement {} is missing",
                root_statement.0,
            ))
        })?;
    let local_public_declaration = match public_declaration {
        KernelDeclarationReference::Local(public_declaration) => {
            let declaration = facts
                .declarations
                .get(public_declaration.0 as usize)
                .filter(|declaration| declaration.id == public_declaration)
                .ok_or_else(|| {
                    KernelOwnerBuildError::new(format!(
                        "kernel {label} direct-linker public declaration {} is missing",
                        public_declaration.0,
                    ))
                })?;
            if declaration.origin
                != (KernelDeclarationOrigin::Statement {
                    statement: root_statement,
                })
            {
                return Err(KernelOwnerBuildError::new(format!(
                    "kernel {label} direct-linker public declaration does not belong to its root statement"
                )));
            }
            Some(declaration)
        }
        KernelDeclarationReference::OwnerPublic(_)
        | KernelDeclarationReference::OwnerDeclaration { .. } => None,
    };
    if result_expression != input.result || result_expression.0 as usize >= input.nodes.len() {
        return Err(KernelOwnerBuildError::new(format!(
            "kernel {label} direct-linker result expression {} is not the canonical local result {}",
            result_expression.0, input.result.0,
        )));
    }
    if !relocations.is_empty() {
        let stable = relocations
            .statements
            .get(root_statement.0 as usize)
            .ok_or_else(|| {
                KernelOwnerBuildError::new(format!(
                    "kernel {label} direct-linker root statement has no stable relocation"
                ))
            })?;
        if !stable.route.statement_route.is_empty() {
            return Err(KernelOwnerBuildError::new(format!(
                "kernel {label} direct-linker root statement is not an item-root relocation"
            )));
        }
    }
    let (expected_local_surface, authored_formals) = match &statement.kind {
        KernelStatementKind::Function { name, parameters } => (
            Some((KernelDeclarationKind::Function, name.as_ref())),
            parameters.len(),
        ),
        KernelStatementKind::Field { name } => {
            (Some((KernelDeclarationKind::Field, name.as_ref())), 0)
        }
        KernelStatementKind::Source {
            field: Some(name), ..
        } => (Some((KernelDeclarationKind::Source, name.as_ref())), 0),
        KernelStatementKind::Hold {
            field: Some(name), ..
        } => (Some((KernelDeclarationKind::Hold, name.as_ref())), 0),
        KernelStatementKind::Hold {
            field: None,
            name: Some(name),
        } => (Some((KernelDeclarationKind::Hold, name.as_ref())), 0),
        KernelStatementKind::List {
            field: Some(name), ..
        } => (Some((KernelDeclarationKind::List, name.as_ref())), 0),
        KernelStatementKind::Source { field: None, .. }
        | KernelStatementKind::Hold {
            field: None,
            name: None,
        }
        | KernelStatementKind::List { field: None, .. }
        | KernelStatementKind::Block
        | KernelStatementKind::Spread
        | KernelStatementKind::Expression => (None, 0),
    };
    match (local_public_declaration, expected_local_surface) {
        (Some(declaration), Some((expected_kind, expected_name)))
            if declaration.kind == expected_kind && declaration.name.as_ref() == expected_name => {}
        (Some(_), Some(_)) => {
            return Err(KernelOwnerBuildError::new(format!(
                "kernel {label} direct-linker public declaration does not match its root statement"
            )));
        }
        (Some(_), None) => {
            return Err(KernelOwnerBuildError::new(format!(
                "kernel {label} direct-linker root statement has no local public declaration surface"
            )));
        }
        (None, _)
            if matches!(
                statement.kind,
                KernelStatementKind::Source { field: None, .. }
                    | KernelStatementKind::Hold { field: None, .. }
                    | KernelStatementKind::List { field: None, .. }
            ) => {}
        (None, _) => {
            return Err(KernelOwnerBuildError::new(format!(
                "kernel {label} direct-linker root statement cannot delegate its public declaration"
            )));
        }
    }
    let expected_formals = authored_formals
        .checked_add(usize::from(linkage.context_formal_ordinal.is_some()))
        .ok_or_else(|| KernelOwnerBuildError::new("kernel formal count overflowed usize"))?;
    if input.formal_count as usize != expected_formals
        || linkage
            .context_formal_ordinal
            .is_some_and(|ordinal| ordinal as usize != authored_formals)
    {
        return Err(KernelOwnerBuildError::new(format!(
            "kernel {label} direct-linker formal/context anchors do not match the canonical formal table"
        )));
    }
    Ok(())
}

fn validate_execution_shapes(
    input: &KernelOwnerProgramInput,
    facts: &KernelDefinitionFactsInput,
    label: &str,
    relocations: &KernelDefinitionRelocations,
) -> Result<(), KernelOwnerBuildError> {
    let expected = input
        .nodes
        .iter()
        .filter(|node| {
            matches!(
                node.kind,
                KernelOwnerNodeKind::Record { .. }
                    | KernelOwnerNodeKind::Block
                    | KernelOwnerNodeKind::When
                    | KernelOwnerNodeKind::MatchArm { .. }
            )
        })
        .count();
    if facts.execution_shapes.is_empty() {
        if !relocations.is_empty() && expected != 0 {
            return Err(KernelOwnerBuildError::new(format!(
                "kernel {label} has no execution-shape rows for {expected} lossy structural expressions"
            )));
        }
        return Ok(());
    }
    if facts.execution_shapes.len() != expected {
        return Err(KernelOwnerBuildError::new(format!(
            "kernel {label} has {} execution-shape rows for {expected} lossy structural expressions",
            facts.execution_shapes.len(),
        )));
    }
    let namespace_len = input
        .nodes
        .len()
        .checked_add(input.external_expressions.len())
        .ok_or_else(|| {
            KernelOwnerBuildError::new(format!(
                "kernel {label} execution input namespace overflows usize"
            ))
        })?;
    let mut previous = None;
    for shape in &facts.execution_shapes {
        let expression = shape.expression();
        let index = expression.0 as usize;
        let Some(node) = input.nodes.get(index) else {
            return Err(KernelOwnerBuildError::new(format!(
                "kernel {label} execution shape references missing expression {index}"
            )));
        };
        if previous.is_some_and(|previous| previous >= expression) {
            return Err(KernelOwnerBuildError::new(format!(
                "kernel {label} execution-shape rows are not strictly ordered by expression"
            )));
        }
        previous = Some(expression);
        match shape {
            KernelExecutionShapeInput::Conditional { .. } => {
                if !matches!(node.kind, KernelOwnerNodeKind::When) {
                    return Err(KernelOwnerBuildError::new(format!(
                        "kernel {label} conditional execution shape {index} does not name a WHEN node"
                    )));
                }
            }
            KernelExecutionShapeInput::Record { fields, .. } => {
                if !matches!(node.kind, KernelOwnerNodeKind::Record { .. })
                    || fields.len() != node.inputs.len()
                {
                    return Err(KernelOwnerBuildError::new(format!(
                        "kernel {label} record execution shape {index} differs from its canonical field table"
                    )));
                }
                for (ordinal, (field, edge)) in fields.iter().zip(&node.inputs).enumerate() {
                    if usize::try_from(field.ordinal) != Ok(ordinal)
                        || field.value != edge.expression
                        || field.value.0 as usize >= namespace_len
                        || !matches!(
                            &edge.role,
                            KernelOwnerEdgeRole::RecordField { name, spread }
                                if name == &field.name && spread == &field.spread
                        )
                    {
                        return Err(KernelOwnerBuildError::new(format!(
                            "kernel {label} record execution shape {index} has an invalid field at ordinal {ordinal}"
                        )));
                    }
                    if let Some(declaration) = field.declaration {
                        validate_structural_declaration(
                            input,
                            facts,
                            declaration,
                            field.value,
                            index,
                        )?;
                    }
                }
            }
            KernelExecutionShapeInput::Block {
                bindings, result, ..
            } => {
                if !matches!(node.kind, KernelOwnerNodeKind::Block) {
                    return Err(KernelOwnerBuildError::new(format!(
                        "kernel {label} BLOCK execution shape {index} does not name a BLOCK node"
                    )));
                }
                for (ordinal, binding) in bindings.iter().enumerate() {
                    if usize::try_from(binding.ordinal) != Ok(ordinal)
                        || binding.value.0 as usize >= namespace_len
                    {
                        return Err(KernelOwnerBuildError::new(format!(
                            "kernel {label} BLOCK execution shape {index} has an invalid binding at ordinal {ordinal}"
                        )));
                    }
                    validate_structural_declaration(
                        input,
                        facts,
                        binding.declaration,
                        binding.value,
                        index,
                    )?;
                }
                let canonical_results = node
                    .inputs
                    .iter()
                    .filter(|edge| edge.role == KernelOwnerEdgeRole::BlockResult)
                    .map(|edge| edge.expression)
                    .collect::<Vec<_>>();
                if canonical_results.as_slice() != result.as_slice()
                    || result.is_some_and(|value| value.0 as usize >= namespace_len)
                {
                    return Err(KernelOwnerBuildError::new(format!(
                        "kernel {label} BLOCK execution shape {index} has a result different from its canonical edge"
                    )));
                }
            }
            KernelExecutionShapeInput::MatchArm {
                selector, bindings, ..
            } => {
                let KernelOwnerNodeKind::MatchArm { pattern } = &node.kind else {
                    return Err(KernelOwnerBuildError::new(format!(
                        "kernel {label} match execution shape {index} does not name a match arm"
                    )));
                };
                let expected_names = match pattern {
                    KernelPattern::Binding { name } => std::slice::from_ref(name),
                    KernelPattern::Tag { fields, .. } => fields,
                    KernelPattern::Wildcard
                    | KernelPattern::Number
                    | KernelPattern::Text
                    | KernelPattern::Bits { .. }
                    | KernelPattern::Invalid => &[],
                };
                if bindings.len() != expected_names.len() {
                    return Err(KernelOwnerBuildError::new(format!(
                        "kernel {label} match execution shape {index} has {} bindings for {} pattern names",
                        bindings.len(),
                        expected_names.len(),
                    )));
                }
                if selector.0 as usize >= namespace_len {
                    return Err(KernelOwnerBuildError::new(format!(
                        "kernel {label} match execution shape {index} references missing selector {}",
                        selector.0,
                    )));
                }
                for (ordinal, (binding, name)) in
                    bindings.iter().zip(expected_names.iter()).enumerate()
                {
                    let Some(declaration) = facts.declarations.get(binding.0 as usize) else {
                        return Err(KernelOwnerBuildError::new(format!(
                            "kernel {label} match execution shape {index} references missing declaration {}",
                            binding.0,
                        )));
                    };
                    if declaration.name.as_ref() != name.as_ref()
                        || declaration.kind != KernelDeclarationKind::PatternBinding
                        || declaration.origin
                            != (KernelDeclarationOrigin::PatternBinding {
                                arm: expression,
                                ordinal: u32::try_from(ordinal)
                                    .expect("pattern binding count exceeds u32"),
                            })
                    {
                        return Err(KernelOwnerBuildError::new(format!(
                            "kernel {label} match execution shape {index} has an invalid binding at ordinal {ordinal}"
                        )));
                    }
                }
            }
        }
    }
    Ok(())
}

fn validate_structural_declaration(
    input: &KernelOwnerProgramInput,
    facts: &KernelDefinitionFactsInput,
    declaration: KernelStructuralDeclarationInput,
    value: KernelExpressionId,
    consumer: usize,
) -> Result<(), KernelOwnerBuildError> {
    match declaration {
        KernelStructuralDeclarationInput::Local(declaration) => {
            if declaration.0 as usize >= facts.declarations.len() {
                return Err(KernelOwnerBuildError::new(format!(
                    "kernel structural expression {consumer} references missing declaration {}",
                    declaration.0,
                )));
            }
        }
        KernelStructuralDeclarationInput::ValueOwnerPublic => {
            if !matches!(
                kernel_value_reference(input, value, consumer)?,
                KernelValueReference::External(_)
            ) {
                return Err(KernelOwnerBuildError::new(format!(
                    "kernel structural expression {consumer} marks a local value as an owner-public declaration"
                )));
            }
        }
    }
    Ok(())
}

pub fn compile_owner_program_with_definition_facts(
    input: &KernelOwnerProgramInput,
    facts: &KernelDefinitionFactsInput,
) -> Result<KernelOwnerProgram, KernelOwnerBuildError> {
    let text = crate::text::compatibility_project_text_snapshot(
        std::slice::from_ref(input),
        std::slice::from_ref(facts),
        &crate::KernelAbiInput::default(),
    )?;
    compile_owner_program_with_definition_facts_and_text(input, facts, text)
}

fn compile_owner_program_with_definition_facts_and_text(
    rich_input: &KernelOwnerProgramInput,
    facts: &KernelDefinitionFactsInput,
    text: ProjectTextSnapshot,
) -> Result<KernelOwnerProgram, KernelOwnerBuildError> {
    let mut call_digest_scratch = Vec::new();
    validate_definition_linker_facts(rich_input, facts, None, &mut call_digest_scratch)?;
    let basis_fingerprint_v14 = definition_basis_fingerprint(rich_input, facts)?;
    if !rich_input.external_expressions.is_empty() {
        return Err(KernelOwnerBuildError::new(
            "standalone owner program cannot import external expressions",
        ));
    }
    if facts.statements.iter().any(|statement| {
        statement
            .children
            .iter()
            .any(|child| matches!(child, KernelStatementChildReference::Owner(_)))
    }) {
        return Err(KernelOwnerBuildError::new(
            "standalone owner statements cannot reference child owners",
        ));
    }
    if facts.lexical_bindings.iter().any(|binding| {
        matches!(
            binding.target,
            KernelLexicalBindingTargetInput::Declaration(
                KernelDeclarationReference::OwnerPublic(_)
                    | KernelDeclarationReference::OwnerDeclaration { .. }
            )
        )
    }) {
        return Err(KernelOwnerBuildError::new(
            "standalone owner lexical bindings cannot reference another owner",
        ));
    }
    if facts.sources.iter().any(|source| {
        matches!(
            source.declaration,
            KernelDeclarationReference::OwnerPublic(_)
                | KernelDeclarationReference::OwnerDeclaration { .. }
        ) || matches!(source.statement, KernelStatementReference::OwnerPublic(_))
    }) || facts.states.iter().any(|state| {
        matches!(
            state.declaration,
            KernelDeclarationReference::OwnerPublic(_)
                | KernelDeclarationReference::OwnerDeclaration { .. }
        ) || matches!(
            state.binding_declaration,
            KernelDeclarationReference::OwnerPublic(_)
                | KernelDeclarationReference::OwnerDeclaration { .. }
        ) || matches!(state.statement, KernelStatementReference::OwnerPublic(_))
    }) || facts.lists.iter().any(|list| {
        matches!(
            list.declaration,
            KernelDeclarationReference::OwnerPublic(_)
                | KernelDeclarationReference::OwnerDeclaration { .. }
        ) || matches!(list.statement, KernelStatementReference::OwnerPublic(_))
    }) {
        return Err(KernelOwnerBuildError::new(
            "standalone owner resources cannot reference another owner",
        ));
    }
    let mut rich_program = KernelProjectProgramInput {
        owners: vec![rich_input.clone()].into_boxed_slice(),
    };
    let mut terms = crate::TypeTermArena::with_text(text.clone());
    crate::pack_project_closed_type_roots(&mut rich_program, &mut terms)?;
    let packed_input_term_count = terms.len();
    let packed_program = crate::pack_kernel_project_program(rich_program, &terms)?;
    let input = packed_program
        .owner(KernelOwnerId(0))
        .expect("one-owner compatibility program retains owner zero");
    let result = checked_expression_index(input.result(), input.node_count(), "owner result")?;
    let mut builder = ComponentProgramBuilder::with_terms(terms);
    let mut mode_builder = ModeProgramBuilder::default();
    let mut packed_input_imports =
        TypeTermImportScratch::with_source_limit(packed_input_term_count);
    let formal_static_variants = vec![None; input.formal_count() as usize];
    let formal_dependent_expressions = [owner_expressions_depend_on_formals(input)];
    let formal_dependent_results = [formal_dependent_expressions[0][result]];
    let principals = vec![allocate_owner_instance(
        &mut builder,
        &mut mode_builder,
        &text,
        input,
        &formal_static_variants,
    )];
    let principal = &principals[0];
    let context = OwnerCompileContext {
        initial_state_surface: false,
        text: &text,
        owner: KernelOwnerId(0),
        input,
        expressions: &principal.expressions,
        formals: &principal.formals,
        formal_requirements: &principal.formal_requirements,
        expression_modes: &principal.expression_modes,
        formal_modes: &principal.formal_modes,
        formal_mode_sources: &principal.formal_mode_sources,
        static_variants: &principal.static_variants,
        formal_static_variants: &principal.formal_static_variants,
        project: None,
        principals: &principals,
        formal_dependent_results: &formal_dependent_results,
        formal_dependent_expressions: &formal_dependent_expressions,
        external_variables: None,
        syntax_selected_calls: None,
        direct_summaries: &[],
        packed_input_types: None,
    };
    let specialization = OwnerSpecialization {
        static_variants: principal.static_variants.clone(),
        reachable: (0..input.node_count())
            .collect::<Vec<_>>()
            .into_boxed_slice(),
        result_syntax_selected: false,
        syntax_selected_calls: vec![false; input.node_count()].into_boxed_slice(),
        invocation_dependencies: formal_dependent_expressions[0].clone(),
        transparent_type_providers: vec![None; input.node_count()].into_boxed_slice(),
    };
    let module = compile_residual_type_module(
        &text,
        Some(builder.terms()),
        &mut packed_input_imports,
        KernelOwnerId(0),
        input,
        None,
        &principals,
        &formal_dependent_results,
        &formal_dependent_expressions,
        &formal_static_variants,
        &specialization,
        None,
        false,
    )?;
    if let Some(call) = module.calls.first() {
        return Err(KernelOwnerBuildError::new(format!(
            "standalone owner node {call} cannot contain a user call"
        )));
    }
    append_residual_type_frame(&mut builder, &module, principal, &[])?;
    for (index, node) in input.nodes().iter().enumerate() {
        let equation = node_mode_equation(&mut mode_builder, &context, index, node)?;
        mode_builder.set(principal.expression_modes[index], equation);
    }

    let expression_outputs = principal
        .expressions
        .iter()
        .zip(input.nodes().iter())
        .map(|(variable, node)| builder.add_output(*variable, node.mode))
        .collect::<Vec<_>>();
    let formal_outputs = principal
        .formal_requirements
        .iter()
        .map(|variable| builder.add_output(*variable, FlowMode::Continuous))
        .collect::<Vec<_>>()
        .into_boxed_slice();
    let modes = mode_builder.solve();
    let expression_modes = principal
        .expression_modes
        .iter()
        .map(|mode| modes[mode.0 as usize])
        .collect::<Vec<_>>()
        .into_boxed_slice();
    let formal_modes = principal
        .formal_modes
        .iter()
        .map(|mode| modes[mode.0 as usize])
        .collect::<Vec<_>>()
        .into_boxed_slice();
    let result_output = expression_outputs[result];
    let statements = collect_statement_artifacts(rich_input, facts)?;
    let declarations = collect_declaration_artifacts(rich_input, facts)?;
    let lexical_bindings = collect_lexical_binding_artifacts(rich_input, facts)?;
    let resources = collect_resource_artifacts(rich_input, facts)?;
    Ok(KernelOwnerProgram {
        component: builder.finish(),
        result_output,
        formal_outputs,
        formal_modes,
        expression_outputs: expression_outputs.into_boxed_slice(),
        expression_modes,
        expression_artifacts: collect_expression_artifacts(rich_input)?,
        linkage: facts.linkage,
        relocations: facts.relocations.clone(),
        presentation: facts.presentation.clone(),
        expression_payloads: facts.expression_payloads.clone(),
        call_syntax: collect_call_syntax_artifacts(rich_input, facts)?,
        execution_shapes: collect_execution_shape_artifacts(rich_input, facts)?,
        statements,
        declarations,
        lexical_bindings,
        resources,
        calls: collect_call_artifacts(rich_input, &vec![false; rich_input.nodes.len()])?,
        effects: collect_host_effect_artifacts(rich_input)?,
        diagnostics: collect_definition_diagnostic_artifacts(KernelOwnerId(0), rich_input, facts)?,
        basis_fingerprint_v14,
    })
}

fn materialize_expression_artifacts_with_local_flushes(
    pending: Box<[PendingKernelExpressionArtifact]>,
    flows: Box<[FlowType]>,
    owner_effects: &[KernelEffectSummary],
) -> Box<[RichKernelExpressionArtifact]> {
    assert_eq!(pending.len(), flows.len());
    let mut bases = vec![Vec::<Type>::new(); pending.len()];
    let mut dependencies = vec![Vec::<usize>::new(); pending.len()];
    for (index, expression) in pending.iter().enumerate() {
        let carries_input_flush = |role: &KernelOwnerEdgeRole| match &expression.kind {
            KernelOwnerNodeKind::Record { .. } | KernelOwnerNodeKind::Block => false,
            KernelOwnerNodeKind::Hold => matches!(role, KernelOwnerEdgeRole::HoldUpdate),
            _ => true,
        };
        for input in expression
            .inputs
            .iter()
            .filter(|input| carries_input_flush(&input.role))
        {
            if let KernelValueReference::Local(provider) = input.value
                && (provider.0 as usize) < pending.len()
            {
                dependencies[index].push(provider.0 as usize);
            }
        }
        if matches!(expression.kind, KernelOwnerNodeKind::Flush) {
            for payload in expression
                .inputs
                .iter()
                .filter(|input| matches!(input.role, KernelOwnerEdgeRole::FlushPayload))
            {
                if let KernelValueReference::Local(payload) = payload.value
                    && let Some(flow) = flows.get(payload.0 as usize)
                {
                    bases[index].push(flow.ty.clone());
                }
            }
        }
        dependencies[index].sort_unstable();
        dependencies[index].dedup();
    }
    let flush_types = solve_flush_graph(bases, dependencies).into_boxed_slice();
    materialize_expression_artifacts(pending, flows, flush_types, owner_effects)
}

fn materialize_expression_artifacts(
    pending: Box<[PendingKernelExpressionArtifact]>,
    flows: Box<[FlowType]>,
    flush_types: Box<[Option<Type>]>,
    owner_effects: &[KernelEffectSummary],
) -> Box<[RichKernelExpressionArtifact]> {
    assert_eq!(
        pending.len(),
        flows.len(),
        "every solved expression must retain one compact artifact row"
    );
    assert_eq!(
        pending.len(),
        flush_types.len(),
        "every solved expression must retain one compact FLUSH-control row"
    );
    pending
        .into_vec()
        .into_iter()
        .zip(flows)
        .zip(flush_types)
        .map(
            |((expression, flow_type), flush_type)| RichKernelExpressionArtifact {
                effect: direct_expression_effect(&expression.kind, owner_effects),
                id: expression.id,
                kind: expression.kind,
                inputs: expression.inputs,
                flow_type,
                flush_type,
            },
        )
        .collect::<Vec<_>>()
        .into_boxed_slice()
}

fn collect_expression_artifacts(
    input: &KernelOwnerProgramInput,
) -> Result<Box<[PendingKernelExpressionArtifact]>, KernelOwnerBuildError> {
    input
        .nodes
        .iter()
        .enumerate()
        .map(|(index, node)| {
            Ok(PendingKernelExpressionArtifact {
                id: KernelExpressionId(
                    u32::try_from(index).expect("kernel owner expression count exceeds u32"),
                ),
                kind: node.kind.clone(),
                inputs: node
                    .inputs
                    .iter()
                    .map(|edge| {
                        Ok(KernelExpressionInputArtifact {
                            role: edge.role.clone(),
                            value: kernel_value_reference(input, edge.expression, index)?,
                        })
                    })
                    .collect::<Result<Vec<_>, KernelOwnerBuildError>>()?
                    .into_boxed_slice(),
            })
        })
        .collect::<Result<Vec<_>, _>>()
        .map(Vec::into_boxed_slice)
}

fn kernel_value_reference(
    input: &KernelOwnerProgramInput,
    expression: KernelExpressionId,
    consumer: usize,
) -> Result<KernelValueReference, KernelOwnerBuildError> {
    let reference = expression.0 as usize;
    if reference < input.nodes.len() {
        return Ok(KernelValueReference::Local(expression));
    }
    input
        .external_expressions
        .get(reference - input.nodes.len())
        .copied()
        .map(KernelValueReference::External)
        .ok_or_else(|| {
            KernelOwnerBuildError::new(format!(
                "kernel expression {consumer} input references expression {reference} outside the local and external namespaces"
            ))
        })
}

fn packed_kernel_value_reference(
    input: PackedKernelOwnerProgramRef<'_>,
    expression: KernelExpressionId,
    consumer: usize,
) -> Result<KernelValueReference, KernelOwnerBuildError> {
    let reference = expression.0 as usize;
    if reference < input.node_count() {
        return Ok(KernelValueReference::Local(expression));
    }
    input
        .external_expressions()
        .get(reference - input.node_count())
        .copied()
        .map(KernelValueReference::External)
        .ok_or_else(|| {
            KernelOwnerBuildError::new(format!(
                "kernel expression {consumer} input references expression {reference} outside the local and external namespaces"
            ))
        })
}

fn collect_statement_artifacts(
    owner: &KernelOwnerProgramInput,
    facts: &KernelDefinitionFactsInput,
) -> Result<Box<[KernelStatementArtifact]>, KernelOwnerBuildError> {
    let statement_count = facts.statements.len();
    let mut claimed_local_children = BTreeSet::new();
    for (index, statement) in facts.statements.iter().enumerate() {
        if statement.id.0 as usize != index {
            return Err(KernelOwnerBuildError::new(format!(
                "kernel statement rows must use dense IDs: row {index} has ID {}",
                statement.id.0
            )));
        }
        for child in &statement.children {
            let KernelStatementChildReference::Local(child) = child else {
                continue;
            };
            if child.0 as usize >= statement_count {
                return Err(KernelOwnerBuildError::new(format!(
                    "kernel statement {index} references missing child statement {}",
                    child.0
                )));
            }
            if child.0 as usize <= index {
                return Err(KernelOwnerBuildError::new(format!(
                    "kernel statement {index} has non-forward child statement {}",
                    child.0
                )));
            }
            if !claimed_local_children.insert(*child) {
                return Err(KernelOwnerBuildError::new(format!(
                    "kernel statement {} has more than one local parent",
                    child.0
                )));
            }
        }
    }
    facts
        .statements
        .iter()
        .map(|statement| {
            Ok(KernelStatementArtifact {
                id: statement.id,
                kind: statement.kind.clone(),
                value: statement
                    .value
                    .map(|value| kernel_value_reference(owner, value, statement.id.0 as usize))
                    .transpose()?,
                value_use: statement.value_use,
                children: statement.children.clone(),
            })
        })
        .collect::<Result<Vec<_>, _>>()
        .map(Vec::into_boxed_slice)
}

fn validate_project_statement_inputs(
    owner: &KernelOwnerProgramInput,
    facts: &KernelDefinitionFactsInput,
) -> Result<(), KernelOwnerBuildError> {
    let mut parent = vec![false; facts.statements.len()];
    for (index, statement) in facts.statements.iter().enumerate() {
        if statement.id.0 as usize != index {
            return Err(KernelOwnerBuildError::new(format!(
                "kernel statement rows must use dense IDs: row {index} has ID {}",
                statement.id.0
            )));
        }
        if let Some(value) = statement.value {
            kernel_value_reference(owner, value, index)?;
        }
        for child in &statement.children {
            let KernelStatementChildReference::Local(child) = child else {
                continue;
            };
            let child = child.0 as usize;
            if child >= facts.statements.len() {
                return Err(KernelOwnerBuildError::new(format!(
                    "kernel statement {index} references missing child statement {child}"
                )));
            }
            if child <= index {
                return Err(KernelOwnerBuildError::new(format!(
                    "kernel statement {index} has non-forward child statement {child}"
                )));
            }
            if std::mem::replace(&mut parent[child], true) {
                return Err(KernelOwnerBuildError::new(format!(
                    "kernel statement {child} has more than one local parent"
                )));
            }
        }
    }
    Ok(())
}

fn collect_declaration_artifacts(
    owner: &KernelOwnerProgramInput,
    facts: &KernelDefinitionFactsInput,
) -> Result<Box<[RichKernelDeclarationArtifact]>, KernelOwnerBuildError> {
    let mut origins = BTreeSet::new();
    facts
        .declarations
        .iter()
        .enumerate()
        .map(|(index, declaration)| {
            if declaration.id.0 as usize != index {
                return Err(KernelOwnerBuildError::new(format!(
                    "kernel declaration rows must use dense IDs: row {index} has ID {}",
                    declaration.id.0
                )));
            }
            if !origins.insert(declaration.origin.clone()) {
                return Err(KernelOwnerBuildError::new(format!(
                    "kernel declaration {index} repeats structural origin {:?}",
                    declaration.origin
                )));
            }
            validate_declaration_origin(owner, facts, declaration)?;
            Ok(RichKernelDeclarationArtifact {
                id: declaration.id,
                origin: declaration.origin.clone(),
                name: declaration.name.clone(),
                kind: declaration.kind,
                value: declaration
                    .value
                    .map(|value| kernel_value_reference(owner, value, index))
                    .transpose()?,
                declared_flow_type: declaration.declared_flow_type.clone(),
            })
        })
        .collect::<Result<Vec<_>, _>>()
        .map(Vec::into_boxed_slice)
}

fn validate_project_declaration_inputs(
    owner: &KernelOwnerProgramInput,
    facts: &KernelDefinitionFactsInput,
) -> Result<(), KernelOwnerBuildError> {
    let mut origins = HashSet::with_capacity(facts.declarations.len());
    for (index, declaration) in facts.declarations.iter().enumerate() {
        if declaration.id.0 as usize != index {
            return Err(KernelOwnerBuildError::new(format!(
                "kernel declaration rows must use dense IDs: row {index} has ID {}",
                declaration.id.0
            )));
        }
        if !origins.insert(&declaration.origin) {
            return Err(KernelOwnerBuildError::new(format!(
                "kernel declaration {index} repeats structural origin {:?}",
                declaration.origin
            )));
        }
        validate_declaration_origin(owner, facts, declaration)?;
        if let Some(value) = declaration.value {
            kernel_value_reference(owner, value, index)?;
        }
    }
    Ok(())
}

fn validate_declaration_origin(
    owner: &KernelOwnerProgramInput,
    facts: &KernelDefinitionFactsInput,
    declaration: &KernelDeclarationInput,
) -> Result<(), KernelOwnerBuildError> {
    let invalid = || {
        KernelOwnerBuildError::new(format!(
            "kernel declaration {} kind {:?} has incompatible origin {:?}",
            declaration.id.0, declaration.kind, declaration.origin
        ))
    };
    match (&declaration.origin, declaration.kind) {
        (
            KernelDeclarationOrigin::Statement { statement },
            KernelDeclarationKind::Function
            | KernelDeclarationKind::Field
            | KernelDeclarationKind::Source
            | KernelDeclarationKind::Hold
            | KernelDeclarationKind::List,
        ) => {
            let statement = facts.statements.get(statement.0 as usize).ok_or_else(|| {
                KernelOwnerBuildError::new(format!(
                    "kernel declaration {} references missing statement {}",
                    declaration.id.0, statement.0
                ))
            })?;
            let matches = match (&statement.kind, declaration.kind) {
                (KernelStatementKind::Function { name, .. }, KernelDeclarationKind::Function)
                | (KernelStatementKind::Field { name }, KernelDeclarationKind::Field) => {
                    name == &declaration.name
                }
                (
                    KernelStatementKind::Source {
                        field: Some(name), ..
                    },
                    KernelDeclarationKind::Source,
                )
                | (
                    KernelStatementKind::Hold {
                        field: Some(name), ..
                    },
                    KernelDeclarationKind::Hold,
                )
                | (
                    KernelStatementKind::List {
                        field: Some(name), ..
                    },
                    KernelDeclarationKind::List,
                ) => name == &declaration.name,
                // An authored fieldless HOLD alias can be the private state
                // declaration for its lexical region. The syntax projection
                // decides whether this statement owns that authority; the
                // kernel validates the exact alias/statement identity here.
                (
                    KernelStatementKind::Hold {
                        field: None,
                        name: Some(name),
                    },
                    KernelDeclarationKind::Hold,
                ) => name == &declaration.name,
                _ => false,
            };
            if !matches {
                return Err(invalid());
            }
        }
        (
            KernelDeclarationOrigin::Parameter { statement, ordinal },
            KernelDeclarationKind::ValueParameter | KernelDeclarationKind::OutParameter,
        ) => {
            let Some(KernelStatementInput {
                kind: KernelStatementKind::Function { parameters, .. },
                ..
            }) = facts.statements.get(statement.0 as usize)
            else {
                return Err(invalid());
            };
            let parameter = parameters
                .iter()
                .find(|parameter| parameter.ordinal == *ordinal)
                .ok_or_else(invalid)?;
            let expected_kind = match parameter.kind {
                KernelParameterKind::Value => KernelDeclarationKind::ValueParameter,
                KernelParameterKind::Out => KernelDeclarationKind::OutParameter,
            };
            if expected_kind != declaration.kind || parameter.name != declaration.name {
                return Err(invalid());
            }
        }
        (
            KernelDeclarationOrigin::RecordField { object, ordinal },
            KernelDeclarationKind::Field,
        ) => {
            let expression = owner.nodes.get(object.0 as usize).ok_or_else(|| {
                KernelOwnerBuildError::new(format!(
                    "kernel declaration {} references missing record expression {}",
                    declaration.id.0, object.0
                ))
            })?;
            if !matches!(expression.kind, KernelOwnerNodeKind::Record { .. }) {
                return Err(invalid());
            }
            let field = expression
                .inputs
                .get(*ordinal as usize)
                .ok_or_else(invalid)?;
            if !matches!(
                &field.role,
                KernelOwnerEdgeRole::RecordField { name, spread: false }
                    if name == &declaration.name
            ) {
                return Err(invalid());
            }
        }
        (
            KernelDeclarationOrigin::PatternBinding { arm, ordinal },
            KernelDeclarationKind::PatternBinding,
        ) => {
            let expression = owner.nodes.get(arm.0 as usize).ok_or_else(|| {
                KernelOwnerBuildError::new(format!(
                    "kernel declaration {} references missing match arm {}",
                    declaration.id.0, arm.0
                ))
            })?;
            let KernelOwnerNodeKind::MatchArm { pattern } = &expression.kind else {
                return Err(invalid());
            };
            let names = match pattern {
                KernelPattern::Binding { name } => std::slice::from_ref(name),
                KernelPattern::Tag { fields, .. } => fields,
                KernelPattern::Wildcard
                | KernelPattern::Number
                | KernelPattern::Text
                | KernelPattern::Bits { .. }
                | KernelPattern::Invalid => &[],
            };
            if names.get(*ordinal as usize).map(Box::as_ref) != Some(declaration.name.as_ref()) {
                return Err(invalid());
            }
        }
        (
            KernelDeclarationOrigin::CallbackBinding { call, .. },
            KernelDeclarationKind::FreshOut,
        ) => {
            let expression = owner.nodes.get(call.0 as usize).ok_or_else(|| {
                KernelOwnerBuildError::new(format!(
                    "kernel declaration {} references missing callback call {}",
                    declaration.id.0, call.0
                ))
            })?;
            if !matches!(
                expression.kind,
                KernelOwnerNodeKind::PureBuiltin { .. } | KernelOwnerNodeKind::UserCall { .. }
            ) {
                return Err(invalid());
            }
        }
        (
            KernelDeclarationOrigin::CallContext { call, .. },
            KernelDeclarationKind::ElementState,
        ) => {
            let expression = owner.nodes.get(call.0 as usize).ok_or_else(|| {
                KernelOwnerBuildError::new(format!(
                    "kernel declaration {} references missing call-context expression {}",
                    declaration.id.0, call.0
                ))
            })?;
            if !matches!(
                expression.kind,
                KernelOwnerNodeKind::RenderConstructor { .. }
                    | KernelOwnerNodeKind::PureBuiltin { .. }
                    | KernelOwnerNodeKind::UserCall { .. }
            ) || declaration.value.is_some()
                || declaration.declared_flow_type.is_none()
            {
                return Err(invalid());
            }
        }
        _ => return Err(invalid()),
    }
    if !matches!(
        declaration.origin,
        KernelDeclarationOrigin::CallContext { .. }
    ) && declaration.declared_flow_type.is_some()
    {
        return Err(invalid());
    }
    Ok(())
}

fn collect_lexical_binding_artifacts(
    owner: &KernelOwnerProgramInput,
    facts: &KernelDefinitionFactsInput,
) -> Result<Box<[KernelLexicalBindingArtifact]>, KernelOwnerBuildError> {
    let mut expressions = BTreeSet::new();
    facts
        .lexical_bindings
        .iter()
        .map(|binding| {
            let expression = checked_expression_index(
                binding.expression,
                owner.nodes.len(),
                "kernel lexical binding expression",
            )?;
            if !expressions.insert(binding.expression) {
                return Err(KernelOwnerBuildError::new(format!(
                    "kernel expression {expression} has more than one lexical binding row"
                )));
            }
            let target = match binding.target {
                KernelLexicalBindingTargetInput::Declaration(reference) => {
                    if let KernelDeclarationReference::Local(declaration) = reference
                        && declaration.0 as usize >= facts.declarations.len()
                    {
                        return Err(KernelOwnerBuildError::new(format!(
                            "kernel expression {expression} references missing declaration {}",
                            declaration.0
                        )));
                    }
                    KernelLexicalBindingTarget::Declaration(reference)
                }
                KernelLexicalBindingTargetInput::ContextFormal { ordinal } => {
                    if ordinal >= owner.formal_count {
                        return Err(KernelOwnerBuildError::new(format!(
                            "kernel expression {expression} references missing context formal {ordinal}"
                        )));
                    }
                    KernelLexicalBindingTarget::ContextFormal { ordinal }
                }
                KernelLexicalBindingTargetInput::Value { provider } => {
                    KernelLexicalBindingTarget::Value {
                        provider: kernel_value_reference(owner, provider, expression)?,
                    }
                }
                KernelLexicalBindingTargetInput::RuntimeContext => {
                    KernelLexicalBindingTarget::RuntimeContext
                }
            };
            Ok(KernelLexicalBindingArtifact {
                expression: binding.expression,
                target,
                projection: binding.projection.clone(),
                access: binding.access,
            })
        })
        .collect::<Result<Vec<_>, _>>()
        .map(Vec::into_boxed_slice)
}

fn validate_project_lexical_inputs(
    owner: &KernelOwnerProgramInput,
    facts: &KernelDefinitionFactsInput,
) -> Result<(), KernelOwnerBuildError> {
    let mut expressions = vec![false; owner.nodes.len()];
    for binding in &facts.lexical_bindings {
        let expression = checked_expression_index(
            binding.expression,
            owner.nodes.len(),
            "kernel lexical binding expression",
        )?;
        if std::mem::replace(&mut expressions[expression], true) {
            return Err(KernelOwnerBuildError::new(format!(
                "kernel expression {expression} has more than one lexical binding row"
            )));
        }
        match binding.target {
            KernelLexicalBindingTargetInput::Declaration(KernelDeclarationReference::Local(
                declaration,
            )) if declaration.0 as usize >= facts.declarations.len() => {
                return Err(KernelOwnerBuildError::new(format!(
                    "kernel expression {expression} references missing declaration {}",
                    declaration.0
                )));
            }
            KernelLexicalBindingTargetInput::ContextFormal { ordinal }
                if ordinal >= owner.formal_count =>
            {
                return Err(KernelOwnerBuildError::new(format!(
                    "kernel expression {expression} references missing context formal {ordinal}"
                )));
            }
            KernelLexicalBindingTargetInput::Value { provider } => {
                kernel_value_reference(owner, provider, expression)?;
            }
            KernelLexicalBindingTargetInput::Declaration(_)
            | KernelLexicalBindingTargetInput::ContextFormal { .. }
            | KernelLexicalBindingTargetInput::RuntimeContext => {}
        }
    }
    Ok(())
}

fn validate_resource_declaration(
    facts: &KernelDefinitionFactsInput,
    declaration: KernelDeclarationReference,
    context: &str,
) -> Result<(), KernelOwnerBuildError> {
    if let KernelDeclarationReference::Local(declaration) = declaration
        && declaration.0 as usize >= facts.declarations.len()
    {
        return Err(KernelOwnerBuildError::new(format!(
            "{context} references missing declaration {}",
            declaration.0
        )));
    }
    Ok(())
}

fn validate_resource_statement(
    facts: &KernelDefinitionFactsInput,
    statement: KernelStatementReference,
    context: &str,
) -> Result<(), KernelOwnerBuildError> {
    let KernelStatementReference::Local(statement) = statement else {
        return Ok(());
    };
    if statement.0 as usize >= facts.statements.len() {
        return Err(KernelOwnerBuildError::new(format!(
            "{context} references missing statement {}",
            statement.0
        )));
    }
    Ok(())
}

fn collect_resource_artifacts(
    owner: &KernelOwnerProgramInput,
    facts: &KernelDefinitionFactsInput,
) -> Result<PendingKernelResources, KernelOwnerBuildError> {
    let mut resource_expressions = BTreeSet::new();
    let sources = facts
        .sources
        .iter()
        .enumerate()
        .map(|(index, source)| {
            if source.id.0 as usize != index {
                return Err(KernelOwnerBuildError::new(format!(
                    "kernel SOURCE rows must use dense IDs: row {index} has ID {}",
                    source.id.0
                )));
            }
            validate_resource_declaration(facts, source.declaration, "kernel SOURCE row")?;
            validate_resource_statement(facts, source.statement, "kernel SOURCE row")?;
            let expression = checked_expression_index(
                source.expression,
                owner.nodes.len(),
                "kernel SOURCE expression",
            )?;
            if !matches!(
                owner.nodes[expression].kind,
                KernelOwnerNodeKind::Source(_) | KernelOwnerNodeKind::SourcePacked(_)
            ) {
                return Err(KernelOwnerBuildError::new(format!(
                    "kernel SOURCE row {index} expression {expression} is not a literal SOURCE"
                )));
            }
            if !resource_expressions.insert((0u8, source.expression)) {
                return Err(KernelOwnerBuildError::new(format!(
                    "kernel SOURCE expression {expression} is published more than once"
                )));
            }
            Ok(PendingKernelSourceArtifact {
                id: source.id,
                declaration: source.declaration,
                statement: source.statement,
                expression: source.expression,
                path: KernelSemanticPath {
                    anchor: source.declaration,
                    projection: source.projection.clone(),
                },
                interval_ms: source.interval_ms,
            })
        })
        .collect::<Result<Vec<_>, _>>()?
        .into_boxed_slice();

    let states = facts
        .states
        .iter()
        .enumerate()
        .map(|(index, state)| {
            if state.id.0 as usize != index {
                return Err(KernelOwnerBuildError::new(format!(
                    "kernel state rows must use dense IDs: row {index} has ID {}",
                    state.id.0
                )));
            }
            validate_resource_declaration(
                facts,
                state.binding_declaration,
                "kernel state binding",
            )?;
            validate_resource_declaration(facts, state.declaration, "kernel state row")?;
            validate_resource_statement(facts, state.statement, "kernel state row")?;
            if state.synthetic_path && !state.projection.is_empty() {
                return Err(KernelOwnerBuildError::new(format!(
                    "kernel synthetic state row {index} already has a structural projection",
                )));
            }
            let expression = checked_expression_index(
                state.expression,
                owner.nodes.len(),
                "kernel state expression",
            )?;
            if !matches!(
                (&owner.nodes[expression].kind, state.kind),
                (KernelOwnerNodeKind::Hold, CheckedStateKind::Hold)
                    | (KernelOwnerNodeKind::Latest, CheckedStateKind::InitialLatest)
                    | (
                        KernelOwnerNodeKind::PureBuiltin {
                            kind: KernelPureBuiltinKind::BoolToggle,
                        },
                        CheckedStateKind::StatefulCall,
                    )
            ) {
                return Err(KernelOwnerBuildError::new(format!(
                    "kernel state row {index} kind {:?} is incompatible with expression {expression} kind {:?}",
                    state.kind, owner.nodes[expression].kind
                )));
            }
            if !resource_expressions.insert((1u8, state.expression)) {
                return Err(KernelOwnerBuildError::new(format!(
                    "kernel state expression {expression} is published more than once"
                )));
            }
            let initial = kernel_value_reference(owner, state.initial, expression)?;
            Ok(PendingKernelStateArtifact {
                binding_declaration: state.binding_declaration,
                declaration: state.declaration,
                statement: state.statement,
                expression: state.expression,
                initial,
                path: KernelSemanticPath {
                    anchor: state.declaration,
                    projection: state.projection.clone(),
                },
                synthetic_path: state.synthetic_path,
                kind: state.kind,
            })
        })
        .collect::<Result<Vec<_>, _>>()?
        .into_boxed_slice();

    let lists = facts
        .lists
        .iter()
        .enumerate()
        .map(|(index, list)| {
            if list.id.0 as usize != index {
                return Err(KernelOwnerBuildError::new(format!(
                    "kernel LIST rows must use dense IDs: row {index} has ID {}",
                    list.id.0
                )));
            }
            validate_resource_declaration(facts, list.declaration, "kernel LIST row")?;
            validate_resource_statement(facts, list.statement, "kernel LIST row")?;
            let producer =
                checked_expression_index(list.producer, owner.nodes.len(), "kernel LIST producer")?;
            let KernelOwnerNodeKind::Collection {
                kind: KernelCollectionKind::List,
                capacity,
            } = &owner.nodes[producer].kind
            else {
                return Err(KernelOwnerBuildError::new(format!(
                    "kernel LIST row {index} producer {producer} is not a list literal"
                )));
            };
            if capacity != &list.capacity {
                return Err(KernelOwnerBuildError::new(format!(
                    "kernel LIST row {index} capacity {:?} differs from producer capacity {:?}",
                    list.capacity, capacity
                )));
            }
            if !resource_expressions.insert((2u8, list.producer)) {
                return Err(KernelOwnerBuildError::new(format!(
                    "kernel LIST producer {producer} is published more than once"
                )));
            }
            Ok(PendingKernelListArtifact {
                id: list.id,
                declaration: list.declaration,
                statement: list.statement,
                producer: list.producer,
                path: KernelSemanticPath {
                    anchor: list.declaration,
                    projection: list.projection.clone(),
                },
                capacity: list.capacity,
                key_policy: list.key_policy,
            })
        })
        .collect::<Result<Vec<_>, _>>()?
        .into_boxed_slice();

    Ok(PendingKernelResources {
        sources,
        states,
        lists,
    })
}

fn validate_project_resource_inputs(
    owner: &KernelOwnerProgramInput,
    facts: &KernelDefinitionFactsInput,
) -> Result<(), KernelOwnerBuildError> {
    let mut published = vec![false; owner.nodes.len()];
    for (index, source) in facts.sources.iter().enumerate() {
        if source.id.0 as usize != index {
            return Err(KernelOwnerBuildError::new(format!(
                "kernel SOURCE rows must use dense IDs: row {index} has ID {}",
                source.id.0
            )));
        }
        validate_resource_declaration(facts, source.declaration, "kernel SOURCE row")?;
        validate_resource_statement(facts, source.statement, "kernel SOURCE row")?;
        let expression = checked_expression_index(
            source.expression,
            owner.nodes.len(),
            "kernel SOURCE expression",
        )?;
        if !matches!(
            owner.nodes[expression].kind,
            KernelOwnerNodeKind::Source(_) | KernelOwnerNodeKind::SourcePacked(_)
        ) {
            return Err(KernelOwnerBuildError::new(format!(
                "kernel SOURCE row {index} expression {expression} is not a literal SOURCE"
            )));
        }
        if std::mem::replace(&mut published[expression], true) {
            return Err(KernelOwnerBuildError::new(format!(
                "kernel SOURCE expression {expression} is published more than once"
            )));
        }
    }
    for (index, state) in facts.states.iter().enumerate() {
        if state.id.0 as usize != index {
            return Err(KernelOwnerBuildError::new(format!(
                "kernel state rows must use dense IDs: row {index} has ID {}",
                state.id.0
            )));
        }
        validate_resource_declaration(facts, state.binding_declaration, "kernel state binding")?;
        validate_resource_declaration(facts, state.declaration, "kernel state row")?;
        validate_resource_statement(facts, state.statement, "kernel state row")?;
        if state.synthetic_path && !state.projection.is_empty() {
            return Err(KernelOwnerBuildError::new(format!(
                "kernel synthetic state row {index} already has a structural projection"
            )));
        }
        let expression = checked_expression_index(
            state.expression,
            owner.nodes.len(),
            "kernel state expression",
        )?;
        if !matches!(
            (&owner.nodes[expression].kind, state.kind),
            (KernelOwnerNodeKind::Hold, CheckedStateKind::Hold)
                | (KernelOwnerNodeKind::Latest, CheckedStateKind::InitialLatest)
                | (
                    KernelOwnerNodeKind::PureBuiltin {
                        kind: KernelPureBuiltinKind::BoolToggle,
                    },
                    CheckedStateKind::StatefulCall,
                )
        ) {
            return Err(KernelOwnerBuildError::new(format!(
                "kernel state row {index} kind {:?} is incompatible with expression {expression} kind {:?}",
                state.kind, owner.nodes[expression].kind
            )));
        }
        if std::mem::replace(&mut published[expression], true) {
            return Err(KernelOwnerBuildError::new(format!(
                "kernel state expression {expression} is published more than once"
            )));
        }
        kernel_value_reference(owner, state.initial, expression)?;
    }
    for (index, list) in facts.lists.iter().enumerate() {
        if list.id.0 as usize != index {
            return Err(KernelOwnerBuildError::new(format!(
                "kernel LIST rows must use dense IDs: row {index} has ID {}",
                list.id.0
            )));
        }
        validate_resource_declaration(facts, list.declaration, "kernel LIST row")?;
        validate_resource_statement(facts, list.statement, "kernel LIST row")?;
        let producer =
            checked_expression_index(list.producer, owner.nodes.len(), "kernel LIST producer")?;
        let KernelOwnerNodeKind::Collection {
            kind: KernelCollectionKind::List,
            capacity,
        } = &owner.nodes[producer].kind
        else {
            return Err(KernelOwnerBuildError::new(format!(
                "kernel LIST row {index} producer {producer} is not a list literal"
            )));
        };
        if capacity != &list.capacity {
            return Err(KernelOwnerBuildError::new(format!(
                "kernel LIST row {index} capacity {:?} differs from producer capacity {:?}",
                list.capacity, capacity
            )));
        }
        if std::mem::replace(&mut published[producer], true) {
            return Err(KernelOwnerBuildError::new(format!(
                "kernel LIST producer {producer} is published more than once"
            )));
        }
    }
    Ok(())
}

fn state_candidate_survives(
    state: &PendingKernelStateArtifact,
    expression_modes: &[FlowMode],
) -> bool {
    if state.kind != CheckedStateKind::InitialLatest {
        return true;
    }
    let KernelValueReference::Local(initial) = state.initial else {
        return false;
    };
    expression_modes
        .get(initial.0 as usize)
        .is_some_and(|mode| *mode == FlowMode::Continuous)
}

fn allocate_synthetic_state_ordinals(
    owner: KernelOwnerId,
    states: &[PendingKernelStateArtifact],
    expression_modes: &[FlowMode],
    next_by_anchor: &mut BTreeMap<KernelOwnerId, u32>,
) -> Box<[Option<u32>]> {
    states
        .iter()
        .map(|state| {
            if !state.synthetic_path || !state_candidate_survives(state, expression_modes) {
                return None;
            }
            let anchor = match state.path.anchor {
                KernelDeclarationReference::Local(_) => owner,
                KernelDeclarationReference::OwnerPublic(owner) => owner,
                KernelDeclarationReference::OwnerDeclaration { owner, .. } => owner,
            };
            let next = next_by_anchor.entry(anchor).or_default();
            let ordinal = *next;
            *next = next
                .checked_add(1)
                .expect("kernel synthetic state-path ordinal exceeds u32");
            Some(ordinal)
        })
        .collect::<Vec<_>>()
        .into_boxed_slice()
}

fn allocate_project_synthetic_state_ordinals(
    program: &PackedKernelProjectProgram,
    owners: &[KernelProjectOwnerOutputs],
    definition_facts: &[KernelDefinitionFactsInput],
) -> Box<[Box<[Option<u32>]>]> {
    debug_assert_eq!(program.definition_count(), owners.len());
    debug_assert_eq!(definition_facts.len(), owners.len());
    let mut next_by_anchor = BTreeMap::<KernelOwnerId, u32>::new();
    owners
        .iter()
        .enumerate()
        .map(|(owner, definition)| {
            let owner_id =
                KernelOwnerId(u32::try_from(owner).expect("kernel definition count exceeds u32"));
            definition_facts[owner]
                .states
                .iter()
                .map(|state| {
                    if !state.synthetic_path
                        || !packed_state_input_candidate_survives(
                            program
                                .owner_at(owner)
                                .expect("validated synthetic-state owner remains present"),
                            state,
                            &definition.expression_modes,
                        )
                    {
                        return None;
                    }
                    let anchor = match state.declaration {
                        KernelDeclarationReference::Local(_) => owner_id,
                        KernelDeclarationReference::OwnerPublic(owner) => owner,
                        KernelDeclarationReference::OwnerDeclaration { owner, .. } => owner,
                    };
                    let next = next_by_anchor.entry(anchor).or_default();
                    let ordinal = *next;
                    *next = next
                        .checked_add(1)
                        .expect("kernel synthetic state-path ordinal exceeds u32");
                    Some(ordinal)
                })
                .collect::<Vec<_>>()
                .into_boxed_slice()
        })
        .collect::<Vec<_>>()
        .into_boxed_slice()
}

#[cfg(test)]
fn state_input_candidate_survives(
    input: &KernelOwnerProgramInput,
    state: &KernelStateInput,
    expression_modes: &[FlowMode],
) -> bool {
    if state.kind != CheckedStateKind::InitialLatest {
        return true;
    }
    let Ok(KernelValueReference::Local(initial)) =
        kernel_value_reference(input, state.initial, state.expression.0 as usize)
    else {
        return false;
    };
    expression_modes
        .get(initial.0 as usize)
        .is_some_and(|mode| *mode == FlowMode::Continuous)
}

fn packed_state_input_candidate_survives(
    input: PackedKernelOwnerProgramRef<'_>,
    state: &KernelStateInput,
    expression_modes: &[FlowMode],
) -> bool {
    if state.kind != CheckedStateKind::InitialLatest {
        return true;
    }
    let Ok(KernelValueReference::Local(initial)) =
        packed_kernel_value_reference(input, state.initial, state.expression.0 as usize)
    else {
        return false;
    };
    expression_modes
        .get(initial.0 as usize)
        .is_some_and(|mode| *mode == FlowMode::Continuous)
}

fn materialize_resource_artifacts(
    pending: PendingKernelResources,
    expressions: &[FlowType],
    public_results: Option<&[FlowType]>,
    synthetic_state_ordinals: &[Option<u32>],
) -> (
    Box<[RichKernelSourceArtifact]>,
    Box<[RichKernelStateArtifact]>,
    Box<[RichKernelListArtifact]>,
) {
    assert_eq!(
        pending.states.len(),
        synthetic_state_ordinals.len(),
        "kernel synthetic state-path table must cover every candidate state",
    );
    let sources = pending
        .sources
        .into_vec()
        .into_iter()
        .map(|source| RichKernelSourceArtifact {
            id: source.id,
            declaration: source.declaration,
            statement: source.statement,
            expression: source.expression,
            path: source.path,
            interval_ms: source.interval_ms,
            payload_type: expressions[source.expression.0 as usize].ty.clone(),
        })
        .collect::<Vec<_>>()
        .into_boxed_slice();
    let states = pending
        .states
        .into_vec()
        .into_iter()
        .zip(synthetic_state_ordinals.iter().copied())
        // Syntax identifies a conservative InitialLatest candidate before
        // solving. Cross-definition inputs can still change the initializer's
        // mode, so the solved expression table is the final cell-authority
        // decision. HOLD rows are unconditional.
        .filter(|(state, _)| {
            if state.kind != CheckedStateKind::InitialLatest {
                return true;
            }
            let KernelValueReference::Local(initial) = state.initial else {
                return false;
            };
            expressions
                .get(initial.0 as usize)
                .is_some_and(|initial| initial.mode == FlowMode::Continuous)
        })
        .enumerate()
        .map(|(index, (state, synthetic_ordinal))| {
            let mut path = state.path;
            if state.synthetic_path {
                let ordinal = synthetic_ordinal
                    .expect("surviving synthetic state candidate has no allocated path ordinal");
                assert!(
                    path.projection.is_empty(),
                    "synthetic state path must begin without a structural projection",
                );
                path.projection =
                    vec![format!("state_{ordinal}").into_boxed_str()].into_boxed_slice();
            } else {
                assert!(
                    synthetic_ordinal.is_none(),
                    "structural state path unexpectedly received a synthetic ordinal",
                );
            }
            RichKernelStateArtifact {
                id: KernelStateId(
                    u32::try_from(index).expect("kernel materialized state count exceeds u32"),
                ),
                binding_declaration: state.binding_declaration,
                declaration: state.declaration,
                statement: state.statement,
                expression: state.expression,
                initial: state.initial,
                path,
                kind: state.kind,
                flow_type: expressions[state.expression.0 as usize].clone(),
            }
        })
        .collect::<Vec<_>>()
        .into_boxed_slice();
    let lists = pending
        .lists
        .into_vec()
        .into_iter()
        .map(|list| {
            let producer = &expressions[list.producer.0 as usize];
            let authority = match list.declaration {
                KernelDeclarationReference::OwnerPublic(owner) => public_results
                    .and_then(|results| results.get(owner.0 as usize))
                    .filter(|result| matches!(result.ty, Type::List(_)))
                    .unwrap_or(producer),
                KernelDeclarationReference::Local(_)
                | KernelDeclarationReference::OwnerDeclaration { .. } => producer,
            };
            let Type::List(item_type) = &authority.ty else {
                unreachable!("a solved LIST literal must retain a List type")
            };
            RichKernelListArtifact {
                id: list.id,
                declaration: list.declaration,
                statement: list.statement,
                producer: list.producer,
                path: list.path,
                item_type: item_type.as_ref().clone(),
                capacity: list.capacity,
                key_policy: list.key_policy,
            }
        })
        .collect::<Vec<_>>()
        .into_boxed_slice();
    (sources, states, lists)
}

fn materialize_call_artifacts(
    owner: KernelOwnerId,
    pending: Box<[PendingKernelCallArtifact]>,
    expressions: &[FlowType],
    public_formals: &[Box<[FlowType]>],
    public_results: &[FlowType],
) -> Box<[RichKernelCallArtifact]> {
    pending
        .into_vec()
        .into_iter()
        .map(|call| {
            let type_substitutions = materialize_user_call_type_substitutions(
                owner,
                &call,
                expressions,
                public_formals,
                public_results,
            );
            RichKernelCallArtifact {
                expression: call.expression,
                target: call.target,
                inputs: call.inputs,
                type_substitutions,
                syntax_discriminated_result: call.syntax_discriminated_candidate
                    && type_has_concrete_outer_shape(&expressions[call.expression.0 as usize].ty),
                result: expressions[call.expression.0 as usize].clone(),
            }
        })
        .collect::<Vec<_>>()
        .into_boxed_slice()
}

fn materialize_user_call_type_substitutions(
    owner: KernelOwnerId,
    call: &PendingKernelCallArtifact,
    expressions: &[FlowType],
    public_formals: &[Box<[FlowType]>],
    public_results: &[FlowType],
) -> Box<[KernelCallTypeSubstitution]> {
    let KernelCallTarget::User {
        target,
        inherited_formal,
    } = call.target
    else {
        return Box::new([]);
    };
    let Some(target_formals) = public_formals.get(target.0 as usize) else {
        return Box::new([]);
    };
    let Some(target_result) = public_results.get(target.0 as usize) else {
        return Box::new([]);
    };

    let mut actuals =
        Vec::with_capacity(call.inputs.len() + usize::from(inherited_formal.is_some()));
    for input in call.inputs.iter() {
        let KernelCallInputRole::Formal { ordinal } = input.role else {
            continue;
        };
        let Some(actual) = call_value_flow(input.value, expressions, public_results) else {
            continue;
        };
        actuals.push((ordinal, &actual.ty));
    }
    if let Some(inherited) = inherited_formal
        && let Some(actual) = public_formals
            .get(owner.0 as usize)
            .and_then(|formals| formals.get(inherited.caller_ordinal as usize))
    {
        actuals.push((inherited.target_ordinal, &actual.ty));
    }

    derive_kernel_call_type_substitutions_from_refs(target_formals, target_result, &actuals, None)
}

/// Derive the canonical substitution environment for one callable
/// occurrence. The callable and actual type-variable namespaces must be
/// disjoint; production solver arenas guarantee that, while differential
/// adapters alpha-isolate legacy definition-local schemes before calling.
pub fn derive_kernel_call_type_substitutions(
    target_formals: &[FlowType],
    target_result: &FlowType,
    actuals: &[(u32, Type)],
    actual_result: Option<&Type>,
) -> Box<[KernelCallTypeSubstitution]> {
    derive_kernel_call_type_substitutions_iter(
        target_formals,
        target_result,
        actuals.iter().map(|(ordinal, actual)| (*ordinal, actual)),
        actual_result,
    )
}

fn derive_kernel_call_type_substitutions_from_refs(
    target_formals: &[FlowType],
    target_result: &FlowType,
    actuals: &[(u32, &Type)],
    actual_result: Option<&Type>,
) -> Box<[KernelCallTypeSubstitution]> {
    derive_kernel_call_type_substitutions_iter(
        target_formals,
        target_result,
        actuals.iter().map(|(ordinal, actual)| (*ordinal, *actual)),
        actual_result,
    )
}

fn derive_kernel_call_type_substitutions_iter<'a>(
    target_formals: &[FlowType],
    target_result: &FlowType,
    actuals: impl IntoIterator<Item = (u32, &'a Type)>,
    actual_result: Option<&Type>,
) -> Box<[KernelCallTypeSubstitution]> {
    derive_kernel_call_type_substitutions_from_lookup(
        target_formals.iter(),
        |ordinal| target_formals.get(ordinal as usize),
        target_result,
        actuals,
        actual_result,
    )
}

fn derive_kernel_call_type_substitutions_from_lookup<'formal, 'actual>(
    target_formals: impl IntoIterator<Item = &'formal FlowType>,
    target_formal: impl Fn(u32) -> Option<&'formal FlowType>,
    target_result: &FlowType,
    actuals: impl IntoIterator<Item = (u32, &'actual Type)>,
    actual_result: Option<&Type>,
) -> Box<[KernelCallTypeSubstitution]> {
    let mut parameter_ids = BTreeMap::new();
    for formal in target_formals {
        collect_callable_type_parameters(&formal.ty, &mut parameter_ids);
    }
    collect_callable_type_parameters(&target_result.ty, &mut parameter_ids);

    let mut substitutions = BTreeMap::new();
    for (ordinal, actual) in actuals {
        let Some(pattern) = target_formal(ordinal) else {
            continue;
        };
        match_call_type_pattern(&pattern.ty, actual, &mut substitutions);
    }

    // The quiescent occurrence result is the final authority for parameters
    // that are both consumed and produced by an immutable ABI callable.
    // Input-only matching is deliberately first-wins so ordinary
    // equality-constrained user calls can diagnose a later incompatible
    // argument and retain their OUT-frame authority. Collection mutators are
    // different: their solved ABI result widens the input collection with the
    // new item/entry. Re-match that result in an isolated map, then override
    // only the parameters it actually exposes. This keeps CheckedCall
    // substitutions coherent with CheckedCall.result without teaching
    // semantic expansion about individual builtins.
    if let Some(actual_result) = actual_result {
        let mut result_substitutions = BTreeMap::new();
        match_call_type_pattern(&target_result.ty, actual_result, &mut result_substitutions);
        substitutions.extend(result_substitutions);
    }

    let mut substitutions = substitutions
        .into_iter()
        .filter_map(|(variable, value)| {
            parameter_ids
                .get(&variable)
                .copied()
                .map(|variable| KernelCallTypeSubstitution { variable, value })
        })
        .collect::<Vec<_>>();
    substitutions.sort_unstable_by_key(|substitution| substitution.variable);
    substitutions.into_boxed_slice()
}

fn call_value_flow<'a>(
    value: KernelValueReference,
    expressions: &'a [FlowType],
    public_results: &'a [FlowType],
) -> Option<&'a FlowType> {
    match value {
        KernelValueReference::Local(expression) => expressions.get(expression.0 as usize),
        KernelValueReference::External(KernelExternalExpression {
            owner,
            target: KernelExternalTarget::Result,
        }) => public_results.get(owner.0 as usize),
        KernelValueReference::External(KernelExternalExpression {
            target: KernelExternalTarget::Expression(_),
            ..
        }) => None,
    }
}

fn collect_callable_type_parameters(
    ty: &Type,
    parameters: &mut BTreeMap<boon_checked::TypeVar, KernelTypeParameterId>,
) {
    match ty {
        Type::Var(variable) => {
            let next = KernelTypeParameterId(
                u32::try_from(parameters.len())
                    .expect("kernel callable type-parameter count exceeds u32"),
            );
            parameters.entry(*variable).or_insert(next);
        }
        Type::Object(shape) => {
            for field in shape.ordered_fields().into_iter().map(|(_, field)| field) {
                collect_callable_type_parameters(field, parameters);
            }
        }
        Type::List(item) | Type::Set(item) => {
            collect_callable_type_parameters(item, parameters);
        }
        Type::Map { key, value } => {
            collect_callable_type_parameters(key, parameters);
            collect_callable_type_parameters(value, parameters);
        }
        Type::Function { args, result } => {
            for argument in args {
                collect_callable_type_parameters(argument, parameters);
            }
            collect_callable_type_parameters(&result.ty, parameters);
        }
        Type::VariantSet(variants) => {
            for variant in variants {
                if let Variant::Tagged { fields, .. } = variant {
                    for field in fields.ordered_fields().into_iter().map(|(_, field)| field) {
                        collect_callable_type_parameters(field, parameters);
                    }
                }
            }
        }
        Type::Union(members) => {
            for member in members {
                collect_callable_type_parameters(member, parameters);
            }
        }
        Type::Text
        | Type::Number
        | Type::Bytes(_)
        | Type::Bits { .. }
        | Type::Absent
        | Type::RenderContract
        | Type::UnresolvedShape { .. }
        | Type::Unknown => {}
    }
}

fn call_type_is_placeholder(ty: &Type) -> bool {
    matches!(
        ty,
        Type::Unknown | Type::Var(_) | Type::UnresolvedShape { .. }
    ) || matches!(ty, Type::Object(shape) if shape.open && shape.fields.is_empty())
}

fn match_call_type_pattern(
    pattern: &Type,
    actual: &Type,
    substitutions: &mut BTreeMap<boon_checked::TypeVar, Type>,
) {
    match (pattern, actual) {
        (Type::Var(_), Type::Unknown | Type::UnresolvedShape { .. } | Type::Absent) => {}
        (Type::Var(variable), actual) => {
            if substitutions
                .get(variable)
                .is_none_or(call_type_is_placeholder)
            {
                substitutions.insert(*variable, actual.clone());
            }
        }
        (Type::List(pattern), Type::List(actual)) | (Type::Set(pattern), Type::Set(actual)) => {
            match_call_type_pattern(pattern, actual, substitutions);
        }
        (
            Type::Map {
                key: pattern_key,
                value: pattern_value,
            },
            Type::Map {
                key: actual_key,
                value: actual_value,
            },
        ) => {
            match_call_type_pattern(pattern_key, actual_key, substitutions);
            match_call_type_pattern(pattern_value, actual_value, substitutions);
        }
        (
            Type::Function {
                args: pattern_args,
                result: pattern_result,
            },
            Type::Function {
                args: actual_args,
                result: actual_result,
            },
        ) if pattern_args.len() == actual_args.len() => {
            for (pattern, actual) in pattern_args.iter().zip(actual_args) {
                match_call_type_pattern(pattern, actual, substitutions);
            }
            match_call_type_pattern(&pattern_result.ty, &actual_result.ty, substitutions);
        }
        (Type::Object(pattern), Type::Object(actual)) => {
            for (name, pattern) in &pattern.fields {
                if let Some(actual) = actual.fields.get(name) {
                    match_call_type_pattern(pattern, actual, substitutions);
                }
            }
        }
        (Type::VariantSet(pattern), Type::VariantSet(actual)) => {
            for pattern in pattern {
                let Variant::Tagged {
                    tag: pattern_tag,
                    fields: pattern_fields,
                } = pattern
                else {
                    continue;
                };
                let Some(Variant::Tagged {
                    fields: actual_fields,
                    ..
                }) = actual.iter().find(
                    |variant| matches!(variant, Variant::Tagged { tag, .. } if tag == pattern_tag),
                )
                else {
                    continue;
                };
                for (name, pattern) in &pattern_fields.fields {
                    if let Some(actual) = actual_fields.fields.get(name) {
                        match_call_type_pattern(pattern, actual, substitutions);
                    }
                }
            }
        }
        (Type::Union(pattern), Type::Union(actual)) => {
            for actual in actual {
                if let Some(pattern) = pattern
                    .iter()
                    .find(|pattern| call_type_pattern_accepts(pattern, actual))
                {
                    match_call_type_pattern(pattern, actual, substitutions);
                }
            }
        }
        (Type::Union(pattern), actual) => {
            if let Some(pattern) = pattern
                .iter()
                .find(|pattern| call_type_pattern_accepts(pattern, actual))
            {
                match_call_type_pattern(pattern, actual, substitutions);
            }
        }
        (pattern, Type::Union(actual)) => {
            for actual in actual
                .iter()
                .filter(|actual| call_type_pattern_accepts(pattern, actual))
            {
                match_call_type_pattern(pattern, actual, substitutions);
            }
        }
        _ => {}
    }
}

fn call_type_pattern_accepts(pattern: &Type, actual: &Type) -> bool {
    match (pattern, actual) {
        (Type::Var(_), Type::Unknown | Type::UnresolvedShape { .. } | Type::Absent) => false,
        (Type::Var(_), _) => true,
        (Type::List(pattern), Type::List(actual)) | (Type::Set(pattern), Type::Set(actual)) => {
            call_type_pattern_accepts(pattern, actual)
        }
        (Type::Object(pattern), Type::Object(actual)) => pattern.fields.iter().all(|(name, ty)| {
            actual
                .fields
                .get(name)
                .is_some_and(|actual| call_type_pattern_accepts(ty, actual))
        }),
        (Type::Union(pattern), actual) => pattern
            .iter()
            .any(|pattern| call_type_pattern_accepts(pattern, actual)),
        (pattern, Type::Union(actual)) => actual
            .iter()
            .all(|actual| call_type_pattern_accepts(pattern, actual)),
        _ => pattern == actual || boon_checked::resolved_type_is_assignable_to(actual, pattern),
    }
}

fn collect_call_syntax_artifacts(
    input: &KernelOwnerProgramInput,
    facts: &KernelDefinitionFactsInput,
) -> Result<Box<[KernelCallSyntaxArtifact]>, KernelOwnerBuildError> {
    facts
        .call_syntax
        .iter()
        .map(|call| {
            let call_index = call.expression.0 as usize;
            Ok(KernelCallSyntaxArtifact {
                expression: call.expression,
                occurrence: call.occurrence.clone(),
                function: call.function.clone(),
                pipe_input: call
                    .pipe_input
                    .map(|value| kernel_value_reference(input, value, call_index))
                    .transpose()?,
                arguments: call
                    .arguments
                    .iter()
                    .map(|argument| {
                        Ok(KernelCallSyntaxArgumentArtifact {
                            ordinal: argument.ordinal,
                            kind: argument.kind,
                            name: argument.name.clone(),
                            value: kernel_value_reference(input, argument.value, call_index)?,
                            span: argument.span,
                        })
                    })
                    .collect::<Result<Vec<_>, KernelOwnerBuildError>>()?
                    .into_boxed_slice(),
                pass: call
                    .pass
                    .map(|pass| {
                        Ok(KernelCallPassArtifact {
                            value: kernel_value_reference(input, pass.value, call_index)?,
                            final_clause: pass.final_clause,
                            span: pass.span,
                        })
                    })
                    .transpose()?,
            })
        })
        .collect::<Result<Vec<_>, _>>()
        .map(Vec::into_boxed_slice)
}

fn collect_execution_shape_artifacts(
    input: &KernelOwnerProgramInput,
    facts: &KernelDefinitionFactsInput,
) -> Result<Box<[KernelExecutionShapeArtifact]>, KernelOwnerBuildError> {
    facts
        .execution_shapes
        .iter()
        .map(|shape| {
            let expression = shape.expression();
            let consumer = expression.0 as usize;
            Ok(match shape {
                KernelExecutionShapeInput::Conditional { kind, .. } => {
                    KernelExecutionShapeArtifact::Conditional {
                        expression,
                        kind: *kind,
                    }
                }
                KernelExecutionShapeInput::Record { fields, .. } => {
                    KernelExecutionShapeArtifact::Record {
                        expression,
                        fields: fields
                            .iter()
                            .map(|field| {
                                Ok(KernelExecutionRecordFieldArtifact {
                                    ordinal: field.ordinal,
                                    declaration: field
                                        .declaration
                                        .map(|declaration| {
                                            link_structural_declaration(
                                                input,
                                                declaration,
                                                field.value,
                                                consumer,
                                            )
                                        })
                                        .transpose()?,
                                    name: field.name.clone(),
                                    value: kernel_value_reference(input, field.value, consumer)?,
                                    spread: field.spread,
                                    span: field.span,
                                })
                            })
                            .collect::<Result<Vec<_>, KernelOwnerBuildError>>()?
                            .into_boxed_slice(),
                    }
                }
                KernelExecutionShapeInput::Block {
                    bindings, result, ..
                } => KernelExecutionShapeArtifact::Block {
                    expression,
                    bindings: bindings
                        .iter()
                        .map(|binding| {
                            Ok(KernelExecutionBlockBindingArtifact {
                                ordinal: binding.ordinal,
                                declaration: link_structural_declaration(
                                    input,
                                    binding.declaration,
                                    binding.value,
                                    consumer,
                                )?,
                                value: kernel_value_reference(input, binding.value, consumer)?,
                                span: binding.span,
                            })
                        })
                        .collect::<Result<Vec<_>, KernelOwnerBuildError>>()?
                        .into_boxed_slice(),
                    result: result
                        .map(|result| kernel_value_reference(input, result, consumer))
                        .transpose()?,
                },
                KernelExecutionShapeInput::MatchArm {
                    selector, bindings, ..
                } => KernelExecutionShapeArtifact::MatchArm {
                    expression,
                    selector: kernel_value_reference(input, *selector, consumer)?,
                    bindings: bindings.clone(),
                },
            })
        })
        .collect::<Result<Vec<_>, _>>()
        .map(Vec::into_boxed_slice)
}

fn link_structural_declaration(
    input: &KernelOwnerProgramInput,
    declaration: KernelStructuralDeclarationInput,
    value: KernelExpressionId,
    consumer: usize,
) -> Result<KernelDeclarationReference, KernelOwnerBuildError> {
    match declaration {
        KernelStructuralDeclarationInput::Local(declaration) => {
            Ok(KernelDeclarationReference::Local(declaration))
        }
        KernelStructuralDeclarationInput::ValueOwnerPublic => {
            let KernelValueReference::External(KernelExternalExpression { owner, .. }) =
                kernel_value_reference(input, value, consumer)?
            else {
                return Err(KernelOwnerBuildError::new(format!(
                    "kernel structural expression {consumer} lost its external owner declaration"
                )));
            };
            Ok(KernelDeclarationReference::OwnerPublic(owner))
        }
    }
}

fn link_packed_structural_declaration(
    input: PackedKernelOwnerProgramRef<'_>,
    declaration: KernelStructuralDeclarationInput,
    value: KernelExpressionId,
    consumer: usize,
) -> Result<KernelDeclarationReference, KernelOwnerBuildError> {
    match declaration {
        KernelStructuralDeclarationInput::Local(declaration) => {
            Ok(KernelDeclarationReference::Local(declaration))
        }
        KernelStructuralDeclarationInput::ValueOwnerPublic => {
            let KernelValueReference::External(KernelExternalExpression { owner, .. }) =
                packed_kernel_value_reference(input, value, consumer)?
            else {
                return Err(KernelOwnerBuildError::new(format!(
                    "kernel structural expression {consumer} lost its external owner declaration"
                )));
            };
            Ok(KernelDeclarationReference::OwnerPublic(owner))
        }
    }
}

fn collect_call_artifacts(
    input: &KernelOwnerProgramInput,
    syntax_discriminated_candidates: &[bool],
) -> Result<Box<[PendingKernelCallArtifact]>, KernelOwnerBuildError> {
    input
        .nodes
        .iter()
        .enumerate()
        .filter_map(|(expression, node)| {
            let (target, uses_abi_inputs) = match &node.kind {
                KernelOwnerNodeKind::UserCall {
                    target,
                    inherited_formal,
                } => (
                    KernelCallTarget::User {
                        target: *target,
                        inherited_formal: *inherited_formal,
                    },
                    false,
                ),
                KernelOwnerNodeKind::RenderConstructor { kind } => (
                    KernelCallTarget::RenderConstructor { kind: kind.clone() },
                    true,
                ),
                KernelOwnerNodeKind::PureBuiltin { kind } => {
                    (KernelCallTarget::PureBuiltin { kind: *kind }, true)
                }
                KernelOwnerNodeKind::FixedAbiCall { .. }
                | KernelOwnerNodeKind::FixedAbiCallPacked { .. } => {
                    (KernelCallTarget::FixedAbi, true)
                }
                KernelOwnerNodeKind::HostEffect { operation } => (
                    KernelCallTarget::HostEffect {
                        operation: operation.clone(),
                    },
                    true,
                ),
                KernelOwnerNodeKind::FieldProjection { field } => (
                    KernelCallTarget::FieldProjection {
                        field: field.clone(),
                    },
                    true,
                ),
                _ => return None,
            };
            Some((|| {
                let mut inputs = Vec::with_capacity(node.inputs.len());
                for edge in &node.inputs {
                    let role = match &edge.role {
                        KernelOwnerEdgeRole::CallArgument { ordinal }
                        | KernelOwnerEdgeRole::CallOutArgument { ordinal }
                            if !uses_abi_inputs =>
                        {
                            KernelCallInputRole::Formal { ordinal: *ordinal }
                        }
                        KernelOwnerEdgeRole::AbiArgument { name } if uses_abi_inputs => {
                            KernelCallInputRole::Abi { name: name.clone() }
                        }
                        role => {
                            return Err(KernelOwnerBuildError::new(format!(
                                "kernel call node {expression} has non-call input role {role:?}"
                            )));
                        }
                    };
                    let value = kernel_value_reference(input, edge.expression, expression)?;
                    inputs.push(KernelCallInputArtifact { role, value });
                }
                Ok(PendingKernelCallArtifact {
                    expression: KernelExpressionId(
                        u32::try_from(expression)
                            .expect("kernel owner expression count exceeds u32"),
                    ),
                    target,
                    inputs: inputs.into_boxed_slice(),
                    syntax_discriminated_candidate: syntax_discriminated_candidates
                        .get(expression)
                        .copied()
                        .unwrap_or(false),
                })
            })())
        })
        .collect::<Result<Vec<_>, _>>()
        .map(Vec::into_boxed_slice)
}

fn validate_project_call_inputs(
    input: &KernelOwnerProgramInput,
) -> Result<(), KernelOwnerBuildError> {
    for (expression, node) in input.nodes.iter().enumerate() {
        let uses_abi_inputs = match node.kind {
            KernelOwnerNodeKind::UserCall { .. } => false,
            KernelOwnerNodeKind::RenderConstructor { .. }
            | KernelOwnerNodeKind::PureBuiltin { .. }
            | KernelOwnerNodeKind::FixedAbiCall { .. }
            | KernelOwnerNodeKind::FixedAbiCallPacked { .. }
            | KernelOwnerNodeKind::HostEffect { .. }
            | KernelOwnerNodeKind::FieldProjection { .. } => true,
            _ => continue,
        };
        for edge in &node.inputs {
            match &edge.role {
                KernelOwnerEdgeRole::CallArgument { .. }
                | KernelOwnerEdgeRole::CallOutArgument { .. }
                    if !uses_abi_inputs => {}
                KernelOwnerEdgeRole::AbiArgument { .. } if uses_abi_inputs => {}
                role => {
                    return Err(KernelOwnerBuildError::new(format!(
                        "kernel call node {expression} has non-call input role {role:?}"
                    )));
                }
            }
            kernel_value_reference(input, edge.expression, expression)?;
        }
    }
    Ok(())
}

fn collect_project_call_solve_rows(
    input: PackedKernelOwnerProgramRef<'_>,
    syntax_discriminated_candidates: &[bool],
    syntax_discriminated_root_outputs: &[Option<OutputId>],
) -> Box<[KernelProjectCallSolve]> {
    input
        .nodes()
        .iter()
        .enumerate()
        .filter(|(_, node)| {
            matches!(
                node.kind,
                PackedKernelOwnerNodeKind::UserCall { .. }
                    | PackedKernelOwnerNodeKind::RenderConstructor { .. }
                    | PackedKernelOwnerNodeKind::PureBuiltin { .. }
                    | PackedKernelOwnerNodeKind::FixedAbiCall { .. }
                    | PackedKernelOwnerNodeKind::HostEffect { .. }
                    | PackedKernelOwnerNodeKind::FieldProjection { .. }
            )
        })
        .map(|(expression, _)| KernelProjectCallSolve {
            expression: KernelExpressionId(
                u32::try_from(expression).expect("kernel owner expression count exceeds u32"),
            ),
            syntax_discriminated_candidate: syntax_discriminated_candidates
                .get(expression)
                .copied()
                .unwrap_or(false),
            syntax_discriminated_root_output: syntax_discriminated_root_outputs
                .get(expression)
                .copied()
                .flatten(),
        })
        .collect::<Vec<_>>()
        .into_boxed_slice()
}

fn collect_definition_diagnostic_artifacts(
    owner: KernelOwnerId,
    input: &KernelOwnerProgramInput,
    facts: &KernelDefinitionFactsInput,
) -> Result<Box<[KernelDiagnosticArtifact]>, KernelOwnerBuildError> {
    validate_definition_diagnostic_inputs(owner, input, facts)?;
    Ok(facts
        .diagnostics
        .iter()
        .map(|diagnostic| KernelDiagnosticArtifact {
            owner,
            severity: diagnostic.severity,
            site: diagnostic.site.clone(),
            kind: diagnostic.kind.clone(),
        })
        .collect::<Vec<_>>()
        .into_boxed_slice())
}

fn collect_packed_definition_diagnostic_artifacts(
    owner: KernelOwnerId,
    input: PackedKernelOwnerProgramRef<'_>,
    facts: &KernelDefinitionFactsInput,
) -> Result<Box<[KernelDiagnosticArtifact]>, KernelOwnerBuildError> {
    validate_packed_definition_diagnostic_inputs(input, facts)?;
    Ok(facts
        .diagnostics
        .iter()
        .map(|diagnostic| KernelDiagnosticArtifact {
            owner,
            severity: diagnostic.severity,
            site: diagnostic.site.clone(),
            kind: diagnostic.kind.clone(),
        })
        .collect::<Vec<_>>()
        .into_boxed_slice())
}

fn validate_packed_definition_diagnostic_inputs(
    input: PackedKernelOwnerProgramRef<'_>,
    facts: &KernelDefinitionFactsInput,
) -> Result<(), KernelOwnerBuildError> {
    for diagnostic in &facts.diagnostics {
        if matches!(&diagnostic.kind, KernelDiagnosticKind::CallInputType { .. }) {
            return Err(KernelOwnerBuildError::new(
                "definition diagnostic inputs cannot supply solved call-input type payloads",
            ));
        }
        match diagnostic.site {
            KernelDiagnosticSite::Expression { expression } => {
                checked_expression_index(
                    expression,
                    input.node_count(),
                    "source diagnostic expression",
                )?;
            }
            KernelDiagnosticSite::CallArgument { call, .. }
            | KernelDiagnosticSite::CallPass { call, .. } => {
                checked_expression_index(call, input.node_count(), "call diagnostic expression")?;
            }
            KernelDiagnosticSite::CallInput { .. } => {
                return Err(KernelOwnerBuildError::new(
                    "definition diagnostic inputs cannot precompute solved call-input failures",
                ));
            }
        }
    }
    for expression in facts.diagnostic_values.iter().copied() {
        packed_kernel_value_reference(input, expression, expression.0 as usize)?;
    }
    Ok(())
}

fn validate_definition_diagnostic_inputs(
    _owner: KernelOwnerId,
    input: &KernelOwnerProgramInput,
    facts: &KernelDefinitionFactsInput,
) -> Result<(), KernelOwnerBuildError> {
    for diagnostic in &facts.diagnostics {
        if matches!(&diagnostic.kind, KernelDiagnosticKind::CallInputType { .. }) {
            return Err(KernelOwnerBuildError::new(
                "definition diagnostic inputs cannot supply solved call-input type payloads",
            ));
        }
        match diagnostic.site {
            KernelDiagnosticSite::Expression { expression } => {
                checked_expression_index(
                    expression,
                    input.nodes.len(),
                    "source diagnostic expression",
                )?;
            }
            KernelDiagnosticSite::CallArgument { call, .. }
            | KernelDiagnosticSite::CallPass { call, .. } => {
                checked_expression_index(call, input.nodes.len(), "call diagnostic expression")?;
            }
            KernelDiagnosticSite::CallInput { .. } => {
                return Err(KernelOwnerBuildError::new(
                    "definition diagnostic inputs cannot precompute solved call-input failures",
                ));
            }
        }
    }
    for expression in facts.diagnostic_values.iter().copied() {
        kernel_value_reference(input, expression, expression.0 as usize)?;
    }
    Ok(())
}

fn collect_host_effect_artifacts(
    input: &KernelOwnerProgramInput,
) -> Result<Box<[KernelHostEffectArtifact]>, KernelOwnerBuildError> {
    input
        .nodes
        .iter()
        .enumerate()
        .filter_map(|(expression, node)| {
            let KernelOwnerNodeKind::HostEffect { operation } = &node.kind else {
                return None;
            };
            Some((|| {
                let policy = host_effect_policy(operation).ok_or_else(|| {
                    KernelOwnerBuildError::new(format!(
                        "kernel host-effect node {expression} names unknown operation `{operation}`"
                    ))
                })?;
                if policy.result_policy != ResultPolicySpec::ReturnValue
                    || !policy.has_typed_schema
                {
                    return Err(KernelOwnerBuildError::new(format!(
                        "kernel host-effect node {expression} operation `{operation}` has no return-value schema"
                    )));
                }
                Ok(KernelHostEffectArtifact {
                    expression: KernelExpressionId(
                        u32::try_from(expression)
                            .expect("kernel owner expression count exceeds u32"),
                    ),
                    operation: policy.operation.into(),
                    replay: policy.replay,
                    barrier: policy.barrier,
                    result_policy: policy.result_policy,
                    delivery: materialize_delivery_policy(policy.delivery),
                })
            })())
        })
        .collect::<Result<Vec<_>, _>>()
        .map(Vec::into_boxed_slice)
}

fn collect_packed_host_effect_artifacts(
    input: PackedKernelOwnerProgramRef<'_>,
) -> Result<Box<[KernelHostEffectArtifact]>, KernelOwnerBuildError> {
    input
        .nodes()
        .iter()
        .enumerate()
        .filter_map(|(expression, node)| {
            let PackedKernelOwnerNodeKind::HostEffect { operation } = node.kind else {
                return None;
            };
            Some((|| {
                let operation = input.symbol(operation).ok_or_else(|| {
                    KernelOwnerBuildError::new(format!(
                        "kernel host-effect node {expression} references text outside its project authority"
                    ))
                })?;
                let policy = host_effect_policy(operation).ok_or_else(|| {
                    KernelOwnerBuildError::new(format!(
                        "kernel host-effect node {expression} names unknown operation `{operation}`"
                    ))
                })?;
                if policy.result_policy != ResultPolicySpec::ReturnValue
                    || !policy.has_typed_schema
                {
                    return Err(KernelOwnerBuildError::new(format!(
                        "kernel host-effect node {expression} operation `{operation}` has no return-value schema"
                    )));
                }
                Ok(KernelHostEffectArtifact {
                    expression: KernelExpressionId(
                        u32::try_from(expression)
                            .expect("kernel owner expression count exceeds u32"),
                    ),
                    operation: policy.operation.into(),
                    replay: policy.replay,
                    barrier: policy.barrier,
                    result_policy: policy.result_policy,
                    delivery: materialize_delivery_policy(policy.delivery),
                })
            })())
        })
        .collect::<Result<Vec<_>, _>>()
        .map(Vec::into_boxed_slice)
}

fn validate_host_effect_inputs(
    input: &KernelOwnerProgramInput,
) -> Result<(), KernelOwnerBuildError> {
    for (expression, node) in input.nodes.iter().enumerate() {
        let KernelOwnerNodeKind::HostEffect { operation } = &node.kind else {
            continue;
        };
        let policy = host_effect_policy(operation).ok_or_else(|| {
            KernelOwnerBuildError::new(format!(
                "kernel host-effect node {expression} names unknown operation `{operation}`"
            ))
        })?;
        if policy.result_policy != ResultPolicySpec::ReturnValue || !policy.has_typed_schema {
            return Err(KernelOwnerBuildError::new(format!(
                "kernel host-effect node {expression} operation `{operation}` has no return-value schema"
            )));
        }
    }
    Ok(())
}

fn materialize_delivery_policy(policy: DeliveryCardinalityPolicySpec) -> DeliveryCardinalitySpec {
    match policy {
        DeliveryCardinalityPolicySpec::Single => DeliveryCardinalitySpec::Single,
        DeliveryCardinalityPolicySpec::Stream {
            initial_credits,
            max_in_flight,
            credit_result_tags,
            terminal_result_tags,
        } => DeliveryCardinalitySpec::Stream {
            initial_credits,
            max_in_flight,
            credit_result_tags: credit_result_tags.to_vec(),
            terminal_result_tags: terminal_result_tags.to_vec(),
        },
    }
}

fn validate_project_expression_inputs(
    input: &KernelOwnerProgramInput,
) -> Result<(), KernelOwnerBuildError> {
    for (consumer, node) in input.nodes.iter().enumerate() {
        for edge in &node.inputs {
            kernel_value_reference(input, edge.expression, consumer)?;
        }
    }
    Ok(())
}

fn expression_formal_dependencies(
    owner: PackedKernelOwnerProgramRef<'_>,
    root: KernelExpressionId,
) -> BTreeSet<u32> {
    let mut dependencies = BTreeSet::new();
    let mut visited = BTreeSet::new();
    let mut pending = vec![root.0 as usize];
    while let Some(expression) = pending.pop() {
        if expression >= owner.node_count() || !visited.insert(expression) {
            continue;
        }
        let node = &owner.nodes()[expression];
        match &node.kind {
            PackedKernelOwnerNodeKind::FormalRead { formal, .. }
            | PackedKernelOwnerNodeKind::ContextRead { formal, .. } => {
                dependencies.insert(*formal);
            }
            _ => {}
        }
        pending.extend(node.inputs(owner).iter().filter_map(|input| {
            let input = input.expression.0 as usize;
            (input < owner.node_count()).then_some(input)
        }));
    }
    dependencies
}

fn expression_contains_nested_formal_read(
    owner: PackedKernelOwnerProgramRef<'_>,
    root: KernelExpressionId,
    formal: u32,
) -> bool {
    let mut visited = BTreeSet::new();
    let mut pending = vec![root.0 as usize];
    while let Some(expression) = pending.pop() {
        if expression >= owner.node_count() || !visited.insert(expression) {
            continue;
        }
        let node = &owner.nodes()[expression];
        if matches!(
            &node.kind,
            PackedKernelOwnerNodeKind::FormalRead {
                formal: candidate,
                fields,
            } | PackedKernelOwnerNodeKind::ContextRead {
                formal: candidate,
                fields,
            } if *candidate == formal && *fields != boon_contract::PathId::ROOT
        ) {
            return true;
        }
        pending.extend(node.inputs(owner).iter().filter_map(|input| {
            let input = input.expression.0 as usize;
            (input < owner.node_count()).then_some(input)
        }));
    }
    false
}

/// Find formal contracts whose field requirements are guarded by syntax
/// selection, then propagate that fact through direct user-call arguments.
///
/// A `WHEN` such as `value |> WHEN { A => value.a; B => value.b }` shapes the
/// principal formal as an object containing both `a` and `b`. Requiring every
/// member of an actual `A[a] | B[b]` value to contain both fields would turn a
/// valid branch-discriminated call into a false diagnostic. Wrapper functions
/// inherit the same property when they forward one of their formals into that
/// parameter, so this is a small fixed point over the packed call graph.
fn project_syntax_discriminated_formals(input: &PackedKernelProjectProgram) -> Vec<Box<[u32]>> {
    let mut formals = vec![BTreeSet::<u32>::new(); input.definition_count()];
    for (owner_index, owner) in input.owners().enumerate() {
        for node in owner
            .nodes()
            .iter()
            .filter(|node| matches!(node.kind, PackedKernelOwnerNodeKind::When))
        {
            for selector in node
                .inputs(owner)
                .iter()
                .filter(|input| matches!(input.role, PackedKernelOwnerEdgeRole::WhenInput))
            {
                for formal in expression_formal_dependencies(owner, selector.expression) {
                    let has_branch_projection = node
                        .inputs(owner)
                        .iter()
                        .filter(|input| matches!(input.role, PackedKernelOwnerEdgeRole::WhenArm))
                        .filter_map(|arm| owner.node(arm.expression))
                        .flat_map(|arm| {
                            arm.inputs(owner).iter().filter(|input| {
                                matches!(input.role, PackedKernelOwnerEdgeRole::MatchOutput)
                            })
                        })
                        .any(|output| {
                            expression_contains_nested_formal_read(owner, output.expression, formal)
                        });
                    if has_branch_projection {
                        formals[owner_index].insert(formal);
                    }
                }
            }
        }
    }

    loop {
        let mut changed = false;
        for (owner_index, owner) in input.owners().enumerate() {
            for node in owner.nodes() {
                let PackedKernelOwnerNodeKind::UserCall {
                    target,
                    inherited_formal,
                } = &node.kind
                else {
                    continue;
                };
                let Some(target_formals) = formals.get(target.0 as usize) else {
                    continue;
                };
                let inherited_is_discriminated = inherited_formal
                    .filter(|inherited| target_formals.contains(&inherited.target_ordinal));
                let discriminated_inputs = node
                    .inputs(owner)
                    .iter()
                    .filter_map(|input| {
                        let PackedKernelOwnerEdgeRole::CallArgument { ordinal } = input.role else {
                            return None;
                        };
                        target_formals
                            .contains(&ordinal)
                            .then_some(input.expression)
                    })
                    .collect::<Vec<_>>();
                let mut propagated = discriminated_inputs
                    .into_iter()
                    .flat_map(|expression| expression_formal_dependencies(owner, expression))
                    .collect::<BTreeSet<_>>();
                if let Some(inherited) = inherited_is_discriminated {
                    propagated.insert(inherited.caller_ordinal);
                }
                let before = formals[owner_index].len();
                formals[owner_index].extend(propagated);
                changed |= formals[owner_index].len() != before;
            }
        }
        if !changed {
            break;
        }
    }

    formals
        .into_iter()
        .map(|formals| formals.into_iter().collect::<Vec<_>>().into_boxed_slice())
        .collect()
}

/// Validate the compatibility DTO while its rich names and source-shaped
/// rows are still available. Production consumes that DTO immediately after
/// this gate; the packed compiler never reconstructs it merely to repeat
/// compatibility validation.
pub(crate) fn validate_compatibility_project_input(
    input: &KernelProjectProgramInput,
    facts: &[KernelDefinitionFactsInput],
) -> Result<(), KernelOwnerBuildError> {
    if facts.len() != input.owners.len() {
        return Err(KernelOwnerBuildError::new(format!(
            "kernel project has {} owners but {} definition-fact tables",
            input.owners.len(),
            facts.len()
        )));
    }
    let validate_project_declaration = |reference: KernelDeclarationReference,
                                        definition: usize,
                                        context: &str|
     -> Result<(), KernelOwnerBuildError> {
        let (owner, declaration) = match reference {
            KernelDeclarationReference::Local(_) => return Ok(()),
            KernelDeclarationReference::OwnerPublic(owner) => (owner, None),
            KernelDeclarationReference::OwnerDeclaration { owner, declaration } => {
                (owner, Some(declaration))
            }
        };
        let Some(target_facts) = facts.get(owner.0 as usize) else {
            return Err(KernelOwnerBuildError::new(format!(
                "kernel definition {definition} {context} references missing owner {}",
                owner.0
            )));
        };
        if let Some(declaration) = declaration
            && target_facts
                .declarations
                .get(declaration.0 as usize)
                .is_none_or(|target| target.id != declaration)
        {
            return Err(KernelOwnerBuildError::new(format!(
                "kernel definition {definition} {context} references missing declaration {} in owner {}",
                declaration.0, owner.0
            )));
        }
        Ok(())
    };
    let mut call_digest_scratch = Vec::new();
    for (definition, (owner, facts)) in input.owners.iter().zip(facts).enumerate() {
        validate_definition_linker_facts(owner, facts, Some(definition), &mut call_digest_scratch)?;
        if let Some(reference) = facts.linkage.public_declaration {
            validate_project_declaration(
                reference,
                definition,
                "direct-linker public declaration",
            )?;
        }
        for statement in &facts.statements {
            for child in &statement.children {
                if let KernelStatementChildReference::Owner(owner) = child
                    && owner.0 as usize >= input.owners.len()
                {
                    return Err(KernelOwnerBuildError::new(format!(
                        "kernel definition {definition} statement {} references missing child owner {}",
                        statement.id.0, owner.0
                    )));
                }
            }
        }
        for binding in &facts.lexical_bindings {
            if let KernelLexicalBindingTargetInput::Declaration(reference) = binding.target {
                validate_project_declaration(
                    reference,
                    definition,
                    &format!("lexical binding {}", binding.expression.0),
                )?;
            }
        }
        let validate_resource_owner = |reference: KernelDeclarationReference, context: &str| {
            validate_project_declaration(reference, definition, context)
        };
        let validate_resource_statement_owner =
            |reference: KernelStatementReference, context: &str| {
                if let KernelStatementReference::OwnerPublic(owner) = reference
                    && owner.0 as usize >= input.owners.len()
                {
                    return Err(KernelOwnerBuildError::new(format!(
                        "kernel definition {definition} {context} references missing owner {}",
                        owner.0
                    )));
                }
                Ok(())
            };
        for source in &facts.sources {
            validate_resource_owner(source.declaration, "SOURCE row")?;
            validate_resource_statement_owner(source.statement, "SOURCE statement")?;
        }
        for state in &facts.states {
            validate_resource_owner(state.declaration, "state row")?;
            validate_resource_owner(state.binding_declaration, "state binding")?;
            validate_resource_statement_owner(state.statement, "state statement")?;
        }
        for list in &facts.lists {
            validate_resource_owner(list.declaration, "LIST row")?;
            validate_resource_statement_owner(list.statement, "LIST statement")?;
        }
        let owner_id = KernelOwnerId(
            u32::try_from(definition).expect("kernel project owner count exceeds u32"),
        );
        validate_project_expression_inputs(owner)?;
        validate_project_call_inputs(owner)?;
        validate_host_effect_inputs(owner)?;
        validate_definition_diagnostic_inputs(owner_id, owner, facts)?;
        validate_project_statement_inputs(owner, facts)?;
        validate_project_declaration_inputs(owner, facts)?;
        validate_project_lexical_inputs(owner, facts)?;
        validate_project_resource_inputs(owner, facts)?;
    }
    Ok(())
}

pub fn compile_project_program(
    input: &KernelProjectProgramInput,
) -> Result<KernelProjectProgram, KernelOwnerBuildError> {
    let facts = (0..input.owners.len())
        .map(|_| KernelDefinitionFactsInput::default())
        .collect::<Vec<_>>()
        .into_boxed_slice();
    compile_project_program_with_definition_facts(input, &facts)
}

pub fn compile_project_program_with_definition_facts(
    input: &KernelProjectProgramInput,
    facts: &[KernelDefinitionFactsInput],
) -> Result<KernelProjectProgram, KernelOwnerBuildError> {
    if facts.len() != input.owners.len() {
        return Err(KernelOwnerBuildError::new(format!(
            "kernel project has {} owners but {} definition-fact tables",
            input.owners.len(),
            facts.len()
        )));
    }
    let text = crate::text::compatibility_project_text_snapshot(
        &input.owners,
        facts,
        &crate::KernelAbiInput::default(),
    )?;
    compile_project_program_with_definition_facts_abi_and_text(
        Arc::new(input.clone()),
        Arc::from(facts.to_vec()),
        Arc::new(crate::KernelAbiInput::default()),
        text,
    )
}

pub(crate) fn compile_project_program_with_definition_facts_abi_and_text(
    input: Arc<KernelProjectProgramInput>,
    facts: Arc<[KernelDefinitionFactsInput]>,
    abi: Arc<crate::KernelAbiInput>,
    text: ProjectTextSnapshot,
) -> Result<KernelProjectProgram, KernelOwnerBuildError> {
    validate_compatibility_project_input(&input, &facts)?;
    let basis_fingerprints = Arc::from(project_definition_basis_fingerprints(&input, &facts)?);
    let mut terms = crate::TypeTermArena::with_text(text.clone());
    let mut input = Arc::try_unwrap(input).unwrap_or_else(|input| input.as_ref().clone());
    crate::pack_project_closed_type_roots(&mut input, &mut terms)?;
    let packed_input_term_count = terms.len();
    let input = Arc::new(crate::pack_kernel_project_program(input, &terms)?);
    let runtime_facts = crate::pack_definition_facts_store(&text, &facts)?;
    compile_project_program_with_definition_facts_abi_text_and_terms(
        input,
        facts,
        runtime_facts,
        abi,
        text,
        terms,
        packed_input_term_count,
        basis_fingerprints,
    )
}

/// Compile one project by consuming the exact mutable type authority prepared
/// for this revision.
///
/// Compatibility entry points above still create an empty arena from their
/// frozen text snapshot. Direct packed input instead interns its closed roots
/// before this call and moves the same arena here; there is no cloneable or
/// separately frozen prelude type store between input and solver.
pub(crate) fn compile_project_program_with_definition_facts_abi_text_and_terms(
    input: Arc<crate::PackedKernelProjectProgram>,
    facts: Arc<[KernelDefinitionFactsInput]>,
    runtime_facts: Arc<crate::PackedDefinitionFactsStore>,
    abi: Arc<crate::KernelAbiInput>,
    text: ProjectTextSnapshot,
    terms: crate::TypeTermArena,
    packed_input_term_count: usize,
    basis_fingerprints: Arc<[[u8; 32]]>,
) -> Result<KernelProjectProgram, KernelOwnerBuildError> {
    let program = Arc::clone(&input);
    let input = input.as_ref();
    if facts.len() != input.definition_count() {
        return Err(KernelOwnerBuildError::new(format!(
            "kernel project has {} owners but {} definition-fact tables",
            input.definition_count(),
            facts.len()
        )));
    }
    if runtime_facts.definition_count() != input.definition_count() {
        return Err(KernelOwnerBuildError::new(format!(
            "kernel project has {} owners but {} packed definition-fact tables",
            input.definition_count(),
            runtime_facts.definition_count(),
        )));
    }
    if basis_fingerprints.len() != input.definition_count() {
        return Err(KernelOwnerBuildError::new(format!(
            "kernel project has {} owners but {} definition-basis fingerprints",
            input.definition_count(),
            basis_fingerprints.len()
        )));
    }
    if packed_input_term_count > terms.len() {
        return Err(KernelOwnerBuildError::new(format!(
            "kernel packed-input term prefix {packed_input_term_count} exceeds the {}-term source arena",
            terms.len(),
        )));
    }
    let mut builder = ComponentProgramBuilder::with_terms(terms);
    let mut mode_builder = ModeProgramBuilder::default();
    let mut invocations = HashMap::new();
    let mut specializations = HashMap::new();
    let mut residual_modules = ResidualModuleCache::new(packed_input_term_count);
    let mut compile_work = KernelCompileWork {
        definition_modules: input.definition_count() as u64,
        principal_expressions: input.owners().map(|owner| owner.node_count() as u64).sum(),
        ..KernelCompileWork::default()
    };
    let formal_dependent_expressions = input
        .owners()
        .map(owner_expressions_depend_on_formals)
        .collect::<Vec<_>>();
    let formal_dependent_results = input
        .owners()
        .zip(&formal_dependent_expressions)
        .map(|(owner, dependencies)| {
            let result = owner.result().0 as usize;
            dependencies.get(result).copied().unwrap_or(true)
        })
        .collect::<Vec<_>>();
    let principals = input
        .owners()
        .map(|owner| {
            allocate_owner_instance(
                &mut builder,
                &mut mode_builder,
                &text,
                owner,
                &vec![None; owner.formal_count() as usize],
            )
        })
        .collect::<Vec<_>>();
    // A call authored inside a formal-derived WHEN arm owns an exact branch
    // occurrence even when the callee itself contains no SELECT. Seed that
    // provenance from the caller graph before compiling nested callees; the
    // call compiler below can additionally mark a result selected inside the
    // callee. Starting from all-false silently downgraded branch-local calls
    // to their generic callable scheme during semantic OUT expansion.
    let mut syntax_discriminated_call_candidates = input
        .owners()
        .enumerate()
        .map(|(owner_index, owner)| {
            syntax_selected_call_nodes(
                &text,
                owner,
                &principals[owner_index].static_variants,
                &formal_dependent_expressions[owner_index],
            )
            .into_vec()
        })
        .collect::<Vec<_>>();
    let mut syntax_discriminated_call_root_outputs = input
        .owners()
        .map(|owner| vec![None; owner.node_count()])
        .collect::<Vec<_>>();
    let syntax_discriminated_formals = project_syntax_discriminated_formals(input);
    let direct_summaries = compile_direct_result_summaries(&mut builder, input);
    for summary in direct_summaries.iter().flatten() {
        compile_work.summary_definition_nodes = compile_work
            .summary_definition_nodes
            .saturating_add(summary.program.nodes.len() as u64);
        compile_work.summary_constant_folded_nodes = compile_work
            .summary_constant_folded_nodes
            .saturating_add(summary.constant_folded_nodes);
        compile_work.summary_selector_fused_records = compile_work
            .summary_selector_fused_records
            .saturating_add(summary.selector_fused_records);
        compile_work.summary_deduplicated_nodes = compile_work
            .summary_deduplicated_nodes
            .saturating_add(summary.deduplicated_nodes);
        compile_work.summary_pruned_nodes = compile_work
            .summary_pruned_nodes
            .saturating_add(summary.pruned_nodes);
        compile_work.summary_pruned_inputs = compile_work
            .summary_pruned_inputs
            .saturating_add(summary.pruned_inputs);
        compile_work.summary_invoke_nodes = compile_work.summary_invoke_nodes.saturating_add(
            summary
                .program
                .nodes
                .iter()
                .filter(|node| matches!(node, KernelSummaryNode::Invoke { .. }))
                .count() as u64,
        );
    }
    for (owner_index, owner) in input.owners().enumerate() {
        let owner_id = KernelOwnerId(
            u32::try_from(owner_index).expect("kernel project owner count exceeds u32"),
        );
        let instance = &principals[owner_index];
        let context = OwnerCompileContext {
            initial_state_surface: false,
            text: &text,
            owner: owner_id,
            input: owner,
            expressions: &instance.expressions,
            formals: &instance.formals,
            formal_requirements: &instance.formal_requirements,
            expression_modes: &instance.expression_modes,
            formal_modes: &instance.formal_modes,
            formal_mode_sources: &instance.formal_mode_sources,
            static_variants: &instance.static_variants,
            formal_static_variants: &instance.formal_static_variants,
            project: Some(input),
            principals: &principals,
            formal_dependent_results: &formal_dependent_results,
            formal_dependent_expressions: &formal_dependent_expressions,
            external_variables: None,
            syntax_selected_calls: None,
            direct_summaries: &direct_summaries,
            packed_input_types: None,
        };
        let mut stack = vec![owner_id];
        let specialization = OwnerSpecialization {
            static_variants: instance.static_variants.clone(),
            reachable: (0..owner.node_count())
                .collect::<Vec<_>>()
                .into_boxed_slice(),
            result_syntax_selected: false,
            syntax_selected_calls: vec![false; owner.node_count()].into_boxed_slice(),
            invocation_dependencies: formal_dependent_expressions[owner_index].clone(),
            transparent_type_providers: vec![None; owner.node_count()].into_boxed_slice(),
        };
        let module = compile_residual_type_module(
            &text,
            Some(builder.terms()),
            &mut residual_modules.packed_type_imports,
            owner_id,
            owner,
            Some(input),
            &principals,
            &formal_dependent_results,
            &formal_dependent_expressions,
            &instance.formal_static_variants,
            &specialization,
            None,
            false,
        )?;
        compile_work.residual_type_modules = compile_work.residual_type_modules.saturating_add(1);
        compile_work.residual_module_operations = compile_work
            .residual_module_operations
            .saturating_add(module.component.operation_count() as u64);
        compile_work.residual_module_terms = compile_work
            .residual_module_terms
            .saturating_add(module.component.terms().len() as u64);
        let external_variables = principal_external_variables(owner, input, &principals)?;
        append_residual_type_frame(&mut builder, &module, instance, &external_variables)?;
        compile_work.residual_frames = compile_work.residual_frames.saturating_add(1);
        for (index, node) in owner.nodes().iter().enumerate() {
            if matches!(node.kind, PackedKernelOwnerNodeKind::UserCall { .. }) {
                compile_node(
                    &mut builder,
                    &mut mode_builder,
                    &mut invocations,
                    &mut specializations,
                    &mut residual_modules,
                    &mut compile_work,
                    &context,
                    &mut stack,
                    index,
                    node,
                    instance.expressions[index],
                    instance.expression_modes[index],
                    true,
                    Some(&mut syntax_discriminated_call_candidates[owner_index][index]),
                    Some(&mut syntax_discriminated_call_root_outputs[owner_index][index]),
                )?;
            } else {
                let equation = node_mode_equation(&mut mode_builder, &context, index, node)?;
                mode_builder.set(instance.expression_modes[index], equation);
            }
        }
    }
    let modes = mode_builder.solve();
    let owners = input
        .owners()
        .enumerate()
        .map(|(owner_index, owner)| {
            let result = checked_expression_index(
                owner.result(),
                owner.node_count(),
                &format!("project owner {owner_index} result"),
            )?;
            let expressions = principals[owner_index]
                .expressions
                .iter()
                .zip(owner.nodes().iter())
                .map(|(variable, node)| builder.add_output(*variable, node.mode))
                .collect::<Vec<_>>()
                .into_boxed_slice();
            Ok(KernelProjectOwnerOutputs {
                result: expressions[result],
                formals: principals[owner_index]
                    .formal_requirements
                    .iter()
                    .map(|variable| builder.add_output(*variable, FlowMode::Continuous))
                    .collect::<Vec<_>>()
                    .into_boxed_slice(),
                formal_modes: principals[owner_index]
                    .formal_modes
                    .iter()
                    .map(|mode| modes[mode.0 as usize])
                    .collect::<Vec<_>>()
                    .into_boxed_slice(),
                expressions,
                expression_modes: principals[owner_index]
                    .expression_modes
                    .iter()
                    .map(|mode| modes[mode.0 as usize])
                    .collect::<Vec<_>>()
                    .into_boxed_slice(),
                calls: collect_project_call_solve_rows(
                    owner,
                    &syntax_discriminated_call_candidates[owner_index],
                    &syntax_discriminated_call_root_outputs[owner_index],
                ),
                syntax_discriminated_formals: syntax_discriminated_formals[owner_index].clone(),
                basis_fingerprint_v14: basis_fingerprints[owner_index],
            })
        })
        .collect::<Result<Vec<_>, KernelOwnerBuildError>>()?;
    #[cfg(debug_assertions)]
    trace_invocation_inputs(&invocations, &modes);
    let component = builder.finish();
    let mut frame_counts = HashMap::<*const ComponentProgram, u64>::new();
    for frame in component.residual_frames.iter() {
        *frame_counts.entry(Arc::as_ptr(&frame.module)).or_default() += 1;
        if frame.module.acyclic_initial_operation_count() == frame.module.operation_count() as u64 {
            compile_work.acyclic_residual_frames =
                compile_work.acyclic_residual_frames.saturating_add(1);
        }
    }
    for (key, module) in &residual_modules.modules {
        let operations = module.component.operation_count() as u64;
        let frames = frame_counts
            .get(&Arc::as_ptr(&module.component))
            .copied()
            .unwrap_or_default();
        let linked = operations.saturating_mul(frames);
        let candidate = KernelResidualModuleWork {
            owner: key.target.0,
            operations: u32::try_from(operations)
                .expect("kernel residual module operation count exceeds u32"),
            frames: u32::try_from(frames).expect("kernel residual module frame count exceeds u32"),
            linked_operations: linked,
        };
        let dominant = KernelResidualModuleWork {
            owner: u32::try_from(compile_work.dominant_module_owner)
                .expect("kernel dominant module owner exceeds u32"),
            operations: u32::try_from(compile_work.dominant_module_operations)
                .expect("kernel dominant module operation count exceeds u32"),
            frames: u32::try_from(compile_work.dominant_module_frames)
                .expect("kernel dominant module frame count exceeds u32"),
            linked_operations: compile_work.dominant_module_linked_operations,
        };
        if residual_module_precedes(candidate, dominant) {
            compile_work.dominant_module_owner = u64::from(candidate.owner);
            compile_work.dominant_module_operations = u64::from(candidate.operations);
            compile_work.dominant_module_frames = u64::from(candidate.frames);
            compile_work.dominant_module_linked_operations = candidate.linked_operations;
        }
        if let Some(position) = compile_work
            .residual_module_ranking
            .iter()
            .position(|current| residual_module_precedes(candidate, *current))
        {
            for index in (position + 1..KERNEL_RESIDUAL_MODULE_RANKING_LEN).rev() {
                compile_work.residual_module_ranking[index] =
                    compile_work.residual_module_ranking[index - 1];
            }
            compile_work.residual_module_ranking[position] = candidate;
        }
    }
    compile_work.linked_operations = component.operation_count() as u64;
    compile_work.scheduled_work_items = component.scheduled_work_item_count() as u64;
    compile_work.linked_terms = component.terms().len() as u64;
    compile_work.acyclic_initial_operations = component.acyclic_initial_operation_count();
    Ok(KernelProjectProgram {
        component,
        program,
        owners: owners.into_boxed_slice(),
        definition_facts: facts,
        runtime_facts,
        abi,
        compile_work,
    })
}

#[derive(Clone, Debug)]
struct OwnerInstance {
    expressions: Vec<TypeVariableId>,
    formals: Vec<TypeVariableId>,
    formal_requirements: Vec<TypeVariableId>,
    expression_modes: Arc<[ModeVariableId]>,
    formal_modes: Vec<ModeVariableId>,
    formal_mode_sources: Arc<[ModeSource]>,
    static_variants: Vec<Option<StaticVariantSet>>,
    formal_static_variants: Vec<Option<StaticVariantSet>>,
}

/// One structural flow-mode authority.
///
/// Types already retain their record/list shape while crossing owner calls.
/// Flow modes need the same provenance: a continuous record may contain a
/// `PresentOrAbsent` SOURCE field, and projecting that field must not collapse
/// to the record's root mode. Expression sources retain the compact residual
/// frame needed to follow record fields, collection items, and call formals;
/// opaque roots are used only where no structural syntax exists.
#[derive(Clone, Debug)]
enum ModeSource {
    Root(ModeVariableId),
    Expression {
        owner: KernelOwnerId,
        expression: usize,
        expression_modes: Arc<[ModeVariableId]>,
        formal_sources: Arc<[ModeSource]>,
    },
}

impl ModeSource {
    fn root_mode(&self) -> ModeVariableId {
        match self {
            Self::Root(mode) => *mode,
            Self::Expression {
                expression,
                expression_modes,
                ..
            } => expression_modes[*expression],
        }
    }
}

/// Immutable compile-time tag set in the project's sole text namespace.
///
/// Invocation and specialization frames share these tiny sorted slabs instead
/// of recursively cloning `BTreeSet<Box<str>>` values. The dense symbol IDs
/// are process-local coordinates; stable receipts continue to resolve their
/// bytes through the owning [`ProjectTextSnapshot`].
type StaticVariantSet = Arc<[SymbolId]>;

fn static_variant_set(symbols: impl IntoIterator<Item = SymbolId>) -> StaticVariantSet {
    let mut symbols = symbols.into_iter().collect::<Vec<_>>();
    symbols.sort_unstable_by_key(|symbol| symbol.as_u32());
    symbols.dedup();
    Arc::from(symbols)
}

fn static_variant_symbol(text: &ProjectTextSnapshot, name: &str) -> SymbolId {
    text.lookup_symbol(name)
        .unwrap_or_else(|| panic!("kernel static variant `{name}` is absent from text authority"))
}

#[derive(Clone, Debug)]
struct CallActual {
    /// Provider surface used to evaluate the callee occurrence.
    variable: TypeVariableId,
    /// Caller-owned surface that accepts definition-local requirements.
    ///
    /// Explicit arguments use the expression occurrence for both roles. An
    /// inherited formal deliberately separates them: its provider is the
    /// caller formal, while requirements must land on the caller's private
    /// formal-requirement surface. Keeping these channels distinct prevents
    /// inherited PASSED calls from silently detaching transitive constraints.
    requirement: TypeVariableId,
    /// Whether this occurrence reads a private output capability and therefore
    /// has a separate caller-owned requirement channel. The provider remains
    /// directional and unchanged; only `requirement` accepts constraints from
    /// the callee definition.
    requirement_backflow: bool,
    mode: ModeVariableId,
    mode_source: ModeSource,
    static_variants: Option<StaticVariantSet>,
}

#[derive(Clone, Debug, Eq, Hash, PartialEq)]
struct InvocationKey {
    target: KernelOwnerId,
    actuals: Box<[(TypeVariableId, ModeVariableId)]>,
    static_variants: Box<[Option<StaticVariantSet>]>,
    initial_state_surface: bool,
}

/// Opt-in K0 attribution only. Debug observers are absent from release
/// producers and must never be scored as performance evidence.
#[cfg(debug_assertions)]
fn trace_invocation_inputs(invocations: &HashMap<InvocationKey, OwnerInstance>, modes: &[FlowMode]) {
    let owners = traced_summary_owners();
    if owners.is_empty() {
        return;
    }
    let mut keys = invocations
        .keys()
        .filter(|key| owners.contains(&key.target.0))
        .collect::<Vec<_>>();
    keys.sort_by(|left, right| {
        left.target.cmp(&right.target)
            .then(left.actuals.cmp(&right.actuals))
            .then(left.initial_state_surface.cmp(&right.initial_state_surface))
            .then_with(|| format!("{:?}", left.static_variants).cmp(&format!("{:?}", right.static_variants)))
    });
    let mut variables = BTreeSet::new();
    for key in keys {
        let flows = key.actuals.iter()
            .map(|(variable, mode)| {
                variables.insert(variable.0);
                (*variable, *mode, modes[mode.0 as usize])
            })
            .collect::<Vec<_>>();
        eprintln!("kernel-invocation-input owner={} actuals={flows:?} variants={:?} initial_state_surface={}", key.target.0, key.static_variants, key.initial_state_surface);
    }
    eprintln!("kernel-trace-variables={}", variables.iter().map(u32::to_string).collect::<Vec<_>>().join(","));
}

#[cfg(debug_assertions)]
fn traced_summary_owners() -> BTreeSet<u32> {
    std::env::var("BOON_KERNEL_TRACE_OWNERS")
        .unwrap_or_default()
        .split(',')
        .filter_map(|value| value.parse().ok())
        .collect()
}

#[derive(Clone, Debug, Eq, Hash, PartialEq)]
struct SpecializationKey {
    target: KernelOwnerId,
    static_variants: Box<[Option<StaticVariantSet>]>,
    initial_state_surface: bool,
}

#[derive(Clone, Debug, Eq, Hash, PartialEq)]
struct OwnerSpecialization {
    static_variants: Vec<Option<StaticVariantSet>>,
    reachable: Box<[usize]>,
    result_syntax_selected: bool,
    syntax_selected_calls: Box<[bool]>,
    invocation_dependencies: Box<[bool]>,
    transparent_type_providers: Box<[Option<usize>]>,
}

#[derive(Debug)]
struct ResidualTypeModule {
    component: Arc<ComponentProgram>,
    local: OwnerInstance,
    external_variables: Box<[TypeVariableId]>,
    calls: Box<[usize]>,
}

#[derive(Debug, Default)]
struct ResidualModuleCache {
    modules: HashMap<SpecializationKey, Arc<ResidualTypeModule>>,
    packed_type_imports: TypeTermImportScratch,
}

impl ResidualModuleCache {
    fn new(packed_input_term_count: usize) -> Self {
        Self {
            modules: HashMap::new(),
            packed_type_imports: TypeTermImportScratch::with_source_limit(packed_input_term_count),
        }
    }
}

#[derive(Clone, Copy, Debug, Eq, Hash, Ord, PartialEq, PartialOrd)]
struct ModeVariableId(u32);

#[derive(Clone, Debug)]
enum ModeEquation {
    Fixed(FlowMode),
    Copy(ModeVariableId),
    Eventful(ModeVariableId),
    Latest(Box<[ModeVariableId]>),
    Call {
        result: FlowMode,
        inputs: Box<[ModeVariableId]>,
    },
}

#[derive(Clone, Debug)]
struct ModeVariable {
    fallback: FlowMode,
    equation: Option<ModeEquation>,
}

#[derive(Default)]
struct ModeProgramBuilder {
    variables: Vec<ModeVariable>,
}

impl ModeProgramBuilder {
    fn new_variable(&mut self, fallback: FlowMode) -> ModeVariableId {
        let id = ModeVariableId(
            u32::try_from(self.variables.len()).expect("kernel mode variable count exceeds u32"),
        );
        self.variables.push(ModeVariable {
            fallback,
            equation: None,
        });
        id
    }

    fn set(&mut self, output: ModeVariableId, equation: ModeEquation) {
        let slot = &mut self.variables[output.0 as usize].equation;
        assert!(slot.is_none(), "kernel mode variable has multiple writers");
        *slot = Some(equation);
    }

    fn solve(self) -> Box<[FlowMode]> {
        let mut reverse = vec![Vec::<usize>::new(); self.variables.len()];
        for (output, variable) in self.variables.iter().enumerate() {
            let inputs: &[ModeVariableId] = match variable.equation.as_ref() {
                Some(ModeEquation::Copy(input)) => std::slice::from_ref(input),
                Some(ModeEquation::Eventful(input)) => std::slice::from_ref(input),
                Some(ModeEquation::Latest(inputs)) => inputs,
                Some(ModeEquation::Call { inputs, .. }) => inputs,
                Some(ModeEquation::Fixed(_)) | None => &[],
            };
            for input in inputs {
                reverse[input.0 as usize].push(output);
            }
        }
        let mut modes = vec![None; self.variables.len()];
        let mut pending = (0..self.variables.len()).collect::<std::collections::VecDeque<_>>();
        let mut queued = vec![true; self.variables.len()];
        while let Some(output) = pending.pop_front() {
            queued[output] = false;
            let next = match self.variables[output].equation.as_ref() {
                Some(ModeEquation::Fixed(mode)) => Some(*mode),
                Some(ModeEquation::Copy(input)) => modes[input.0 as usize],
                Some(ModeEquation::Eventful(input)) => modes[input.0 as usize].filter(|mode| {
                    matches!(mode, FlowMode::TickPresent | FlowMode::PresentOrAbsent)
                }),
                Some(ModeEquation::Latest(inputs)) => {
                    latest_mode(inputs.iter().filter_map(|input| modes[input.0 as usize]))
                }
                Some(ModeEquation::Call { result, inputs }) => inputs
                    .iter()
                    .filter_map(|input| modes[input.0 as usize])
                    .fold(Some(*result), merge_call_mode),
                None => None,
            };
            if modes[output] == next {
                continue;
            }
            modes[output] = next;
            for consumer in &reverse[output] {
                if !queued[*consumer] {
                    queued[*consumer] = true;
                    pending.push_back(*consumer);
                }
            }
        }
        self.variables
            .into_iter()
            .enumerate()
            .map(|(index, variable)| modes[index].unwrap_or(variable.fallback))
            .collect::<Vec<_>>()
            .into_boxed_slice()
    }
}

fn latest_mode(modes: impl IntoIterator<Item = FlowMode>) -> Option<FlowMode> {
    let mut saw_mode = false;
    let mut saw_continuous = false;
    let mut saw_present = false;
    for mode in modes {
        saw_mode = true;
        match mode {
            FlowMode::Continuous => saw_continuous = true,
            FlowMode::TickPresent | FlowMode::PresentOrAbsent => saw_present = true,
            FlowMode::Absent => {}
        }
    }
    saw_mode.then_some(if saw_continuous {
        FlowMode::Continuous
    } else if saw_present {
        FlowMode::PresentOrAbsent
    } else {
        FlowMode::Absent
    })
}

fn merge_call_mode(left: Option<FlowMode>, right: FlowMode) -> Option<FlowMode> {
    match (left, right) {
        (None, mode) => Some(mode),
        (Some(FlowMode::Absent), _) | (_, FlowMode::Absent) => Some(FlowMode::Absent),
        (Some(FlowMode::PresentOrAbsent), _) | (_, FlowMode::PresentOrAbsent) => {
            Some(FlowMode::PresentOrAbsent)
        }
        (Some(FlowMode::TickPresent), _) | (_, FlowMode::TickPresent) => {
            Some(FlowMode::TickPresent)
        }
        (Some(FlowMode::Continuous), FlowMode::Continuous) => Some(FlowMode::Continuous),
    }
}

fn allocate_owner_instance(
    builder: &mut ComponentProgramBuilder,
    mode_builder: &mut ModeProgramBuilder,
    text: &ProjectTextSnapshot,
    owner: PackedKernelOwnerProgramRef<'_>,
    formal_static_variants: &[Option<StaticVariantSet>],
) -> OwnerInstance {
    let static_variants =
        infer_static_variants(text, builder.terms(), owner, formal_static_variants);
    allocate_owner_instance_with_static_variants(
        builder,
        mode_builder,
        owner,
        formal_static_variants,
        static_variants,
        None,
    )
}

fn allocate_owner_instance_with_static_variants(
    builder: &mut ComponentProgramBuilder,
    mode_builder: &mut ModeProgramBuilder,
    owner: PackedKernelOwnerProgramRef<'_>,
    formal_static_variants: &[Option<StaticVariantSet>],
    static_variants: Vec<Option<StaticVariantSet>>,
    transparent_type_providers: Option<&[Option<usize>]>,
) -> OwnerInstance {
    let mut expressions = Vec::with_capacity(owner.node_count());
    for (index, node) in owner.nodes().iter().enumerate() {
        if let Some(provider) = transparent_type_providers.and_then(|providers| providers[index]) {
            expressions.push(
                *expressions
                    .get(provider)
                    .expect("transparent type provider precedes its match arm"),
            );
        } else if matches!(
            node.kind,
            PackedKernelOwnerNodeKind::FormalRead { .. }
                | PackedKernelOwnerNodeKind::ContextRead { .. }
                | PackedKernelOwnerNodeKind::LexicalRead { .. }
                | PackedKernelOwnerNodeKind::PatternRead { .. }
        ) {
            expressions.push(builder.new_variable());
        } else {
            expressions.push(builder.new_authoritative_provider());
        }
    }
    assert_eq!(formal_static_variants.len(), owner.formal_count() as usize);
    let expression_modes = owner
        .nodes()
        .iter()
        .map(|node| mode_builder.new_variable(node.mode))
        .collect::<Vec<_>>()
        .into();
    let formal_modes = (0..owner.formal_count())
        .map(|_| mode_builder.new_variable(FlowMode::Continuous))
        .collect::<Vec<_>>();
    let formal_mode_sources = formal_modes
        .iter()
        .copied()
        .map(ModeSource::Root)
        .collect::<Vec<_>>()
        .into();
    OwnerInstance {
        expressions,
        formals: (0..owner.formal_count())
            .map(|_| builder.new_contextual_hole())
            .collect(),
        formal_requirements: (0..owner.formal_count())
            .map(|_| builder.new_contextual_hole())
            .collect(),
        expression_modes,
        formal_modes,
        formal_mode_sources,
        static_variants,
        formal_static_variants: formal_static_variants.to_vec(),
    }
}

fn allocate_invocation_owner_instance(
    builder: &mut ComponentProgramBuilder,
    mode_builder: &mut ModeProgramBuilder,
    owner: PackedKernelOwnerProgramRef<'_>,
    principal: &OwnerInstance,
    actuals: &[CallActual],
    formal_static_variants: &[Option<StaticVariantSet>],
    static_variants: Vec<Option<StaticVariantSet>>,
    expression_dependencies: &[bool],
    reachable: &[usize],
    transparent_type_providers: &[Option<usize>],
) -> (OwnerInstance, u64) {
    assert_eq!(actuals.len(), owner.formal_count() as usize);
    assert_eq!(expression_dependencies.len(), owner.node_count());
    let mut reachable_expressions = vec![false; owner.node_count()];
    for index in reachable {
        reachable_expressions[*index] = true;
    }
    let pruned_expressions = reachable_expressions
        .iter()
        .zip(expression_dependencies)
        .filter(|(reachable, dependent)| !**reachable && **dependent)
        .count() as u64;
    let mut expressions = Vec::with_capacity(owner.node_count());
    for (index, node) in owner.nodes().iter().enumerate() {
        if !expression_dependencies[index] || !reachable_expressions[index] {
            expressions.push(principal.expressions[index]);
        } else if let Some(provider) = transparent_type_providers[index] {
            expressions.push(
                *expressions
                    .get(provider)
                    .expect("transparent type provider precedes its match arm"),
            );
        } else if matches!(
            node.kind,
            PackedKernelOwnerNodeKind::FormalRead { .. }
                | PackedKernelOwnerNodeKind::ContextRead { .. }
                | PackedKernelOwnerNodeKind::LexicalRead { .. }
                | PackedKernelOwnerNodeKind::PatternRead { .. }
        ) {
            expressions.push(builder.new_variable());
        } else {
            expressions.push(builder.new_authoritative_provider());
        }
    }
    let expression_modes = owner
        .nodes()
        .iter()
        .enumerate()
        .map(|(index, node)| {
            if expression_dependencies[index] && reachable_expressions[index] {
                mode_builder.new_variable(node.mode)
            } else {
                principal.expression_modes[index]
            }
        })
        .collect::<Vec<_>>()
        .into();
    (
        OwnerInstance {
            expressions,
            formals: actuals.iter().map(|actual| actual.variable).collect(),
            formal_requirements: (0..owner.formal_count())
                .map(|_| builder.new_contextual_hole())
                .collect(),
            expression_modes,
            formal_modes: actuals.iter().map(|actual| actual.mode).collect(),
            formal_mode_sources: actuals
                .iter()
                .map(|actual| actual.mode_source.clone())
                .collect::<Vec<_>>()
                .into(),
            static_variants,
            formal_static_variants: formal_static_variants.to_vec(),
        },
        pruned_expressions,
    )
}

#[derive(Clone, Copy)]
struct PackedInputTypeProjection<'a> {
    imports: &'a TypeTermImportSession<'a>,
}

struct OwnerCompileContext<'a> {
    initial_state_surface: bool,
    text: &'a ProjectTextSnapshot,
    owner: KernelOwnerId,
    input: PackedKernelOwnerProgramRef<'a>,
    expressions: &'a [TypeVariableId],
    formals: &'a [TypeVariableId],
    formal_requirements: &'a [TypeVariableId],
    expression_modes: &'a Arc<[ModeVariableId]>,
    formal_modes: &'a [ModeVariableId],
    formal_mode_sources: &'a Arc<[ModeSource]>,
    static_variants: &'a [Option<StaticVariantSet>],
    formal_static_variants: &'a [Option<StaticVariantSet>],
    project: Option<&'a PackedKernelProjectProgram>,
    principals: &'a [OwnerInstance],
    formal_dependent_results: &'a [bool],
    formal_dependent_expressions: &'a [Box<[bool]>],
    external_variables: Option<&'a [TypeVariableId]>,
    syntax_selected_calls: Option<&'a [bool]>,
    direct_summaries: &'a [Option<Arc<CompiledDirectSummary>>],
    /// Closed project-input roots relocated once into a separately owned
    /// residual module. Principal compilation uses the original authority and
    /// therefore leaves this empty. The scoped import session prevents another
    /// module from advancing the reusable table while these IDs are live.
    packed_input_types: Option<PackedInputTypeProjection<'a>>,
}

fn edge_static_variants(
    context: &OwnerCompileContext<'_>,
    edge: &crate::PackedKernelOwnerInputEdge,
) -> Option<StaticVariantSet> {
    let expression = edge.expression.0 as usize;
    if expression < context.input.node_count() {
        return context.static_variants[expression].clone();
    }
    let external = context
        .input
        .external_expressions()
        .get(expression.checked_sub(context.input.node_count())?)?;
    let owner = context.principals.get(external.owner.0 as usize)?;
    let expression = match external.target {
        KernelExternalTarget::Expression(expression) => expression.0 as usize,
        KernelExternalTarget::Result => context.project?.owner(external.owner)?.result().0 as usize,
    };
    owner.static_variants.get(expression)?.clone()
}

fn infer_static_variants(
    text: &ProjectTextSnapshot,
    terms: &crate::TypeTermArena,
    owner: PackedKernelOwnerProgramRef<'_>,
    formal_static_variants: &[Option<StaticVariantSet>],
) -> Vec<Option<StaticVariantSet>> {
    let mut variants = vec![None; owner.node_count()];
    for (index, node) in owner.nodes().iter().enumerate() {
        variants[index] = match &node.kind {
            PackedKernelOwnerNodeKind::Known(reference)
            | PackedKernelOwnerNodeKind::Source(reference) => terms
                .resolve_type_ref(*reference)
                .and_then(|term| match terms.term(term) {
                    TypeTerm::VariantSet(values) => {
                        Some(static_variant_set(values.iter().map(VariantTerm::tag)))
                    }
                    _ => None,
                }),
            PackedKernelOwnerNodeKind::Tag(tag) => Some(static_variant_set([*tag])),
            PackedKernelOwnerNodeKind::Record { tag: Some(tag) } => {
                Some(static_variant_set([*tag]))
            }
            PackedKernelOwnerNodeKind::FormalRead { formal, fields }
            | PackedKernelOwnerNodeKind::ContextRead { formal, fields }
                if *fields == boon_contract::PathId::ROOT =>
            {
                formal_static_variants
                    .get(*formal as usize)
                    .cloned()
                    .flatten()
            }
            PackedKernelOwnerNodeKind::Infix { operation }
                if text.symbol(*operation).is_some_and(infix_returns_bool) =>
            {
                Some(static_variant_set([
                    static_variant_symbol(text, "False"),
                    static_variant_symbol(text, "True"),
                ]))
            }
            PackedKernelOwnerNodeKind::PureBuiltin {
                kind:
                    KernelPureBuiltinKind::TextPredicate
                    | KernelPureBuiltinKind::ListPredicate
                    | KernelPureBuiltinKind::Boolean
                    | KernelPureBuiltinKind::BoolToggle,
            } => Some(static_variant_set([
                static_variant_symbol(text, "False"),
                static_variant_symbol(text, "True"),
            ])),
            PackedKernelOwnerNodeKind::PureBuiltin {
                kind: KernelPureBuiltinKind::StreamPulses,
            } => Some(static_variant_set([static_variant_symbol(text, "Pulse")])),
            _ => None,
        };
    }
    for _ in 0..=owner.node_count() {
        let mut changed = false;
        for (index, node) in owner.nodes().iter().enumerate() {
            let next = match &node.kind {
                PackedKernelOwnerNodeKind::Block => {
                    merge_static_edge_variants(owner, node, &variants, |role| {
                        matches!(role, PackedKernelOwnerEdgeRole::BlockResult)
                    })
                }
                PackedKernelOwnerNodeKind::LexicalRead { fields }
                | PackedKernelOwnerNodeKind::ValueRead { fields, .. }
                | PackedKernelOwnerNodeKind::DerivedRead { fields }
                    if *fields == boon_contract::PathId::ROOT =>
                {
                    merge_static_edge_variants(owner, node, &variants, |role| {
                        matches!(role, PackedKernelOwnerEdgeRole::ReadProvider)
                    })
                }
                PackedKernelOwnerNodeKind::Latest => {
                    merge_static_edge_variants(owner, node, &variants, |role| {
                        matches!(role, PackedKernelOwnerEdgeRole::LatestBranch)
                    })
                }
                PackedKernelOwnerNodeKind::When => {
                    let arms = possible_when_arm_expressions(text, owner, index, &variants);
                    merge_static_expression_variants(&arms, &variants)
                }
                PackedKernelOwnerNodeKind::Then => {
                    let has_output = node
                        .inputs(owner)
                        .iter()
                        .any(|edge| matches!(edge.role, PackedKernelOwnerEdgeRole::ThenOutput));
                    merge_static_edge_variants(owner, node, &variants, |role| {
                        matches!(role, PackedKernelOwnerEdgeRole::ThenOutput)
                            || (!has_output && matches!(role, PackedKernelOwnerEdgeRole::ThenInput))
                    })
                }
                PackedKernelOwnerNodeKind::Draining => {
                    merge_static_edge_variants(owner, node, &variants, |role| {
                        matches!(role, PackedKernelOwnerEdgeRole::DrainingInput)
                    })
                }
                PackedKernelOwnerNodeKind::MatchArm { .. } => {
                    merge_static_edge_variants(owner, node, &variants, |role| {
                        matches!(role, PackedKernelOwnerEdgeRole::MatchOutput)
                    })
                }
                PackedKernelOwnerNodeKind::Arrow => {
                    merge_static_edge_variants(owner, node, &variants, |role| {
                        matches!(role, PackedKernelOwnerEdgeRole::ArrowOutput)
                    })
                }
                _ => variants[index].clone(),
            };
            if variants[index] != next {
                variants[index] = next;
                changed = true;
            }
        }
        if !changed {
            break;
        }
    }
    variants
}

fn type_has_concrete_outer_shape(ty: &Type) -> bool {
    match ty {
        Type::Object(_) => true,
        Type::VariantSet(variants) => !variants.is_empty(),
        Type::Union(members) => !members.is_empty(),
        Type::Unknown | Type::UnresolvedShape { .. } | Type::Var(_) => false,
        Type::Text
        | Type::Number
        | Type::Bytes(_)
        | Type::Bits { .. }
        | Type::Absent
        | Type::List(_)
        | Type::Map { .. }
        | Type::Set(_)
        | Type::Function { .. }
        | Type::RenderContract => true,
    }
}

fn packed_term_has_concrete_outer_shape(terms: &crate::TypeTermArena, term: TypeTermId) -> bool {
    match terms.term_head(term) {
        TypeTermHead::VariantSet(variants) | TypeTermHead::Union(variants) => variants.len() != 0,
        TypeTermHead::OpenObjectPlaceholder
        | TypeTermHead::UnresolvedShape(_)
        | TypeTermHead::Variable(_)
        | TypeTermHead::Unknown => false,
        TypeTermHead::Text
        | TypeTermHead::Number
        | TypeTermHead::Bytes(_)
        | TypeTermHead::Absent
        | TypeTermHead::Object { .. }
        | TypeTermHead::RenderContract
        | TypeTermHead::List(_)
        | TypeTermHead::Function { .. }
        | TypeTermHead::Map { .. }
        | TypeTermHead::Set(_)
        | TypeTermHead::Bits(_) => true,
    }
}

fn merge_static_edge_variants(
    owner: PackedKernelOwnerProgramRef<'_>,
    node: &PackedKernelOwnerNode,
    variants: &[Option<StaticVariantSet>],
    selected: impl Fn(&PackedKernelOwnerEdgeRole) -> bool,
) -> Option<StaticVariantSet> {
    let expressions = node
        .inputs(owner)
        .iter()
        .filter(|edge| selected(&edge.role))
        .map(|edge| edge.expression.0 as usize)
        .collect::<Vec<_>>();
    if expressions
        .iter()
        .any(|expression| *expression >= owner.node_count())
    {
        return None;
    }
    merge_static_expression_variants(&expressions, variants)
}

fn merge_static_expression_variants(
    expressions: &[usize],
    variants: &[Option<StaticVariantSet>],
) -> Option<StaticVariantSet> {
    if expressions.is_empty() {
        return None;
    }
    let mut merged = Vec::new();
    for expression in expressions {
        merged.extend(variants.get(*expression)?.as_ref()?.iter().copied());
    }
    Some(static_variant_set(merged))
}

fn possible_when_arm_expressions(
    _text: &ProjectTextSnapshot,
    owner: PackedKernelOwnerProgramRef<'_>,
    when: usize,
    variants: &[Option<StaticVariantSet>],
) -> Vec<usize> {
    let node = &owner.nodes()[when];
    let arms = node
        .inputs(owner)
        .iter()
        .filter(|edge| matches!(edge.role, PackedKernelOwnerEdgeRole::WhenArm))
        .map(|edge| edge.expression.0 as usize)
        .filter(|arm| *arm < owner.node_count())
        .collect::<Vec<_>>();
    let selector = node
        .inputs(owner)
        .iter()
        .find(|edge| matches!(edge.role, PackedKernelOwnerEdgeRole::WhenInput))
        .map(|edge| edge.expression.0 as usize)
        .filter(|selector| *selector < owner.node_count())
        .and_then(|selector| variants.get(selector))
        .and_then(Option::as_ref);
    let Some(selector) = selector else {
        return arms;
    };
    let mut selected = BTreeSet::new();
    for tag in selector.iter().copied() {
        if let Some(arm) = arms.iter().copied().find(|arm| {
            matches!(
                &owner.nodes()[*arm].kind,
                PackedKernelOwnerNodeKind::MatchArm { pattern }
                    if static_pattern_accepts_tag(pattern, tag)
            )
        }) {
            selected.insert(arm);
        }
    }
    selected.into_iter().collect()
}

fn static_pattern_accepts_tag(pattern: &crate::PackedKernelPattern, tag: SymbolId) -> bool {
    match pattern {
        crate::PackedKernelPattern::Wildcard | crate::PackedKernelPattern::Binding { .. } => true,
        crate::PackedKernelPattern::Tag { name, .. } => *name == tag,
        crate::PackedKernelPattern::Number
        | crate::PackedKernelPattern::Text
        | crate::PackedKernelPattern::Bits { .. }
        | crate::PackedKernelPattern::Invalid => false,
    }
}

fn reachable_owner_nodes(
    text: &ProjectTextSnapshot,
    owner: PackedKernelOwnerProgramRef<'_>,
    result: usize,
    variants: &[Option<StaticVariantSet>],
) -> BTreeSet<usize> {
    let mut reachable = BTreeSet::new();
    let mut pending = vec![result];
    while let Some(index) = pending.pop() {
        if !reachable.insert(index) {
            continue;
        }
        let node = &owner.nodes()[index];
        if matches!(node.kind, PackedKernelOwnerNodeKind::When) {
            pending.extend(
                node.inputs(owner)
                    .iter()
                    .filter(|edge| matches!(edge.role, PackedKernelOwnerEdgeRole::WhenInput))
                    .map(|edge| edge.expression.0 as usize)
                    .filter(|input| *input < owner.node_count()),
            );
            pending.extend(possible_when_arm_expressions(text, owner, index, variants));
        } else {
            pending.extend(
                node.inputs(owner)
                    .iter()
                    .map(|edge| edge.expression.0 as usize)
                    .filter(|input| *input < owner.node_count()),
            );
        }
    }
    reachable
}

/// Mark calls whose result is constructed under a formal-derived `WHEN` arm.
///
/// This is occurrence provenance, not ordinary reachability. A definition
/// retains every state update in its public result. An invocation evaluates a
/// branch as a construction site, so stateful callees below that constructor
/// expose their initializer surface; the separately owned state artifact keeps
/// the complete update domain. This does not require a parallel static-type
/// evaluator merely to rediscover a tag nested inside another call's record.
fn syntax_selected_call_nodes(
    text: &ProjectTextSnapshot,
    owner: PackedKernelOwnerProgramRef<'_>,
    variants: &[Option<StaticVariantSet>],
    formal_dependencies: &[bool],
) -> Box<[bool]> {
    let mut selected_calls = vec![false; owner.node_count()];
    for (when, node) in owner.nodes().iter().enumerate() {
        if !matches!(node.kind, PackedKernelOwnerNodeKind::When) {
            continue;
        }
        let Some(selector) = node
            .inputs(owner)
            .iter()
            .find(|edge| matches!(edge.role, PackedKernelOwnerEdgeRole::WhenInput))
            .map(|edge| edge.expression.0 as usize)
            .filter(|selector| *selector < owner.node_count())
        else {
            continue;
        };
        if !formal_dependencies.get(selector).copied().unwrap_or(false) {
            continue;
        }
        let arms = possible_when_arm_expressions(text, owner, when, variants);
        for arm in arms {
            for expression in reachable_owner_nodes(text, owner, arm, variants) {
                if matches!(
                    owner.nodes()[expression].kind,
                    PackedKernelOwnerNodeKind::UserCall { .. }
                ) {
                    selected_calls[expression] = true;
                }
            }
        }
    }
    selected_calls.into_boxed_slice()
}

fn invocation_expression_dependencies(
    owner: PackedKernelOwnerProgramRef<'_>,
    formal_dependencies: &[bool],
    syntax_selected_calls: &[bool],
) -> Box<[bool]> {
    let mut dependent = formal_dependencies
        .iter()
        .zip(syntax_selected_calls)
        .map(|(formal, selected)| *formal || *selected)
        .collect::<Vec<_>>();
    loop {
        let mut changed = false;
        for (index, node) in owner.nodes().iter().enumerate() {
            if dependent[index] {
                continue;
            }
            if node.inputs(owner).iter().any(|edge| {
                dependent
                    .get(edge.expression.0 as usize)
                    .copied()
                    .unwrap_or(false)
            }) {
                dependent[index] = true;
                changed = true;
            }
        }
        if !changed {
            return dependent.into_boxed_slice();
        }
    }
}

/// Type-only aliases that need no invocation-local publication.
///
/// Principal frames still materialize every authored expression for checked
/// artifacts. Specialized invocation frames may point a transparent match arm
/// directly at its sole output, because the enclosing SELECT owns detachment
/// and publication. Field-backed delimiter arms remain real record producers.
fn transparent_type_providers(owner: PackedKernelOwnerProgramRef<'_>) -> Box<[Option<usize>]> {
    let mut has_use = vec![false; owner.node_count()];
    let mut select_only = vec![true; owner.node_count()];
    for node in owner.nodes() {
        for edge in node.inputs(owner) {
            let expression = edge.expression.0 as usize;
            if expression >= owner.node_count() {
                continue;
            }
            has_use[expression] = true;
            select_only[expression] &= matches!(edge.role, PackedKernelOwnerEdgeRole::WhenArm);
        }
    }
    owner
        .nodes()
        .iter()
        .enumerate()
        .map(|(expression, node)| {
            let PackedKernelOwnerNodeKind::MatchArm { .. } = node.kind else {
                return None;
            };
            let mut outputs = node
                .inputs(owner)
                .iter()
                .filter(|edge| matches!(edge.role, PackedKernelOwnerEdgeRole::MatchOutput));
            let output = outputs.next()?;
            let provider = output.expression.0 as usize;
            (outputs.next().is_none()
                && node.inputs(owner).len() == 1
                && provider < expression
                && has_use[expression]
                && select_only[expression]
                && owner.result().0 as usize != expression)
                .then_some(provider)
        })
        .collect::<Vec<_>>()
        .into_boxed_slice()
}

/// Return whether each expression requires an invocation-local cell.
///
/// This intentionally walks the unspecialized local graph rather than the
/// statically sliced occurrence graph. In addition to formal-dependent values,
/// every HOLD is occurrence-owned even when its initializer and updates are
/// syntactically formal-independent. A principal result may be reused only
/// when every invocation computes the same non-stateful value and imposes no
/// formal requirement. User-call inherited formals are implicit inputs, so
/// they are treated as dependencies even though they do not have an ordinary
/// edge.
fn owner_expressions_depend_on_formals(owner: PackedKernelOwnerProgramRef<'_>) -> Box<[bool]> {
    let mut dependent = owner
        .nodes()
        .iter()
        .map(|node| {
            matches!(
                node.kind,
                PackedKernelOwnerNodeKind::FormalRead { .. }
                    | PackedKernelOwnerNodeKind::ContextRead { .. }
                    | PackedKernelOwnerNodeKind::FreshOut
                    | PackedKernelOwnerNodeKind::Hold
                    | PackedKernelOwnerNodeKind::UserCall {
                        inherited_formal: Some(_),
                        ..
                    }
            )
        })
        .collect::<Vec<_>>();
    loop {
        let mut changed = false;
        for (index, node) in owner.nodes().iter().enumerate() {
            if dependent[index] {
                continue;
            }
            if node.inputs(owner).iter().any(|edge| {
                dependent
                    .get(edge.expression.0 as usize)
                    .copied()
                    .unwrap_or(false)
            }) {
                dependent[index] = true;
                changed = true;
            }
        }
        if !changed {
            return dependent.into_boxed_slice();
        }
    }
}

fn import_residual_packed_input_types<'a>(
    builder: &mut ComponentProgramBuilder,
    source: &'a crate::TypeTermArena,
    owner: PackedKernelOwnerProgramRef<'_>,
    specialization: &OwnerSpecialization,
    invocation_dependencies: Option<&[bool]>,
    transparent_type_providers: Option<&[Option<usize>]>,
    term_cache: &'a mut TypeTermImportScratch,
) -> Result<Option<TypeTermImportSession<'a>>, KernelOwnerBuildError> {
    let packed_reference = |index: usize| {
        if invocation_dependencies.is_some_and(|dependencies| !dependencies[index])
            || transparent_type_providers.is_some_and(|providers| providers[index].is_some())
        {
            return None;
        }
        owner.nodes().get(index).and_then(|node| match node.kind {
            PackedKernelOwnerNodeKind::Known(reference)
            | PackedKernelOwnerNodeKind::Source(reference)
            | PackedKernelOwnerNodeKind::FixedAbiCall { result: reference } => Some(reference),
            _ => None,
        })
    };
    if !specialization
        .reachable
        .iter()
        .copied()
        .any(|index| packed_reference(index).is_some())
    {
        return Ok(None);
    }

    let mut session = term_cache.begin(source, builder.terms());
    for reference in specialization
        .reachable
        .iter()
        .copied()
        .filter_map(packed_reference)
    {
        let term = source.resolve_type_ref(reference).ok_or_else(|| {
            KernelOwnerBuildError::new(
                "residual module closed type belongs to another project authority",
            )
        })?;
        if source.has_variable(term) {
            return Err(KernelOwnerBuildError::new(
                "residual module project-input type unexpectedly contains solver variables",
            ));
        }
        if session.imported_ref(builder.terms(), reference).is_none() {
            builder.terms_mut().import_mapped_term_reusing(
                source,
                term,
                &mut |_| unreachable!("closed project-input type has no variable"),
                &mut session,
                false,
            );
        }
    }
    Ok(Some(session))
}

fn compile_residual_type_module(
    text: &ProjectTextSnapshot,
    packed_input_source: Option<&crate::TypeTermArena>,
    packed_input_imports: &mut TypeTermImportScratch,
    owner_id: KernelOwnerId,
    owner: PackedKernelOwnerProgramRef<'_>,
    project: Option<&PackedKernelProjectProgram>,
    principals: &[OwnerInstance],
    formal_dependent_results: &[bool],
    formal_dependent_expressions: &[Box<[bool]>],
    formal_static_variants: &[Option<StaticVariantSet>],
    specialization: &OwnerSpecialization,
    invocation_dependencies: Option<&[bool]>,
    initial_state_surface: bool,
) -> Result<Arc<ResidualTypeModule>, KernelOwnerBuildError> {
    let residual_transparent_type_providers = invocation_dependencies.map(|dependencies| {
        specialization
            .transparent_type_providers
            .iter()
            .copied()
            .enumerate()
            .map(|(expression, provider)| {
                (dependencies[expression]
                    && specialization.reachable.binary_search(&expression).is_ok())
                .then_some(provider)
                .flatten()
            })
            .collect::<Vec<_>>()
    });
    let mut builder = ComponentProgramBuilder::with_text(text.clone());
    let packed_input_types = packed_input_source
        .map(|source| {
            import_residual_packed_input_types(
                &mut builder,
                source,
                owner,
                specialization,
                invocation_dependencies,
                residual_transparent_type_providers.as_deref(),
                packed_input_imports,
            )
        })
        .transpose()?
        .flatten();
    let mut mode_builder = ModeProgramBuilder::default();
    let local = allocate_owner_instance_with_static_variants(
        &mut builder,
        &mut mode_builder,
        owner,
        formal_static_variants,
        specialization.static_variants.clone(),
        residual_transparent_type_providers.as_deref(),
    );
    let external_variables = owner
        .external_expressions()
        .iter()
        .map(|_| builder.new_contextual_hole())
        .collect::<Vec<_>>();
    let context = OwnerCompileContext {
        initial_state_surface,
        text,
        owner: owner_id,
        input: owner,
        expressions: &local.expressions,
        formals: &local.formals,
        formal_requirements: &local.formal_requirements,
        expression_modes: &local.expression_modes,
        formal_modes: &local.formal_modes,
        formal_mode_sources: &local.formal_mode_sources,
        static_variants: &local.static_variants,
        formal_static_variants: &local.formal_static_variants,
        project,
        principals,
        formal_dependent_results,
        formal_dependent_expressions,
        external_variables: Some(&external_variables),
        syntax_selected_calls: Some(&specialization.syntax_selected_calls),
        direct_summaries: &[],
        packed_input_types: packed_input_types
            .as_ref()
            .map(|imports| PackedInputTypeProjection { imports }),
    };
    let mut invocations = HashMap::new();
    let mut specializations = HashMap::new();
    let mut residual_modules = ResidualModuleCache::default();
    let mut compile_work = KernelCompileWork::default();
    let mut stack = vec![owner_id];
    let mut calls = Vec::new();
    for index in specialization.reachable.iter().copied() {
        if invocation_dependencies.is_some_and(|dependencies| !dependencies[index]) {
            continue;
        }
        if residual_transparent_type_providers
            .as_ref()
            .is_some_and(|providers| providers[index].is_some())
        {
            continue;
        }
        let node = owner.nodes().get(index).ok_or_else(|| {
            KernelOwnerBuildError::new(format!(
                "residual module owner {} references missing node {index}",
                owner_id.0
            ))
        })?;
        if matches!(node.kind, PackedKernelOwnerNodeKind::UserCall { .. }) {
            calls.push(index);
            continue;
        }
        compile_node(
            &mut builder,
            &mut mode_builder,
            &mut invocations,
            &mut specializations,
            &mut residual_modules,
            &mut compile_work,
            &context,
            &mut stack,
            index,
            node,
            local.expressions[index],
            local.expression_modes[index],
            false,
            None,
            None,
        )?;
    }
    Ok(Arc::new(ResidualTypeModule {
        component: Arc::new(builder.finish()),
        local,
        external_variables: external_variables.into_boxed_slice(),
        calls: calls.into_boxed_slice(),
    }))
}

fn append_residual_type_frame(
    builder: &mut ComponentProgramBuilder,
    module: &ResidualTypeModule,
    instance: &OwnerInstance,
    external_variables: &[TypeVariableId],
) -> Result<u32, KernelOwnerBuildError> {
    if external_variables.len() != module.external_variables.len() {
        return Err(KernelOwnerBuildError::new(format!(
            "residual frame supplies {} external variables for {} module imports",
            external_variables.len(),
            module.external_variables.len()
        )));
    }
    let mut variables = vec![None; module.component.variable_count()];
    let mut map = |local: TypeVariableId,
                   global: TypeVariableId,
                   role: &str|
     -> Result<(), KernelOwnerBuildError> {
        let slot = variables.get_mut(local.0 as usize).ok_or_else(|| {
            KernelOwnerBuildError::new(format!(
                "residual module {role} variable {} is outside its frame",
                local.0
            ))
        })?;
        if slot
            .replace(global)
            .is_some_and(|previous| previous != global)
        {
            return Err(KernelOwnerBuildError::new(format!(
                "residual module {role} variable {} has conflicting frame mappings",
                local.0
            )));
        }
        Ok(())
    };
    for (local, global) in module.local.expressions.iter().zip(&instance.expressions) {
        map(*local, *global, "expression")?;
    }
    for (local, global) in module.local.formals.iter().zip(&instance.formals) {
        map(*local, *global, "formal")?;
    }
    for (local, global) in module
        .local
        .formal_requirements
        .iter()
        .zip(&instance.formal_requirements)
    {
        map(*local, *global, "formal requirement")?;
    }
    for (local, global) in module.external_variables.iter().zip(external_variables) {
        map(*local, *global, "external")?;
    }
    for (index, spec) in module
        .component
        .variable_specs()
        .iter()
        .copied()
        .enumerate()
    {
        if variables[index].is_none() {
            variables[index] = Some(builder.new_variable_with(spec));
        }
    }
    let variables = variables
        .into_iter()
        .map(|variable| variable.expect("every residual frame variable is mapped"))
        .collect::<Vec<_>>();
    Ok(builder.add_residual_frame(Arc::clone(&module.component), variables))
}

fn principal_external_variables(
    owner: PackedKernelOwnerProgramRef<'_>,
    project: &PackedKernelProjectProgram,
    principals: &[OwnerInstance],
) -> Result<Vec<TypeVariableId>, KernelOwnerBuildError> {
    owner
        .external_expressions()
        .iter()
        .map(|external| {
            let target_instance = principals.get(external.owner.0 as usize).ok_or_else(|| {
                KernelOwnerBuildError::new(format!(
                    "residual module imports missing owner {}",
                    external.owner.0
                ))
            })?;
            let target_owner = project.owner(external.owner).ok_or_else(|| {
                KernelOwnerBuildError::new(format!(
                    "residual module imports missing owner input {}",
                    external.owner.0
                ))
            })?;
            let expression = match external.target {
                KernelExternalTarget::Expression(expression) => checked_expression_index(
                    expression,
                    target_owner.node_count(),
                    "residual external expression",
                )?,
                KernelExternalTarget::Result => checked_expression_index(
                    target_owner.result(),
                    target_owner.node_count(),
                    "residual external result",
                )?,
            };
            target_instance
                .expressions
                .get(expression)
                .copied()
                .ok_or_else(|| {
                    KernelOwnerBuildError::new(format!(
                        "residual module imports missing owner {} expression {expression}",
                        external.owner.0
                    ))
                })
        })
        .collect()
}

fn specialize_owner(
    specializations: &mut HashMap<SpecializationKey, OwnerSpecialization>,
    compile_work: &mut KernelCompileWork,
    text: &ProjectTextSnapshot,
    terms: &crate::TypeTermArena,
    project: &PackedKernelProjectProgram,
    formal_dependent_expressions: &[Box<[bool]>],
    target: KernelOwnerId,
    actuals: &[CallActual],
    initial_state_surface: bool,
) -> Result<(SpecializationKey, OwnerSpecialization), KernelOwnerBuildError> {
    let formal_static_variants = actuals
        .iter()
        .map(|actual| actual.static_variants.clone())
        .collect::<Vec<_>>()
        .into_boxed_slice();
    specialize_owner_static(
        specializations,
        compile_work,
        text,
        terms,
        project,
        formal_dependent_expressions,
        target,
        formal_static_variants,
        initial_state_surface,
    )
}

fn specialize_owner_static(
    specializations: &mut HashMap<SpecializationKey, OwnerSpecialization>,
    compile_work: &mut KernelCompileWork,
    text: &ProjectTextSnapshot,
    terms: &crate::TypeTermArena,
    project: &PackedKernelProjectProgram,
    formal_dependent_expressions: &[Box<[bool]>],
    target: KernelOwnerId,
    formal_static_variants: Box<[Option<StaticVariantSet>]>,
    initial_state_surface: bool,
) -> Result<(SpecializationKey, OwnerSpecialization), KernelOwnerBuildError> {
    let owner = project.owner(target).ok_or_else(|| {
        KernelOwnerBuildError::new(format!("user call targets missing owner {}", target.0))
    })?;
    let key = SpecializationKey {
        target,
        static_variants: formal_static_variants.clone(),
        initial_state_surface,
    };
    if let Some(specialization) = specializations.get(&key) {
        compile_work.reused_specialization_plans =
            compile_work.reused_specialization_plans.saturating_add(1);
        return Ok((key, specialization.clone()));
    }
    let static_variants = infer_static_variants(text, terms, owner, &formal_static_variants);
    let result = checked_expression_index(
        owner.result(),
        owner.node_count(),
        "specialized owner result",
    )?;
    let reachable = reachable_owner_nodes(text, owner, result, &static_variants)
        .into_iter()
        .collect::<Vec<_>>()
        .into_boxed_slice();
    let dependencies = &formal_dependent_expressions[target.0 as usize];
    let local_result_syntax_selected = reachable.iter().copied().any(|expression| {
        let node = &owner.nodes()[expression];
        if !matches!(node.kind, PackedKernelOwnerNodeKind::When) {
            return false;
        }
        node.inputs(owner)
            .iter()
            .find(|edge| matches!(edge.role, PackedKernelOwnerEdgeRole::WhenInput))
            .map(|edge| edge.expression.0 as usize)
            .filter(|selector| *selector < owner.node_count())
            .is_some_and(|selector| {
                dependencies.get(selector).copied().unwrap_or(false)
                    && static_variants
                        .get(selector)
                        .and_then(Option::as_ref)
                        .is_some_and(|variants| variants.len() == 1)
            })
    });
    let syntax_selected_calls =
        syntax_selected_call_nodes(text, owner, &static_variants, dependencies);
    let specialization = OwnerSpecialization {
        invocation_dependencies: invocation_expression_dependencies(
            owner,
            dependencies,
            &syntax_selected_calls,
        ),
        reachable,
        result_syntax_selected: local_result_syntax_selected,
        syntax_selected_calls,
        static_variants,
        transparent_type_providers: transparent_type_providers(owner),
    };
    specializations.insert(key.clone(), specialization.clone());
    compile_work.specialization_plans = compile_work.specialization_plans.saturating_add(1);
    Ok((key, specialization))
}

fn instantiate_owner(
    builder: &mut ComponentProgramBuilder,
    mode_builder: &mut ModeProgramBuilder,
    invocations: &mut HashMap<InvocationKey, OwnerInstance>,
    specializations: &mut HashMap<SpecializationKey, OwnerSpecialization>,
    residual_modules: &mut ResidualModuleCache,
    compile_work: &mut KernelCompileWork,
    text: &ProjectTextSnapshot,
    project: &PackedKernelProjectProgram,
    principals: &[OwnerInstance],
    formal_dependent_results: &[bool],
    formal_dependent_expressions: &[Box<[bool]>],
    direct_summaries: &[Option<Arc<CompiledDirectSummary>>],
    actuals: &[CallActual],
    specialization_key: SpecializationKey,
    specialization: OwnerSpecialization,
    stack: &mut Vec<KernelOwnerId>,
) -> Result<OwnerInstance, KernelOwnerBuildError> {
    let target = specialization_key.target;
    let initial_state_surface = specialization_key.initial_state_surface;
    compile_work.max_call_depth = compile_work.max_call_depth.max(stack.len() as u64);
    let owner = project.owner(target).ok_or_else(|| {
        KernelOwnerBuildError::new(format!("user call targets missing owner {}", target.0))
    })?;
    if actuals.len() != owner.formal_count() as usize {
        return Err(KernelOwnerBuildError::new(format!(
            "user call to owner {} supplies {} actuals for {} formals",
            target.0,
            actuals.len(),
            owner.formal_count()
        )));
    }
    if stack.contains(&target) {
        return principals.get(target.0 as usize).cloned().ok_or_else(|| {
            KernelOwnerBuildError::new(format!(
                "recursive user call targets missing principal owner {}",
                target.0
            ))
        });
    }

    let formal_static_variants = specialization_key.static_variants.to_vec();
    let key = InvocationKey {
        target,
        actuals: actuals
            .iter()
            .map(|actual| (actual.variable, actual.mode))
            .collect::<Vec<_>>()
            .into_boxed_slice(),
        static_variants: formal_static_variants.clone().into_boxed_slice(),
        initial_state_surface,
    };
    let owns_state = owner
        .nodes()
        .iter()
        .any(|node| matches!(node.kind, PackedKernelOwnerNodeKind::Hold));
    if !owns_state {
        if let Some(instance) = invocations.get(&key) {
            compile_work.reused_invocation_frames =
                compile_work.reused_invocation_frames.saturating_add(1);
            return Ok(instance.clone());
        }
    }
    compile_work.invocation_frames = compile_work.invocation_frames.saturating_add(1);
    // Invocation frames borrow the caller's provider/mode roots directly.
    // The detached FormalRead occurrences and private requirement roots below
    // still isolate consumers; the redundant actual -> fresh-formal publish
    // layer only obscured identical applications from composition.
    let expression_dependencies = &specialization.invocation_dependencies;
    let principal = &principals[target.0 as usize];
    let (instance, pruned_expressions) = allocate_invocation_owner_instance(
        builder,
        mode_builder,
        owner,
        principal,
        actuals,
        &formal_static_variants,
        specialization.static_variants.clone(),
        expression_dependencies,
        &specialization.reachable,
        &specialization.transparent_type_providers,
    );
    compile_work.pruned_invocation_expressions = compile_work
        .pruned_invocation_expressions
        .saturating_add(pruned_expressions);
    compile_work.principal_expression_reuses =
        compile_work.principal_expression_reuses.saturating_add(
            specialization
                .reachable
                .iter()
                .filter(|index| !expression_dependencies[**index])
                .count() as u64,
        );
    let module = if let Some(module) = residual_modules.modules.get(&specialization_key) {
        Arc::clone(module)
    } else {
        let module = compile_residual_type_module(
            text,
            Some(builder.terms()),
            &mut residual_modules.packed_type_imports,
            target,
            owner,
            Some(project),
            principals,
            formal_dependent_results,
            formal_dependent_expressions,
            &formal_static_variants,
            &specialization,
            Some(expression_dependencies),
            initial_state_surface,
        )?;
        compile_work.residual_type_modules = compile_work.residual_type_modules.saturating_add(1);
        compile_work.residual_module_operations = compile_work
            .residual_module_operations
            .saturating_add(module.component.operation_count() as u64);
        compile_work.residual_module_terms = compile_work
            .residual_module_terms
            .saturating_add(module.component.terms().len() as u64);
        residual_modules
            .modules
            .insert(specialization_key, Arc::clone(&module));
        module
    };
    let external_variables = principal_external_variables(owner, project, principals)?;
    stack.push(target);
    let result = (|| {
        let context = OwnerCompileContext {
            initial_state_surface,
            text,
            owner: target,
            input: owner,
            expressions: &instance.expressions,
            formals: &instance.formals,
            formal_requirements: &instance.formal_requirements,
            expression_modes: &instance.expression_modes,
            formal_modes: &instance.formal_modes,
            formal_mode_sources: &instance.formal_mode_sources,
            static_variants: &instance.static_variants,
            formal_static_variants: &instance.formal_static_variants,
            project: Some(project),
            principals,
            formal_dependent_results,
            formal_dependent_expressions,
            external_variables: None,
            syntax_selected_calls: Some(&specialization.syntax_selected_calls),
            direct_summaries,
            packed_input_types: None,
        };
        append_residual_type_frame(builder, &module, &instance, &external_variables)?;
        compile_work.residual_frames = compile_work.residual_frames.saturating_add(1);
        for index in specialization.reachable.iter().copied() {
            if !expression_dependencies[index] {
                continue;
            }
            let node = &owner.nodes()[index];
            if matches!(node.kind, PackedKernelOwnerNodeKind::UserCall { .. }) {
                compile_node(
                    builder,
                    mode_builder,
                    invocations,
                    specializations,
                    residual_modules,
                    compile_work,
                    &context,
                    stack,
                    index,
                    node,
                    instance.expressions[index],
                    instance.expression_modes[index],
                    true,
                    None,
                    None,
                )?;
            } else {
                let equation = node_mode_equation(mode_builder, &context, index, node)?;
                mode_builder.set(instance.expression_modes[index], equation);
            }
        }
        Ok::<(), KernelOwnerBuildError>(())
    })();
    let popped = stack.pop();
    debug_assert_eq!(popped, Some(target));
    result?;
    for (actual, requirement) in actuals.iter().zip(&instance.formal_requirements) {
        // A closed or directionally derived actual is provider authority, not
        // a writable formal scaffold. Callee requirements remain useful for
        // open caller formals, but must never widen a concrete occurrence.
        if builder.is_authoritative(actual.variable) && !actual.requirement_backflow {
            continue;
        }
        let actual = builder.variable_term(actual.requirement);
        let requirement = builder.variable_term(*requirement);
        builder.add_unify(actual, requirement);
    }
    if !owns_state {
        invocations.insert(key, instance.clone());
    }
    Ok(instance)
}

fn direct_result_summary_supported(
    project: &PackedKernelProjectProgram,
    owner_id: KernelOwnerId,
    expression: usize,
    active: &mut BTreeSet<(KernelOwnerId, usize)>,
    trace: bool,
) -> bool {
    let Some(owner) = project.owner(owner_id) else {
        return false;
    };
    let Some(node) = owner.nodes().get(expression) else {
        return false;
    };
    if !active.insert((owner_id, expression)) {
        return false;
    }
    let child = |edge: &crate::PackedKernelOwnerInputEdge,
                 active: &mut BTreeSet<(KernelOwnerId, usize)>| {
        direct_result_summary_supported(project, owner_id, edge.expression.0 as usize, active, trace)
    };
    let inputs = node.inputs(owner);
    let supported = match &node.kind {
        PackedKernelOwnerNodeKind::Known(_) | PackedKernelOwnerNodeKind::Source(_) => {
            inputs.is_empty()
        }
        PackedKernelOwnerNodeKind::Absent
        | PackedKernelOwnerNodeKind::Text
        | PackedKernelOwnerNodeKind::Number
        | PackedKernelOwnerNodeKind::Byte
        | PackedKernelOwnerNodeKind::Bits(_)
        | PackedKernelOwnerNodeKind::Tag(_)
        | PackedKernelOwnerNodeKind::FormalRead { .. }
        | PackedKernelOwnerNodeKind::ContextRead { .. } => inputs.is_empty(),
        PackedKernelOwnerNodeKind::TextTemplate => inputs.iter().all(|edge| {
            matches!(edge.role, PackedKernelOwnerEdgeRole::TextDynamic) && child(edge, active)
        }),
        PackedKernelOwnerNodeKind::Record { .. } => inputs.iter().all(|edge| {
            matches!(edge.role, PackedKernelOwnerEdgeRole::RecordField { .. })
                && child(edge, active)
        }),
        PackedKernelOwnerNodeKind::Collection { kind, .. } => match kind {
            KernelCollectionKind::List
            | KernelCollectionKind::Bytes
            | KernelCollectionKind::Set => inputs.iter().all(|edge| {
                matches!(edge.role, PackedKernelOwnerEdgeRole::CollectionItem)
                    && child(edge, active)
            }),
            KernelCollectionKind::Map => inputs.iter().all(|edge| {
                matches!(edge.role, PackedKernelOwnerEdgeRole::MapEntry) && child(edge, active)
            }),
        },
        PackedKernelOwnerNodeKind::MapEntry => inputs.iter().all(|edge| {
            matches!(
                edge.role,
                PackedKernelOwnerEdgeRole::MapKey | PackedKernelOwnerEdgeRole::MapValue
            ) && child(edge, active)
        }),
        PackedKernelOwnerNodeKind::Block => {
            let mut results = inputs
                .iter()
                .filter(|edge| matches!(edge.role, PackedKernelOwnerEdgeRole::BlockResult));
            results
                .next()
                .is_some_and(|result| results.next().is_none() && child(result, active))
        }
        PackedKernelOwnerNodeKind::Draining => {
            let mut draining = inputs
                .iter()
                .filter(|edge| matches!(edge.role, PackedKernelOwnerEdgeRole::DrainingInput));
            draining
                .next()
                .is_some_and(|input| draining.next().is_none() && child(input, active))
        }
        PackedKernelOwnerNodeKind::LexicalRead { .. }
        | PackedKernelOwnerNodeKind::ValueRead { .. }
        | PackedKernelOwnerNodeKind::DerivedRead { .. } => {
            let providers = inputs
                .iter()
                .filter(|edge| matches!(edge.role, PackedKernelOwnerEdgeRole::ReadProvider))
                .collect::<Vec<_>>();
            matches!(providers.as_slice(), [provider] if {
                let reference = provider.expression.0 as usize;
                if reference < owner.node_count() {
                    direct_result_summary_supported(project, owner_id, reference, active, trace)
                } else {
                    owner
                        .external_expressions()
                        .get(reference - owner.node_count())
                        .is_some()
                }
            })
        }
        // A pattern projection owns tag-sensitive formal shaping and cannot
        // be represented by the generic field-projection summary bytecode.
        PackedKernelOwnerNodeKind::PatternRead { .. } => false,
        PackedKernelOwnerNodeKind::UserCall { target, .. } => {
            let Some(target_owner) = project.owner(*target) else {
                active.remove(&(owner_id, expression));
                return false;
            };
            inputs.iter().all(|edge| {
                matches!(edge.role, PackedKernelOwnerEdgeRole::CallArgument { .. })
                    && child(edge, active)
            }) && direct_result_summary_supported(
                project,
                *target,
                target_owner.result().0 as usize,
                active,
                trace,
            )
        }
        PackedKernelOwnerNodeKind::RenderConstructor { .. } => inputs.iter().all(|edge| {
            matches!(edge.role, PackedKernelOwnerEdgeRole::AbiArgument { .. })
                && child(edge, active)
        }),
        PackedKernelOwnerNodeKind::PureBuiltin { kind }
            if direct_summary_fixed_builtin_supported(*kind) =>
        {
            inputs.iter().all(|edge| {
                matches!(edge.role, PackedKernelOwnerEdgeRole::AbiArgument { .. })
                    && child(edge, active)
            })
        }
        PackedKernelOwnerNodeKind::When => {
            let selectors = inputs
                .iter()
                .filter(|edge| matches!(edge.role, PackedKernelOwnerEdgeRole::WhenInput))
                .collect::<Vec<_>>();
            matches!(selectors.as_slice(), [selector] if child(selector, active))
                && inputs.iter().all(|edge| match edge.role {
                    PackedKernelOwnerEdgeRole::WhenInput => true,
                    PackedKernelOwnerEdgeRole::WhenArm => child(edge, active),
                    _ => false,
                })
        }
        PackedKernelOwnerNodeKind::MatchArm { .. } => {
            let outputs = inputs
                .iter()
                .filter(|edge| matches!(edge.role, PackedKernelOwnerEdgeRole::MatchOutput))
                .collect::<Vec<_>>();
            if !outputs.is_empty() {
                matches!(outputs.as_slice(), [output] if inputs.len() == 1 && child(output, active))
            } else if inputs
                .iter()
                .any(|edge| matches!(edge.role, PackedKernelOwnerEdgeRole::RecordField { .. }))
            {
                inputs.iter().all(|edge| {
                    matches!(edge.role, PackedKernelOwnerEdgeRole::RecordField { .. })
                        && child(edge, active)
                })
            } else {
                inputs.is_empty()
            }
        }
        PackedKernelOwnerNodeKind::Then => {
            let has_output = inputs
                .iter()
                .any(|edge| matches!(edge.role, PackedKernelOwnerEdgeRole::ThenOutput));
            let selected = inputs
                .iter()
                .filter(|edge| {
                    matches!(edge.role, PackedKernelOwnerEdgeRole::ThenOutput)
                        || (!has_output
                            && matches!(edge.role, PackedKernelOwnerEdgeRole::ThenInput))
                })
                .collect::<Vec<_>>();
            matches!(selected.as_slice(), [value] if child(value, active))
                && inputs.iter().all(|edge| {
                    matches!(
                        edge.role,
                        PackedKernelOwnerEdgeRole::ThenInput
                            | PackedKernelOwnerEdgeRole::ThenOutput
                    ) && child(edge, active)
                })
        }
        PackedKernelOwnerNodeKind::Infix { .. } => {
            let left = inputs
                .iter()
                .filter(|edge| matches!(edge.role, PackedKernelOwnerEdgeRole::InfixLeft))
                .collect::<Vec<_>>();
            let right = inputs
                .iter()
                .filter(|edge| matches!(edge.role, PackedKernelOwnerEdgeRole::InfixRight))
                .collect::<Vec<_>>();
            matches!(left.as_slice(), [left] if child(left, active))
                && matches!(right.as_slice(), [right] if child(right, active))
                && inputs.len() == 2
        }
        PackedKernelOwnerNodeKind::Arrow => {
            let outputs = inputs
                .iter()
                .filter(|edge| matches!(edge.role, PackedKernelOwnerEdgeRole::ArrowOutput))
                .collect::<Vec<_>>();
            matches!(outputs.as_slice(), [output] if inputs.len() == 1 && child(output, active))
        }
        PackedKernelOwnerNodeKind::Delimiter
        | PackedKernelOwnerNodeKind::Unknown
        | PackedKernelOwnerNodeKind::FreshOut => inputs.is_empty(),
        _ => false,
    };
    active.remove(&(owner_id, expression));
    #[cfg(debug_assertions)]
    if trace && !supported {
        // Predicates short-circuit in source edge order. The first emitted
        // rejection is the leaf cause; later rows describe its result path.
        eprintln!("kernel-summary-rejection owner={} expression={expression} kind={:?}", owner_id.0, node.kind);
    }
    supported
}

fn direct_summary_fixed_builtin_supported(kind: KernelPureBuiltinKind) -> bool {
    matches!(
        kind,
        KernelPureBuiltinKind::TextConstant
            | KernelPureBuiltinKind::TextTransform
            | KernelPureBuiltinKind::TextSlice
            | KernelPureBuiltinKind::TextLength
            | KernelPureBuiltinKind::TextConcat
            | KernelPureBuiltinKind::TextPredicate
            | KernelPureBuiltinKind::TextToNumber
            | KernelPureBuiltinKind::NumberToText
            | KernelPureBuiltinKind::NumberMath
            | KernelPureBuiltinKind::NumberRound
            | KernelPureBuiltinKind::NumberProjection
            | KernelPureBuiltinKind::Boolean
            | KernelPureBuiltinKind::BoolToggle
            | KernelPureBuiltinKind::RecordConstructor
            | KernelPureBuiltinKind::TextJoin
            | KernelPureBuiltinKind::FieldColor
    )
}

/// Tiny summary definitions cost less to inline than to enter through a
/// nested scratch frame. Larger definitions remain shared so call-heavy
/// projects do not duplicate their bytecode at every occurrence.
const SHARED_SUMMARY_MIN_NODES: usize = 128;

#[derive(Clone, Debug)]
enum DirectSummaryInput {
    FormalProjection {
        formal: u32,
        fields: Box<[SymbolId]>,
        parameter_derived: bool,
    },
    External {
        owner: KernelOwnerId,
        expression: usize,
    },
}

#[derive(Clone, Copy, Debug)]
enum DirectSummaryMode {
    Fixed {
        owner: KernelOwnerId,
        expression: usize,
    },
    Input(u32),
}

#[derive(Clone, Debug)]
struct CompiledDirectSummary {
    program: Arc<KernelSummaryProgram>,
    inputs: Box<[DirectSummaryInput]>,
    result_mode: DirectSummaryMode,
    formal_count: usize,
    constant_folded_nodes: u64,
    selector_fused_records: u64,
    deduplicated_nodes: u64,
    pruned_nodes: u64,
    pruned_inputs: u64,
    shared_bytecode: bool,
}

#[derive(Clone, Debug)]
enum PlannedSummaryActual {
    Formal(u32),
    Value(PlannedSummaryValue),
}

#[derive(Clone, Copy, Debug)]
struct PlannedSummaryValue {
    value: KernelSummaryValueId,
    mode: DirectSummaryMode,
    formal_projection_input: Option<u32>,
}

struct DirectSummaryPlanCompiler<'a> {
    builder: &'a mut ComponentProgramBuilder,
    project: &'a PackedKernelProjectProgram,
    summaries: &'a [Option<Arc<CompiledDirectSummary>>],
    nodes: Vec<KernelSummaryNode>,
    inputs: Vec<DirectSummaryInput>,
    formal_projection_inputs: HashMap<(u32, Box<[SymbolId]>, bool), (u32, KernelSummaryValueId)>,
}

impl DirectSummaryPlanCompiler<'_> {
    fn fold_constant_nodes(&mut self) -> (u64, u64) {
        fold_constant_summary_nodes(self.builder, &mut self.nodes)
    }

    fn compact_result(&mut self, result: &mut PlannedSummaryValue) -> (u64, u64) {
        compact_summary_result(&mut self.nodes, &mut self.inputs, result)
    }

    fn deduplicate_nodes(&mut self, result: &mut PlannedSummaryValue) -> u64 {
        deduplicate_summary_nodes(&mut self.nodes, result)
    }

    fn push_node(&mut self, node: KernelSummaryNode) -> KernelSummaryValueId {
        let id = KernelSummaryValueId(
            u32::try_from(self.nodes.len()).expect("kernel summary value count exceeds u32"),
        );
        self.nodes.push(node);
        id
    }

    fn push_formal_projection(
        &mut self,
        formal: u32,
        fields: Box<[SymbolId]>,
        parameter_derived: bool,
    ) -> PlannedSummaryValue {
        let key = (formal, fields.clone(), parameter_derived);
        if let Some((input, value)) = self.formal_projection_inputs.get(&key).copied() {
            return PlannedSummaryValue {
                value,
                mode: DirectSummaryMode::Input(input),
                formal_projection_input: Some(input),
            };
        }
        let input =
            u32::try_from(self.inputs.len()).expect("kernel summary input count exceeds u32");
        self.inputs.push(DirectSummaryInput::FormalProjection {
            formal,
            fields,
            parameter_derived,
        });
        let value = self.push_node(KernelSummaryNode::Input(input));
        self.formal_projection_inputs.insert(key, (input, value));
        PlannedSummaryValue {
            value,
            mode: DirectSummaryMode::Input(input),
            formal_projection_input: Some(input),
        }
    }

    fn project_value(
        &mut self,
        value: PlannedSummaryValue,
        fields: PackedKernelPathRef<'_>,
        mode: DirectSummaryMode,
    ) -> Option<PlannedSummaryValue> {
        if fields.is_empty() {
            return Some(value);
        }
        let fields = fields.iter().collect::<Vec<_>>();
        if let Some(input) = value.formal_projection_input {
            let DirectSummaryInput::FormalProjection {
                formal,
                fields: prefix,
                parameter_derived,
            } = self.inputs.get(input as usize)?.clone()
            else {
                return None;
            };
            let mut projection = prefix.into_vec();
            projection.extend(fields);
            return Some(self.push_formal_projection(
                formal,
                projection.into_boxed_slice(),
                parameter_derived,
            ));
        }
        Some(PlannedSummaryValue {
            value: self.push_node(KernelSummaryNode::Projection {
                provider: value.value,
                fields: fields.into_boxed_slice(),
            }),
            mode,
            formal_projection_input: None,
        })
    }

    fn project_interned_formal_value(
        &mut self,
        value: PlannedSummaryValue,
        fields: &[SymbolId],
    ) -> Option<PlannedSummaryValue> {
        if fields.is_empty() {
            return Some(value);
        }
        let input = value.formal_projection_input?;
        let DirectSummaryInput::FormalProjection {
            formal,
            fields: prefix,
            parameter_derived,
        } = self.inputs.get(input as usize)?.clone()
        else {
            return None;
        };
        let mut projection = prefix.into_vec();
        projection.extend_from_slice(fields);
        Some(self.push_formal_projection(formal, projection.into_boxed_slice(), parameter_derived))
    }

    fn compile_shared_invoke(
        &mut self,
        summary: &CompiledDirectSummary,
        actuals: &[PlannedSummaryActual],
    ) -> Option<PlannedSummaryValue> {
        if actuals.len() != summary.formal_count {
            return None;
        }
        let mut values = Vec::with_capacity(summary.inputs.len());
        let mut modes = Vec::with_capacity(summary.inputs.len());
        for input in summary.inputs.iter() {
            let value = match input {
                DirectSummaryInput::FormalProjection {
                    formal,
                    fields,
                    parameter_derived,
                } => match actuals.get(*formal as usize)? {
                    PlannedSummaryActual::Formal(formal) => {
                        self.push_formal_projection(*formal, fields.clone(), *parameter_derived)
                    }
                    PlannedSummaryActual::Value(value) => {
                        self.project_interned_formal_value(*value, fields)?
                    }
                },
                DirectSummaryInput::External { owner, expression } => {
                    let input = u32::try_from(self.inputs.len())
                        .expect("kernel summary input count exceeds u32");
                    self.inputs.push(DirectSummaryInput::External {
                        owner: *owner,
                        expression: *expression,
                    });
                    PlannedSummaryValue {
                        value: self.push_node(KernelSummaryNode::Input(input)),
                        mode: DirectSummaryMode::Fixed {
                            owner: *owner,
                            expression: *expression,
                        },
                        formal_projection_input: None,
                    }
                }
            };
            values.push(value.value);
            modes.push(value.mode);
        }
        let mode = match summary.result_mode {
            DirectSummaryMode::Fixed { owner, expression } => {
                DirectSummaryMode::Fixed { owner, expression }
            }
            DirectSummaryMode::Input(input) => *modes.get(input as usize)?,
        };
        Some(PlannedSummaryValue {
            value: self.push_node(KernelSummaryNode::Invoke {
                program: Arc::clone(&summary.program),
                inputs: values.into_boxed_slice(),
            }),
            mode,
            formal_projection_input: None,
        })
    }

    fn compile_expression(
        &mut self,
        owner_id: KernelOwnerId,
        expression: usize,
        actuals: &[PlannedSummaryActual],
        active: &mut BTreeSet<(KernelOwnerId, usize)>,
    ) -> Option<PlannedSummaryValue> {
        if !active.insert((owner_id, expression)) {
            return None;
        }
        let result = (|| {
            let owner = self.project.owner(owner_id)?;
            let node = owner.nodes().get(expression)?;
            let node_inputs = node.inputs(owner);
            let fixed_mode = DirectSummaryMode::Fixed {
                owner: owner_id,
                expression,
            };
            let term_value = |compiler: &mut Self, term| PlannedSummaryValue {
                value: compiler.push_node(KernelSummaryNode::Term(term)),
                mode: fixed_mode,
                formal_projection_input: None,
            };
            match &node.kind {
                PackedKernelOwnerNodeKind::Known(reference)
                | PackedKernelOwnerNodeKind::Source(reference) => {
                    let value = self.builder.terms().resolve_type_ref(*reference)?;
                    Some(term_value(self, value))
                }
                PackedKernelOwnerNodeKind::Absent => {
                    let value = self.builder.terms().absent();
                    Some(term_value(self, value))
                }
                PackedKernelOwnerNodeKind::Text => {
                    let value = self.builder.terms().text();
                    Some(term_value(self, value))
                }
                PackedKernelOwnerNodeKind::TextTemplate => {
                    let mut dependencies = Vec::with_capacity(node_inputs.len());
                    for edge in node_inputs {
                        if !matches!(edge.role, PackedKernelOwnerEdgeRole::TextDynamic) {
                            return None;
                        }
                        dependencies.push(
                            self.compile_expression(
                                owner_id,
                                edge.expression.0 as usize,
                                actuals,
                                active,
                            )?
                            .value,
                        );
                    }
                    let text = self.builder.terms().text();
                    let result = self.push_node(KernelSummaryNode::Term(text));
                    Some(PlannedSummaryValue {
                        value: self.push_node(KernelSummaryNode::Sequence {
                            inputs: dependencies.into_boxed_slice(),
                            result,
                        }),
                        mode: fixed_mode,
                        formal_projection_input: None,
                    })
                }
                PackedKernelOwnerNodeKind::Number => {
                    let value = self.builder.terms().number();
                    Some(term_value(self, value))
                }
                PackedKernelOwnerNodeKind::Byte => {
                    let value = self.builder.terms_mut().bytes(crate::BytesTerm::Fixed(1));
                    Some(term_value(self, value))
                }
                PackedKernelOwnerNodeKind::Bits(width) => {
                    let value = self.builder.terms_mut().bits(*width);
                    Some(term_value(self, value))
                }
                PackedKernelOwnerNodeKind::Tag(tag) => {
                    let tag = VariantTerm::Tag(*tag);
                    let value = self.builder.terms_mut().variant_set([tag]);
                    Some(term_value(self, value))
                }
                PackedKernelOwnerNodeKind::FormalRead { formal, fields } => {
                    let fields = owner.path(*fields)?;
                    let actual = actuals.get(*formal as usize)?;
                    match actual {
                        PlannedSummaryActual::Formal(formal) => {
                            let fields = fields.iter().collect::<Vec<_>>().into_boxed_slice();
                            Some(self.push_formal_projection(*formal, fields, true))
                        }
                        PlannedSummaryActual::Value(value) => {
                            self.project_value(*value, fields, fixed_mode)
                        }
                    }
                }
                PackedKernelOwnerNodeKind::ContextRead { formal, fields } => {
                    let fields = owner.path(*fields)?;
                    let actual = actuals.get(*formal as usize)?;
                    match actual {
                        PlannedSummaryActual::Formal(formal) => {
                            let fields = fields.iter().collect::<Vec<_>>().into_boxed_slice();
                            Some(self.push_formal_projection(*formal, fields, false))
                        }
                        PlannedSummaryActual::Value(value) => {
                            self.project_value(*value, fields, fixed_mode)
                        }
                    }
                }
                PackedKernelOwnerNodeKind::Record { tag } => {
                    let mut entries = Vec::with_capacity(node_inputs.len());
                    for edge in node_inputs {
                        let PackedKernelOwnerEdgeRole::RecordField { name, spread } = edge.role
                        else {
                            return None;
                        };
                        let value = self.compile_expression(
                            owner_id,
                            edge.expression.0 as usize,
                            actuals,
                            active,
                        )?;
                        if spread {
                            entries.push(KernelSummaryRecordEntry::Spread { value: value.value });
                        } else {
                            entries.push(KernelSummaryRecordEntry::Field {
                                name,
                                value: value.value,
                            });
                        }
                    }
                    let tag = *tag;
                    Some(PlannedSummaryValue {
                        value: self.push_node(KernelSummaryNode::Record {
                            tag,
                            entries: entries.into_boxed_slice(),
                        }),
                        mode: fixed_mode,
                        formal_projection_input: None,
                    })
                }
                PackedKernelOwnerNodeKind::Collection { kind, .. } => match kind {
                    KernelCollectionKind::List | KernelCollectionKind::Set => {
                        let mut inputs = Vec::with_capacity(node_inputs.len());
                        for edge in node_inputs {
                            if !matches!(edge.role, PackedKernelOwnerEdgeRole::CollectionItem) {
                                return None;
                            }
                            inputs.push(
                                self.compile_expression(
                                    owner_id,
                                    edge.expression.0 as usize,
                                    actuals,
                                    active,
                                )?
                                .value,
                            );
                        }
                        let kind = match kind {
                            KernelCollectionKind::List => KernelCollectionOperationKind::List,
                            KernelCollectionKind::Set => KernelCollectionOperationKind::Set,
                            _ => unreachable!(),
                        };
                        Some(PlannedSummaryValue {
                            value: self.push_node(KernelSummaryNode::Collection {
                                kind,
                                inputs: inputs.into_boxed_slice(),
                                values: Box::new([]),
                            }),
                            mode: fixed_mode,
                            formal_projection_input: None,
                        })
                    }
                    KernelCollectionKind::Bytes => {
                        let mut dependencies = Vec::with_capacity(node_inputs.len());
                        for edge in node_inputs {
                            if !matches!(edge.role, PackedKernelOwnerEdgeRole::CollectionItem) {
                                return None;
                            }
                            dependencies.push(
                                self.compile_expression(
                                    owner_id,
                                    edge.expression.0 as usize,
                                    actuals,
                                    active,
                                )?
                                .value,
                            );
                        }
                        let bytes = self
                            .builder
                            .terms_mut()
                            .bytes(crate::BytesTerm::Fixed(node_inputs.len()));
                        let result = self.push_node(KernelSummaryNode::Term(bytes));
                        Some(PlannedSummaryValue {
                            value: self.push_node(KernelSummaryNode::Sequence {
                                inputs: dependencies.into_boxed_slice(),
                                result,
                            }),
                            mode: fixed_mode,
                            formal_projection_input: None,
                        })
                    }
                    KernelCollectionKind::Map => {
                        let mut keys = Vec::new();
                        let mut values = Vec::new();
                        for edge in node_inputs {
                            if !matches!(edge.role, PackedKernelOwnerEdgeRole::MapEntry) {
                                return None;
                            }
                            let entry = owner.nodes().get(edge.expression.0 as usize)?;
                            if !matches!(entry.kind, PackedKernelOwnerNodeKind::MapEntry) {
                                return None;
                            }
                            for entry_edge in entry.inputs(owner) {
                                let value = self.compile_expression(
                                    owner_id,
                                    entry_edge.expression.0 as usize,
                                    actuals,
                                    active,
                                )?;
                                match entry_edge.role {
                                    PackedKernelOwnerEdgeRole::MapKey => keys.push(value.value),
                                    PackedKernelOwnerEdgeRole::MapValue => values.push(value.value),
                                    _ => return None,
                                }
                            }
                        }
                        Some(PlannedSummaryValue {
                            value: self.push_node(KernelSummaryNode::Collection {
                                kind: KernelCollectionOperationKind::Map,
                                inputs: keys.into_boxed_slice(),
                                values: values.into_boxed_slice(),
                            }),
                            mode: fixed_mode,
                            formal_projection_input: None,
                        })
                    }
                },
                PackedKernelOwnerNodeKind::MapEntry => {
                    let mut dependencies = Vec::with_capacity(node_inputs.len());
                    for edge in node_inputs {
                        if !matches!(
                            edge.role,
                            PackedKernelOwnerEdgeRole::MapKey | PackedKernelOwnerEdgeRole::MapValue
                        ) {
                            return None;
                        }
                        dependencies.push(
                            self.compile_expression(
                                owner_id,
                                edge.expression.0 as usize,
                                actuals,
                                active,
                            )?
                            .value,
                        );
                    }
                    let absent = self.builder.terms().absent();
                    let result = self.push_node(KernelSummaryNode::Term(absent));
                    Some(PlannedSummaryValue {
                        value: self.push_node(KernelSummaryNode::Sequence {
                            inputs: dependencies.into_boxed_slice(),
                            result,
                        }),
                        mode: fixed_mode,
                        formal_projection_input: None,
                    })
                }
                PackedKernelOwnerNodeKind::Block => {
                    let results = node_inputs
                        .iter()
                        .filter(|edge| matches!(edge.role, PackedKernelOwnerEdgeRole::BlockResult))
                        .collect::<Vec<_>>();
                    let [result] = results.as_slice() else {
                        return None;
                    };
                    self.compile_expression(owner_id, result.expression.0 as usize, actuals, active)
                }
                PackedKernelOwnerNodeKind::Draining => {
                    let inputs = node_inputs
                        .iter()
                        .filter(|edge| {
                            matches!(edge.role, PackedKernelOwnerEdgeRole::DrainingInput)
                        })
                        .collect::<Vec<_>>();
                    let [input] = inputs.as_slice() else {
                        return None;
                    };
                    self.compile_expression(owner_id, input.expression.0 as usize, actuals, active)
                }
                PackedKernelOwnerNodeKind::LexicalRead { fields }
                | PackedKernelOwnerNodeKind::ValueRead { fields, .. }
                | PackedKernelOwnerNodeKind::DerivedRead { fields } => {
                    let fields = owner.path(*fields)?;
                    let providers = node_inputs
                        .iter()
                        .filter(|edge| matches!(edge.role, PackedKernelOwnerEdgeRole::ReadProvider))
                        .collect::<Vec<_>>();
                    let [provider] = providers.as_slice() else {
                        return None;
                    };
                    let reference = provider.expression.0 as usize;
                    let provider = if reference < owner.node_count() {
                        self.compile_expression(owner_id, reference, actuals, active)?
                    } else {
                        let external = owner
                            .external_expressions()
                            .get(reference - owner.node_count())?;
                        let target_owner = self.project.owner(external.owner)?;
                        let expression = match external.target {
                            KernelExternalTarget::Expression(expression) => expression.0 as usize,
                            KernelExternalTarget::Result => target_owner.result().0 as usize,
                        };
                        let input = u32::try_from(self.inputs.len())
                            .expect("kernel summary input count exceeds u32");
                        self.inputs.push(DirectSummaryInput::External {
                            owner: external.owner,
                            expression,
                        });
                        PlannedSummaryValue {
                            value: self.push_node(KernelSummaryNode::Input(input)),
                            mode: DirectSummaryMode::Fixed {
                                owner: external.owner,
                                expression,
                            },
                            formal_projection_input: None,
                        }
                    };
                    self.project_value(provider, fields, fixed_mode)
                }
                PackedKernelOwnerNodeKind::PatternRead { .. } => None,
                PackedKernelOwnerNodeKind::UserCall {
                    target,
                    inherited_formal,
                } => {
                    let target_owner = self.project.owner(*target)?;
                    let mut target_actuals = vec![None; target_owner.formal_count() as usize];
                    for edge in node_inputs {
                        let PackedKernelOwnerEdgeRole::CallArgument { ordinal } = edge.role else {
                            return None;
                        };
                        let value = self.compile_expression(
                            owner_id,
                            edge.expression.0 as usize,
                            actuals,
                            active,
                        )?;
                        let slot = target_actuals.get_mut(ordinal as usize)?;
                        if slot.replace(PlannedSummaryActual::Value(value)).is_some() {
                            return None;
                        }
                    }
                    if let Some(inherited) = inherited_formal {
                        let actual = actuals.get(inherited.caller_ordinal as usize)?.clone();
                        let slot = target_actuals.get_mut(inherited.target_ordinal as usize)?;
                        if slot.replace(actual).is_some() {
                            return None;
                        }
                    }
                    let target_actuals = target_actuals.into_iter().collect::<Option<Vec<_>>>()?;
                    let shared = self
                        .summaries
                        .get(target.0 as usize)
                        .and_then(Clone::clone)
                        .filter(|summary| summary.shared_bytecode);
                    if let Some(shared) = shared
                        && let Some(result) =
                            self.compile_shared_invoke(shared.as_ref(), &target_actuals)
                    {
                        return Some(result);
                    }
                    self.compile_expression(
                        *target,
                        target_owner.result().0 as usize,
                        &target_actuals,
                        active,
                    )
                }
                PackedKernelOwnerNodeKind::RenderConstructor { kind } => {
                    let mut entries = Vec::with_capacity(node_inputs.len() + 1);
                    let mut direction = None;
                    for edge in node_inputs {
                        let PackedKernelOwnerEdgeRole::AbiArgument { name } = edge.role else {
                            return None;
                        };
                        let name_text = owner.symbol(name)?;
                        let mut value = self.compile_expression(
                            owner_id,
                            edge.expression.0 as usize,
                            actuals,
                            active,
                        )?;
                        if let Some(expected) = render_argument_requirement(self.builder, name_text)
                        {
                            value.value = self.push_node(KernelSummaryNode::Constrain {
                                value: value.value,
                                expected,
                            });
                        }
                        if name_text == "direction" {
                            direction = Some(value.value);
                        }
                        entries.push(KernelSummaryRecordEntry::Field {
                            name,
                            value: value.value,
                        });
                    }
                    let kind = match kind {
                        crate::PackedKernelRenderConstructorKind::Fixed(tag) => {
                            let tag = VariantTerm::Tag(*tag);
                            let term = self.builder.terms_mut().variant_set([tag]);
                            self.push_node(KernelSummaryNode::Term(term))
                        }
                        crate::PackedKernelRenderConstructorKind::StripeDirection => {
                            let row_tag = self.builder.terms_mut().variant_tag("Row");
                            let row = self.builder.terms_mut().variant_set([row_tag]);
                            let stack_tag = self.builder.terms_mut().variant_tag("Stack");
                            let stack = self.builder.terms_mut().variant_set([stack_tag]);
                            let fallback = self.builder.terms_mut().union([row, stack]);
                            let fallback_value = self.push_node(KernelSummaryNode::Term(fallback));
                            if let Some(direction) = direction {
                                let row_value = self.push_node(KernelSummaryNode::Term(row));
                                let stack_value = self.push_node(KernelSummaryNode::Term(stack));
                                let row_name = self.builder.terms().intern_name("Row");
                                let column_name = self.builder.terms().intern_name("Column");
                                self.push_node(KernelSummaryNode::Select {
                                    selector: direction,
                                    syntax_discriminating: false,
                                    arms: vec![
                                        KernelSummarySelectArm {
                                            pattern: crate::PackedKernelPattern::Tag {
                                                name: row_name,
                                                fields: boon_contract::PathId::ROOT,
                                            },
                                            output: row_value,
                                        },
                                        KernelSummarySelectArm {
                                            pattern: crate::PackedKernelPattern::Tag {
                                                name: column_name,
                                                fields: boon_contract::PathId::ROOT,
                                            },
                                            output: stack_value,
                                        },
                                        KernelSummarySelectArm {
                                            pattern: crate::PackedKernelPattern::Wildcard,
                                            output: fallback_value,
                                        },
                                    ]
                                    .into_boxed_slice(),
                                })
                            } else {
                                fallback_value
                            }
                        }
                    };
                    let kind_name = self.builder.terms_mut().intern_name("kind");
                    entries.push(KernelSummaryRecordEntry::Field {
                        name: kind_name,
                        value: kind,
                    });
                    Some(PlannedSummaryValue {
                        value: self.push_node(KernelSummaryNode::Record {
                            tag: None,
                            entries: entries.into_boxed_slice(),
                        }),
                        mode: fixed_mode,
                        formal_projection_input: None,
                    })
                }
                PackedKernelOwnerNodeKind::PureBuiltin { kind }
                    if direct_summary_fixed_builtin_supported(*kind) =>
                {
                    let mut dependencies = Vec::with_capacity(node_inputs.len());
                    let mut record_entries = Vec::with_capacity(node_inputs.len());
                    let mut names = HashSet::new();
                    for edge in node_inputs {
                        let PackedKernelOwnerEdgeRole::AbiArgument { name } = edge.role else {
                            return None;
                        };
                        if !names.insert(name) {
                            return None;
                        }
                        let name_text = owner.symbol(name)?;
                        let mut value = self.compile_expression(
                            owner_id,
                            edge.expression.0 as usize,
                            actuals,
                            active,
                        )?;
                        if let Some(expected) =
                            pure_builtin_argument_requirement(self.builder, *kind, name_text)
                        {
                            value.value = self.push_node(KernelSummaryNode::Constrain {
                                value: value.value,
                                expected,
                            });
                        }
                        if matches!(kind, KernelPureBuiltinKind::RecordConstructor) {
                            record_entries.push(KernelSummaryRecordEntry::Field {
                                name,
                                value: value.value,
                            });
                        }
                        dependencies.push(value.value);
                    }
                    let result = match kind {
                        KernelPureBuiltinKind::TextConstant
                        | KernelPureBuiltinKind::TextTransform
                        | KernelPureBuiltinKind::TextSlice
                        | KernelPureBuiltinKind::TextConcat
                        | KernelPureBuiltinKind::NumberToText
                        | KernelPureBuiltinKind::TextJoin
                        | KernelPureBuiltinKind::FieldColor => self.builder.terms().text(),
                        KernelPureBuiltinKind::NumberMath
                        | KernelPureBuiltinKind::NumberRound
                        | KernelPureBuiltinKind::NumberProjection
                        | KernelPureBuiltinKind::TextLength => self.builder.terms().number(),
                        KernelPureBuiltinKind::TextPredicate
                        | KernelPureBuiltinKind::Boolean
                        | KernelPureBuiltinKind::BoolToggle => boolean_type(self.builder),
                        KernelPureBuiltinKind::TextToNumber => parsed_number_type(self.builder),
                        KernelPureBuiltinKind::RecordConstructor => {
                            let value = self.push_node(KernelSummaryNode::Record {
                                tag: None,
                                entries: record_entries.into_boxed_slice(),
                            });
                            return Some(PlannedSummaryValue {
                                value,
                                mode: fixed_mode,
                                formal_projection_input: None,
                            });
                        }
                        _ => return None,
                    };
                    let result = self.push_node(KernelSummaryNode::Term(result));
                    Some(PlannedSummaryValue {
                        value: self.push_node(KernelSummaryNode::Sequence {
                            inputs: dependencies.into_boxed_slice(),
                            result,
                        }),
                        mode: fixed_mode,
                        formal_projection_input: None,
                    })
                }
                PackedKernelOwnerNodeKind::When => {
                    let mut selector = None;
                    let mut arms = Vec::new();
                    for edge in node_inputs {
                        match edge.role {
                            PackedKernelOwnerEdgeRole::WhenInput => {
                                if selector.is_some() {
                                    return None;
                                }
                                selector = Some(self.compile_expression(
                                    owner_id,
                                    edge.expression.0 as usize,
                                    actuals,
                                    active,
                                )?);
                            }
                            PackedKernelOwnerEdgeRole::WhenArm => {
                                let arm = owner.nodes().get(edge.expression.0 as usize)?;
                                let PackedKernelOwnerNodeKind::MatchArm { pattern } = arm.kind
                                else {
                                    return None;
                                };
                                let output = self.compile_expression(
                                    owner_id,
                                    edge.expression.0 as usize,
                                    actuals,
                                    active,
                                )?;
                                arms.push(KernelSummarySelectArm {
                                    pattern,
                                    output: output.value,
                                });
                            }
                            _ => return None,
                        }
                    }
                    let selector = selector?;
                    Some(PlannedSummaryValue {
                        value: self.push_node(KernelSummaryNode::Select {
                            selector: selector.value,
                            syntax_discriminating: true,
                            arms: arms.into_boxed_slice(),
                        }),
                        mode: selector.mode,
                        formal_projection_input: None,
                    })
                }
                PackedKernelOwnerNodeKind::MatchArm { .. } => {
                    let outputs = node_inputs
                        .iter()
                        .filter(|edge| matches!(edge.role, PackedKernelOwnerEdgeRole::MatchOutput))
                        .collect::<Vec<_>>();
                    if let [output] = outputs.as_slice() {
                        if node_inputs.len() != 1 {
                            return None;
                        }
                        self.compile_expression(
                            owner_id,
                            output.expression.0 as usize,
                            actuals,
                            active,
                        )
                    } else if outputs.is_empty()
                        && node_inputs.iter().all(|edge| {
                            matches!(edge.role, PackedKernelOwnerEdgeRole::RecordField { .. })
                        })
                        && !node_inputs.is_empty()
                    {
                        let mut entries = Vec::with_capacity(node_inputs.len());
                        for edge in node_inputs {
                            let PackedKernelOwnerEdgeRole::RecordField { name, spread } = edge.role
                            else {
                                return None;
                            };
                            let value = self.compile_expression(
                                owner_id,
                                edge.expression.0 as usize,
                                actuals,
                                active,
                            )?;
                            if spread {
                                entries
                                    .push(KernelSummaryRecordEntry::Spread { value: value.value });
                            } else {
                                entries.push(KernelSummaryRecordEntry::Field {
                                    name,
                                    value: value.value,
                                });
                            }
                        }
                        Some(PlannedSummaryValue {
                            value: self.push_node(KernelSummaryNode::Record {
                                tag: None,
                                entries: entries.into_boxed_slice(),
                            }),
                            mode: fixed_mode,
                            formal_projection_input: None,
                        })
                    } else if outputs.is_empty() && node_inputs.is_empty() {
                        let absent = self.builder.terms().absent();
                        Some(term_value(self, absent))
                    } else {
                        None
                    }
                }
                PackedKernelOwnerNodeKind::Then => {
                    let has_output = node_inputs
                        .iter()
                        .any(|edge| matches!(edge.role, PackedKernelOwnerEdgeRole::ThenOutput));
                    let mut dependencies = Vec::with_capacity(node_inputs.len());
                    let mut selected = None;
                    for edge in node_inputs {
                        if !matches!(
                            edge.role,
                            PackedKernelOwnerEdgeRole::ThenInput
                                | PackedKernelOwnerEdgeRole::ThenOutput
                        ) {
                            return None;
                        }
                        let value = self.compile_expression(
                            owner_id,
                            edge.expression.0 as usize,
                            actuals,
                            active,
                        )?;
                        if matches!(edge.role, PackedKernelOwnerEdgeRole::ThenOutput)
                            || (!has_output
                                && matches!(edge.role, PackedKernelOwnerEdgeRole::ThenInput))
                        {
                            if selected.replace(value.value).is_some() {
                                return None;
                            }
                        }
                        dependencies.push(value.value);
                    }
                    let selected = selected?;
                    Some(PlannedSummaryValue {
                        value: self.push_node(KernelSummaryNode::Sequence {
                            inputs: dependencies.into_boxed_slice(),
                            result: selected,
                        }),
                        mode: fixed_mode,
                        formal_projection_input: None,
                    })
                }
                PackedKernelOwnerNodeKind::Infix { operation } => {
                    let operation = owner.symbol(*operation)?;
                    let mut left = None;
                    let mut right = None;
                    for edge in node_inputs {
                        let slot = match edge.role {
                            PackedKernelOwnerEdgeRole::InfixLeft => &mut left,
                            PackedKernelOwnerEdgeRole::InfixRight => &mut right,
                            _ => return None,
                        };
                        if slot
                            .replace(self.compile_expression(
                                owner_id,
                                edge.expression.0 as usize,
                                actuals,
                                active,
                            )?)
                            .is_some()
                        {
                            return None;
                        }
                    }
                    let (Some(mut left), Some(mut right)) = (left, right) else {
                        return None;
                    };
                    if infix_requires_number_operands(operation) {
                        let number = self.builder.terms().number();
                        left.value = self.push_node(KernelSummaryNode::Constrain {
                            value: left.value,
                            expected: number,
                        });
                        right.value = self.push_node(KernelSummaryNode::Constrain {
                            value: right.value,
                            expected: number,
                        });
                    }
                    let result = if infix_returns_bool(operation) {
                        boolean_type(self.builder)
                    } else {
                        self.builder.terms().number()
                    };
                    let result = self.push_node(KernelSummaryNode::Term(result));
                    Some(PlannedSummaryValue {
                        value: self.push_node(KernelSummaryNode::Sequence {
                            inputs: vec![left.value, right.value].into_boxed_slice(),
                            result,
                        }),
                        mode: fixed_mode,
                        formal_projection_input: None,
                    })
                }
                PackedKernelOwnerNodeKind::Arrow => {
                    let outputs = node_inputs
                        .iter()
                        .filter(|edge| matches!(edge.role, PackedKernelOwnerEdgeRole::ArrowOutput))
                        .collect::<Vec<_>>();
                    let [output] = outputs.as_slice() else {
                        return None;
                    };
                    if node_inputs.len() != 1 {
                        return None;
                    }
                    self.compile_expression(owner_id, output.expression.0 as usize, actuals, active)
                }
                PackedKernelOwnerNodeKind::Delimiter if node_inputs.is_empty() => {
                    Some(PlannedSummaryValue {
                        value: self.push_node(KernelSummaryNode::ContextualHole),
                        mode: fixed_mode,
                        formal_projection_input: None,
                    })
                }
                PackedKernelOwnerNodeKind::Unknown if node_inputs.is_empty() => {
                    let unknown = self.builder.terms().unknown();
                    Some(term_value(self, unknown))
                }
                _ => None,
            }
        })();
        active.remove(&(owner_id, expression));
        result
    }
}

/// Replace definition-constant summary subgraphs with one interned type term.
///
/// The summary evaluator is deliberately lazy across SELECT arms, so this pass
/// never evaluates an input, a requirement, or a nested invocation. It folds
/// only closed term algebra whose value cannot vary by call occurrence. Large
/// library constructors consequently own their constant record/collection
/// shapes once instead of rebuilding and re-interning them on every call.
fn fold_constant_summary_nodes(
    builder: &mut ComponentProgramBuilder,
    nodes: &mut Vec<KernelSummaryNode>,
) -> (u64, u64) {
    let mut constants = vec![None; nodes.len()];
    let mut folded = 0_u64;
    let mut fused_records = 0_u64;
    let mut index = 0;
    while index < nodes.len() {
        let node = nodes[index].clone();
        let constant = match &node {
            KernelSummaryNode::Input(_)
            | KernelSummaryNode::ContextualHole
            | KernelSummaryNode::Constrain { .. }
            | KernelSummaryNode::Invoke { .. } => None,
            KernelSummaryNode::Term(term) => {
                (!builder.terms().has_variable(*term)).then_some(*term)
            }
            KernelSummaryNode::Projection { provider, fields } => {
                constant_summary_projection(builder, *provider, fields, &constants)
            }
            KernelSummaryNode::Sequence {
                inputs: dependencies,
                result,
            } => dependencies
                .iter()
                .all(|dependency| summary_constant(&constants, *dependency).is_some())
                .then(|| summary_constant(&constants, *result))
                .flatten(),
            KernelSummaryNode::Collection {
                kind,
                inputs,
                values,
            } => constant_summary_collection(builder, *kind, inputs, values, &constants),
            KernelSummaryNode::Select { selector, arms, .. } => {
                constant_summary_select(builder, *selector, arms, &constants)
            }
            KernelSummaryNode::Record { tag, entries } => {
                constant_summary_record(builder, *tag, entries, &constants)
            }
        };
        constants[index] = constant;
        if let Some(constant) = constant {
            if !matches!(node, KernelSummaryNode::Term(term) if term == constant) {
                nodes[index] = KernelSummaryNode::Term(constant);
                folded = folded.saturating_add(1);
            }
        } else if let KernelSummaryNode::Record { tag, entries } = &node
            && let Some((selector, syntax_discriminating, variants)) =
                fuse_constant_summary_record_selectors(builder, *tag, entries, nodes, &constants)
        {
            let arms = variants
                .into_iter()
                .map(|(pattern, term)| {
                    let output = KernelSummaryValueId(
                        u32::try_from(nodes.len()).expect("kernel summary value count exceeds u32"),
                    );
                    nodes.push(KernelSummaryNode::Term(term));
                    constants.push(Some(term));
                    KernelSummarySelectArm { pattern, output }
                })
                .collect::<Vec<_>>()
                .into_boxed_slice();
            nodes[index] = KernelSummaryNode::Select {
                selector,
                syntax_discriminating,
                arms,
            };
            fused_records = fused_records.saturating_add(1);
        }
        index += 1;
    }
    (folded, fused_records)
}

/// Fuse a record whose dynamic fields all branch on the same selector into
/// one selector over complete closed record terms. Structural widening of the
/// resulting records is equivalent to the original field-wise joins, while a
/// singleton selector now performs one decision instead of one per field.
fn fuse_constant_summary_record_selectors(
    builder: &mut ComponentProgramBuilder,
    tag: Option<SymbolId>,
    entries: &[KernelSummaryRecordEntry],
    nodes: &[KernelSummaryNode],
    constants: &[Option<TypeTermId>],
) -> Option<(
    KernelSummaryValueId,
    bool,
    Vec<(crate::PackedKernelPattern, TypeTermId)>,
)> {
    let mut selector = None;
    let mut patterns = None::<Vec<crate::PackedKernelPattern>>;
    let mut has_dynamic_field = false;
    let mut syntax_discriminating = false;
    for entry in entries {
        let KernelSummaryRecordEntry::Field { value, .. } = entry else {
            return None;
        };
        if summary_constant(constants, *value).is_some() {
            continue;
        }
        let KernelSummaryNode::Select {
            selector: field_selector,
            syntax_discriminating: field_syntax_discriminating,
            arms,
        } = nodes.get(value.0 as usize)?
        else {
            return None;
        };
        if arms.is_empty()
            || arms.iter().any(|arm| {
                summary_constant(constants, arm.output)
                    .is_none_or(|term| matches!(builder.terms().term(term), TypeTerm::Absent))
            })
        {
            return None;
        }
        if selector
            .replace(*field_selector)
            .is_some_and(|previous| previous != *field_selector)
        {
            return None;
        }
        let field_patterns = arms.iter().map(|arm| arm.pattern).collect::<Vec<_>>();
        if patterns
            .as_ref()
            .is_some_and(|patterns| *patterns != field_patterns)
        {
            return None;
        }
        patterns.get_or_insert(field_patterns);
        syntax_discriminating |= *field_syntax_discriminating;
        has_dynamic_field = true;
    }
    if !has_dynamic_field {
        return None;
    }
    let selector = selector?;
    let patterns = patterns?;
    let mut variants = Vec::with_capacity(patterns.len());
    for (ordinal, pattern) in patterns.into_iter().enumerate() {
        let mut fields = Vec::with_capacity(entries.len());
        for entry in entries {
            let KernelSummaryRecordEntry::Field { name, value } = entry else {
                unreachable!("record-selector fusion rejected spreads above")
            };
            let value = if let Some(value) = summary_constant(constants, *value) {
                value
            } else {
                let KernelSummaryNode::Select { arms, .. } = &nodes[value.0 as usize] else {
                    unreachable!("record-selector fusion validated every dynamic field")
                };
                summary_constant(constants, arms[ordinal].output)
                    .expect("record-selector fusion validated closed arm outputs")
            };
            insert_constant_summary_field(&mut fields, *name, value);
        }
        let record = intern_constant_summary_record(builder, tag, fields);
        variants.push((pattern, record));
    }
    Some((selector, syntax_discriminating, variants))
}

/// Hash-cons pure nodes inside one immutable definition summary.
///
/// This pass canonicalizes the summary DAG after constant folding, but it does
/// not merge nodes that own requirement or evaluation-order effects. In
/// particular, CONSTRAIN, SEQUENCE, and INVOKE remain distinct even when their
/// printed operands match. Pure parents are eligible only when their complete
/// local dependency graph is also pure. The result is one definition-owned
/// computation for repeated type algebra without copying bytecode into callers.
fn deduplicate_summary_nodes(
    nodes: &mut Vec<KernelSummaryNode>,
    result: &mut PlannedSummaryValue,
) -> u64 {
    let old_nodes = std::mem::take(nodes);
    let old_node_count = old_nodes.len();
    let mut relocations = vec![None; old_node_count];
    let mut pure = vec![false; old_node_count];
    let mut active = vec![false; old_node_count];
    let mut interner = HashMap::<u64, Vec<KernelSummaryValueId>>::new();
    let mut canonical = Vec::with_capacity(old_node_count);
    for index in 0..old_node_count {
        canonicalize_summary_node(
            index,
            &old_nodes,
            &mut relocations,
            &mut pure,
            &mut active,
            &mut interner,
            &mut canonical,
        );
    }
    result.value = relocations[result.value.0 as usize]
        .expect("kernel summary result receives a canonical value");
    *nodes = canonical;
    u64::try_from(old_node_count - nodes.len()).expect("summary CSE delta exceeds u64")
}

#[allow(clippy::too_many_arguments)]
fn canonicalize_summary_node(
    index: usize,
    old_nodes: &[KernelSummaryNode],
    relocations: &mut [Option<KernelSummaryValueId>],
    purities: &mut [bool],
    active: &mut [bool],
    interner: &mut HashMap<u64, Vec<KernelSummaryValueId>>,
    canonical: &mut Vec<KernelSummaryNode>,
) -> (KernelSummaryValueId, bool) {
    if let Some(value) = relocations
        .get(index)
        .copied()
        .expect("kernel summary CSE references an existing node")
    {
        return (value, purities[index]);
    }
    if std::mem::replace(&mut active[index], true) {
        panic!("kernel summary CSE found a value cycle through {index}");
    }
    let mut node = old_nodes[index].clone();
    let is_pure = match &mut node {
        KernelSummaryNode::Input(_) | KernelSummaryNode::Term(_) => true,
        KernelSummaryNode::ContextualHole => false,
        KernelSummaryNode::Projection { provider, .. } => {
            let (value, pure) = canonicalize_summary_value(
                *provider,
                old_nodes,
                relocations,
                purities,
                active,
                interner,
                canonical,
            );
            *provider = value;
            pure
        }
        KernelSummaryNode::Constrain { value, .. } => {
            *value = canonicalize_summary_value(
                *value,
                old_nodes,
                relocations,
                purities,
                active,
                interner,
                canonical,
            )
            .0;
            false
        }
        KernelSummaryNode::Sequence {
            inputs: dependencies,
            result,
        } => {
            for dependency in dependencies {
                *dependency = canonicalize_summary_value(
                    *dependency,
                    old_nodes,
                    relocations,
                    purities,
                    active,
                    interner,
                    canonical,
                )
                .0;
            }
            *result = canonicalize_summary_value(
                *result,
                old_nodes,
                relocations,
                purities,
                active,
                interner,
                canonical,
            )
            .0;
            false
        }
        KernelSummaryNode::Collection { inputs, values, .. } => {
            let mut pure = true;
            for value in inputs.iter_mut().chain(values.iter_mut()) {
                let (canonical_value, value_is_pure) = canonicalize_summary_value(
                    *value,
                    old_nodes,
                    relocations,
                    purities,
                    active,
                    interner,
                    canonical,
                );
                *value = canonical_value;
                pure &= value_is_pure;
            }
            pure
        }
        KernelSummaryNode::Invoke {
            inputs: arguments, ..
        } => {
            for argument in arguments {
                *argument = canonicalize_summary_value(
                    *argument,
                    old_nodes,
                    relocations,
                    purities,
                    active,
                    interner,
                    canonical,
                )
                .0;
            }
            false
        }
        KernelSummaryNode::Select { selector, arms, .. } => {
            let (canonical_selector, mut pure) = canonicalize_summary_value(
                *selector,
                old_nodes,
                relocations,
                purities,
                active,
                interner,
                canonical,
            );
            *selector = canonical_selector;
            for arm in arms {
                let (output, output_is_pure) = canonicalize_summary_value(
                    arm.output,
                    old_nodes,
                    relocations,
                    purities,
                    active,
                    interner,
                    canonical,
                );
                arm.output = output;
                pure &= output_is_pure;
            }
            pure
        }
        KernelSummaryNode::Record { entries, .. } => {
            let mut pure = true;
            for entry in entries {
                let value = match entry {
                    KernelSummaryRecordEntry::Field { value, .. }
                    | KernelSummaryRecordEntry::Spread { value } => value,
                };
                let (canonical_value, value_is_pure) = canonicalize_summary_value(
                    *value,
                    old_nodes,
                    relocations,
                    purities,
                    active,
                    interner,
                    canonical,
                );
                *value = canonical_value;
                pure &= value_is_pure;
            }
            pure
        }
    };
    let hash = is_pure.then(|| pure_summary_node_hash(&node));
    let value = match hash {
        Some(hash) => {
            let existing = interner.get(&hash).and_then(|bucket| {
                bucket
                    .iter()
                    .copied()
                    .find(|candidate| canonical[candidate.0 as usize] == node)
            });
            if let Some(existing) = existing {
                existing
            } else {
                let value = KernelSummaryValueId(
                    u32::try_from(canonical.len()).expect("kernel summary value count exceeds u32"),
                );
                canonical.push(node);
                interner.entry(hash).or_default().push(value);
                value
            }
        }
        None => {
            let value = KernelSummaryValueId(
                u32::try_from(canonical.len()).expect("kernel summary value count exceeds u32"),
            );
            canonical.push(node);
            value
        }
    };
    active[index] = false;
    relocations[index] = Some(value);
    purities[index] = is_pure;
    (value, is_pure)
}

#[allow(clippy::too_many_arguments)]
fn canonicalize_summary_value(
    value: KernelSummaryValueId,
    old_nodes: &[KernelSummaryNode],
    relocations: &mut [Option<KernelSummaryValueId>],
    purities: &mut [bool],
    active: &mut [bool],
    interner: &mut HashMap<u64, Vec<KernelSummaryValueId>>,
    canonical: &mut Vec<KernelSummaryNode>,
) -> (KernelSummaryValueId, bool) {
    canonicalize_summary_node(
        value.0 as usize,
        old_nodes,
        relocations,
        purities,
        active,
        interner,
        canonical,
    )
}

fn pure_summary_node_hash(node: &KernelSummaryNode) -> u64 {
    let mut hasher = std::collections::hash_map::DefaultHasher::new();
    match node {
        KernelSummaryNode::Input(input) => {
            0_u8.hash(&mut hasher);
            input.hash(&mut hasher);
        }
        KernelSummaryNode::Term(term) => {
            1_u8.hash(&mut hasher);
            term.hash(&mut hasher);
        }
        KernelSummaryNode::Projection { provider, fields } => {
            2_u8.hash(&mut hasher);
            provider.hash(&mut hasher);
            fields.hash(&mut hasher);
        }
        KernelSummaryNode::Collection {
            kind,
            inputs,
            values,
        } => {
            3_u8.hash(&mut hasher);
            let kind = match kind {
                KernelCollectionOperationKind::List => 0,
                KernelCollectionOperationKind::Set => 1,
                KernelCollectionOperationKind::Map => 2,
            };
            kind.hash(&mut hasher);
            inputs.hash(&mut hasher);
            values.hash(&mut hasher);
        }
        KernelSummaryNode::Select { selector, arms, .. } => {
            4_u8.hash(&mut hasher);
            selector.hash(&mut hasher);
            for arm in arms {
                arm.pattern.hash(&mut hasher);
                arm.output.hash(&mut hasher);
            }
        }
        KernelSummaryNode::Record { tag, entries } => {
            5_u8.hash(&mut hasher);
            tag.hash(&mut hasher);
            for entry in entries {
                match entry {
                    KernelSummaryRecordEntry::Field { name, value } => {
                        0_u8.hash(&mut hasher);
                        name.hash(&mut hasher);
                        value.hash(&mut hasher);
                    }
                    KernelSummaryRecordEntry::Spread { value } => {
                        1_u8.hash(&mut hasher);
                        value.hash(&mut hasher);
                    }
                }
            }
        }
        KernelSummaryNode::ContextualHole
        | KernelSummaryNode::Constrain { .. }
        | KernelSummaryNode::Sequence { .. }
        | KernelSummaryNode::Invoke { .. } => {
            unreachable!("effect-owning summary nodes are never hash-consed")
        }
    }
    hasher.finish()
}

/// Retain only bytecode and occurrence inputs reachable from one summary
/// result. Normalization deliberately leaves node IDs stable while it runs;
/// this final compaction performs one dense relocation after every rewrite is
/// complete. The caller's pre-normalization sharing decision is kept
/// separately, so a large definition cannot become per-call inline code merely
/// because its normalized program is compact.
fn compact_summary_result(
    nodes: &mut Vec<KernelSummaryNode>,
    inputs: &mut Vec<DirectSummaryInput>,
    result: &mut PlannedSummaryValue,
) -> (u64, u64) {
    let old_node_count = nodes.len();
    let old_input_count = inputs.len();
    let mut reachable = vec![false; old_node_count];
    let mut used_inputs = vec![false; old_input_count];
    let mut pending = vec![result.value];
    while let Some(value) = pending.pop() {
        let index = value.0 as usize;
        let Some(seen) = reachable.get_mut(index) else {
            panic!(
                "kernel summary compaction references missing value {}",
                value.0
            )
        };
        if *seen {
            continue;
        }
        *seen = true;
        match &nodes[index] {
            KernelSummaryNode::Input(input) => {
                *used_inputs
                    .get_mut(*input as usize)
                    .expect("kernel summary input belongs to its compact program") = true;
            }
            KernelSummaryNode::Term(_) | KernelSummaryNode::ContextualHole => {}
            KernelSummaryNode::Projection { provider, .. } => pending.push(*provider),
            KernelSummaryNode::Constrain { value, .. } => pending.push(*value),
            KernelSummaryNode::Sequence {
                inputs: dependencies,
                result,
            } => {
                pending.extend(dependencies.iter().copied());
                pending.push(*result);
            }
            KernelSummaryNode::Collection {
                inputs: items,
                values,
                ..
            } => pending.extend(items.iter().chain(values.iter()).copied()),
            KernelSummaryNode::Invoke {
                inputs: arguments, ..
            } => pending.extend(arguments.iter().copied()),
            KernelSummaryNode::Select { selector, arms, .. } => {
                pending.push(*selector);
                pending.extend(arms.iter().map(|arm| arm.output));
            }
            KernelSummaryNode::Record { entries, .. } => {
                pending.extend(entries.iter().map(|entry| match entry {
                    KernelSummaryRecordEntry::Field { value, .. }
                    | KernelSummaryRecordEntry::Spread { value } => *value,
                }));
            }
        }
    }
    for input in [
        match result.mode {
            DirectSummaryMode::Input(input) => Some(input),
            DirectSummaryMode::Fixed { .. } => None,
        },
        result.formal_projection_input,
    ]
    .into_iter()
    .flatten()
    {
        *used_inputs
            .get_mut(input as usize)
            .expect("kernel summary result mode references a compact input") = true;
    }

    let mut value_relocations = vec![None; old_node_count];
    let mut next_value = 0_u32;
    for (index, reachable) in reachable.iter().copied().enumerate() {
        if reachable {
            value_relocations[index] = Some(KernelSummaryValueId(next_value));
            next_value = next_value
                .checked_add(1)
                .expect("kernel summary value count exceeds u32");
        }
    }
    let mut input_relocations = vec![None; old_input_count];
    let mut next_input = 0_u32;
    for (index, used) in used_inputs.iter().copied().enumerate() {
        if used {
            input_relocations[index] = Some(next_input);
            next_input = next_input
                .checked_add(1)
                .expect("kernel summary input count exceeds u32");
        }
    }

    let old_nodes = std::mem::take(nodes);
    nodes.extend(
        old_nodes
            .into_iter()
            .enumerate()
            .filter_map(|(index, mut node)| {
                reachable[index].then(|| {
                    relocate_summary_node(&mut node, &value_relocations, &input_relocations);
                    node
                })
            }),
    );
    let old_inputs = std::mem::take(inputs);
    inputs.extend(
        old_inputs
            .into_iter()
            .enumerate()
            .filter_map(|(index, input)| used_inputs[index].then_some(input)),
    );
    result.value = relocated_summary_value(result.value, &value_relocations);
    result.mode = match result.mode {
        DirectSummaryMode::Fixed { owner, expression } => {
            DirectSummaryMode::Fixed { owner, expression }
        }
        DirectSummaryMode::Input(input) => DirectSummaryMode::Input(
            input_relocations[input as usize]
                .expect("kernel summary result mode input remains reachable"),
        ),
    };
    result.formal_projection_input = result.formal_projection_input.map(|input| {
        input_relocations[input as usize]
            .expect("kernel summary result projection input remains reachable")
    });
    (
        u64::try_from(old_node_count - nodes.len()).expect("summary node delta exceeds u64"),
        u64::try_from(old_input_count - inputs.len()).expect("summary input delta exceeds u64"),
    )
}

fn relocate_summary_node(
    node: &mut KernelSummaryNode,
    values: &[Option<KernelSummaryValueId>],
    inputs: &[Option<u32>],
) {
    match node {
        KernelSummaryNode::Input(input) => {
            *input = inputs[*input as usize].expect("reachable summary input has a relocation");
        }
        KernelSummaryNode::Term(_) | KernelSummaryNode::ContextualHole => {}
        KernelSummaryNode::Projection { provider, .. } => {
            *provider = relocated_summary_value(*provider, values);
        }
        KernelSummaryNode::Constrain { value, .. } => {
            *value = relocated_summary_value(*value, values);
        }
        KernelSummaryNode::Sequence {
            inputs: dependencies,
            result,
        } => {
            for dependency in dependencies {
                *dependency = relocated_summary_value(*dependency, values);
            }
            *result = relocated_summary_value(*result, values);
        }
        KernelSummaryNode::Collection {
            inputs: items,
            values: map_values,
            ..
        } => {
            for value in items.iter_mut().chain(map_values.iter_mut()) {
                *value = relocated_summary_value(*value, values);
            }
        }
        KernelSummaryNode::Invoke {
            inputs: arguments, ..
        } => {
            for argument in arguments {
                *argument = relocated_summary_value(*argument, values);
            }
        }
        KernelSummaryNode::Select { selector, arms, .. } => {
            *selector = relocated_summary_value(*selector, values);
            for arm in arms {
                arm.output = relocated_summary_value(arm.output, values);
            }
        }
        KernelSummaryNode::Record { entries, .. } => {
            for entry in entries {
                let value = match entry {
                    KernelSummaryRecordEntry::Field { value, .. }
                    | KernelSummaryRecordEntry::Spread { value } => value,
                };
                *value = relocated_summary_value(*value, values);
            }
        }
    }
}

fn relocated_summary_value(
    value: KernelSummaryValueId,
    relocations: &[Option<KernelSummaryValueId>],
) -> KernelSummaryValueId {
    relocations[value.0 as usize].expect("reachable summary value has a relocation")
}

fn summary_constant(
    constants: &[Option<TypeTermId>],
    value: KernelSummaryValueId,
) -> Option<TypeTermId> {
    constants.get(value.0 as usize).copied().flatten()
}

fn constant_summary_projection(
    builder: &mut ComponentProgramBuilder,
    provider: KernelSummaryValueId,
    fields: &[SymbolId],
    constants: &[Option<TypeTermId>],
) -> Option<TypeTermId> {
    let mut provider = summary_constant(constants, provider)?;
    for field in fields {
        provider = constant_summary_project_field(builder, provider, *field).unwrap_or_else(|| {
            let field = builder.terms().name(*field).to_owned();
            builder.terms_mut().unresolved_shape(format!(
                "authoritative summary value omits projection `{field}`"
            ))
        });
    }
    Some(provider)
}

fn constant_summary_project_field(
    builder: &mut ComponentProgramBuilder,
    provider: TypeTermId,
    field: SymbolId,
) -> Option<TypeTermId> {
    match builder.terms().term_head(provider) {
        TypeTermHead::Object { shape, .. } => builder.terms().lookup_object_field(shape, field),
        TypeTermHead::Union(members) => {
            let members = builder.terms().term_ids(members).to_vec();
            let projected = members
                .into_iter()
                .filter_map(|member| constant_summary_project_field(builder, member, field))
                .collect::<Vec<_>>();
            (!projected.is_empty()).then(|| builder.terms_mut().union(projected))
        }
        TypeTermHead::VariantSet(variants) => {
            let variants = builder.terms().variant_terms(variants).to_vec();
            let projected = variants
                .into_iter()
                .filter_map(|variant| match variant {
                    VariantTerm::Tagged { fields, .. } => {
                        constant_summary_project_field(builder, fields, field)
                    }
                    VariantTerm::Tag(_) => None,
                })
                .collect::<Vec<_>>();
            (!projected.is_empty()).then(|| builder.terms_mut().union(projected))
        }
        _ => None,
    }
}

fn constant_summary_collection(
    builder: &mut ComponentProgramBuilder,
    kind: KernelCollectionOperationKind,
    inputs: &[KernelSummaryValueId],
    values: &[KernelSummaryValueId],
    constants: &[Option<TypeTermId>],
) -> Option<TypeTermId> {
    let inputs = inputs
        .iter()
        .map(|value| summary_constant(constants, *value))
        .collect::<Option<Vec<_>>>()?;
    let values = values
        .iter()
        .map(|value| summary_constant(constants, *value))
        .collect::<Option<Vec<_>>>()?;
    let item = if inputs.is_empty() {
        match kind {
            KernelCollectionOperationKind::List => builder.terms().open_object(),
            KernelCollectionOperationKind::Set | KernelCollectionOperationKind::Map => {
                builder.terms().unknown()
            }
        }
    } else {
        constant_summary_structural_widen(builder, &inputs)
    };
    Some(match kind {
        KernelCollectionOperationKind::List => builder.terms_mut().list(item),
        KernelCollectionOperationKind::Set => builder.terms_mut().set(item),
        KernelCollectionOperationKind::Map => {
            let value = if values.is_empty() {
                builder.terms().unknown()
            } else {
                constant_summary_structural_widen(builder, &values)
            };
            builder.terms_mut().map(item, value)
        }
    })
}

fn constant_summary_structural_widen(
    builder: &mut ComponentProgramBuilder,
    values: &[TypeTermId],
) -> TypeTermId {
    values
        .iter()
        .copied()
        .fold(None, |current, value| {
            Some(match current {
                None => value,
                Some(current) => builder.terms_mut().structural_widen(current, value),
            })
        })
        .unwrap_or_else(|| builder.terms().absent())
}

fn constant_summary_select(
    builder: &mut ComponentProgramBuilder,
    selector: KernelSummaryValueId,
    arms: &[KernelSummarySelectArm],
    constants: &[Option<TypeTermId>],
) -> Option<TypeTermId> {
    let selector = summary_constant(constants, selector)?;
    let singleton = matches!(
        builder.terms().term(selector),
        TypeTerm::VariantSet(variants) if variants.len() == 1
    );
    let mut candidates = Vec::new();
    for arm in arms {
        if singleton && !constant_summary_pattern_accepts(builder, selector, &arm.pattern) {
            continue;
        }
        let candidate = summary_constant(constants, arm.output)?;
        if !matches!(builder.terms().term(candidate), TypeTerm::Absent) {
            candidates.push(candidate);
            if singleton {
                break;
            }
        }
    }
    Some(constant_summary_structural_widen(builder, &candidates))
}

fn constant_summary_pattern_accepts(
    builder: &ComponentProgramBuilder,
    selector: TypeTermId,
    pattern: &crate::PackedKernelPattern,
) -> bool {
    match pattern {
        crate::PackedKernelPattern::Wildcard | crate::PackedKernelPattern::Binding { .. } => true,
        crate::PackedKernelPattern::Number => {
            matches!(builder.terms().term(selector), TypeTerm::Number)
        }
        crate::PackedKernelPattern::Text => {
            matches!(builder.terms().term(selector), TypeTerm::Text)
        }
        crate::PackedKernelPattern::Bits { width } => {
            matches!(builder.terms().term(selector), TypeTerm::Bits(actual) if actual == *width)
        }
        crate::PackedKernelPattern::Tag { name, .. } => {
            matches!(builder.terms().term(selector), TypeTerm::VariantSet(variants) if variants.iter().any(|variant| variant.tag() == *name))
        }
        crate::PackedKernelPattern::Invalid => false,
    }
}

fn constant_summary_record(
    builder: &mut ComponentProgramBuilder,
    tag: Option<SymbolId>,
    entries: &[KernelSummaryRecordEntry],
    constants: &[Option<TypeTermId>],
) -> Option<TypeTermId> {
    let mut fields = Vec::<(SymbolId, TypeTermId)>::new();
    for entry in entries {
        match entry {
            KernelSummaryRecordEntry::Field { name, value } => {
                let value = summary_constant(constants, *value)?;
                insert_constant_summary_field(&mut fields, *name, value);
            }
            KernelSummaryRecordEntry::Spread { value } => {
                let value = summary_constant(constants, *value)?;
                if !merge_constant_summary_spread(builder, value, &mut fields) {
                    return None;
                }
            }
        }
    }
    Some(intern_constant_summary_record(builder, tag, fields))
}

fn intern_constant_summary_record(
    builder: &mut ComponentProgramBuilder,
    tag: Option<SymbolId>,
    fields: Vec<(SymbolId, TypeTermId)>,
) -> TypeTermId {
    let object = builder.terms_mut().object(fields, false);
    if let Some(tag) = tag {
        let tag = builder.terms().name(tag).to_owned();
        let variant = builder.terms_mut().tagged_variant(tag, object);
        builder.terms_mut().variant_set([variant])
    } else {
        object
    }
}

fn merge_constant_summary_spread(
    builder: &mut ComponentProgramBuilder,
    spread: TypeTermId,
    fields: &mut Vec<(SymbolId, TypeTermId)>,
) -> bool {
    match builder.terms().term_head(spread) {
        TypeTermHead::Object { shape, .. } => {
            let spread_fields = builder.terms().object_fields_for_shape(shape).into_vec();
            for field in spread_fields {
                insert_constant_summary_field(fields, field.name, field.ty);
            }
            true
        }
        TypeTermHead::Union(members) => builder
            .terms()
            .term_ids(members)
            .to_vec()
            .into_iter()
            .all(|member| merge_constant_summary_spread(builder, member, fields)),
        TypeTermHead::VariantSet(variants)
            if builder
                .terms()
                .variant_terms(variants)
                .iter()
                .any(|variant| builder.terms().name(variant.tag()) == "UNPLUGGED") =>
        {
            true
        }
        TypeTermHead::Unknown | TypeTermHead::UnresolvedShape(_) => true,
        _ => false,
    }
}

fn insert_constant_summary_field(
    fields: &mut Vec<(SymbolId, TypeTermId)>,
    name: SymbolId,
    value: TypeTermId,
) {
    if let Some((_, current)) = fields.iter_mut().find(|(candidate, _)| *candidate == name) {
        *current = value;
    } else {
        fields.push((name, value));
    }
}

fn compile_direct_result_summaries(
    builder: &mut ComponentProgramBuilder,
    project: &PackedKernelProjectProgram,
) -> Vec<Option<Arc<CompiledDirectSummary>>> {
    #[cfg(debug_assertions)]
    let traced = traced_summary_owners();
    let targets = project
        .owners()
        .flat_map(|owner| owner.nodes().iter())
        .filter_map(|node| match node.kind {
            PackedKernelOwnerNodeKind::UserCall { target, .. } => Some(target),
            _ => None,
        })
        .collect::<BTreeSet<_>>();
    let supported = targets
        .into_iter()
        .filter(|target| {
            let Some(owner) = project.owner(*target) else {
                return false;
            };
            let trace = false;
            #[cfg(debug_assertions)]
            let trace = traced.contains(&target.0) || trace;
            #[cfg(debug_assertions)]
            if trace {
                eprintln!("kernel-summary-candidate owner={}", target.0);
            }
            direct_result_summary_supported(
                project,
                *target,
                owner.result().0 as usize,
                &mut BTreeSet::new(),
                trace,
            )
        })
        .collect::<BTreeSet<_>>();
    let mut order = Vec::with_capacity(supported.len());
    let mut states = vec![0_u8; project.definition_count()];
    for target in supported.iter().copied() {
        append_direct_summary_order(project, target, &supported, &mut states, &mut order);
    }
    let mut summaries = vec![None; project.definition_count()];
    for target in order {
        let Some(owner) = project.owner(target) else {
            continue;
        };
        let result = owner.result().0 as usize;
        let actuals = (0..owner.formal_count())
            .map(PlannedSummaryActual::Formal)
            .collect::<Vec<_>>();
        let mut compiler = DirectSummaryPlanCompiler {
            builder,
            project,
            summaries: &summaries,
            nodes: Vec::new(),
            inputs: Vec::new(),
            formal_projection_inputs: HashMap::new(),
        };
        let Some(mut result) =
            compiler.compile_expression(target, result, &actuals, &mut BTreeSet::new())
        else {
            continue;
        };
        let shared_bytecode = compiler.nodes.len() >= SHARED_SUMMARY_MIN_NODES;
        let (constant_folded_nodes, selector_fused_records) = compiler.fold_constant_nodes();
        let deduplicated_nodes = compiler.deduplicate_nodes(&mut result);
        let (pruned_nodes, pruned_inputs) = compiler.compact_result(&mut result);
        summaries[target.0 as usize] = Some(Arc::new(CompiledDirectSummary {
            program: Arc::new(KernelSummaryProgram {
                definition: target.0,
                nodes: compiler.nodes.into_boxed_slice(),
                result: result.value,
            }),
            inputs: compiler.inputs.into_boxed_slice(),
            result_mode: result.mode,
            formal_count: owner.formal_count() as usize,
            constant_folded_nodes,
            selector_fused_records,
            deduplicated_nodes,
            pruned_nodes,
            pruned_inputs,
            shared_bytecode,
        }));
    }
    summaries
}

fn append_direct_summary_order(
    project: &PackedKernelProjectProgram,
    target: KernelOwnerId,
    supported: &BTreeSet<KernelOwnerId>,
    states: &mut [u8],
    order: &mut Vec<KernelOwnerId>,
) {
    let index = target.0 as usize;
    match states.get(index).copied() {
        Some(2) => return,
        Some(1) | None => return,
        Some(_) => {}
    }
    states[index] = 1;
    if let Some(owner) = project.owner_at(index) {
        let mut dependencies = BTreeSet::new();
        collect_direct_summary_call_targets(
            owner,
            owner.result().0 as usize,
            &mut BTreeSet::new(),
            &mut dependencies,
        );
        for dependency in dependencies {
            if supported.contains(&dependency) {
                append_direct_summary_order(project, dependency, supported, states, order);
            }
        }
    }
    states[index] = 2;
    order.push(target);
}

fn collect_direct_summary_call_targets(
    owner: PackedKernelOwnerProgramRef<'_>,
    expression: usize,
    active: &mut BTreeSet<usize>,
    targets: &mut BTreeSet<KernelOwnerId>,
) {
    if !active.insert(expression) {
        return;
    }
    let Some(node) = owner.nodes().get(expression) else {
        active.remove(&expression);
        return;
    };
    if let PackedKernelOwnerNodeKind::UserCall { target, .. } = node.kind {
        targets.insert(target);
    }
    for edge in node.inputs(owner) {
        let dependency = edge.expression.0 as usize;
        if dependency < owner.node_count() {
            collect_direct_summary_call_targets(owner, dependency, active, targets);
        }
    }
    active.remove(&expression);
}

fn emit_compiled_direct_summary(
    builder: &mut ComponentProgramBuilder,
    mode_builder: &mut ModeProgramBuilder,
    context: &OwnerCompileContext<'_>,
    source_node: usize,
    output: TypeVariableId,
    output_mode: ModeVariableId,
    actuals: &[CallActual],
    summary: &CompiledDirectSummary,
) -> Result<(), KernelOwnerBuildError> {
    if actuals.len() != summary.formal_count {
        return Err(KernelOwnerBuildError::new(format!(
            "compiled direct summary receives {} actuals for {} formals",
            actuals.len(),
            summary.formal_count
        )));
    }
    let mut call_inputs = Vec::with_capacity(summary.inputs.len());
    let mut input_modes = Vec::with_capacity(summary.inputs.len());
    for input in summary.inputs.iter() {
        match input {
            DirectSummaryInput::FormalProjection {
                formal,
                fields,
                parameter_derived,
            } => {
                let actual = actuals.get(*formal as usize).ok_or_else(|| {
                    KernelOwnerBuildError::new(format!(
                        "compiled direct summary reads missing formal {formal}"
                    ))
                })?;
                let mut steps = Vec::with_capacity(fields.len().max(1));
                if fields.is_empty() {
                    steps.push(KernelSummaryProjectionStep {
                        field: None,
                        consumer: builder.new_variable(),
                    });
                } else {
                    for field in fields.iter().copied() {
                        steps.push(KernelSummaryProjectionStep {
                            field: Some(field),
                            consumer: builder.new_variable(),
                        });
                    }
                }
                if !builder.is_authoritative(actual.variable) || actual.requirement_backflow {
                    // Summary inputs are detached projections so a concrete
                    // call-site provider can never be specialized by the
                    // callee. An open caller formal is different: the
                    // callee's definition-local requirement must flow back to
                    // that formal's private requirement surface. Recreate the
                    // same root/path equation used by a full invocation frame
                    // without allocating that frame.
                    let consumer = steps
                        .last()
                        .expect("a summary projection always has one step")
                        .consumer;
                    let requirement_root = builder.new_contextual_hole();
                    let requirement = requirement_projection(builder, requirement_root, fields);
                    let consumer = builder.variable_term(consumer);
                    let requirement = builder.variable_term(requirement);
                    builder.add_unify(consumer, requirement);
                    let actual = builder.variable_term(actual.requirement);
                    let requirement_root = builder.variable_term(requirement_root);
                    builder.add_unify(actual, requirement_root);
                }
                call_inputs.push(KernelSummaryCallInput::Projection {
                    provider: actual.variable,
                    steps: steps.into_boxed_slice(),
                    parameter_derived: *parameter_derived,
                });
                input_modes.push(projected_mode_variable(
                    mode_builder,
                    context,
                    source_node,
                    &actual.mode_source,
                    fields,
                    &mut BTreeSet::new(),
                )?);
            }
            DirectSummaryInput::External { owner, expression } => {
                let instance = context.principals.get(owner.0 as usize).ok_or_else(|| {
                    KernelOwnerBuildError::new(format!(
                        "compiled direct summary imports missing owner {}",
                        owner.0
                    ))
                })?;
                let variable = instance.expressions.get(*expression).copied().ok_or_else(|| {
                    KernelOwnerBuildError::new(format!(
                        "compiled direct summary imports missing owner {} expression {expression}",
                        owner.0
                    ))
                })?;
                call_inputs.push(KernelSummaryCallInput::Term(
                    builder.variable_term(variable),
                ));
                input_modes.push(instance.expression_modes[*expression]);
            }
        }
    }
    builder.add_summary_call(output, Arc::clone(&summary.program), call_inputs);
    let mode = match summary.result_mode {
        DirectSummaryMode::Fixed { owner, expression } => context
            .principals
            .get(owner.0 as usize)
            .and_then(|instance| instance.expression_modes.get(expression))
            .copied()
            .ok_or_else(|| {
                KernelOwnerBuildError::new(format!(
                    "compiled direct summary mode references missing owner {} expression {expression}",
                    owner.0
                ))
            })?,
        DirectSummaryMode::Input(input) => input_modes
            .get(input as usize)
            .copied()
            .ok_or_else(|| {
                KernelOwnerBuildError::new(format!(
                    "compiled direct summary mode references missing input {input}"
                ))
            })?,
    };
    mode_builder.set(output_mode, ModeEquation::Copy(mode));
    Ok(())
}

fn resolve_packed_input_type(
    builder: &ComponentProgramBuilder,
    context: &OwnerCompileContext<'_>,
    reference: crate::KernelTypeRef,
    index: usize,
    label: &str,
) -> Result<TypeTermId, KernelOwnerBuildError> {
    builder
        .terms()
        .resolve_type_ref(reference)
        .or_else(|| {
            context
                .packed_input_types
                .and_then(|types| types.imports.imported_ref(builder.terms(), reference))
        })
        .ok_or_else(|| {
            KernelOwnerBuildError::new(format!(
                "kernel owner node {index} carries a {label} from another project authority"
            ))
        })
}

fn compile_node(
    builder: &mut ComponentProgramBuilder,
    mode_builder: &mut ModeProgramBuilder,
    invocations: &mut HashMap<InvocationKey, OwnerInstance>,
    specializations: &mut HashMap<SpecializationKey, OwnerSpecialization>,
    residual_modules: &mut ResidualModuleCache,
    compile_work: &mut KernelCompileWork,
    context: &OwnerCompileContext<'_>,
    stack: &mut Vec<KernelOwnerId>,
    index: usize,
    node: &PackedKernelOwnerNode,
    output: TypeVariableId,
    output_mode: ModeVariableId,
    compile_mode: bool,
    mut syntax_discriminated_result: Option<&mut bool>,
    mut syntax_discriminated_root_output: Option<&mut Option<OutputId>>,
) -> Result<(), KernelOwnerBuildError> {
    use crate::PackedKernelOwnerEdgeRole as KernelOwnerEdgeRole;
    use crate::PackedKernelOwnerNodeKind as KernelOwnerNodeKind;
    use crate::PackedKernelPattern as KernelPattern;
    use crate::PackedKernelRenderConstructorKind as KernelRenderConstructorKind;

    let node_inputs = node.inputs(context.input);
    match &node.kind {
        KernelOwnerNodeKind::Known(reference) | KernelOwnerNodeKind::Source(reference) => {
            let provider =
                resolve_packed_input_type(builder, context, *reference, index, "closed type")?;
            builder.add_publish(output, [provider], PublishMode::Replace);
        }
        KernelOwnerNodeKind::Absent => {
            let absent = builder.terms().absent();
            builder.add_publish(output, [absent], PublishMode::Replace);
        }
        KernelOwnerNodeKind::Text | KernelOwnerNodeKind::TextTemplate => {
            let text = builder.terms().text();
            builder.add_publish(output, [text], PublishMode::Replace);
        }
        KernelOwnerNodeKind::Number => {
            let number = builder.terms().number();
            builder.add_publish(output, [number], PublishMode::Replace);
        }
        KernelOwnerNodeKind::Byte => {
            let byte = builder.terms_mut().bytes(crate::BytesTerm::Fixed(1));
            builder.add_publish(output, [byte], PublishMode::Replace);
        }
        KernelOwnerNodeKind::Bits(width) => {
            let bits = builder.terms_mut().bits(*width);
            builder.add_publish(output, [bits], PublishMode::Replace);
        }
        KernelOwnerNodeKind::Tag(tag) => {
            let tag = VariantTerm::Tag(*tag);
            let variants = builder.terms_mut().variant_set([tag]);
            builder.add_publish(output, [variants], PublishMode::Replace);
        }
        KernelOwnerNodeKind::Record { tag } => {
            compile_record(builder, context, index, node, output, *tag)?;
        }
        KernelOwnerNodeKind::Block => {
            let mut results = node_inputs
                .iter()
                .filter(|edge| matches!(edge.role, KernelOwnerEdgeRole::BlockResult));
            let result = results.next().ok_or_else(|| {
                KernelOwnerBuildError::new(format!(
                    "kernel owner node {index} BLOCK has no result edge"
                ))
            })?;
            if results.next().is_some() {
                return Err(KernelOwnerBuildError::new(format!(
                    "kernel owner node {index} BLOCK has multiple result edges"
                )));
            }
            let provider = edge_variable(context, index, result)?;
            builder.add_projection_into(provider, [], output);
        }
        KernelOwnerNodeKind::Collection { kind, .. } => match kind {
            KernelCollectionKind::List | KernelCollectionKind::Set => {
                let items = selected_edge_terms(builder, context, index, node, |role| {
                    matches!(role, KernelOwnerEdgeRole::CollectionItem)
                })?;
                let kind = match kind {
                    KernelCollectionKind::List => KernelCollectionOperationKind::List,
                    KernelCollectionKind::Set => KernelCollectionOperationKind::Set,
                    _ => unreachable!(),
                };
                builder.add_collection(output, kind, items, []);
            }
            KernelCollectionKind::Bytes => {
                let size = node_inputs
                    .iter()
                    .filter(|edge| matches!(edge.role, KernelOwnerEdgeRole::CollectionItem))
                    .count();
                let bytes = builder.terms_mut().bytes(crate::BytesTerm::Fixed(size));
                builder.add_publish(output, [bytes], PublishMode::Replace);
            }
            KernelCollectionKind::Map => {
                let mut keys = Vec::new();
                let mut values = Vec::new();
                for edge in node_inputs {
                    if !matches!(edge.role, KernelOwnerEdgeRole::MapEntry) {
                        continue;
                    }
                    let entry_index = checked_expression_index(
                        edge.expression,
                        context.input.node_count(),
                        "map entry",
                    )?;
                    let entry = &context.input.nodes()[entry_index];
                    if !matches!(entry.kind, KernelOwnerNodeKind::MapEntry) {
                        return Err(KernelOwnerBuildError::new(format!(
                            "kernel owner node {index} map edge targets non-entry node {entry_index}"
                        )));
                    }
                    keys.extend(selected_edge_terms(
                        builder,
                        context,
                        entry_index,
                        entry,
                        |role| matches!(role, KernelOwnerEdgeRole::MapKey),
                    )?);
                    values.extend(selected_edge_terms(
                        builder,
                        context,
                        entry_index,
                        entry,
                        |role| matches!(role, KernelOwnerEdgeRole::MapValue),
                    )?);
                }
                builder.add_collection(output, KernelCollectionOperationKind::Map, keys, values);
            }
        },
        KernelOwnerNodeKind::MapEntry => {
            // The enclosing MAP consumes its exact key/value edges. The entry
            // itself remains an internal delimiter rather than a value type.
            let absent = builder.terms().absent();
            builder.add_publish(output, [absent], PublishMode::Replace);
        }
        KernelOwnerNodeKind::FormalRead { formal, fields } => {
            if !node_inputs.is_empty() {
                return Err(KernelOwnerBuildError::new(format!(
                    "kernel owner node {index} formal read has explicit inputs"
                )));
            }
            let provider = context
                .formals
                .get(*formal as usize)
                .copied()
                .ok_or_else(|| {
                    KernelOwnerBuildError::new(format!(
                        "kernel owner node {index} reads missing formal {formal}"
                    ))
                })?;
            let path = context.input.path(*fields).ok_or_else(|| {
                KernelOwnerBuildError::new(format!(
                    "kernel owner node {index} formal read has an invalid packed path"
                ))
            })?;
            builder.add_projection_into(provider, path.iter(), output);
            let requirement = context
                .formal_requirements
                .get(*formal as usize)
                .copied()
                .ok_or_else(|| {
                    KernelOwnerBuildError::new(format!(
                        "kernel owner node {index} reads missing formal requirement {formal}"
                    ))
                })?;
            let requirement = requirement_projection_iter(builder, requirement, path.iter());
            let requirement = builder.variable_term(requirement);
            let output_term = builder.variable_term(output);
            builder.add_unify(output_term, requirement);
        }
        KernelOwnerNodeKind::ContextRead { formal, fields } => {
            if !node_inputs.is_empty() {
                return Err(KernelOwnerBuildError::new(format!(
                    "kernel owner node {index} context read has explicit inputs"
                )));
            }
            let provider = context
                .formals
                .get(*formal as usize)
                .copied()
                .ok_or_else(|| {
                    KernelOwnerBuildError::new(format!(
                        "kernel owner node {index} reads missing context formal {formal}"
                    ))
                })?;
            let path = context.input.path(*fields).ok_or_else(|| {
                KernelOwnerBuildError::new(format!(
                    "kernel owner node {index} context read has an invalid packed path"
                ))
            })?;
            builder.add_projection_into(provider, path.iter(), output);
            // PASSED is provider-only across the call boundary, but its
            // definition still owns a private structural requirement. Keep
            // that requirement connected to the detached occurrence so
            // diagnostics can compare an explicit PASS value against the
            // callable contract without ever reshaping the captured provider.
            let requirement = context
                .formal_requirements
                .get(*formal as usize)
                .copied()
                .ok_or_else(|| {
                    KernelOwnerBuildError::new(format!(
                        "kernel owner node {index} reads missing context formal requirement {formal}"
                    ))
                })?;
            let requirement = requirement_projection_iter(builder, requirement, path.iter());
            let requirement = builder.variable_term(requirement);
            let output_term = builder.variable_term(output);
            builder.add_unify(output_term, requirement);
        }
        KernelOwnerNodeKind::LexicalRead { fields } => {
            let mut providers = node_inputs
                .iter()
                .filter(|edge| matches!(edge.role, KernelOwnerEdgeRole::ReadProvider));
            let provider = providers.next().ok_or_else(|| {
                KernelOwnerBuildError::new(format!(
                    "kernel owner node {index} lexical read has no provider"
                ))
            })?;
            if providers.next().is_some() || node_inputs.len() != 1 {
                return Err(KernelOwnerBuildError::new(format!(
                    "kernel owner node {index} lexical read must have exactly one provider"
                )));
            }
            let provider = edge_variable(context, index, provider)?;
            let path = context.input.path(*fields).ok_or_else(|| {
                KernelOwnerBuildError::new(format!(
                    "kernel owner node {index} lexical read has an invalid packed path"
                ))
            })?;
            if path.is_empty() {
                builder.add_alias(provider, output);
            } else {
                builder.add_projection_into(provider, path.iter(), output);
            }
        }
        KernelOwnerNodeKind::ValueRead { fields, .. }
        | KernelOwnerNodeKind::DerivedRead { fields } => {
            let mut providers = node_inputs
                .iter()
                .filter(|edge| matches!(edge.role, KernelOwnerEdgeRole::ReadProvider));
            let provider = providers.next().ok_or_else(|| {
                KernelOwnerBuildError::new(format!(
                    "kernel owner node {index} value read has no provider"
                ))
            })?;
            if providers.next().is_some() || node_inputs.len() != 1 {
                return Err(KernelOwnerBuildError::new(format!(
                    "kernel owner node {index} value read must have exactly one provider"
                )));
            }
            let provider = edge_variable(context, index, provider)?;
            let path = context.input.path(*fields).ok_or_else(|| {
                KernelOwnerBuildError::new(format!(
                    "kernel owner node {index} value read has an invalid packed path"
                ))
            })?;
            builder.add_projection_into(provider, path.iter(), output);
        }
        KernelOwnerNodeKind::PatternRead { pattern, fields } => {
            let mut providers = node_inputs
                .iter()
                .filter(|edge| matches!(edge.role, KernelOwnerEdgeRole::ReadProvider));
            let provider = providers.next().ok_or_else(|| {
                KernelOwnerBuildError::new(format!(
                    "kernel owner node {index} pattern read has no provider"
                ))
            })?;
            if providers.next().is_some() || node_inputs.len() != 1 {
                return Err(KernelOwnerBuildError::new(format!(
                    "kernel owner node {index} pattern read must have exactly one provider"
                )));
            }
            let provider = edge_variable(context, index, provider)?;
            let fields = context.input.path(*fields).ok_or_else(|| {
                KernelOwnerBuildError::new(format!(
                    "kernel owner node {index} pattern read has an invalid packed path"
                ))
            })?;
            builder.add_pattern_projection_into(provider, *pattern, fields.iter(), output);
        }
        KernelOwnerNodeKind::CollectionItemRead => {
            let mut providers = node_inputs
                .iter()
                .filter(|edge| matches!(edge.role, KernelOwnerEdgeRole::ReadProvider));
            let provider = providers.next().ok_or_else(|| {
                KernelOwnerBuildError::new(format!(
                    "kernel owner node {index} collection item read has no provider"
                ))
            })?;
            if providers.next().is_some() || node_inputs.len() != 1 {
                return Err(KernelOwnerBuildError::new(format!(
                    "kernel owner node {index} collection item read must have exactly one provider"
                )));
            }
            let provider = edge_variable(context, index, provider)?;
            builder.add_collection_item_projection(provider, output);
        }
        KernelOwnerNodeKind::FreshOut => {
            if !node_inputs.is_empty() {
                return Err(KernelOwnerBuildError::new(format!(
                    "kernel owner node {index} fresh OUT has explicit inputs"
                )));
            }
            // The matching call frame writes constraints into this private
            // variable. Publishing Unknown here would erase that authority.
        }
        KernelOwnerNodeKind::UserCall {
            target,
            inherited_formal,
        } => {
            compile_work.compiled_call_sites = compile_work.compiled_call_sites.saturating_add(1);
            let project = context.project.ok_or_else(|| {
                KernelOwnerBuildError::new(format!(
                    "standalone owner node {index} cannot call owner {}",
                    target.0
                ))
            })?;
            let target_owner = project.owner(*target).ok_or_else(|| {
                KernelOwnerBuildError::new(format!(
                    "kernel owner node {index} calls missing owner {}",
                    target.0
                ))
            })?;
            let mut actuals = vec![None; target_owner.formal_count() as usize];
            for edge in node_inputs {
                let (ordinal, variable) = match edge.role {
                    KernelOwnerEdgeRole::CallArgument { ordinal } => {
                        (ordinal, edge_variable(context, index, edge)?)
                    }
                    KernelOwnerEdgeRole::CallOutArgument { ordinal } => {
                        (ordinal, edge_output_variable(context, index, edge)?)
                    }
                    _ => {
                        return Err(KernelOwnerBuildError::new(format!(
                            "kernel owner node {index} user call has non-argument edge {:?}",
                            edge.role
                        )));
                    }
                };
                let requirement_backflow =
                    matches!(edge.role, KernelOwnerEdgeRole::CallOutArgument { .. })
                        || edge_reads_output_capability(context, index, edge)?;
                // A callback/output occurrence has two independent surfaces:
                // collection data flows forward through `variable`, while the
                // called definition's shape requirements flow backward into a
                // private hole. Coalescing the channels would make a use such
                // as `row.kind` rewrite the checked callback occurrence from a
                // generic value into `{ kind: _ }` and could specialize the
                // original collection producer.
                let requirement = if requirement_backflow {
                    builder.new_contextual_hole()
                } else {
                    variable
                };
                if requirement_backflow {
                    bind_output_capability_requirement(builder, context, edge, requirement)?;
                }
                let slot = actuals.get_mut(ordinal as usize).ok_or_else(|| {
                    KernelOwnerBuildError::new(format!(
                        "kernel owner node {index} supplies out-of-range argument {ordinal}"
                    ))
                })?;
                if slot.is_some() {
                    return Err(KernelOwnerBuildError::new(format!(
                        "kernel owner node {index} repeats argument {ordinal}"
                    )));
                }
                *slot = Some(CallActual {
                    variable,
                    requirement,
                    requirement_backflow,
                    mode: edge_mode_variable(context, index, edge)?,
                    mode_source: mode_source_for_edge(
                        context,
                        context.owner,
                        context.expression_modes,
                        context.formal_mode_sources,
                        edge,
                    )?,
                    static_variants: edge_static_variants(context, edge),
                });
            }
            if let Some(inherited) = inherited_formal {
                let actual = context
                    .formals
                    .get(inherited.caller_ordinal as usize)
                    .copied()
                    .ok_or_else(|| {
                        KernelOwnerBuildError::new(format!(
                            "kernel owner node {index} inherits missing caller formal {}",
                            inherited.caller_ordinal
                        ))
                    })?;
                let actual_requirement = context
                    .formal_requirements
                    .get(inherited.caller_ordinal as usize)
                    .copied()
                    .ok_or_else(|| {
                        KernelOwnerBuildError::new(format!(
                            "kernel owner node {index} inherits missing caller formal requirement {}",
                            inherited.caller_ordinal
                        ))
                    })?;
                let actual_mode = context
                    .formal_modes
                    .get(inherited.caller_ordinal as usize)
                    .copied()
                    .ok_or_else(|| {
                        KernelOwnerBuildError::new(format!(
                            "kernel owner node {index} inherits missing caller mode {}",
                            inherited.caller_ordinal
                        ))
                    })?;
                let actual_mode_source = context
                    .formal_mode_sources
                    .get(inherited.caller_ordinal as usize)
                    .cloned()
                    .ok_or_else(|| {
                        KernelOwnerBuildError::new(format!(
                            "kernel owner node {index} inherits missing caller mode source {}",
                            inherited.caller_ordinal
                        ))
                    })?;
                let slot = actuals
                    .get_mut(inherited.target_ordinal as usize)
                    .ok_or_else(|| {
                        KernelOwnerBuildError::new(format!(
                            "kernel owner node {index} inherits out-of-range target formal {}",
                            inherited.target_ordinal
                        ))
                    })?;
                if slot
                    .replace(CallActual {
                        variable: actual,
                        requirement: actual_requirement,
                        requirement_backflow: false,
                        mode: actual_mode,
                        mode_source: actual_mode_source,
                        static_variants: context
                            .formal_static_variants
                            .get(inherited.caller_ordinal as usize)
                            .cloned()
                            .flatten(),
                    })
                    .is_some()
                {
                    return Err(KernelOwnerBuildError::new(format!(
                        "kernel owner node {index} supplies and inherits target formal {}",
                        inherited.target_ordinal
                    )));
                }
            }
            let actuals = actuals
                .into_iter()
                .enumerate()
                .map(|(ordinal, actual)| {
                    actual.ok_or_else(|| {
                        KernelOwnerBuildError::new(format!(
                            "kernel owner node {index} omits argument {ordinal}"
                        ))
                    })
                })
                .collect::<Result<Vec<_>, _>>()?;
            let initial_state_surface = context.initial_state_surface
                || context
                    .syntax_selected_calls
                    .and_then(|calls| calls.get(index))
                    .copied()
                    .unwrap_or(false);
            let (specialization_key, specialization) = specialize_owner(
                specializations,
                compile_work,
                context.text,
                builder.terms(),
                project,
                context.formal_dependent_expressions,
                *target,
                &actuals,
                initial_state_surface,
            )?;
            if let Some(selected) = syntax_discriminated_result.as_deref_mut() {
                *selected |= specialization.result_syntax_selected;
            }
            let result = checked_expression_index(
                target_owner.result(),
                target_owner.node_count(),
                "user-call result",
            )?;
            // A formal-independent definition is already represented by its
            // principal frame. Reusing that frame is exact: no actual can
            // alter the result, select a different branch, or receive a
            // requirement from the result cone. This is the first flag-day
            // step away from cloning a complete callee residual for every
            // call occurrence.
            if !context.formal_dependent_results[target.0 as usize] {
                compile_work.principal_result_reuses =
                    compile_work.principal_result_reuses.saturating_add(1);
                let provider = builder
                    .variable_term(context.principals[target.0 as usize].expressions[result]);
                builder.add_publish(output, [provider], PublishMode::Replace);
                mode_builder.set(
                    output_mode,
                    ModeEquation::Copy(
                        context.principals[target.0 as usize].expression_modes[result],
                    ),
                );
                return Ok(());
            }
            if let KernelOwnerNodeKind::FormalRead { formal, fields }
            | KernelOwnerNodeKind::ContextRead { formal, fields } =
                &target_owner.nodes()[result].kind
            {
                if !target_owner.nodes()[result].inputs(target_owner).is_empty() {
                    return Err(KernelOwnerBuildError::new(format!(
                        "kernel owner {} direct-result formal read has explicit inputs",
                        target.0
                    )));
                }
                let actual = actuals.get(*formal as usize).ok_or_else(|| {
                    KernelOwnerBuildError::new(format!(
                        "kernel owner {} direct-result summary reads missing formal {formal}",
                        target.0
                    ))
                })?;
                let path = target_owner.path(*fields).ok_or_else(|| {
                    KernelOwnerBuildError::new(format!(
                        "kernel owner {} direct-result formal read has an invalid packed path",
                        target.0
                    ))
                })?;
                let mode_path = path.iter().collect::<Vec<_>>();
                builder.add_projection_into(actual.variable, path.iter(), output);
                if matches!(
                    &target_owner.nodes()[result].kind,
                    KernelOwnerNodeKind::FormalRead { .. }
                ) && (!builder.is_authoritative(actual.variable) || actual.requirement_backflow)
                {
                    let requirement_root = builder.new_contextual_hole();
                    let requirement =
                        requirement_projection_iter(builder, requirement_root, path.iter());
                    let output_term = builder.variable_term(output);
                    let requirement = builder.variable_term(requirement);
                    builder.add_unify(output_term, requirement);
                    let actual_term = builder.variable_term(actual.requirement);
                    let requirement_root = builder.variable_term(requirement_root);
                    builder.add_unify(actual_term, requirement_root);
                }
                let projected_mode = projected_mode_variable(
                    mode_builder,
                    context,
                    index,
                    &actual.mode_source,
                    &mode_path,
                    &mut BTreeSet::new(),
                )?;
                mode_builder.set(output_mode, ModeEquation::Copy(projected_mode));
                compile_work.direct_result_summaries =
                    compile_work.direct_result_summaries.saturating_add(1);
                return Ok(());
            }
            if let Some(Some(summary)) = context.direct_summaries.get(target.0 as usize) {
                emit_compiled_direct_summary(
                    builder,
                    mode_builder,
                    context,
                    index,
                    output,
                    output_mode,
                    &actuals,
                    summary,
                )?;
                compile_work.direct_result_summaries =
                    compile_work.direct_result_summaries.saturating_add(1);
                return Ok(());
            }
            let instance = instantiate_owner(
                builder,
                mode_builder,
                invocations,
                specializations,
                residual_modules,
                compile_work,
                context.text,
                project,
                context.principals,
                context.formal_dependent_results,
                context.formal_dependent_expressions,
                context.direct_summaries,
                &actuals,
                specialization_key,
                specialization,
                stack,
            )?;
            if let Some(receipt) = syntax_discriminated_root_output.as_deref_mut()
                && matches!(target_owner.nodes()[result].kind, KernelOwnerNodeKind::When)
            {
                *receipt = Some(builder.add_output(
                    instance.expressions[result],
                    target_owner.nodes()[result].mode,
                ));
            }
            let provider = builder.variable_term(instance.expressions[result]);
            builder.add_publish(output, [provider], PublishMode::Replace);
            mode_builder.set(
                output_mode,
                ModeEquation::Copy(instance.expression_modes[result]),
            );
        }
        KernelOwnerNodeKind::FieldProjection { field } => {
            let mut providers = node_inputs.iter().filter(|edge| {
                matches!(edge.role, KernelOwnerEdgeRole::AbiArgument { name }
                    if context.input.symbol(name).is_some_and(|name| matches!(name, "$pipe" | "input")))
            });
            let provider = providers.next().ok_or_else(|| {
                KernelOwnerBuildError::new(format!(
                    "kernel owner node {index} field projection has no provider"
                ))
            })?;
            if providers.next().is_some() || node_inputs.len() != 1 {
                return Err(KernelOwnerBuildError::new(format!(
                    "kernel owner node {index} field projection must have exactly one provider"
                )));
            }
            let provider = edge_variable(context, index, provider)?;
            builder.add_projection_into(provider, [*field], output);
        }
        KernelOwnerNodeKind::RenderConstructor { kind } => {
            let mut fields = Vec::with_capacity(node_inputs.len() + 1);
            let mut direction = None;
            for edge in node_inputs {
                let KernelOwnerEdgeRole::AbiArgument { name } = edge.role else {
                    return Err(KernelOwnerBuildError::new(format!(
                        "kernel owner node {index} render constructor has invalid edge {:?}",
                        edge.role
                    )));
                };
                let value = edge_variable(context, index, edge)?;
                let name_text = context.input.symbol(name).ok_or_else(|| {
                    KernelOwnerBuildError::new(format!(
                        "kernel owner node {index} render argument has an invalid symbol"
                    ))
                })?;
                if name_text == "direction" {
                    direction = Some(value);
                }
                let value_term = builder.variable_term(value);
                constrain_render_argument(builder, name_text, value_term);
                fields.push((name, value_term));
            }
            let kind = match kind {
                KernelRenderConstructorKind::Fixed(tag) => {
                    let tag = VariantTerm::Tag(*tag);
                    builder.terms_mut().variant_set([tag])
                }
                KernelRenderConstructorKind::StripeDirection => {
                    let kind = builder.new_authoritative_provider();
                    let row_name = builder.terms_mut().intern_name("Row");
                    let row = builder
                        .terms_mut()
                        .variant_set([VariantTerm::Tag(row_name)]);
                    let stack_name = builder.terms_mut().intern_name("Stack");
                    let stack = builder
                        .terms_mut()
                        .variant_set([VariantTerm::Tag(stack_name)]);
                    let column_name = builder.terms_mut().intern_name("Column");
                    let fallback = builder.terms_mut().union([row, stack]);
                    match direction {
                        Some(direction) => {
                            builder.add_select(
                                kind,
                                direction,
                                [
                                    KernelSelectArm {
                                        pattern: KernelPattern::Tag {
                                            name: row_name,
                                            fields: boon_contract::PathId::ROOT,
                                        },
                                        output: row,
                                    },
                                    KernelSelectArm {
                                        pattern: KernelPattern::Tag {
                                            name: column_name,
                                            fields: boon_contract::PathId::ROOT,
                                        },
                                        output: stack,
                                    },
                                    KernelSelectArm {
                                        pattern: KernelPattern::Wildcard,
                                        output: fallback,
                                    },
                                ],
                            );
                        }
                        None => {
                            builder.add_publish(kind, [fallback], PublishMode::Replace);
                        }
                    }
                    builder.variable_term(kind)
                }
            };
            let kind_name = builder.terms_mut().intern_name("kind");
            fields.push((kind_name, kind));
            let result = builder.terms_mut().object(fields, false);
            builder.add_publish(output, [result], PublishMode::Replace);
        }
        KernelOwnerNodeKind::PureBuiltin { kind } => {
            let mut arguments = BTreeMap::new();
            let mut argument_edges = BTreeMap::new();
            for edge in node_inputs {
                let KernelOwnerEdgeRole::AbiArgument { name } = edge.role else {
                    return Err(KernelOwnerBuildError::new(format!(
                        "kernel owner node {index} pure builtin has invalid edge {:?}",
                        edge.role
                    )));
                };
                let name_text = context.input.symbol(name).ok_or_else(|| {
                    KernelOwnerBuildError::new(format!(
                        "kernel owner node {index} pure builtin argument has an invalid symbol"
                    ))
                })?;
                let value = edge_variable(context, index, edge)?;
                if arguments.insert(name_text, value).is_some() {
                    return Err(KernelOwnerBuildError::new(format!(
                        "kernel owner node {index} pure builtin repeats argument `{name_text}`"
                    )));
                }
                argument_edges.insert(name_text, edge);
                let value = builder.variable_term(value);
                constrain_pure_builtin_argument(builder, *kind, name_text, value);
            }
            let argument = |name: &str| {
                arguments.get(name).copied().ok_or_else(|| {
                    KernelOwnerBuildError::new(format!(
                        "kernel owner {} node {index} pure builtin omits argument `{name}`",
                        context.owner.0
                    ))
                })
            };
            let list_argument = || {
                arguments
                    .get("$pipe")
                    .or_else(|| arguments.get("list"))
                    .copied()
                    .ok_or_else(|| {
                        KernelOwnerBuildError::new(format!(
                            "kernel owner {} node {index} list builtin omits its `$pipe`/`list` input",
                            context.owner.0
                        ))
                    })
            };
            let map_argument = || {
                arguments
                    .get("$pipe")
                    .or_else(|| arguments.get("map"))
                    .copied()
                    .ok_or_else(|| {
                        KernelOwnerBuildError::new(format!(
                            "kernel owner {} node {index} map builtin omits its `$pipe`/`map` input",
                            context.owner.0
                        ))
                    })
            };
            let set_argument = || {
                arguments
                    .get("$pipe")
                    .or_else(|| arguments.get("set"))
                    .copied()
                    .ok_or_else(|| {
                        KernelOwnerBuildError::new(format!(
                            "kernel owner {} node {index} set builtin omits its `$pipe`/`set` input",
                            context.owner.0
                        ))
                    })
            };
            let stream_argument = || {
                arguments
                    .get("$pipe")
                    .or_else(|| arguments.get("stream"))
                    .copied()
                    .ok_or_else(|| {
                        KernelOwnerBuildError::new(format!(
                            "kernel owner {} node {index} stream builtin omits its `$pipe`/`stream` input",
                            context.owner.0
                        ))
                    })
            };
            if matches!(
                kind,
                KernelPureBuiltinKind::ListPredicate
                    | KernelPureBuiltinKind::ListFilter
                    | KernelPureBuiltinKind::ListMap
                    | KernelPureBuiltinKind::ListFind
                    | KernelPureBuiltinKind::ListSort
            ) && let Some(item_edge) = argument_edges.get("item").copied()
            {
                // Contextual collection calls drive the OUT port regardless
                // of whether the caller created it fresh or forwarded an
                // enclosing OUT. This single equation replaces the old
                // special-case projection attached only to a bare identifier.
                let item = edge_output_variable(context, index, item_edge)?;
                builder.add_collection_item_projection(list_argument()?, item);
            }
            if matches!(kind, KernelPureBuiltinKind::ListAppend) {
                // Append preserves the existing list item authority and
                // widens it directionally with the new item. Publishing only
                // `List<item>` loses every variant contributed by the input
                // collection; equality-unifying the two would instead
                // backflow the widened result into both producers.
                let existing_item = builder.new_authoritative_provider();
                builder.add_collection_item_projection(list_argument()?, existing_item);
                let existing_item = builder.variable_term(existing_item);
                let appended_item = builder.variable_term(argument("item")?);
                builder.add_collection(
                    output,
                    KernelCollectionOperationKind::List,
                    [existing_item, appended_item],
                    [],
                );
                return Ok(());
            }
            if matches!(kind, KernelPureBuiltinKind::SetAdd) {
                let set = set_argument()?;
                let existing_item = builder.new_authoritative_provider();
                builder.add_collection_item_projection(set, existing_item);
                let existing_item = builder.variable_term(existing_item);
                let added_item = builder.variable_term(argument("item")?);
                builder.add_collection(
                    output,
                    KernelCollectionOperationKind::Set,
                    [existing_item, added_item],
                    [],
                );
                return Ok(());
            }
            if matches!(kind, KernelPureBuiltinKind::MapUpsert) {
                let map = map_argument()?;
                let entry = argument("entry")?;
                let existing_key = builder.new_authoritative_provider();
                let existing_value = builder.new_authoritative_provider();
                builder.add_map_key_projection(map, existing_key);
                builder.add_map_value_projection(map, existing_value);
                let existing_key_term = builder.variable_term(existing_key);
                let existing_value_term = builder.variable_term(existing_value);
                let key_name = builder.terms_mut().intern_name("key");
                let value_name = builder.terms_mut().intern_name("value");
                let entry_key = builder.add_projection(entry, [key_name]);
                let entry_value = builder.add_projection(entry, [value_name]);
                let entry_key_term = builder.variable_term(entry_key);
                let entry_value_term = builder.variable_term(entry_value);
                builder.add_collection(
                    output,
                    KernelCollectionOperationKind::Map,
                    [existing_key_term, entry_key_term],
                    [existing_value_term, entry_value_term],
                );
                return Ok(());
            }
            let result = match kind {
                KernelPureBuiltinKind::TextConstant
                | KernelPureBuiltinKind::TextTransform
                | KernelPureBuiltinKind::TextSlice
                | KernelPureBuiltinKind::TextConcat
                | KernelPureBuiltinKind::NumberToText
                | KernelPureBuiltinKind::TextJoin
                | KernelPureBuiltinKind::FieldColor => builder.terms().text(),
                KernelPureBuiltinKind::NumberMath
                | KernelPureBuiltinKind::NumberRound
                | KernelPureBuiltinKind::NumberProjection
                | KernelPureBuiltinKind::TextLength
                | KernelPureBuiltinKind::ListLength => builder.terms().number(),
                KernelPureBuiltinKind::TextPredicate
                | KernelPureBuiltinKind::ListPredicate
                | KernelPureBuiltinKind::Boolean
                | KernelPureBuiltinKind::BoolToggle => boolean_type(builder),
                KernelPureBuiltinKind::TextToNumber => parsed_number_type(builder),
                KernelPureBuiltinKind::RecordConstructor => {
                    let fields = node_inputs
                        .iter()
                        .map(|edge| {
                            let KernelOwnerEdgeRole::AbiArgument { name } = edge.role else {
                                unreachable!("pure builtin argument roles were validated above")
                            };
                            let name_text = context.input.symbol(name).expect(
                                "validated pure builtin argument symbol belongs to owner text",
                            );
                            let value = arguments[name_text];
                            (name, builder.variable_term(value))
                        })
                        .collect::<Vec<_>>();
                    builder.terms_mut().object(fields, false)
                }
                KernelPureBuiltinKind::ListFilter | KernelPureBuiltinKind::ListSort => {
                    builder.variable_term(list_argument()?)
                }
                KernelPureBuiltinKind::ListMap => {
                    let item = builder.variable_term(argument("new")?);
                    builder.terms_mut().list(item)
                }
                KernelPureBuiltinKind::ListFind => {
                    let item = builder.variable_term(argument("item")?);
                    found_or_not_found_type(builder, item)
                }
                KernelPureBuiltinKind::ListGet => {
                    let item = builder.new_authoritative_provider();
                    builder.add_collection_item_projection(list_argument()?, item);
                    let item = builder.variable_term(item);
                    found_or_not_found_type(builder, item)
                }
                KernelPureBuiltinKind::ListLatest => {
                    let item = builder.new_authoritative_provider();
                    builder.add_collection_item_projection(list_argument()?, item);
                    builder.variable_term(item)
                }
                KernelPureBuiltinKind::ListAppend => unreachable!("handled above"),
                KernelPureBuiltinKind::ListChunk => {
                    let item = builder.new_authoritative_provider();
                    builder.add_collection_item_projection(list_argument()?, item);
                    let item = builder.variable_term(item);
                    let label_name = builder.terms_mut().intern_name("label");
                    let items_name = builder.terms_mut().intern_name("items");
                    let label = builder.terms().text();
                    let items = builder.terms_mut().list(item);
                    let chunk = builder
                        .terms_mut()
                        .object([(label_name, label), (items_name, items)], false);
                    builder.terms_mut().list(chunk)
                }
                KernelPureBuiltinKind::MapGet => {
                    let map = map_argument()?;
                    let key = argument("key")?;
                    let map_key = builder.new_authoritative_provider();
                    let value = builder.new_authoritative_provider();
                    builder.add_map_key_projection(map, map_key);
                    builder.add_map_value_projection(map, value);
                    let key_term = builder.variable_term(key);
                    let map_key_term = builder.variable_term(map_key);
                    let value_term = builder.variable_term(value);
                    builder.add_unify(key_term, map_key_term);
                    found_or_not_found_type(builder, value_term)
                }
                KernelPureBuiltinKind::MapRemove => {
                    let map = map_argument()?;
                    let key = argument("key")?;
                    let map_key = builder.new_authoritative_provider();
                    builder.add_map_key_projection(map, map_key);
                    let key_term = builder.variable_term(key);
                    let map_key_term = builder.variable_term(map_key);
                    let map_term = builder.variable_term(map);
                    builder.add_unify(key_term, map_key_term);
                    map_term
                }
                KernelPureBuiltinKind::SetRemove => {
                    let set = set_argument()?;
                    let item = argument("item")?;
                    let existing_item = builder.new_authoritative_provider();
                    builder.add_collection_item_projection(set, existing_item);
                    let item_term = builder.variable_term(item);
                    let existing_item_term = builder.variable_term(existing_item);
                    let set_term = builder.variable_term(set);
                    builder.add_unify(item_term, existing_item_term);
                    set_term
                }
                KernelPureBuiltinKind::SetContains => {
                    let set = set_argument()?;
                    let item = argument("item")?;
                    let existing_item = builder.new_authoritative_provider();
                    builder.add_collection_item_projection(set, existing_item);
                    let item_term = builder.variable_term(item);
                    let existing_item_term = builder.variable_term(existing_item);
                    builder.add_unify(item_term, existing_item_term);
                    boolean_type(builder)
                }
                KernelPureBuiltinKind::StreamPulses => {
                    let pulse = builder.terms_mut().variant_tag("Pulse");
                    builder.terms_mut().variant_set([pulse])
                }
                KernelPureBuiltinKind::StreamSkip => builder.variable_term(stream_argument()?),
                KernelPureBuiltinKind::MapUpsert | KernelPureBuiltinKind::SetAdd => {
                    unreachable!("handled above")
                }
            };
            builder.add_publish(output, [result], PublishMode::Replace);
        }
        KernelOwnerNodeKind::FixedAbiCall { result } => {
            if !node_inputs.is_empty() {
                return Err(KernelOwnerBuildError::new(format!(
                    "kernel owner node {index} fixed ABI call has explicit inputs"
                )));
            }
            let result =
                resolve_packed_input_type(builder, context, *result, index, "fixed ABI result")?;
            builder.add_publish(output, [result], PublishMode::Replace);
        }
        KernelOwnerNodeKind::HostEffect { operation } => {
            let operation = context.input.symbol(*operation).ok_or_else(|| {
                KernelOwnerBuildError::new(format!(
                    "kernel owner node {index} host effect has an invalid operation symbol"
                ))
            })?;
            compile_host_effect(builder, context, index, node, output, operation)?;
        }
        KernelOwnerNodeKind::Latest => {
            let branches = selected_edge_terms(builder, context, index, node, |role| {
                matches!(role, KernelOwnerEdgeRole::LatestBranch)
            })?;
            if branches.is_empty() {
                // An empty LATEST carries no value-shape evidence. `Absent`
                // remains a runtime value/type used by explicit absent
                // providers, while the empty selector is a contextual hole.
                // HOLD widening consequently ignores it without claiming that
                // the LATEST expression itself has the Absent value type.
                let unknown = builder.terms().unknown();
                builder.add_publish(output, [unknown], PublishMode::Replace);
            } else {
                builder.add_publish(output, branches, PublishMode::Union);
            }
        }
        KernelOwnerNodeKind::When => {
            let mut selector = None;
            let mut selector_parameter_derived = false;
            let mut arms = Vec::new();
            let possible_arms = possible_when_arm_references(context, index, node)?;
            for edge in node_inputs {
                match edge.role {
                    KernelOwnerEdgeRole::WhenInput => {
                        let selector_expression = edge.expression.0 as usize;
                        selector_parameter_derived = selector_expression
                            < context.input.node_count()
                            && context
                                .formal_dependent_expressions
                                .get(context.owner.0 as usize)
                                .and_then(|dependencies| dependencies.get(selector_expression))
                                .copied()
                                .unwrap_or(false);
                        if selector
                            .replace(edge_variable(context, index, edge)?)
                            .is_some()
                        {
                            return Err(KernelOwnerBuildError::new(format!(
                                "kernel owner node {index} WHEN repeats its selector"
                            )));
                        }
                    }
                    KernelOwnerEdgeRole::WhenArm => {
                        if !possible_arms.contains(&(edge.expression.0 as usize)) {
                            continue;
                        }
                        let arm = referenced_node(context, index, edge)?;
                        let KernelOwnerNodeKind::MatchArm { pattern } = &arm.kind else {
                            return Err(KernelOwnerBuildError::new(format!(
                                "kernel owner node {index} WHEN targets a non-arm expression"
                            )));
                        };
                        let arm = edge_variable(context, index, edge)?;
                        arms.push(KernelSelectArm {
                            pattern: *pattern,
                            output: builder.variable_term(arm),
                        });
                    }
                    _ => {
                        return Err(KernelOwnerBuildError::new(format!(
                            "kernel owner node {index} WHEN has invalid edge {:?}",
                            edge.role
                        )));
                    }
                }
            }
            let selector = selector.ok_or_else(|| {
                KernelOwnerBuildError::new(format!(
                    "kernel owner node {index} WHEN has no selector"
                ))
            })?;
            // A closed match domain constrains a generic selector to the
            // union of its authored patterns. A wildcard or binding arm is
            // deliberately open: it accepts values outside the listed tags,
            // so publishing the explicit arms as a closed VariantSet would
            // incorrectly reject values handled by the fallback branch.
            if !arms.iter().any(|arm| {
                matches!(
                    arm.pattern,
                    KernelPattern::Wildcard | KernelPattern::Binding { .. }
                )
            }) {
                let selector_requirement = builder.variable_term(selector);
                for arm in &arms {
                    if let Some(requirement) =
                        pattern_requirement_term(builder, context.input, &arm.pattern)
                    {
                        builder.add_unify(selector_requirement, requirement);
                    }
                }
            }
            builder.add_select_with_parameter_provenance(
                output,
                selector,
                selector_parameter_derived,
                arms,
            );
        }
        KernelOwnerNodeKind::Then => {
            let has_output = node_inputs
                .iter()
                .any(|edge| matches!(edge.role, KernelOwnerEdgeRole::ThenOutput));
            publish_selected_edges(
                builder,
                context,
                index,
                node,
                output,
                |role| {
                    matches!(role, KernelOwnerEdgeRole::ThenOutput)
                        || (!has_output && matches!(role, KernelOwnerEdgeRole::ThenInput))
                },
                PublishMode::Union,
            )?;
        }
        KernelOwnerNodeKind::Infix { operation } => {
            let operation = context.input.symbol(*operation).ok_or_else(|| {
                KernelOwnerBuildError::new(format!(
                    "kernel owner node {index} infix has an invalid operation symbol"
                ))
            })?;
            let mut left = None;
            let mut right = None;
            for edge in node_inputs {
                let slot = match edge.role {
                    KernelOwnerEdgeRole::InfixLeft => &mut left,
                    KernelOwnerEdgeRole::InfixRight => &mut right,
                    _ => {
                        return Err(KernelOwnerBuildError::new(format!(
                            "kernel owner node {index} infix `{operation}` has invalid edge {:?}",
                            edge.role
                        )));
                    }
                };
                if slot.replace(edge_variable(context, index, edge)?).is_some() {
                    return Err(KernelOwnerBuildError::new(format!(
                        "kernel owner node {index} infix `{operation}` repeats an operand"
                    )));
                }
            }
            let (Some(left), Some(right)) = (left, right) else {
                return Err(KernelOwnerBuildError::new(format!(
                    "kernel owner node {index} infix `{operation}` requires two operands"
                )));
            };
            if infix_requires_number_operands(operation) {
                let number = builder.terms().number();
                let left = builder.variable_term(left);
                builder.add_unify(left, number);
                let right = builder.variable_term(right);
                builder.add_unify(right, number);
            }
            let result = if infix_returns_bool(operation) {
                let false_tag = builder.terms_mut().variant_tag("False");
                let true_tag = builder.terms_mut().variant_tag("True");
                builder.terms_mut().variant_set([false_tag, true_tag])
            } else {
                builder.terms().number()
            };
            builder.add_publish(output, [result], PublishMode::Replace);
        }
        KernelOwnerNodeKind::Draining => {
            publish_selected_edges(
                builder,
                context,
                index,
                node,
                output,
                |role| matches!(role, KernelOwnerEdgeRole::DrainingInput),
                PublishMode::Replace,
            )?;
        }
        KernelOwnerNodeKind::Hold => {
            if context.initial_state_surface {
                publish_selected_edges(
                    builder,
                    context,
                    index,
                    node,
                    output,
                    |role| matches!(role, KernelOwnerEdgeRole::HoldInitial),
                    PublishMode::Replace,
                )?;
            } else {
                // A normal definition or direct call denotes the complete
                // state domain. Only a proven syntax-selected construction
                // occurrence uses the initializer-only surface above.
                publish_selected_edges(
                    builder,
                    context,
                    index,
                    node,
                    output,
                    |role| {
                        matches!(
                            role,
                            KernelOwnerEdgeRole::HoldInitial | KernelOwnerEdgeRole::HoldUpdate
                        )
                    },
                    PublishMode::StructuralWiden,
                )?;
            }
        }
        KernelOwnerNodeKind::MatchArm { .. } => {
            if node_inputs
                .iter()
                .any(|edge| matches!(edge.role, KernelOwnerEdgeRole::MatchOutput))
            {
                publish_selected_edges(
                    builder,
                    context,
                    index,
                    node,
                    output,
                    |role| matches!(role, KernelOwnerEdgeRole::MatchOutput),
                    PublishMode::Replace,
                )?;
            } else if node_inputs
                .iter()
                .any(|edge| matches!(edge.role, KernelOwnerEdgeRole::RecordField { .. }))
            {
                compile_record(builder, context, index, node, output, None)?;
            } else {
                let absent = builder.terms().absent();
                builder.add_publish(output, [absent], PublishMode::Replace);
            }
        }
        KernelOwnerNodeKind::Arrow => {
            publish_selected_edges(
                builder,
                context,
                index,
                node,
                output,
                |role| matches!(role, KernelOwnerEdgeRole::ArrowOutput),
                PublishMode::Replace,
            )?;
        }
        KernelOwnerNodeKind::Flush => {
            let payloads = node_inputs
                .iter()
                .filter(|edge| matches!(edge.role, KernelOwnerEdgeRole::FlushPayload))
                .count();
            if payloads != 1 || node_inputs.len() != 1 {
                return Err(KernelOwnerBuildError::new(format!(
                    "kernel owner node {index} FLUSH must have exactly one payload; found {payloads}",
                )));
            }
            let absent = builder.terms().absent();
            builder.add_publish(output, [absent], PublishMode::Replace);
        }
        KernelOwnerNodeKind::Delimiter => {
            // `[]` is a contextual syntax hole, not the runtime type Unknown.
            // Its consumer supplies the concrete record/collection shape.
            // Keeping this private variable unwritten is the same ownership
            // rule used by FreshOut above.
        }
        KernelOwnerNodeKind::Unknown => {
            let unknown = builder.terms().unknown();
            builder.add_publish(output, [unknown], PublishMode::Replace);
        }
    }
    if compile_mode && !matches!(node.kind, KernelOwnerNodeKind::UserCall { .. }) {
        let equation = node_mode_equation(mode_builder, context, index, node)?;
        mode_builder.set(output_mode, equation);
    }
    Ok(())
}

fn compile_record(
    builder: &mut ComponentProgramBuilder,
    context: &OwnerCompileContext<'_>,
    node_index: usize,
    node: &PackedKernelOwnerNode,
    output: TypeVariableId,
    tag: Option<SymbolId>,
) -> Result<(), KernelOwnerBuildError> {
    let mut entries = Vec::new();
    for edge in node.inputs(context.input) {
        let PackedKernelOwnerEdgeRole::RecordField { name, spread } = edge.role else {
            continue;
        };
        let value = edge_variable(context, node_index, edge)?;
        let value = builder.variable_term(value);
        if spread {
            entries.push(KernelRecordEntry::Spread { value });
        } else {
            entries.push(KernelRecordEntry::Field { name, value });
        }
    }
    builder.add_record(output, tag, entries);
    Ok(())
}

fn publish_selected_edges(
    builder: &mut ComponentProgramBuilder,
    context: &OwnerCompileContext<'_>,
    node_index: usize,
    node: &PackedKernelOwnerNode,
    output: TypeVariableId,
    selected: impl Fn(&PackedKernelOwnerEdgeRole) -> bool,
    mode: PublishMode,
) -> Result<(), KernelOwnerBuildError> {
    let terms = selected_edge_terms(builder, context, node_index, node, selected)?;
    if terms.is_empty() && mode == PublishMode::Replace {
        return Err(KernelOwnerBuildError::new(format!(
            "kernel owner node {node_index} has no selected provider"
        )));
    }
    builder.add_publish(output, terms, mode);
    Ok(())
}

/// Build the invocation-private requirement surface for one formal read.
///
/// Provider projections remain directional and detached. Requirements instead
/// form ordinary equations, so a use such as `width + 1` constrains the fresh
/// call frame without specializing the callable's principal frame or another
/// invocation.
fn requirement_projection(
    builder: &mut ComponentProgramBuilder,
    root: TypeVariableId,
    fields: &[SymbolId],
) -> TypeVariableId {
    requirement_projection_iter(builder, root, fields.iter().copied())
}

fn requirement_projection_iter(
    builder: &mut ComponentProgramBuilder,
    root: TypeVariableId,
    fields: impl IntoIterator<Item = SymbolId>,
) -> TypeVariableId {
    let mut provider = root;
    for field in fields {
        let consumer = builder.new_variable();
        let consumer_term = builder.variable_term(consumer);
        let scaffold = builder.terms_mut().object([(field, consumer_term)], true);
        let provider_term = builder.variable_term(provider);
        builder.add_unify(provider_term, scaffold);
        provider = consumer;
    }
    provider
}

fn pattern_requirement_term(
    builder: &mut ComponentProgramBuilder,
    owner: PackedKernelOwnerProgramRef<'_>,
    pattern: &crate::PackedKernelPattern,
) -> Option<TypeTermId> {
    Some(match pattern {
        crate::PackedKernelPattern::Wildcard
        | crate::PackedKernelPattern::Binding { .. }
        | crate::PackedKernelPattern::Invalid => {
            return None;
        }
        crate::PackedKernelPattern::Number => builder.terms().number(),
        crate::PackedKernelPattern::Text => builder.terms().text(),
        crate::PackedKernelPattern::Bits { width } => builder.terms_mut().bits(*width),
        crate::PackedKernelPattern::Tag { name, fields } => {
            let fields = owner.path(*fields)?;
            if fields.is_empty() {
                let tag = VariantTerm::Tag(*name);
                builder.terms_mut().variant_set([tag])
            } else {
                let fields = fields
                    .iter()
                    .map(|name| {
                        let value = builder.new_contextual_hole();
                        (name, builder.variable_term(value))
                    })
                    .collect::<Vec<_>>();
                let fields = builder.terms_mut().object(fields, true);
                let tag = VariantTerm::Tagged { tag: *name, fields };
                builder.terms_mut().variant_set([tag])
            }
        }
    })
}

fn selected_edge_terms(
    builder: &mut ComponentProgramBuilder,
    context: &OwnerCompileContext<'_>,
    node_index: usize,
    node: &PackedKernelOwnerNode,
    selected: impl Fn(&PackedKernelOwnerEdgeRole) -> bool,
) -> Result<Vec<crate::TypeTermId>, KernelOwnerBuildError> {
    node.inputs(context.input)
        .iter()
        .filter(|edge| selected(&edge.role))
        .map(|edge| {
            let variable = edge_variable(context, node_index, edge)?;
            Ok(builder.variable_term(variable))
        })
        .collect()
}

fn node_mode_equation(
    mode_builder: &mut ModeProgramBuilder,
    context: &OwnerCompileContext<'_>,
    node_index: usize,
    node: &PackedKernelOwnerNode,
) -> Result<ModeEquation, KernelOwnerBuildError> {
    use crate::PackedKernelOwnerEdgeRole as KernelOwnerEdgeRole;
    use crate::PackedKernelOwnerNodeKind as KernelOwnerNodeKind;

    let node_inputs = node.inputs(context.input);
    let copy = |selected: &dyn Fn(&PackedKernelOwnerEdgeRole) -> bool| {
        let mut inputs = node_inputs.iter().filter(|edge| selected(&edge.role));
        let input = inputs.next().ok_or_else(|| {
            KernelOwnerBuildError::new(format!(
                "kernel owner node {node_index} has no provider for its flow mode"
            ))
        })?;
        if inputs.next().is_some() {
            return Err(KernelOwnerBuildError::new(format!(
                "kernel owner node {node_index} has multiple providers for one flow mode"
            )));
        }
        edge_mode_variable(context, node_index, input).map(ModeEquation::Copy)
    };
    match &node.kind {
        KernelOwnerNodeKind::FormalRead { formal, fields }
        | KernelOwnerNodeKind::ContextRead { formal, fields } => {
            let fields = context
                .input
                .path(*fields)
                .ok_or_else(|| {
                    KernelOwnerBuildError::new(format!(
                        "kernel owner node {node_index} formal mode has an invalid packed path"
                    ))
                })?
                .iter()
                .collect::<Vec<_>>();
            let source = context
                .formal_mode_sources
                .get(*formal as usize)
                .ok_or_else(|| {
                    KernelOwnerBuildError::new(format!(
                        "kernel owner node {node_index} reads missing formal mode source {formal}"
                    ))
                })?;
            projected_mode_variable(
                mode_builder,
                context,
                node_index,
                source,
                &fields,
                &mut BTreeSet::new(),
            )
            .map(ModeEquation::Copy)
        }
        KernelOwnerNodeKind::ValueRead {
            fields,
            mode_narrowing,
        } => {
            if let Some(selector) = mode_narrowing {
                let selector = context
                    .expression_modes
                    .get(selector.0 as usize)
                    .copied()
                    .ok_or_else(|| {
                        KernelOwnerBuildError::new(format!(
                            "kernel owner node {node_index} has an out-of-range mode-narrowing selector {}",
                            selector.0
                        ))
                    })?;
                return Ok(ModeEquation::Copy(selector));
            }
            // A whole-value read consumes the provider declaration's public
            // mode. A nested read instead projects the authored field's mode
            // through the finalized public result expression. The latter is
            // required for event fields inside an otherwise continuous
            // record: publishing the record as an owner result must not erase
            // the field's PresentOrAbsent surface.
            let fields = context
                .input
                .path(*fields)
                .ok_or_else(|| {
                    KernelOwnerBuildError::new(format!(
                        "kernel owner node {node_index} value mode has an invalid packed path"
                    ))
                })?
                .iter()
                .collect::<Vec<_>>();
            let mut providers = node_inputs
                .iter()
                .filter(|edge| matches!(edge.role, KernelOwnerEdgeRole::ReadProvider));
            let provider = providers.next().ok_or_else(|| {
                KernelOwnerBuildError::new(format!(
                    "kernel owner node {node_index} value read has no mode provider"
                ))
            })?;
            if providers.next().is_some() {
                return Err(KernelOwnerBuildError::new(format!(
                    "kernel owner node {node_index} value read has multiple mode providers"
                )));
            }
            if fields.is_empty() {
                edge_mode_variable(context, node_index, provider).map(ModeEquation::Copy)
            } else {
                projected_edge_mode_variable(mode_builder, context, node_index, provider, &fields)
                    .map(ModeEquation::Copy)
            }
        }
        KernelOwnerNodeKind::PatternRead { .. } => {
            let providers = node_inputs
                .iter()
                .filter(|edge| matches!(edge.role, KernelOwnerEdgeRole::ReadProvider))
                .count();
            if providers != 1 {
                return Err(KernelOwnerBuildError::new(format!(
                    "kernel owner node {node_index} pattern read has {providers} mode providers instead of one"
                )));
            }
            // A pattern binding is a stable value inside the selected arm.
            // The selector's event mode activates the arm/WHEN expression;
            // copying that mode onto the bound payload would incorrectly turn
            // ordinary uses of `value => value` into event occurrences.
            Ok(ModeEquation::Fixed(node.mode))
        }
        KernelOwnerNodeKind::LexicalRead { fields }
        | KernelOwnerNodeKind::DerivedRead { fields } => {
            let fields = context
                .input
                .path(*fields)
                .ok_or_else(|| {
                    KernelOwnerBuildError::new(format!(
                        "kernel owner node {node_index} lexical mode has an invalid packed path"
                    ))
                })?
                .iter()
                .collect::<Vec<_>>();
            let mut providers = node_inputs
                .iter()
                .filter(|edge| matches!(edge.role, KernelOwnerEdgeRole::ReadProvider));
            let provider = providers.next().ok_or_else(|| {
                KernelOwnerBuildError::new(format!(
                    "kernel owner node {node_index} value read has no mode provider"
                ))
            })?;
            if providers.next().is_some() {
                return Err(KernelOwnerBuildError::new(format!(
                    "kernel owner node {node_index} value read has multiple mode providers"
                )));
            }
            if fields.is_empty() {
                return edge_mode_variable(context, node_index, provider).map(ModeEquation::Copy);
            }
            projected_edge_mode_variable(mode_builder, context, node_index, provider, &fields)
                .map(ModeEquation::Copy)
        }
        KernelOwnerNodeKind::CollectionItemRead => {
            copy(&|role| matches!(role, KernelOwnerEdgeRole::ReadProvider))
        }
        KernelOwnerNodeKind::FreshOut => {
            let mut active = BTreeSet::new();
            match output_binding_collection_item_mode_variable(
                mode_builder,
                context,
                node_index,
                &[],
                &mut active,
            )? {
                Some(provider) => Ok(ModeEquation::Copy(provider)),
                None => Ok(ModeEquation::Fixed(node.mode)),
            }
        }
        KernelOwnerNodeKind::Block => {
            copy(&|role| matches!(role, KernelOwnerEdgeRole::BlockResult))
        }
        KernelOwnerNodeKind::Latest => node_inputs
            .iter()
            .filter(|edge| matches!(edge.role, KernelOwnerEdgeRole::LatestBranch))
            .map(|edge| edge_mode_variable(context, node_index, edge))
            .collect::<Result<Vec<_>, _>>()
            .map(|inputs| ModeEquation::Latest(inputs.into_boxed_slice())),
        KernelOwnerNodeKind::When => copy(&|role| matches!(role, KernelOwnerEdgeRole::WhenInput)),
        KernelOwnerNodeKind::Draining => {
            copy(&|role| matches!(role, KernelOwnerEdgeRole::DrainingInput))
        }
        KernelOwnerNodeKind::MatchArm { .. } => {
            if node_inputs
                .iter()
                .any(|edge| matches!(edge.role, KernelOwnerEdgeRole::MatchOutput))
            {
                copy(&|role| matches!(role, KernelOwnerEdgeRole::MatchOutput))
            } else if node_inputs
                .iter()
                .any(|edge| matches!(edge.role, KernelOwnerEdgeRole::RecordField { .. }))
            {
                Ok(ModeEquation::Fixed(node.mode))
            } else {
                Ok(ModeEquation::Fixed(FlowMode::Absent))
            }
        }
        KernelOwnerNodeKind::Arrow => {
            if node_inputs
                .iter()
                .any(|edge| matches!(edge.role, KernelOwnerEdgeRole::ArrowOutput))
            {
                copy(&|role| matches!(role, KernelOwnerEdgeRole::ArrowOutput))
            } else {
                Ok(ModeEquation::Fixed(FlowMode::Absent))
            }
        }
        KernelOwnerNodeKind::PureBuiltin {
            kind: KernelPureBuiltinKind::ListMap,
        } => copy(&|role| {
            matches!(role, KernelOwnerEdgeRole::AbiArgument { name }
                if context.input.symbol(*name) == Some("new"))
        }),
        KernelOwnerNodeKind::PureBuiltin {
            kind: KernelPureBuiltinKind::ListLatest,
        } => copy(&|role| {
            matches!(role, KernelOwnerEdgeRole::AbiArgument { name }
                if context.input.symbol(*name).is_some_and(|name| matches!(name, "$pipe" | "list")))
        }),
        KernelOwnerNodeKind::FieldProjection { .. } => copy(&|role| {
            matches!(role, KernelOwnerEdgeRole::AbiArgument { name }
                if context.input.symbol(*name).is_some_and(|name| matches!(name, "$pipe" | "input")))
        }),
        KernelOwnerNodeKind::UserCall { .. } => Err(KernelOwnerBuildError::new(format!(
            "kernel owner node {node_index} user-call mode must come from its invocation"
        ))),
        KernelOwnerNodeKind::Known(_)
        | KernelOwnerNodeKind::Source(_)
        | KernelOwnerNodeKind::Absent
        | KernelOwnerNodeKind::Text
        | KernelOwnerNodeKind::TextTemplate
        | KernelOwnerNodeKind::Number
        | KernelOwnerNodeKind::Byte
        | KernelOwnerNodeKind::Bits(_)
        | KernelOwnerNodeKind::Tag(_)
        | KernelOwnerNodeKind::Record { .. }
        | KernelOwnerNodeKind::Collection { .. }
        | KernelOwnerNodeKind::MapEntry
        | KernelOwnerNodeKind::RenderConstructor { .. }
        | KernelOwnerNodeKind::PureBuiltin { .. }
        | KernelOwnerNodeKind::FixedAbiCall { .. }
        | KernelOwnerNodeKind::HostEffect { .. }
        | KernelOwnerNodeKind::Then
        | KernelOwnerNodeKind::Infix { .. }
        | KernelOwnerNodeKind::Hold
        | KernelOwnerNodeKind::Flush
        | KernelOwnerNodeKind::Delimiter
        | KernelOwnerNodeKind::Unknown => Ok(ModeEquation::Fixed(node.mode)),
    }
}

fn possible_when_arm_references(
    context: &OwnerCompileContext<'_>,
    node_index: usize,
    node: &PackedKernelOwnerNode,
) -> Result<BTreeSet<usize>, KernelOwnerBuildError> {
    let inputs = node.inputs(context.input);
    let arm_edges = inputs
        .iter()
        .filter(|edge| matches!(edge.role, PackedKernelOwnerEdgeRole::WhenArm))
        .collect::<Vec<_>>();
    let selector = inputs
        .iter()
        .find(|edge| matches!(edge.role, PackedKernelOwnerEdgeRole::WhenInput))
        .and_then(|edge| edge_static_variants(context, edge));
    let Some(selector) = selector else {
        return Ok(arm_edges
            .into_iter()
            .map(|edge| edge.expression.0 as usize)
            .collect());
    };
    let mut selected = BTreeSet::new();
    for tag in selector.iter().copied() {
        for edge in &arm_edges {
            let arm = referenced_node(context, node_index, edge)?;
            let PackedKernelOwnerNodeKind::MatchArm { pattern } = &arm.kind else {
                return Err(KernelOwnerBuildError::new(format!(
                    "kernel owner node {node_index} WHEN targets a non-arm expression"
                )));
            };
            if static_pattern_accepts_tag(pattern, tag) {
                selected.insert(edge.expression.0 as usize);
                break;
            }
        }
    }
    Ok(selected)
}

fn infix_returns_bool(operation: &str) -> bool {
    matches!(operation, "==" | "!=" | ">" | "<" | ">=" | "<=")
}

fn boolean_type(builder: &mut ComponentProgramBuilder) -> crate::TypeTermId {
    let false_tag = builder.terms_mut().variant_tag("False");
    let true_tag = builder.terms_mut().variant_tag("True");
    builder.terms_mut().variant_set([false_tag, true_tag])
}

fn found_or_not_found_type(
    builder: &mut ComponentProgramBuilder,
    item: crate::TypeTermId,
) -> crate::TypeTermId {
    let value = builder.terms_mut().intern_name("value");
    let fields = builder.terms_mut().object([(value, item)], false);
    let found = builder.terms_mut().tagged_variant("Found", fields);
    let not_found = builder.terms_mut().variant_tag("NotFound");
    builder
        .terms_mut()
        .variant_set_preserving_order([found, not_found])
}

fn parsed_number_type(builder: &mut ComponentProgramBuilder) -> crate::TypeTermId {
    let value = builder.terms_mut().intern_name("value");
    let number = builder.terms().number();
    let parsed_fields = builder.terms_mut().object([(value, number)], false);
    let parsed = builder.terms_mut().tagged_variant("Parsed", parsed_fields);

    let reason = builder.terms_mut().intern_name("reason");
    let position = builder.terms_mut().intern_name("position");
    let text = builder.terms().text();
    let number = builder.terms().number();
    let invalid_fields = builder
        .terms_mut()
        .object([(reason, text), (position, number)], false);
    let invalid = builder
        .terms_mut()
        .tagged_variant("InvalidNumber", invalid_fields);
    builder
        .terms_mut()
        .variant_set_preserving_order([parsed, invalid])
}

fn rounding_rule_type(builder: &mut ComponentProgramBuilder) -> crate::TypeTermId {
    let variants = ExactRoundingRule::ALL
        .into_iter()
        .map(|rule| builder.terms_mut().variant_tag(rule.as_tag()))
        .collect::<Vec<_>>();
    builder.terms_mut().variant_set(variants)
}

fn compile_host_effect(
    builder: &mut ComponentProgramBuilder,
    context: &OwnerCompileContext<'_>,
    index: usize,
    node: &PackedKernelOwnerNode,
    output: TypeVariableId,
    operation: &str,
) -> Result<(), KernelOwnerBuildError> {
    let spec = host_effect_spec(operation).ok_or_else(|| {
        KernelOwnerBuildError::new(format!(
            "kernel owner node {index} names unknown host effect `{operation}`"
        ))
    })?;
    if spec.result_policy != ResultPolicySpec::ReturnValue {
        return Err(KernelOwnerBuildError::new(format!(
            "kernel owner node {index} host effect `{operation}` has no return value"
        )));
    }
    let schema = spec.schema.ok_or_else(|| {
        KernelOwnerBuildError::new(format!(
            "kernel owner node {index} host effect `{operation}` has no type schema"
        ))
    })?;
    let ValueType::Record {
        fields,
        open: false,
    } = &schema.intent
    else {
        return Err(KernelOwnerBuildError::new(format!(
            "kernel owner node {index} host effect `{operation}` requires a closed record intent"
        )));
    };

    let pipe_field = fields.first().map(|field| field.name);
    let mut arguments = BTreeMap::<&str, TypeVariableId>::new();
    for edge in node.inputs(context.input) {
        let PackedKernelOwnerEdgeRole::AbiArgument { name } = edge.role else {
            return Err(KernelOwnerBuildError::new(format!(
                "kernel owner node {index} host effect has invalid edge {:?}",
                edge.role
            )));
        };
        let name = context.input.symbol(name).ok_or_else(|| {
            KernelOwnerBuildError::new(format!(
                "kernel owner node {index} host effect argument has an invalid symbol"
            ))
        })?;
        let name = if name == "$pipe" {
            pipe_field.ok_or_else(|| {
                KernelOwnerBuildError::new(format!(
                    "kernel owner node {index} cannot pipe into argument-free host effect `{operation}`"
                ))
            })?
        } else {
            name
        };
        if !fields.iter().any(|field| field.name == name) {
            return Err(KernelOwnerBuildError::new(format!(
                "kernel owner node {index} host effect `{operation}` has no argument `{name}`"
            )));
        }
        let value = edge_variable(context, index, edge)?;
        if arguments.insert(name, value).is_some() {
            return Err(KernelOwnerBuildError::new(format!(
                "kernel owner node {index} host effect `{operation}` repeats argument `{name}`"
            )));
        }
    }
    for field in fields {
        let Some(actual) = arguments.get(field.name).copied() else {
            if schema
                .intent_defaults
                .iter()
                .any(|default| default.field_name == field.name)
            {
                continue;
            }
            return Err(KernelOwnerBuildError::new(format!(
                "kernel owner node {index} host effect `{operation}` omits required argument `{}`",
                field.name
            )));
        };
        let expected = effect_schema_type_to_checked(&field.value_type);
        let expected = builder
            .terms_mut()
            .import_checked_type(&expected, &mut |_| {
                unreachable!("host ABI types are closed")
            });
        let actual = builder.variable_term(actual);
        builder.add_unify(actual, expected);
    }

    let result = effect_schema_type_to_checked(&schema.result);
    let result = builder
        .terms_mut()
        .import_checked_type(&result, &mut |_| unreachable!("host ABI types are closed"));
    builder.add_publish(output, [result], PublishMode::Replace);
    Ok(())
}

fn effect_schema_type_to_checked(value_type: &ValueType) -> Type {
    match value_type {
        ValueType::Number => Type::Number,
        ValueType::Text => Type::Text,
        ValueType::Bytes { fixed_len } => {
            Type::Bytes(fixed_len.map_or(BytesType::Dynamic, |length| {
                BytesType::Fixed(
                    usize::try_from(length).expect("host ABI fixed byte length fits usize"),
                )
            }))
        }
        ValueType::List { item } => Type::List(Type::shared(effect_schema_type_to_checked(item))),
        ValueType::Record { fields, open } => Type::object(ObjectShape::from_ordered_fields(
            fields.iter().map(|field| {
                (
                    field.name.to_owned(),
                    effect_schema_type_to_checked(&field.value_type),
                )
            }),
            *open,
        )),
        ValueType::Variant { variants } => Type::VariantSet(
            variants
                .iter()
                .map(|variant| {
                    if variant.fields.is_empty() {
                        Variant::Tag(variant.tag.to_owned())
                    } else {
                        Variant::Tagged {
                            tag: variant.tag.to_owned(),
                            fields: ObjectShape::from_ordered_fields(
                                variant.fields.iter().map(|field| {
                                    (
                                        field.name.to_owned(),
                                        effect_schema_type_to_checked(&field.value_type),
                                    )
                                }),
                                false,
                            ),
                        }
                    }
                })
                .collect(),
        ),
    }
}

fn constrain_pure_builtin_argument(
    builder: &mut ComponentProgramBuilder,
    kind: KernelPureBuiltinKind,
    name: &str,
    value: TypeTermId,
) {
    if let Some(expected) = pure_builtin_argument_requirement(builder, kind, name) {
        builder.add_unify(value, expected);
    }
}

fn pure_builtin_argument_requirement(
    builder: &mut ComponentProgramBuilder,
    kind: KernelPureBuiltinKind,
    name: &str,
) -> Option<TypeTermId> {
    match kind {
        KernelPureBuiltinKind::TextConstant => None,
        KernelPureBuiltinKind::TextTransform
        | KernelPureBuiltinKind::TextLength
        | KernelPureBuiltinKind::TextPredicate => Some(builder.terms().text()),
        KernelPureBuiltinKind::TextToNumber if matches!(name, "$pipe" | "input" | "text") => {
            Some(builder.terms().text())
        }
        KernelPureBuiltinKind::TextToNumber if name == "radix" => Some(builder.terms().number()),
        KernelPureBuiltinKind::TextToNumber => None,
        KernelPureBuiltinKind::TextSlice if matches!(name, "$pipe" | "input") => {
            Some(builder.terms().text())
        }
        KernelPureBuiltinKind::TextSlice => Some(builder.terms().number()),
        // Text/concat accepts the runtime's text-formattable scalar family.
        // That is a validation contract, not an equality constraint.
        KernelPureBuiltinKind::TextConcat | KernelPureBuiltinKind::FieldColor => None,
        KernelPureBuiltinKind::RecordConstructor
            if matches!(
                name,
                "azimuth" | "altitude" | "spread" | "intensity" | "radius" | "softness"
            ) =>
        {
            Some(builder.terms().number())
        }
        KernelPureBuiltinKind::RecordConstructor => None,
        KernelPureBuiltinKind::TextJoin if name == "$pipe" => {
            let item = builder.terms().text();
            Some(builder.terms_mut().list(item))
        }
        KernelPureBuiltinKind::TextJoin => Some(builder.terms().text()),
        KernelPureBuiltinKind::NumberToText if name == "prefix" => Some(boolean_type(builder)),
        KernelPureBuiltinKind::NumberToText | KernelPureBuiltinKind::NumberMath => {
            Some(builder.terms().number())
        }
        KernelPureBuiltinKind::NumberRound if name == "using" => Some(rounding_rule_type(builder)),
        KernelPureBuiltinKind::NumberRound => Some(builder.terms().number()),
        KernelPureBuiltinKind::NumberProjection if name == "zoom" => None,
        KernelPureBuiltinKind::NumberProjection => Some(builder.terms().number()),
        KernelPureBuiltinKind::Boolean | KernelPureBuiltinKind::BoolToggle
            if matches!(name, "$pipe" | "value" | "left" | "right") =>
        {
            Some(boolean_type(builder))
        }
        KernelPureBuiltinKind::Boolean | KernelPureBuiltinKind::BoolToggle => None,
        KernelPureBuiltinKind::ListLength
        | KernelPureBuiltinKind::ListPredicate
        | KernelPureBuiltinKind::ListFilter
        | KernelPureBuiltinKind::ListMap
        | KernelPureBuiltinKind::ListFind
        | KernelPureBuiltinKind::ListGet
        | KernelPureBuiltinKind::ListLatest
        | KernelPureBuiltinKind::ListAppend
        | KernelPureBuiltinKind::ListSort
        | KernelPureBuiltinKind::ListChunk
            if matches!(name, "$pipe" | "list") =>
        {
            let item = builder.new_variable();
            let item = builder.variable_term(item);
            Some(builder.terms_mut().list(item))
        }
        KernelPureBuiltinKind::ListFilter | KernelPureBuiltinKind::ListFind if name == "if" => {
            Some(boolean_type(builder))
        }
        KernelPureBuiltinKind::ListChunk if name == "size" => Some(builder.terms().number()),
        KernelPureBuiltinKind::ListGet if name == "position" => Some(builder.terms().number()),
        KernelPureBuiltinKind::ListLength
        | KernelPureBuiltinKind::ListPredicate
        | KernelPureBuiltinKind::ListFilter
        | KernelPureBuiltinKind::ListMap
        | KernelPureBuiltinKind::ListFind
        | KernelPureBuiltinKind::ListGet
        | KernelPureBuiltinKind::ListLatest
        | KernelPureBuiltinKind::ListAppend
        | KernelPureBuiltinKind::ListSort
        | KernelPureBuiltinKind::ListChunk => None,
        KernelPureBuiltinKind::MapGet
        | KernelPureBuiltinKind::MapUpsert
        | KernelPureBuiltinKind::MapRemove
        | KernelPureBuiltinKind::SetAdd
        | KernelPureBuiltinKind::SetRemove
        | KernelPureBuiltinKind::SetContains => None,
        KernelPureBuiltinKind::StreamPulses if matches!(name, "$pipe" | "count") => {
            Some(builder.terms().number())
        }
        KernelPureBuiltinKind::StreamPulses => None,
        KernelPureBuiltinKind::StreamSkip if name == "count" => Some(builder.terms().number()),
        KernelPureBuiltinKind::StreamSkip => None,
    }
}

fn constrain_render_argument(builder: &mut ComponentProgramBuilder, name: &str, value: TypeTermId) {
    if let Some(expected) = render_argument_requirement(builder, name) {
        builder.add_unify(value, expected);
    }
}

fn render_argument_requirement(
    builder: &mut ComponentProgramBuilder,
    name: &str,
) -> Option<TypeTermId> {
    match name {
        "text"
        | "label"
        | "target"
        | "input_id"
        | "source"
        | "artifact_id"
        | "bootstrap_source"
        | "bootstrap_artifact_id" => Some(builder.terms().text()),
        "gap" | "revision" => Some(builder.terms().number()),
        "visible" | "selected" | "checked" | "focus" => {
            let false_tag = builder.terms_mut().variant_tag("False");
            let true_tag = builder.terms_mut().variant_tag("True");
            Some(builder.terms_mut().variant_set([false_tag, true_tag]))
        }
        "root" | "child" => Some(builder.terms().render_contract()),
        "items" | "contents" => {
            let item = builder.terms().render_contract();
            Some(builder.terms_mut().list(item))
        }
        "element" | "style" | "placeholder" | "lights" | "geometry" | "activate_focus" => {
            Some(builder.terms().open_object())
        }
        // Stripe direction is a Row/Column tag even though the legacy ABI
        // models the validation slot as an open object.
        "direction" => None,
        _ => None,
    }
}

fn infix_requires_number_operands(operation: &str) -> bool {
    matches!(
        operation,
        "+" | "-" | "*" | "/" | "%" | ">" | "<" | ">=" | "<="
    )
}

type ActiveModeProjection = BTreeSet<(KernelOwnerId, usize, usize, bool, bool)>;

fn owner_mode_input<'a>(
    context: &'a OwnerCompileContext<'a>,
    owner: KernelOwnerId,
) -> Result<PackedKernelOwnerProgramRef<'a>, KernelOwnerBuildError> {
    if owner == context.owner {
        return Ok(context.input);
    }
    context
        .project
        .and_then(|project| project.owner(owner))
        .ok_or_else(|| {
            KernelOwnerBuildError::new(format!(
                "owner {} mode projection references missing owner {}",
                context.owner.0, owner.0
            ))
        })
}

fn mode_source_for_edge(
    context: &OwnerCompileContext<'_>,
    owner: KernelOwnerId,
    expression_modes: &Arc<[ModeVariableId]>,
    formal_sources: &Arc<[ModeSource]>,
    edge: &crate::PackedKernelOwnerInputEdge,
) -> Result<ModeSource, KernelOwnerBuildError> {
    let input = owner_mode_input(context, owner)?;
    let reference = edge.expression.0 as usize;
    if reference < input.node_count() {
        return Ok(ModeSource::Expression {
            owner,
            expression: reference,
            expression_modes: Arc::clone(expression_modes),
            formal_sources: Arc::clone(formal_sources),
        });
    }
    let external_index = reference - input.node_count();
    let external = input.external_expressions().get(external_index).ok_or_else(|| {
        KernelOwnerBuildError::new(format!(
            "owner {} mode projection references external expression {external_index} outside 0..{}",
            owner.0,
            input.external_expressions().len()
        ))
    })?;
    let project = context.project.ok_or_else(|| {
        KernelOwnerBuildError::new(format!(
            "owner {} mode projection references an external owner outside a project",
            owner.0
        ))
    })?;
    let target = project.owner(external.owner).ok_or_else(|| {
        KernelOwnerBuildError::new(format!(
            "owner {} mode projection references missing owner {}",
            owner.0, external.owner.0
        ))
    })?;
    let target_instance = context
        .principals
        .get(external.owner.0 as usize)
        .ok_or_else(|| {
            KernelOwnerBuildError::new(format!(
                "owner {} mode projection references missing principal owner {}",
                owner.0, external.owner.0
            ))
        })?;
    let expression = match external.target {
        KernelExternalTarget::Expression(expression) => {
            checked_expression_index(expression, target.node_count(), "external mode projection")?
        }
        KernelExternalTarget::Result => checked_expression_index(
            target.result(),
            target.node_count(),
            "external result mode projection",
        )?,
    };
    Ok(ModeSource::Expression {
        owner: external.owner,
        expression,
        expression_modes: Arc::clone(&target_instance.expression_modes),
        formal_sources: Arc::clone(&target_instance.formal_mode_sources),
    })
}

fn selected_mode_edge<'a>(
    owner: PackedKernelOwnerProgramRef<'a>,
    node: &'a PackedKernelOwnerNode,
    selected: impl Fn(&PackedKernelOwnerEdgeRole) -> bool,
) -> Option<&'a crate::PackedKernelOwnerInputEdge> {
    node.inputs(owner).iter().find(|edge| selected(&edge.role))
}

fn merge_projected_modes(
    mode_builder: &mut ModeProgramBuilder,
    mut inputs: Vec<ModeVariableId>,
    fallback: ModeVariableId,
) -> ModeVariableId {
    inputs.sort_unstable();
    inputs.dedup();
    match inputs.as_slice() {
        [] => fallback,
        [input] => *input,
        _ => {
            let output = mode_builder.new_variable(FlowMode::Continuous);
            mode_builder.set(output, ModeEquation::Latest(inputs.into_boxed_slice()));
            output
        }
    }
}

fn merge_contextual_call_modes(
    mode_builder: &mut ModeProgramBuilder,
    mut inputs: Vec<ModeVariableId>,
    result: FlowMode,
    fallback: ModeVariableId,
) -> ModeVariableId {
    inputs.sort_unstable();
    inputs.dedup();
    if inputs.is_empty() {
        return fallback;
    }
    let output = mode_builder.new_variable(result);
    mode_builder.set(
        output,
        ModeEquation::Call {
            result,
            inputs: inputs.into_boxed_slice(),
        },
    );
    output
}

fn eventful_projected_mode(
    mode_builder: &mut ModeProgramBuilder,
    input: ModeVariableId,
) -> ModeVariableId {
    let output = mode_builder.new_variable(FlowMode::Continuous);
    mode_builder.set(output, ModeEquation::Eventful(input));
    output
}

fn user_call_result_mode_source(
    context: &OwnerCompileContext<'_>,
    source_node: usize,
    owner: KernelOwnerId,
    expression_modes: &Arc<[ModeVariableId]>,
    formal_sources: &Arc<[ModeSource]>,
    node: &PackedKernelOwnerNode,
    target: KernelOwnerId,
    inherited_formal: Option<KernelInheritedFormal>,
) -> Result<ModeSource, KernelOwnerBuildError> {
    let project = context.project.ok_or_else(|| {
        KernelOwnerBuildError::new(format!(
            "kernel owner node {source_node} projects through a user call outside a project"
        ))
    })?;
    let target_input = project.owner(target).ok_or_else(|| {
        KernelOwnerBuildError::new(format!(
            "kernel owner node {source_node} projects through missing owner {}",
            target.0
        ))
    })?;
    let target_instance = context.principals.get(target.0 as usize).ok_or_else(|| {
        KernelOwnerBuildError::new(format!(
            "kernel owner node {source_node} projects through missing principal owner {}",
            target.0
        ))
    })?;
    let mut actuals = vec![None; target_input.formal_count() as usize];
    let owner_input = owner_mode_input(context, owner)?;
    for edge in node.inputs(owner_input) {
        let PackedKernelOwnerEdgeRole::CallArgument { ordinal } = edge.role else {
            continue;
        };
        let actual = mode_source_for_edge(context, owner, expression_modes, formal_sources, edge)?;
        let slot = actuals.get_mut(ordinal as usize).ok_or_else(|| {
            KernelOwnerBuildError::new(format!(
                "kernel owner node {source_node} projects out-of-range argument {ordinal}"
            ))
        })?;
        if slot.replace(actual).is_some() {
            return Err(KernelOwnerBuildError::new(format!(
                "kernel owner node {source_node} projects repeated argument {ordinal}"
            )));
        }
    }
    if let Some(inherited) = inherited_formal {
        let actual = formal_sources
            .get(inherited.caller_ordinal as usize)
            .cloned()
            .ok_or_else(|| {
                KernelOwnerBuildError::new(format!(
                    "kernel owner node {source_node} projects missing inherited formal {}",
                    inherited.caller_ordinal
                ))
            })?;
        let slot = actuals
            .get_mut(inherited.target_ordinal as usize)
            .ok_or_else(|| {
                KernelOwnerBuildError::new(format!(
                    "kernel owner node {source_node} projects out-of-range inherited formal {}",
                    inherited.target_ordinal
                ))
            })?;
        if slot.replace(actual).is_some() {
            return Err(KernelOwnerBuildError::new(format!(
                "kernel owner node {source_node} projects repeated inherited formal {}",
                inherited.target_ordinal
            )));
        }
    }
    let actuals = actuals
        .into_iter()
        .enumerate()
        .map(|(ordinal, actual)| {
            actual.ok_or_else(|| {
                KernelOwnerBuildError::new(format!(
                    "kernel owner node {source_node} projects omitted argument {ordinal}"
                ))
            })
        })
        .collect::<Result<Vec<_>, _>>()?;
    let result = checked_expression_index(
        target_input.result(),
        target_input.node_count(),
        "projected user-call result",
    )?;
    Ok(ModeSource::Expression {
        owner: target,
        expression: result,
        expression_modes: Arc::clone(&target_instance.expression_modes),
        formal_sources: actuals.into(),
    })
}

fn projected_edge_mode_variable(
    mode_builder: &mut ModeProgramBuilder,
    context: &OwnerCompileContext<'_>,
    node_index: usize,
    edge: &crate::PackedKernelOwnerInputEdge,
    fields: &[SymbolId],
) -> Result<ModeVariableId, KernelOwnerBuildError> {
    let source = mode_source_for_edge(
        context,
        context.owner,
        context.expression_modes,
        context.formal_mode_sources,
        edge,
    )?;
    projected_mode_variable(
        mode_builder,
        context,
        node_index,
        &source,
        fields,
        &mut BTreeSet::new(),
    )
}

fn projected_mode_variable(
    mode_builder: &mut ModeProgramBuilder,
    context: &OwnerCompileContext<'_>,
    source_node: usize,
    source: &ModeSource,
    fields: &[SymbolId],
    active: &mut ActiveModeProjection,
) -> Result<ModeVariableId, KernelOwnerBuildError> {
    let ModeSource::Expression {
        owner,
        expression,
        expression_modes,
        formal_sources,
    } = source
    else {
        return Ok(source.root_mode());
    };
    let input = owner_mode_input(context, *owner)?;
    let node = input.nodes().get(*expression).ok_or_else(|| {
        KernelOwnerBuildError::new(format!(
            "kernel owner node {source_node} projects missing owner {} expression {expression}",
            owner.0
        ))
    })?;
    let mode = source.root_mode();
    let unproven_branch = active.iter().any(|key| key.4)
        || matches!(
            node.kind,
            PackedKernelOwnerNodeKind::Latest | PackedKernelOwnerNodeKind::When
        );
    let active_key = (*owner, *expression, fields.len(), false, unproven_branch);
    if !active.insert(active_key) {
        return Ok(mode);
    }
    let follow = |edge: &crate::PackedKernelOwnerInputEdge| {
        mode_source_for_edge(context, *owner, expression_modes, formal_sources, edge)
    };
    let result = match &node.kind {
        PackedKernelOwnerNodeKind::FormalRead {
            formal,
            fields: provider_fields,
        }
        | PackedKernelOwnerNodeKind::ContextRead {
            formal,
            fields: provider_fields,
        } => {
            let mut combined = input
                .path(*provider_fields)
                .expect("packed formal mode path remains valid")
                .iter()
                .collect::<Vec<_>>();
            combined.extend_from_slice(fields);
            let provider = formal_sources.get(*formal as usize).ok_or_else(|| {
                KernelOwnerBuildError::new(format!(
                    "kernel owner node {source_node} projects missing formal {formal}"
                ))
            })?;
            projected_mode_variable(
                mode_builder,
                context,
                source_node,
                provider,
                &combined,
                active,
            )?
        }
        PackedKernelOwnerNodeKind::FreshOut => output_binding_collection_item_mode_variable(
            mode_builder,
            context,
            *expression,
            fields,
            active,
        )?
        .unwrap_or(mode),
        PackedKernelOwnerNodeKind::LexicalRead {
            fields: provider_fields,
        }
        | PackedKernelOwnerNodeKind::ValueRead {
            fields: provider_fields,
            ..
        }
        | PackedKernelOwnerNodeKind::DerivedRead {
            fields: provider_fields,
        }
        | PackedKernelOwnerNodeKind::PatternRead {
            fields: provider_fields,
            ..
        } => {
            let provider = selected_mode_edge(input, node, |role| {
                matches!(role, PackedKernelOwnerEdgeRole::ReadProvider)
            });
            if let Some(provider) = provider {
                let mut combined = input
                    .path(*provider_fields)
                    .expect("packed read mode path remains valid")
                    .iter()
                    .collect::<Vec<_>>();
                combined.extend_from_slice(fields);
                let provider = follow(provider)?;
                if combined.is_empty() {
                    provider.root_mode()
                } else {
                    projected_mode_variable(
                        mode_builder,
                        context,
                        source_node,
                        &provider,
                        &combined,
                        active,
                    )?
                }
            } else {
                mode
            }
        }
        PackedKernelOwnerNodeKind::UserCall {
            target,
            inherited_formal,
        } => {
            let result = user_call_result_mode_source(
                context,
                source_node,
                *owner,
                expression_modes,
                formal_sources,
                node,
                *target,
                *inherited_formal,
            )?;
            projected_mode_variable(mode_builder, context, source_node, &result, fields, active)?
        }
        PackedKernelOwnerNodeKind::Block => {
            if let Some(edge) = selected_mode_edge(input, node, |role| {
                matches!(role, PackedKernelOwnerEdgeRole::BlockResult)
            }) {
                let provider = follow(edge)?;
                projected_mode_variable(
                    mode_builder,
                    context,
                    source_node,
                    &provider,
                    fields,
                    active,
                )?
            } else {
                mode
            }
        }
        PackedKernelOwnerNodeKind::Draining => {
            if let Some(edge) = selected_mode_edge(input, node, |role| {
                matches!(role, PackedKernelOwnerEdgeRole::DrainingInput)
            }) {
                let provider = follow(edge)?;
                projected_mode_variable(
                    mode_builder,
                    context,
                    source_node,
                    &provider,
                    fields,
                    active,
                )?
            } else {
                mode
            }
        }
        PackedKernelOwnerNodeKind::MatchArm { .. } => {
            if let Some(edge) = selected_mode_edge(input, node, |role| {
                matches!(role, PackedKernelOwnerEdgeRole::MatchOutput)
            }) {
                let provider = follow(edge)?;
                projected_mode_variable(
                    mode_builder,
                    context,
                    source_node,
                    &provider,
                    fields,
                    active,
                )?
            } else {
                mode
            }
        }
        PackedKernelOwnerNodeKind::Arrow => {
            if let Some(edge) = selected_mode_edge(input, node, |role| {
                matches!(role, PackedKernelOwnerEdgeRole::ArrowOutput)
            }) {
                let provider = follow(edge)?;
                projected_mode_variable(
                    mode_builder,
                    context,
                    source_node,
                    &provider,
                    fields,
                    active,
                )?
            } else {
                mode
            }
        }
        PackedKernelOwnerNodeKind::CollectionItemRead => {
            if let Some(edge) = selected_mode_edge(input, node, |role| {
                matches!(role, PackedKernelOwnerEdgeRole::ReadProvider)
            }) {
                let provider = follow(edge)?;
                if fields.is_empty() {
                    projected_mode_variable(
                        mode_builder,
                        context,
                        source_node,
                        &provider,
                        fields,
                        active,
                    )?
                } else {
                    projected_collection_item_mode_variable(
                        mode_builder,
                        context,
                        source_node,
                        &provider,
                        fields,
                        active,
                    )?
                }
            } else {
                mode
            }
        }
        PackedKernelOwnerNodeKind::PureBuiltin {
            kind: KernelPureBuiltinKind::ListMap,
        } if fields.is_empty() => {
            if let Some(edge) = selected_mode_edge(input, node, |role| {
                matches!(role, PackedKernelOwnerEdgeRole::AbiArgument { name }
                    if input.symbol(*name) == Some("$pipe"))
            }) {
                let provider = follow(edge)?;
                projected_mode_variable(
                    mode_builder,
                    context,
                    source_node,
                    &provider,
                    fields,
                    active,
                )?
            } else {
                let inputs = node
                    .inputs(input)
                    .iter()
                    .map(|edge| {
                        let provider = follow(edge)?;
                        projected_mode_variable(
                            mode_builder,
                            context,
                            source_node,
                            &provider,
                            fields,
                            active,
                        )
                    })
                    .collect::<Result<Vec<_>, KernelOwnerBuildError>>()?;
                merge_contextual_call_modes(mode_builder, inputs, node.mode, mode)
            }
        }
        PackedKernelOwnerNodeKind::PureBuiltin {
            kind: KernelPureBuiltinKind::ListMap,
        } => {
            if let Some(edge) = selected_mode_edge(input, node, |role| {
                matches!(role, PackedKernelOwnerEdgeRole::AbiArgument { name }
                    if input.symbol(*name) == Some("new"))
            }) {
                let provider = follow(edge)?;
                projected_mode_variable(
                    mode_builder,
                    context,
                    source_node,
                    &provider,
                    fields,
                    active,
                )?
            } else {
                mode
            }
        }
        PackedKernelOwnerNodeKind::PureBuiltin {
            kind: KernelPureBuiltinKind::ListLatest,
        } if fields.is_empty() => {
            let inputs = node
                .inputs(input)
                .iter()
                .map(|edge| {
                    let provider = follow(edge)?;
                    projected_mode_variable(
                        mode_builder,
                        context,
                        source_node,
                        &provider,
                        fields,
                        active,
                    )
                })
                .collect::<Result<Vec<_>, KernelOwnerBuildError>>()?;
            merge_contextual_call_modes(mode_builder, inputs, node.mode, mode)
        }
        PackedKernelOwnerNodeKind::PureBuiltin {
            kind: KernelPureBuiltinKind::ListLatest,
        } => {
            if let Some(edge) = selected_mode_edge(input, node, |role| {
                matches!(role, PackedKernelOwnerEdgeRole::AbiArgument { name }
                    if input.symbol(*name).is_some_and(|name| matches!(name, "$pipe" | "list")))
            }) {
                let provider = follow(edge)?;
                if fields.is_empty() {
                    projected_mode_variable(
                        mode_builder,
                        context,
                        source_node,
                        &provider,
                        fields,
                        active,
                    )?
                } else {
                    projected_collection_item_mode_variable(
                        mode_builder,
                        context,
                        source_node,
                        &provider,
                        fields,
                        active,
                    )?
                }
            } else {
                mode
            }
        }
        PackedKernelOwnerNodeKind::When if fields.is_empty() => {
            if let Some(edge) = selected_mode_edge(input, node, |role| {
                matches!(role, PackedKernelOwnerEdgeRole::WhenInput)
            }) {
                let provider = follow(edge)?;
                projected_mode_variable(
                    mode_builder,
                    context,
                    source_node,
                    &provider,
                    fields,
                    active,
                )?
            } else {
                mode
            }
        }
        PackedKernelOwnerNodeKind::Latest | PackedKernelOwnerNodeKind::When => {
            let selected = |role: &PackedKernelOwnerEdgeRole| match &node.kind {
                PackedKernelOwnerNodeKind::Latest => {
                    matches!(role, PackedKernelOwnerEdgeRole::LatestBranch)
                }
                PackedKernelOwnerNodeKind::When => {
                    matches!(role, PackedKernelOwnerEdgeRole::WhenArm)
                }
                _ => false,
            };
            let projected = node
                .inputs(input)
                .iter()
                .filter(|edge| selected(&edge.role))
                .map(|edge| {
                    let provider = follow(edge)?;
                    projected_mode_variable(
                        mode_builder,
                        context,
                        source_node,
                        &provider,
                        fields,
                        active,
                    )
                })
                .collect::<Result<Vec<_>, KernelOwnerBuildError>>()?;
            merge_projected_modes(mode_builder, projected, mode)
        }
        PackedKernelOwnerNodeKind::PureBuiltin { .. }
        | PackedKernelOwnerNodeKind::RenderConstructor { .. }
        | PackedKernelOwnerNodeKind::HostEffect { .. }
            if fields.is_empty() =>
        {
            let inputs = node
                .inputs(input)
                .iter()
                .map(|edge| {
                    let provider = follow(edge)?;
                    projected_mode_variable(
                        mode_builder,
                        context,
                        source_node,
                        &provider,
                        fields,
                        active,
                    )
                })
                .collect::<Result<Vec<_>, KernelOwnerBuildError>>()?;
            merge_contextual_call_modes(mode_builder, inputs, node.mode, mode)
        }
        PackedKernelOwnerNodeKind::Record { .. } if !fields.is_empty() => {
            let field = &fields[0];
            if let Some(edge) = selected_mode_edge(input, node, |role| {
                matches!(
                    role,
                    PackedKernelOwnerEdgeRole::RecordField { name, spread: false }
                        if name == field
                )
            }) {
                let provider = follow(edge)?;
                projected_mode_variable(
                    mode_builder,
                    context,
                    source_node,
                    &provider,
                    &fields[1..],
                    active,
                )?
            } else {
                let projected_spreads = node
                    .inputs(input)
                    .iter()
                    .filter(|edge| {
                        matches!(
                            edge.role,
                            PackedKernelOwnerEdgeRole::RecordField { spread: true, .. }
                        )
                    })
                    .map(|edge| {
                        let provider = follow(edge)?;
                        projected_mode_variable(
                            mode_builder,
                            context,
                            source_node,
                            &provider,
                            fields,
                            active,
                        )
                    })
                    .collect::<Result<Vec<_>, KernelOwnerBuildError>>()?;
                if projected_spreads.is_empty() && unproven_branch {
                    // A closed branch which does not define this field is not
                    // a continuous provider for the projection. Keep it
                    // unresolved here so a real eventful provider in another
                    // WHEN/LATEST branch determines the merged occurrence.
                    eventful_projected_mode(mode_builder, mode)
                } else if projected_spreads.is_empty() {
                    mode
                } else {
                    merge_projected_modes(mode_builder, projected_spreads, mode)
                }
            }
        }
        _ if !fields.is_empty() => eventful_projected_mode(mode_builder, mode),
        _ => mode,
    };
    active.remove(&active_key);
    Ok(result)
}

fn projected_collection_item_mode_variable(
    mode_builder: &mut ModeProgramBuilder,
    context: &OwnerCompileContext<'_>,
    source_node: usize,
    source: &ModeSource,
    fields: &[SymbolId],
    active: &mut ActiveModeProjection,
) -> Result<ModeVariableId, KernelOwnerBuildError> {
    let ModeSource::Expression {
        owner,
        expression,
        expression_modes,
        formal_sources,
    } = source
    else {
        return Ok(source.root_mode());
    };
    let input = owner_mode_input(context, *owner)?;
    let node = input.nodes().get(*expression).ok_or_else(|| {
        KernelOwnerBuildError::new(format!(
            "kernel owner node {source_node} projects an item from missing owner {} expression {expression}",
            owner.0
        ))
    })?;
    let mode = source.root_mode();
    let active_key = (*owner, *expression, fields.len(), true, true);
    if !active.insert(active_key) {
        return Ok(mode);
    }
    let follow = |edge: &crate::PackedKernelOwnerInputEdge| {
        mode_source_for_edge(context, *owner, expression_modes, formal_sources, edge)
    };
    let result = match &node.kind {
        PackedKernelOwnerNodeKind::Collection {
            kind: KernelCollectionKind::List | KernelCollectionKind::Set,
            ..
        } => {
            let projected = node
                .inputs(input)
                .iter()
                .filter(|edge| matches!(edge.role, PackedKernelOwnerEdgeRole::CollectionItem))
                .map(|edge| {
                    let provider = follow(edge)?;
                    projected_mode_variable(
                        mode_builder,
                        context,
                        source_node,
                        &provider,
                        fields,
                        active,
                    )
                })
                .collect::<Result<Vec<_>, KernelOwnerBuildError>>()?;
            merge_projected_modes(mode_builder, projected, mode)
        }
        PackedKernelOwnerNodeKind::PureBuiltin {
            kind: KernelPureBuiltinKind::ListMap,
        } => {
            if let Some(edge) = selected_mode_edge(input, node, |role| {
                matches!(role, PackedKernelOwnerEdgeRole::AbiArgument { name }
                    if input.symbol(*name) == Some("new"))
            }) {
                let provider = follow(edge)?;
                projected_mode_variable(
                    mode_builder,
                    context,
                    source_node,
                    &provider,
                    fields,
                    active,
                )?
            } else {
                mode
            }
        }
        PackedKernelOwnerNodeKind::PureBuiltin {
            kind: KernelPureBuiltinKind::ListFilter | KernelPureBuiltinKind::ListSort,
        } => {
            if let Some(edge) = selected_mode_edge(input, node, |role| {
                matches!(role, PackedKernelOwnerEdgeRole::AbiArgument { name }
                    if input.symbol(*name).is_some_and(|name| matches!(name, "$pipe" | "list")))
            }) {
                let provider = follow(edge)?;
                projected_collection_item_mode_variable(
                    mode_builder,
                    context,
                    source_node,
                    &provider,
                    fields,
                    active,
                )?
            } else {
                mode
            }
        }
        PackedKernelOwnerNodeKind::LexicalRead {
            fields: provider_fields,
        }
        | PackedKernelOwnerNodeKind::ValueRead {
            fields: provider_fields,
            ..
        }
        | PackedKernelOwnerNodeKind::DerivedRead {
            fields: provider_fields,
        }
        | PackedKernelOwnerNodeKind::PatternRead {
            fields: provider_fields,
            ..
        } if input
            .path(*provider_fields)
            .is_some_and(PackedKernelPathRef::is_empty) =>
        {
            if let Some(edge) = selected_mode_edge(input, node, |role| {
                matches!(role, PackedKernelOwnerEdgeRole::ReadProvider)
            }) {
                let provider = follow(edge)?;
                projected_collection_item_mode_variable(
                    mode_builder,
                    context,
                    source_node,
                    &provider,
                    fields,
                    active,
                )?
            } else {
                mode
            }
        }
        PackedKernelOwnerNodeKind::Block => {
            if let Some(edge) = selected_mode_edge(input, node, |role| {
                matches!(role, PackedKernelOwnerEdgeRole::BlockResult)
            }) {
                let provider = follow(edge)?;
                projected_collection_item_mode_variable(
                    mode_builder,
                    context,
                    source_node,
                    &provider,
                    fields,
                    active,
                )?
            } else {
                mode
            }
        }
        PackedKernelOwnerNodeKind::Draining => {
            if let Some(edge) = selected_mode_edge(input, node, |role| {
                matches!(role, PackedKernelOwnerEdgeRole::DrainingInput)
            }) {
                let provider = follow(edge)?;
                projected_collection_item_mode_variable(
                    mode_builder,
                    context,
                    source_node,
                    &provider,
                    fields,
                    active,
                )?
            } else {
                mode
            }
        }
        PackedKernelOwnerNodeKind::UserCall {
            target,
            inherited_formal,
        } => {
            let provider = user_call_result_mode_source(
                context,
                source_node,
                *owner,
                expression_modes,
                formal_sources,
                node,
                *target,
                *inherited_formal,
            )?;
            projected_collection_item_mode_variable(
                mode_builder,
                context,
                source_node,
                &provider,
                fields,
                active,
            )?
        }
        _ => mode,
    };
    active.remove(&active_key);
    Ok(result)
}

fn output_binding_collection_item_mode_variable(
    mode_builder: &mut ModeProgramBuilder,
    context: &OwnerCompileContext<'_>,
    source_node: usize,
    fields: &[SymbolId],
    active: &mut ActiveModeProjection,
) -> Result<Option<ModeVariableId>, KernelOwnerBuildError> {
    let Some((consumer_index, list)) = output_binding_collection_driver(context, source_node)?
    else {
        return Ok(None);
    };
    let provider = mode_source_for_edge(
        context,
        context.owner,
        context.expression_modes,
        context.formal_mode_sources,
        list,
    )?;
    projected_collection_item_mode_variable(
        mode_builder,
        context,
        consumer_index,
        &provider,
        fields,
        active,
    )
    .map(Some)
}

fn output_binding_collection_driver<'a>(
    context: &'a OwnerCompileContext<'_>,
    source_node: usize,
) -> Result<Option<(usize, &'a crate::PackedKernelOwnerInputEdge)>, KernelOwnerBuildError> {
    let mut consumers = context
        .input
        .nodes()
        .iter()
        .enumerate()
        .filter(|(_, node)| {
            matches!(
                node.kind,
                PackedKernelOwnerNodeKind::PureBuiltin {
                    kind: KernelPureBuiltinKind::ListPredicate
                        | KernelPureBuiltinKind::ListFilter
                        | KernelPureBuiltinKind::ListMap
                        | KernelPureBuiltinKind::ListFind
                        | KernelPureBuiltinKind::ListSort
                }
            ) && node.inputs(context.input).iter().any(|edge| {
                matches!(edge.role, PackedKernelOwnerEdgeRole::AbiArgument { name }
                    if context.input.symbol(name) == Some("item"))
                    && edge.expression.0 as usize == source_node
            })
        });
    let Some((consumer_index, consumer)) = consumers.next() else {
        return Ok(None);
    };
    if consumers.next().is_some() {
        return Err(KernelOwnerBuildError::new(format!(
            "kernel owner node {source_node} is driven by multiple contextual collection calls"
        )));
    }
    let list = selected_mode_edge(context.input, consumer, |role| {
        matches!(role, PackedKernelOwnerEdgeRole::AbiArgument { name }
            if context.input.symbol(*name).is_some_and(|name| matches!(name, "$pipe" | "list")))
    })
    .ok_or_else(|| {
        KernelOwnerBuildError::new(format!(
            "kernel owner node {consumer_index} drives OUT {source_node} without a list input"
        ))
    })?;
    Ok(Some((consumer_index, list)))
}

/// Route a callback consumer requirement back through its collection input.
///
/// The requirement channel stops at owner/public providers. A definition-local
/// formal is different: its principal shape is inferred from every use, so a
/// callback requirement on `item.field` must constrain the corresponding
/// `list[].field` formal surface. Filter/sort preserve that item identity and
/// are traversed transparently. The callback occurrence itself remains a
/// detached directional read and is never unified with this surface.
fn bind_output_capability_requirement(
    builder: &mut ComponentProgramBuilder,
    context: &OwnerCompileContext<'_>,
    edge: &crate::PackedKernelOwnerInputEdge,
    requirement: TypeVariableId,
) -> Result<(), KernelOwnerBuildError> {
    let Some((output, fields)) =
        output_capability_read_path(context, edge.expression.0 as usize, &mut BTreeSet::new())?
    else {
        return Ok(());
    };
    let Some((_, list)) = output_binding_collection_driver(context, output)? else {
        return Ok(());
    };
    let item_requirement = if fields.is_empty() {
        requirement
    } else {
        let root = builder.new_contextual_hole();
        let projected = requirement_projection(builder, root, &fields);
        let projected = builder.variable_term(projected);
        let requirement = builder.variable_term(requirement);
        builder.add_unify(projected, requirement);
        root
    };
    let Some(list_requirement) = expression_requirement_variable(
        builder,
        context,
        list.expression.0 as usize,
        &mut BTreeSet::new(),
    )?
    else {
        return Ok(());
    };
    let item_requirement = builder.variable_term(item_requirement);
    let list_shape = builder.terms_mut().list(item_requirement);
    let list_requirement = builder.variable_term(list_requirement);
    builder.add_unify(list_requirement, list_shape);
    Ok(())
}

fn output_capability_read_path(
    context: &OwnerCompileContext<'_>,
    expression: usize,
    active: &mut BTreeSet<usize>,
) -> Result<Option<(usize, Vec<SymbolId>)>, KernelOwnerBuildError> {
    if expression >= context.input.node_count() || !active.insert(expression) {
        return Ok(None);
    }
    let node = &context.input.nodes()[expression];
    let inputs = node.inputs(context.input);
    let result = match &node.kind {
        PackedKernelOwnerNodeKind::FreshOut => Some((expression, Vec::new())),
        PackedKernelOwnerNodeKind::LexicalRead { fields }
        | PackedKernelOwnerNodeKind::ValueRead { fields, .. }
        | PackedKernelOwnerNodeKind::DerivedRead { fields } => {
            let providers = inputs
                .iter()
                .filter(|edge| matches!(edge.role, PackedKernelOwnerEdgeRole::ReadProvider))
                .collect::<Vec<_>>();
            let [provider] = providers.as_slice() else {
                active.remove(&expression);
                return Ok(None);
            };
            output_capability_read_path(context, provider.expression.0 as usize, active)?.map(
                |(output, mut path)| {
                    path.extend(
                        context
                            .input
                            .path(*fields)
                            .expect("packed output-capability path remains valid")
                            .iter(),
                    );
                    (output, path)
                },
            )
        }
        _ => None,
    };
    active.remove(&expression);
    Ok(result)
}

fn expression_requirement_variable(
    builder: &mut ComponentProgramBuilder,
    context: &OwnerCompileContext<'_>,
    expression: usize,
    active: &mut BTreeSet<usize>,
) -> Result<Option<TypeVariableId>, KernelOwnerBuildError> {
    if expression >= context.input.node_count() || !active.insert(expression) {
        return Ok(None);
    }
    let node = &context.input.nodes()[expression];
    let inputs = node.inputs(context.input);
    let result = match &node.kind {
        PackedKernelOwnerNodeKind::FormalRead { formal, fields } => {
            let root = context
                .formal_requirements
                .get(*formal as usize)
                .copied()
                .ok_or_else(|| {
                    KernelOwnerBuildError::new(format!(
                        "kernel owner node {expression} reads missing formal requirement {formal}"
                    ))
                })?;
            let fields = context
                .input
                .path(*fields)
                .expect("packed formal requirement path remains valid");
            Some(requirement_projection_iter(builder, root, fields.iter()))
        }
        PackedKernelOwnerNodeKind::LexicalRead { fields }
        | PackedKernelOwnerNodeKind::DerivedRead { fields } => {
            let providers = inputs
                .iter()
                .filter(|edge| matches!(edge.role, PackedKernelOwnerEdgeRole::ReadProvider))
                .collect::<Vec<_>>();
            let [provider] = providers.as_slice() else {
                active.remove(&expression);
                return Ok(None);
            };
            let Some(root) = expression_requirement_variable(
                builder,
                context,
                provider.expression.0 as usize,
                active,
            )?
            else {
                active.remove(&expression);
                return Ok(None);
            };
            let fields = context
                .input
                .path(*fields)
                .expect("packed lexical requirement path remains valid");
            Some(requirement_projection_iter(builder, root, fields.iter()))
        }
        PackedKernelOwnerNodeKind::Block => {
            let provider = inputs
                .iter()
                .find(|edge| matches!(edge.role, PackedKernelOwnerEdgeRole::BlockResult));
            match provider {
                Some(provider) => expression_requirement_variable(
                    builder,
                    context,
                    provider.expression.0 as usize,
                    active,
                )?,
                None => None,
            }
        }
        PackedKernelOwnerNodeKind::PureBuiltin {
            kind: KernelPureBuiltinKind::ListFilter | KernelPureBuiltinKind::ListSort,
        } => {
            let provider = inputs.iter().find(|edge| {
                matches!(edge.role, PackedKernelOwnerEdgeRole::AbiArgument { name }
                    if context.input.symbol(name).is_some_and(|name| matches!(name, "$pipe" | "list")))
            });
            match provider {
                Some(provider) => expression_requirement_variable(
                    builder,
                    context,
                    provider.expression.0 as usize,
                    active,
                )?,
                None => None,
            }
        }
        // Cross-owner/public values are provider-only boundaries. Requirements
        // must not specialize their producer or leak into another owner.
        _ => None,
    };
    active.remove(&expression);
    Ok(result)
}

fn edge_variable(
    context: &OwnerCompileContext<'_>,
    node_index: usize,
    edge: &crate::PackedKernelOwnerInputEdge,
) -> Result<TypeVariableId, KernelOwnerBuildError> {
    let reference = edge.expression.0 as usize;
    if reference < context.input.node_count() {
        return Ok(context.expressions[reference]);
    }
    let external_index = reference - context.input.node_count();
    if let Some(external_variables) = context.external_variables {
        return external_variables
            .get(external_index)
            .copied()
            .ok_or_else(|| {
                KernelOwnerBuildError::new(format!(
                    "input of owner {} node {node_index} references external frame variable {external_index} outside 0..{}",
                    context.owner.0,
                    external_variables.len()
                ))
            });
    }
    let external = context
        .input
        .external_expressions()
        .get(external_index)
        .ok_or_else(|| {
            KernelOwnerBuildError::new(format!(
                "input of owner {} node {node_index} references external expression {external_index} outside 0..{}",
                context.owner.0,
                context.input.external_expressions().len()
            ))
        })?;
    let target_owner = context
        .principals
        .get(external.owner.0 as usize)
        .ok_or_else(|| {
            KernelOwnerBuildError::new(format!(
                "input of owner {} node {node_index} references missing owner {}",
                context.owner.0, external.owner.0
            ))
        })?;
    match external.target {
        KernelExternalTarget::Expression(expression) => target_owner
            .expressions
            .get(expression.0 as usize)
            .copied()
            .ok_or_else(|| {
                KernelOwnerBuildError::new(format!(
                    "input of owner {} node {node_index} references missing owner {} expression {}",
                    context.owner.0, external.owner.0, expression.0
                ))
            }),
        KernelExternalTarget::Result => {
            let project = context.project.ok_or_else(|| {
                KernelOwnerBuildError::new(format!(
                    "input of owner {} node {node_index} references an owner result outside a project",
                    context.owner.0
                ))
            })?;
            let target_input = project.owner(external.owner).ok_or_else(|| {
                KernelOwnerBuildError::new(format!(
                    "input of owner {} node {node_index} references missing owner {} result",
                    context.owner.0, external.owner.0
                ))
            })?;
            let result = checked_expression_index(
                target_input.result(),
                target_input.node_count(),
                "external owner result",
            )?;
            Ok(target_owner.expressions[result])
        }
    }
}

/// Resolve the producer capability named by an `OUT` actual.
///
/// Ordinary reads are detached occurrences and therefore cannot be used as
/// the destination of a call-frame equation. A bare `OUT` creates a private
/// variable, while forwarding an enclosing `OUT` aliases that formal's frame
/// variable directly. Keeping this distinction explicit prevents the call and
/// the formal-read projection from becoming competing directional writers.
fn edge_output_variable(
    context: &OwnerCompileContext<'_>,
    node_index: usize,
    edge: &crate::PackedKernelOwnerInputEdge,
) -> Result<TypeVariableId, KernelOwnerBuildError> {
    let reference = edge.expression.0 as usize;
    let node = context.input.nodes().get(reference).ok_or_else(|| {
        KernelOwnerBuildError::new(format!(
            "OUT input of owner {} node {node_index} must reference a local output binding",
            context.owner.0
        ))
    })?;
    match &node.kind {
        PackedKernelOwnerNodeKind::FreshOut => context
            .expressions
            .get(reference)
            .copied()
            .ok_or_else(|| {
                KernelOwnerBuildError::new(format!(
                    "OUT input of owner {} node {node_index} references missing fresh output {reference}",
                    context.owner.0
                ))
            }),
        PackedKernelOwnerNodeKind::FormalRead { formal, fields }
            if context
                .input
                .path(*fields)
                .is_some_and(PackedKernelPathRef::is_empty) => context
            .formals
            .get(*formal as usize)
            .copied()
            .ok_or_else(|| {
                KernelOwnerBuildError::new(format!(
                    "OUT input of owner {} node {node_index} forwards missing formal {formal}",
                    context.owner.0
                ))
            }),
        _ => Err(KernelOwnerBuildError::new(format!(
            "OUT input of owner {} node {node_index} must be a bare fresh output or enclosing OUT formal",
            context.owner.0
        ))),
    }
}

fn edge_reads_output_capability(
    context: &OwnerCompileContext<'_>,
    _node_index: usize,
    edge: &crate::PackedKernelOwnerInputEdge,
) -> Result<bool, KernelOwnerBuildError> {
    fn visit(
        context: &OwnerCompileContext<'_>,
        expression: usize,
        active: &mut BTreeSet<usize>,
    ) -> Result<bool, KernelOwnerBuildError> {
        if expression >= context.input.node_count() || !active.insert(expression) {
            return Ok(false);
        }
        let node = &context.input.nodes()[expression];
        let result = match &node.kind {
            PackedKernelOwnerNodeKind::FreshOut | PackedKernelOwnerNodeKind::CollectionItemRead => {
                true
            }
            PackedKernelOwnerNodeKind::LexicalRead { .. }
            | PackedKernelOwnerNodeKind::ValueRead { .. }
            | PackedKernelOwnerNodeKind::DerivedRead { .. } => {
                let providers = node
                    .inputs(context.input)
                    .iter()
                    .filter(|edge| matches!(edge.role, PackedKernelOwnerEdgeRole::ReadProvider))
                    .collect::<Vec<_>>();
                let [provider] = providers.as_slice() else {
                    active.remove(&expression);
                    return Ok(false);
                };
                visit(context, provider.expression.0 as usize, active)?
            }
            _ => false,
        };
        active.remove(&expression);
        Ok(result)
    }

    visit(context, edge.expression.0 as usize, &mut BTreeSet::new())
}

fn referenced_node<'a>(
    context: &'a OwnerCompileContext<'a>,
    node_index: usize,
    edge: &crate::PackedKernelOwnerInputEdge,
) -> Result<&'a PackedKernelOwnerNode, KernelOwnerBuildError> {
    let reference = edge.expression.0 as usize;
    if reference < context.input.node_count() {
        return context.input.nodes().get(reference).ok_or_else(|| {
            KernelOwnerBuildError::new(format!(
                "owner {} node {node_index} references missing local node {reference}",
                context.owner.0
            ))
        });
    }
    let external_index = reference - context.input.node_count();
    let external = context
        .input
        .external_expressions()
        .get(external_index)
        .ok_or_else(|| {
            KernelOwnerBuildError::new(format!(
                "owner {} node {node_index} references missing external node {external_index}",
                context.owner.0
            ))
        })?;
    let project = context.project.ok_or_else(|| {
        KernelOwnerBuildError::new(format!(
            "owner {} node {node_index} references an external node outside a project",
            context.owner.0
        ))
    })?;
    let target = project.owner(external.owner).ok_or_else(|| {
        KernelOwnerBuildError::new(format!(
            "owner {} node {node_index} references missing owner {}",
            context.owner.0, external.owner.0
        ))
    })?;
    let expression = match external.target {
        KernelExternalTarget::Expression(expression) => {
            checked_expression_index(expression, target.node_count(), "external node reference")?
        }
        KernelExternalTarget::Result => checked_expression_index(
            target.result(),
            target.node_count(),
            "external result node reference",
        )?,
    };
    target.nodes().get(expression).ok_or_else(|| {
        KernelOwnerBuildError::new(format!(
            "owner {} node {node_index} references missing owner {} node {expression}",
            context.owner.0, external.owner.0
        ))
    })
}

fn edge_mode_variable(
    context: &OwnerCompileContext<'_>,
    node_index: usize,
    edge: &crate::PackedKernelOwnerInputEdge,
) -> Result<ModeVariableId, KernelOwnerBuildError> {
    let reference = edge.expression.0 as usize;
    if reference < context.input.node_count() {
        return Ok(context.expression_modes[reference]);
    }
    let external_index = reference - context.input.node_count();
    let external = context
        .input
        .external_expressions()
        .get(external_index)
        .ok_or_else(|| {
            KernelOwnerBuildError::new(format!(
                "mode input of owner {} node {node_index} references external expression {external_index} outside 0..{}",
                context.owner.0,
                context.input.external_expressions().len()
            ))
        })?;
    let target_owner = context
        .principals
        .get(external.owner.0 as usize)
        .ok_or_else(|| {
            KernelOwnerBuildError::new(format!(
                "mode input of owner {} node {node_index} references missing owner {}",
                context.owner.0, external.owner.0
            ))
        })?;
    match external.target {
        KernelExternalTarget::Expression(expression) => target_owner
            .expression_modes
            .get(expression.0 as usize)
            .copied()
            .ok_or_else(|| {
                KernelOwnerBuildError::new(format!(
                    "mode input of owner {} node {node_index} references missing owner {} expression {}",
                    context.owner.0, external.owner.0, expression.0
                ))
            }),
        KernelExternalTarget::Result => {
            let project = context.project.ok_or_else(|| {
                KernelOwnerBuildError::new(format!(
                    "mode input of owner {} node {node_index} references an owner result outside a project",
                    context.owner.0
                ))
            })?;
            let target_input = project
                .owner(external.owner)
                .ok_or_else(|| {
                    KernelOwnerBuildError::new(format!(
                        "mode input of owner {} node {node_index} references missing owner {} result",
                        context.owner.0, external.owner.0
                    ))
                })?;
            let result = checked_expression_index(
                target_input.result(),
                target_input.node_count(),
                "external owner result mode",
            )?;
            Ok(target_owner.expression_modes[result])
        }
    }
}

fn checked_expression_index(
    expression: KernelExpressionId,
    len: usize,
    context: &str,
) -> Result<usize, KernelOwnerBuildError> {
    let index = expression.0 as usize;
    if index >= len {
        return Err(KernelOwnerBuildError::new(format!(
            "{context} references expression {} outside 0..{len}",
            expression.0
        )));
    }
    Ok(index)
}

